import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useLocation } from 'react-router-dom'
import {
  Brain,
  ChevronRight,
  Copy,
  Lightbulb,
  Loader2,
  MessageSquare,
  Send,
  Sparkles,
  X,
  AlertTriangle,
  TrendingUp,
  BarChart3,
  DollarSign,
  Check,
  Zap,
} from 'lucide-react'
import { cn } from '@/utils/cn'
import { AICopilotEngine } from '@/engines/AICopilotEngine'
import { FinanceCopilotEngine } from '@/engines/FinanceCopilotEngine'
import { useCopilotSidebar } from '@/hooks/useCopilotSidebar'
import type { GLState, BudgetState } from '@/types'

// ─── Context-aware suggestion map ───────────────────────────────────────────

interface PageContext {
  label: string
  suggestions: string[]
  alertThreshold: number
}

const PAGE_CONTEXTS: Record<string, PageContext> = {
  '/dashboard': {
    label: 'Dashboard',
    suggestions: [
      'Show me a revenue vs expense summary',
      'What are the top 5 variance items this period?',
      'Generate a quick P&L overview',
    ],
    alertThreshold: 0.1,
  },
  '/budgets': {
    label: 'Budgets',
    suggestions: [
      'Suggest a budget allocation formula',
      'Show budget utilization by department',
      'What is the remaining budget headroom?',
    ],
    alertThreshold: 0.1,
  },
  '/budgets/bva': {
    label: 'Budget vs Actuals',
    suggestions: [
      'Which line items have the largest variance?',
      'Show variance percentage by category',
      'Explain the unfavorable variance in OpEx',
    ],
    alertThreshold: 0.1,
  },
  '/forecasts': {
    label: 'Forecasts',
    suggestions: [
      'Suggest a growth rate formula for next quarter',
      'Show forecast confidence intervals',
      'What assumptions drive this forecast?',
    ],
    alertThreshold: 0.15,
  },
  '/variance': {
    label: 'Variance Analysis',
    suggestions: [
      'Show all variances above 10%',
      'Explain the variance formula being used',
      'Compare favorable vs unfavorable totals',
    ],
    alertThreshold: 0.1,
  },
  '/reports': {
    label: 'Reports',
    suggestions: [
      'Help me build a custom report formula',
      'Summarize key metrics for this report',
      'Suggest chart types for this data',
    ],
    alertThreshold: 0.1,
  },
  '/analytics': {
    label: 'Analytics',
    suggestions: [
      'What trends do you see in this data?',
      'Suggest a CAGR calculation',
      'Show YoY growth analysis',
    ],
    alertThreshold: 0.12,
  },
  '/scenarios': {
    label: 'Scenarios',
    suggestions: [
      'What if revenue drops 15%?',
      'Show best/worst/base case comparison',
      'Suggest NPV for this scenario',
    ],
    alertThreshold: 0.15,
  },
}

const DEFAULT_CONTEXT: PageContext = {
  label: 'General',
  suggestions: [
    'Help me write a financial formula',
    'Explain how variance percentage works',
    'What can you help me with?',
  ],
  alertThreshold: 0.1,
}

// ─── Types ──────────────────────────────────────────────────────────────────

interface CopilotMessage {
  id: string
  role: 'user' | 'assistant'
  content: string
  timestamp: Date
  confidence?: number
  sources?: string[]
  chartType?: string
  formula?: string
}

interface CopilotAlert {
  id: string
  type: 'variance' | 'budget' | 'forecast' | 'info'
  severity: 'high' | 'medium' | 'low'
  message: string
  detail: string
  metric?: string
  value?: number
  threshold?: number
}

interface CopilotSidebarProps {
  gl?: GLState
  budget?: BudgetState
  className?: string
}

// ─── Helpers ────────────────────────────────────────────────────────────────

let msgCounter = 0
function nextId(prefix: string) {
  return `${prefix}-${Date.now()}-${++msgCounter}`
}

function getContextForPath(pathname: string): PageContext {
  const exact = PAGE_CONTEXTS[pathname]
  if (exact) return exact
  const prefix = Object.keys(PAGE_CONTEXTS).find((k) => k !== '/' && pathname.startsWith(k))
  return prefix ? PAGE_CONTEXTS[prefix] : DEFAULT_CONTEXT
}

function generateAlerts(gl?: GLState, budget?: BudgetState, threshold = 0.1): CopilotAlert[] {
  const alerts: CopilotAlert[] = []

  // Budget approval alerts
  if (budget?.budgets) {
    const inReview = budget.budgets.filter((b) => b.status === 'InReview')
    if (inReview.length > 0) {
      alerts.push({
        id: 'budget-pending',
        type: 'budget',
        severity: 'medium',
        message: `${inReview.length} budget(s) awaiting approval`,
        detail: 'InReview budgets need action before period close',
        metric: 'Budgets',
      })
    }

    const draft = budget.budgets.filter((b) => b.status === 'Draft')
    if (draft.length > 0) {
      alerts.push({
        id: 'budget-draft',
        type: 'budget',
        severity: 'low',
        message: `${draft.length} draft budget(s) not yet submitted`,
        detail: 'Complete and submit for review',
        metric: 'Budgets',
      })
    }
  }

  // GL-based revenue vs expense alerts
  if (gl?.entries) {
    const totalRevenue = gl.entries.reduce((s, e) => s + e.credit, 0)
    const totalExpense = gl.entries.reduce((s, e) => s + e.debit, 0)

    if (totalExpense > totalRevenue && totalRevenue > 0) {
      alerts.push({
        id: 'expense-exceeds',
        type: 'forecast',
        severity: 'high',
        message: 'Expenses exceed revenue in current period',
        detail: `Net: $${((totalRevenue - totalExpense) / 1000).toFixed(0)}K — action needed`,
        metric: 'Net Income',
        value: totalRevenue - totalExpense,
      })
    }

    // Flag large single entries (> 10% of total revenue)
    if (totalRevenue > 0) {
      const largeEntries = gl.entries.filter(
        (e) => e.amount > totalRevenue * threshold && e.debit > 0
      )
      if (largeEntries.length > 0) {
        alerts.push({
          id: 'large-entries',
          type: 'variance',
          severity: 'medium',
          message: `${largeEntries.length} expense(s) exceed ${threshold * 100}% of revenue`,
          detail: 'Review for budget alignment',
          metric: 'Expenses',
          value: largeEntries.length,
          threshold,
        })
      }
    }
  }

  if (alerts.length === 0) {
    alerts.push({
      id: 'all-clear',
      type: 'info',
      severity: 'low',
      message: 'No critical alerts',
      detail: 'All metrics are within expected ranges',
    })
  }

  return alerts
}

// ─── Sub-components ─────────────────────────────────────────────────────────

function AlertCard({ alert }: { alert: CopilotAlert }) {
  const severityColors = {
    high: 'border-red-500/40 bg-red-500/10',
    medium: 'border-amber-500/40 bg-amber-500/10',
    low: 'border-emerald-500/40 bg-emerald-500/10',
  }
  const severityIcon = {
    high: <AlertTriangle className="w-4 h-4 text-red-400" />,
    medium: <AlertTriangle className="w-4 h-4 text-amber-400" />,
    low: <Check className="w-4 h-4 text-emerald-400" />,
  }

  return (
    <div
      className={cn('rounded-lg border p-3 transition-colors', severityColors[alert.severity])}
      role="alert"
    >
      <div className="flex items-start gap-2.5">
        <div className="mt-0.5 flex-shrink-0">{severityIcon[alert.severity]}</div>
        <div className="min-w-0 flex-1">
          <p className="text-xs font-semibold" style={{ color: 'var(--text-primary)' }}>
            {alert.message}
          </p>
          <p className="mt-1 text-[11px] leading-relaxed" style={{ color: 'var(--text-muted)' }}>
            {alert.detail}
          </p>
        </div>
      </div>
    </div>
  )
}

function SuggestionChip({ label, onClick }: { label: string; onClick: () => void }) {
  return (
    <button
      onClick={onClick}
      className="group flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-[11px] font-medium transition-all hover:border-[var(--accent-primary)] hover:bg-[var(--accent-primary)]/10"
      style={{
        borderColor: 'var(--border-subtle)',
        color: 'var(--text-secondary)',
      }}
    >
      <Sparkles className="w-3 h-3 opacity-50 group-hover:opacity-100" />
      {label}
    </button>
  )
}

function FormulaDisplay({
  formula,
  description,
  confidence,
  onCopy,
}: {
  formula: string
  description: string
  confidence: number
  onCopy: () => void
}) {
  const [copied, setCopied] = useState(false)

  const handleCopy = () => {
    onCopy()
    setCopied(true)
    setTimeout(() => setCopied(false), 1500)
  }

  return (
    <div
      className="rounded-lg border p-3"
      style={{
        borderColor: 'var(--border-subtle)',
        background: 'var(--bg-elevated)',
      }}
    >
      <div className="flex items-center justify-between">
        <span
          className="text-[10px] font-medium uppercase tracking-wider"
          style={{ color: 'var(--text-muted)' }}
        >
          Suggested Formula
        </span>
        <div className="flex items-center gap-2">
          <span className="text-[10px] tabular-nums" style={{ color: 'var(--text-muted)' }}>
            {Math.round(confidence * 100)}% match
          </span>
          <button
            onClick={handleCopy}
            className="rounded p-1 transition-colors hover:bg-[var(--bg-surface)]"
            aria-label={copied ? 'Copied' : 'Copy formula'}
          >
            {copied ? (
              <Check className="w-3 h-3 text-emerald-400" />
            ) : (
              <Copy className="w-3 h-3" style={{ color: 'var(--text-muted)' }} />
            )}
          </button>
        </div>
      </div>
      <code
        className="mt-1.5 block font-mono text-xs font-medium"
        style={{ color: 'var(--accent-primary)' }}
      >
        {formula}
      </code>
      <p className="mt-1 text-[11px]" style={{ color: 'var(--text-muted)' }}>
        {description}
      </p>
    </div>
  )
}

// ─── Main Component ─────────────────────────────────────────────────────────

export function CopilotSidebar({ gl, budget, className }: CopilotSidebarProps) {
  const { isOpen, activeTab, toggle, close, setActiveTab } = useCopilotSidebar()
  const location = useLocation()
  const scrollRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const [messages, setMessages] = useState<CopilotMessage[]>([])
  const [inputValue, setInputValue] = useState('')
  const [isProcessing, setIsProcessing] = useState(false)
  const [formulaResult, setFormulaResult] = useState<ReturnType<
    typeof AICopilotEngine.suggestFormula
  > | null>(null)

  // ── Context & Alerts ────────────────────────────────────────────────────

  const pageContext = useMemo(() => getContextForPath(location.pathname), [location.pathname])

  const alerts = useMemo(
    () => generateAlerts(gl, budget, pageContext.alertThreshold),
    [gl, budget, pageContext.alertThreshold]
  )

  const highAlertCount = useMemo(() => alerts.filter((a) => a.severity === 'high').length, [alerts])

  // ── Welcome message ─────────────────────────────────────────────────────

  useEffect(() => {
    if (messages.length === 0) {
      setMessages([
        {
          id: 'welcome',
          role: 'assistant',
          content: `I'm your financial copilot. I can help with formulas, variance analysis, and data insights. You're on the **${pageContext.label}** page — try one of the suggestions below.`,
          timestamp: new Date(),
        },
      ])
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  // ── Auto-scroll ─────────────────────────────────────────────────────────

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight
    }
  }, [messages])

  // ── Focus input on open ─────────────────────────────────────────────────

  useEffect(() => {
    if (isOpen && inputRef.current) {
      const timer = setTimeout(() => inputRef.current?.focus(), 200)
      return () => clearTimeout(timer)
    }
  }, [isOpen])

  // ── Keyboard shortcut ───────────────────────────────────────────────────

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) close()
      if ((e.metaKey || e.ctrlKey) && e.key === 'j') {
        e.preventDefault()
        toggle()
      }
    }
    document.addEventListener('keydown', handler)
    return () => document.removeEventListener('keydown', handler)
  }, [isOpen, close, toggle])

  // ── Message handling ─────────────────────────────────────────────────────

  const sendMessage = useCallback(
    (text: string) => {
      if (!text.trim() || isProcessing) return

      const userMsg: CopilotMessage = {
        id: nextId('user'),
        role: 'user',
        content: text.trim(),
        timestamp: new Date(),
      }
      setMessages((prev) => [...prev, userMsg])
      setInputValue('')
      setIsProcessing(true)

      // Check for formula-like input
      const formulaSuggestion = AICopilotEngine.suggestFormula(text)
      if (formulaSuggestion.confidence > 0) {
        setFormulaResult(formulaSuggestion)
      }

      setTimeout(() => {
        try {
          const answer = FinanceCopilotEngine.answer(text, { gl, budget })
          const assistantMsg: CopilotMessage = {
            id: nextId('assistant'),
            role: 'assistant',
            content: answer.answer,
            timestamp: new Date(),
            confidence: answer.confidence,
            sources: answer.sources,
            chartType: answer.chartType,
            formula: formulaSuggestion.confidence > 0 ? formulaSuggestion.formula : undefined,
          }
          setMessages((prev) => [...prev, assistantMsg])
        } catch {
          setMessages((prev) => [
            ...prev,
            {
              id: nextId('error'),
              role: 'assistant',
              content:
                'I could not process that. Try rephrasing or use one of the suggested prompts.',
              timestamp: new Date(),
            },
          ])
        } finally {
          setIsProcessing(false)
        }
      }, 200)
    },
    [gl, budget, isProcessing]
  )

  const handleSuggestionClick = useCallback(
    (suggestion: string) => {
      setInputValue(suggestion)
      sendMessage(suggestion)
    },
    [sendMessage]
  )

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault()
        sendMessage(inputValue)
      }
    },
    [inputValue, sendMessage]
  )

  // ── Render ──────────────────────────────────────────────────────────────

  const tabs = [
    { id: 'chat' as const, label: 'Chat', icon: MessageSquare },
    { id: 'alerts' as const, label: 'Alerts', icon: AlertTriangle, badge: highAlertCount },
    { id: 'suggestions' as const, label: 'Insights', icon: Lightbulb },
  ]

  return (
    <>
      {/* ── Floating trigger button ──────────────────────────────────────── */}
      {!isOpen && (
        <button
          onClick={toggle}
          className={cn(
            'fixed right-4 bottom-4 z-50 flex h-12 w-12 items-center justify-center rounded-full shadow-lg transition-all hover:scale-105',
            'bg-[var(--accent-primary)] text-white',
            className
          )}
          aria-label="Open AI Copilot (Ctrl+J)"
          title="AI Copilot (Ctrl+J)"
        >
          <Brain className="h-5 w-5" />
          {highAlertCount > 0 && (
            <span className="absolute -right-1 -top-1 flex h-5 w-5 items-center justify-center rounded-full bg-red-500 text-[10px] font-bold text-white">
              {highAlertCount}
            </span>
          )}
        </button>
      )}

      {/* ── Backdrop (mobile) ────────────────────────────────────────────── */}
      {isOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/40 md:hidden"
          onClick={close}
          aria-hidden="true"
        />
      )}

      {/* ── Sidebar panel ────────────────────────────────────────────────── */}
      <aside
        className={cn(
          'fixed right-0 top-0 z-50 flex h-full flex-col border-l shadow-2xl transition-transform duration-300',
          isOpen ? 'translate-x-0' : 'translate-x-full',
          'w-full sm:w-[380px] md:w-[400px]',
          className
        )}
        style={{
          background: 'var(--bg-surface)',
          borderColor: 'var(--border-subtle)',
        }}
        role="complementary"
        aria-label="AI Financial Copilot"
      >
        {/* Header */}
        <div
          className="flex h-14 items-center justify-between border-b px-4"
          style={{ borderColor: 'var(--border-subtle)' }}
        >
          <div className="flex items-center gap-2.5">
            <div
              className="flex h-7 w-7 items-center justify-center rounded-lg"
              style={{ background: 'var(--accent-primary)', opacity: 0.9 }}
            >
              <Brain className="h-4 w-4 text-white" />
            </div>
            <div>
              <h2 className="text-sm font-semibold" style={{ color: 'var(--text-primary)' }}>
                AI Copilot
              </h2>
              <p className="text-[10px]" style={{ color: 'var(--text-muted)' }}>
                {pageContext.label} context
              </p>
            </div>
          </div>
          <div className="flex items-center gap-1">
            <kbd
              className="hidden rounded border px-1.5 py-0.5 text-[10px] font-medium md:inline-block"
              style={{
                borderColor: 'var(--border-subtle)',
                color: 'var(--text-muted)',
              }}
            >
              ⌘J
            </kbd>
            <button
              onClick={close}
              className="rounded-md p-1.5 transition-colors hover:bg-[var(--bg-elevated)]"
              style={{ color: 'var(--text-muted)' }}
              aria-label="Close copilot"
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>

        {/* Tab bar */}
        <div
          className="flex border-b px-2"
          style={{ borderColor: 'var(--border-subtle)' }}
          role="tablist"
        >
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={cn(
                'relative flex items-center gap-1.5 px-3 py-2.5 text-xs font-medium transition-colors',
                activeTab === tab.id
                  ? 'text-[var(--accent-primary)]'
                  : 'text-[var(--text-muted)] hover:text-[var(--text-secondary)]'
              )}
              role="tab"
              aria-selected={activeTab === tab.id}
            >
              <tab.icon className="w-3.5 h-3.5" />
              {tab.label}
              {tab.badge && tab.badge > 0 && (
                <span className="ml-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-red-500 px-1 text-[10px] font-bold text-white">
                  {tab.badge}
                </span>
              )}
              {activeTab === tab.id && (
                <div
                  className="absolute bottom-0 left-2 right-2 h-0.5 rounded-full"
                  style={{ background: 'var(--accent-primary)' }}
                />
              )}
            </button>
          ))}
        </div>

        {/* Content area */}
        <div className="flex-1 overflow-hidden">
          {/* ── Chat Tab ─────────────────────────────────────────────────── */}
          {activeTab === 'chat' && (
            <div className="flex h-full flex-col">
              <div
                ref={scrollRef}
                className="flex-1 overflow-y-auto px-4 py-3"
                role="log"
                aria-live="polite"
                aria-label="Copilot messages"
              >
                <div className="space-y-3">
                  {messages.map((msg) => (
                    <div
                      key={msg.id}
                      className={cn(
                        'flex gap-2.5',
                        msg.role === 'user' ? 'justify-end' : 'justify-start'
                      )}
                    >
                      {msg.role === 'assistant' && (
                        <div
                          className="flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full"
                          style={{ background: 'var(--accent-primary)', opacity: 0.15 }}
                        >
                          <Zap className="h-3 w-3" style={{ color: 'var(--accent-primary)' }} />
                        </div>
                      )}
                      <div
                        className={cn(
                          'max-w-[85%] rounded-xl px-3 py-2 text-xs leading-relaxed',
                          msg.role === 'user'
                            ? 'rounded-tr-sm bg-[var(--accent-primary)] text-white'
                            : 'rounded-tl-sm'
                        )}
                        style={
                          msg.role === 'assistant'
                            ? {
                                background: 'var(--bg-elevated)',
                                color: 'var(--text-primary)',
                              }
                            : undefined
                        }
                      >
                        <p className="whitespace-pre-wrap">{msg.content}</p>

                        {/* Formula display */}
                        {msg.formula && (
                          <div className="mt-2">
                            <FormulaDisplay
                              formula={msg.formula}
                              description={AICopilotEngine.explainFormula(msg.formula)}
                              confidence={msg.confidence ?? 0.85}
                              onCopy={() => navigator.clipboard.writeText(msg.formula!)}
                            />
                          </div>
                        )}

                        {/* Metadata */}
                        {msg.role === 'assistant' && (msg.confidence || msg.sources?.length) && (
                          <div
                            className="mt-1.5 flex flex-wrap items-center gap-2 border-t pt-1.5"
                            style={{ borderColor: 'var(--border-subtle)' }}
                          >
                            {msg.confidence && msg.confidence > 0 && (
                              <span
                                className="text-[10px] tabular-nums"
                                style={{ color: 'var(--text-muted)' }}
                              >
                                {Math.round(msg.confidence * 100)}% confident
                              </span>
                            )}
                            {msg.sources?.map((src) => (
                              <span
                                key={src}
                                className="rounded-full bg-[var(--bg-surface)] px-2 py-0.5 text-[10px]"
                                style={{ color: 'var(--text-muted)' }}
                              >
                                {src}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}

                  {/* Processing indicator */}
                  {isProcessing && (
                    <div className="flex items-center gap-2 px-1">
                      <div
                        className="flex h-6 w-6 items-center justify-center rounded-full"
                        style={{ background: 'var(--accent-primary)', opacity: 0.15 }}
                      >
                        <Loader2
                          className="h-3 w-3 animate-spin"
                          style={{ color: 'var(--accent-primary)' }}
                        />
                      </div>
                      <span className="text-xs" style={{ color: 'var(--text-muted)' }}>
                        Analyzing...
                      </span>
                    </div>
                  )}
                </div>
              </div>

              {/* Suggestions */}
              <div
                className="flex flex-wrap gap-1.5 border-t px-4 py-2.5"
                style={{ borderColor: 'var(--border-subtle)' }}
              >
                {pageContext.suggestions.map((s) => (
                  <SuggestionChip
                    key={s}
                    label={s.length > 35 ? s.slice(0, 35) + '…' : s}
                    onClick={() => handleSuggestionClick(s)}
                  />
                ))}
              </div>

              {/* Input */}
              <div className="border-t px-4 py-3" style={{ borderColor: 'var(--border-subtle)' }}>
                <div
                  className="flex items-center gap-2 rounded-lg border px-3 py-2 transition-colors focus-within:border-[var(--accent-primary)]"
                  style={{
                    borderColor: 'var(--border-subtle)',
                    background: 'var(--bg-elevated)',
                  }}
                >
                  <MessageSquare
                    className="h-3.5 w-3.5 flex-shrink-0"
                    style={{ color: 'var(--text-muted)' }}
                  />
                  <input
                    ref={inputRef}
                    type="text"
                    value={inputValue}
                    onChange={(e) => setInputValue(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Ask about revenue, formulas, variances..."
                    className="flex-1 bg-transparent text-xs outline-none placeholder:text-[var(--text-muted)]"
                    style={{ color: 'var(--text-primary)' }}
                    disabled={isProcessing}
                    aria-label="Ask the AI copilot"
                  />
                  <button
                    onClick={() => sendMessage(inputValue)}
                    disabled={!inputValue.trim() || isProcessing}
                    className="flex-shrink-0 rounded-md p-1 transition-colors hover:bg-[var(--bg-surface)] disabled:opacity-30"
                    style={{ color: 'var(--accent-primary)' }}
                    aria-label="Send message"
                  >
                    <Send className="h-3.5 w-3.5" />
                  </button>
                </div>
                <p
                  className="mt-1.5 text-center text-[10px]"
