import { useState, useCallback, useEffect, useRef } from 'react'

import { FileDropZone } from '@/components/ui/FileDropZone'
import { Button } from '@/components/ui/Button'
import {
  ImportEngine,
  type ImportValidationResult,
  type ImportProgress,
  type ImportSnapshot,
} from '@/engines/ImportEngine'
import { CheckCircle2, AlertCircle, RotateCcw, FileText } from 'lucide-react'
import { cn } from '@/utils/cn'

export interface FileUploaderProps {
  onImport?: (data: Record<string, unknown>[], columns: string[]) => void
  requiredColumns?: string[]
  numericColumns?: string[]
  dateColumns?: string[]
  maxRows?: number
}

export function FileUploader({
  onImport,
  requiredColumns,
  numericColumns,
  dateColumns,
  maxRows,
}: FileUploaderProps) {
  const engineRef = useRef(new ImportEngine())
  const [progress, setProgress] = useState<ImportProgress>({
    status: 'idle',
    percent: 0,
    message: '',
  })
  const [result, setResult] = useState<ImportValidationResult | null>(null)
  const [snapshot, setSnapshot] = useState<ImportSnapshot | null>(null)
  const [history, setHistory] = useState<ImportSnapshot[]>([])

  useEffect(() => {
    const engine = engineRef.current
    const unsub = engine.onProgress(setProgress)
    setHistory(engine.getSnapshots())
    return unsub
  }, [])

  const handleFile = useCallback(
    async (file: File) => {
      setResult(null)
      setSnapshot(null)

      const engine = engineRef.current
      const { result: importResult, snapshot: importSnapshot } = await engine.importFile(file, {
        requiredColumns,
        numericColumns,
        dateColumns,
        maxRows,
      })

      setResult(importResult)
      setSnapshot(importSnapshot)
      setHistory(engine.getSnapshots())
    },
    [requiredColumns, numericColumns, dateColumns, maxRows]
  )

  const handleConfirm = useCallback(() => {
    if (result && result.valid && onImport) {
      onImport(result.preview, result.columns)
      if (snapshot) {
        snapshot.applied = true
        setHistory(engineRef.current.getSnapshots())
      }
    }
  }, [result, snapshot, onImport])

  const handleRollback = useCallback((snapshotId: string) => {
    const engine = engineRef.current
    engine.rollback(snapshotId)
    setHistory(engine.getSnapshots())
    setResult(null)
    setSnapshot(null)
  }, [])

  const hasErrors = result ? result.errors.length > 0 : false
  const hasWarnings = result ? result.warnings.length > 0 : false

  return (
    <div className="max-w-2xl mx-auto space-y-4">
      {/* Drop Zone */}
      <FileDropZone onFile={handleFile} accept=".csv,.xlsx,.xls,.json" />

      {/* Progress Bar */}
      {progress.status !== 'idle' &&
        progress.status !== 'complete' &&
        progress.status !== 'error' && (
          <div className="space-y-2">
            <div className="flex justify-between text-xs text-[var(--text-secondary)]">
              <span>{progress.message}</span>
              <span>{progress.percent}%</span>
            </div>
            <div className="h-2 bg-[var(--bg-surface)] rounded-full overflow-hidden">
              <div
                className="h-full bg-[var(--accent-primary)] transition-all duration-300"
                style={{ width: `${progress.percent}%` }}
              />
            </div>
          </div>
        )}

      {/* Error Display */}
      {progress.status === 'error' && (
        <div className="flex items-start gap-3 p-4 bg-red-500/10 border border-red-500/30 rounded-lg">
          <AlertCircle className="h-5 w-5 text-red-500 mt-0.5 shrink-0" />
          <div>
            <p className="text-sm font-bold text-red-500">Import Failed</p>
            <p className="text-xs text-red-400 mt-1">{progress.message}</p>
          </div>
        </div>
      )}

      {/* Validation Result Summary */}
      {result && (
        <div
          className={cn(
            'p-4 rounded-lg border',
            hasErrors
              ? 'bg-red-500/10 border-red-500/30'
              : hasWarnings
                ? 'bg-yellow-500/10 border-yellow-500/30'
                : 'bg-green-500/10 border-green-500/30'
          )}
        >
          <div className="flex items-center gap-2 mb-2">
            {hasErrors ? (
              <AlertCircle className="h-5 w-5 text-red-500" />
            ) : hasWarnings ? (
              <AlertCircle className="h-5 w-5 text-yellow-500" />
            ) : (
              <CheckCircle2 className="h-5 w-5 text-green-500" />
            )}
            <span className="font-bold text-sm">
              {result.rowCount} rows, {result.columnCount} columns
            </span>
          </div>

          {/* Errors */}
          {result.errors.length > 0 && (
            <div className="mt-2 space-y-1">
              {result.errors.slice(0, 5).map((err, i) => (
                <p key={i} className="text-xs text-red-400">
                  Row {err.row}: {err.message}
                </p>
              ))}
              {result.errors.length > 5 && (
                <p className="text-xs text-red-400">
                  ...and {result.errors.length - 5} more errors
                </p>
              )}
            </div>
          )}

          {/* Warnings */}
          {result.warnings.length > 0 && (
            <div className="mt-2 space-y-1">
              {result.warnings.slice(0, 3).map((warn, i) => (
                <p key={i} className="text-xs text-yellow-400">
                  Row {warn.row}: {warn.message}
                </p>
              ))}
              {result.warnings.length > 3 && (
                <p className="text-xs text-yellow-400">
                  ...and {result.warnings.length - 3} more warnings
                </p>
              )}
            </div>
          )}

          {/* Confirm Button */}
          <div className="mt-3 flex gap-2">
            <Button onClick={handleConfirm} disabled={hasErrors} size="sm">
              {hasErrors ? 'Fix Errors to Continue' : 'Confirm & Import'}
            </Button>
          </div>
        </div>
      )}

      {/* Import History (Rollback) */}
      {history.length > 0 && (
        <div className="p-4 rounded-lg border border-[var(--border-subtle)] bg-[var(--bg-surface)]">
          <h4 className="text-xs font-bold text-[var(--text-secondary)] uppercase tracking-wider mb-2">
            Import History
          </h4>
          <div className="space-y-2">
            {history
              .slice(-5)
              .reverse()
              .map((snap) => (
                <div key={snap.id} className="flex items-center justify-between text-xs">
                  <div className="flex items-center gap-2">
                    <FileText className="h-3.5 w-3.5 text-[var(--text-secondary)]" />
                    <span className="text-[var(--text-primary)]">{snap.fileName}</span>
                    <span className="text-[var(--text-secondary)]">
                      {snap.rowCount} rows &middot; {snap.columns.length} cols
                    </span>
                    {snap.applied && <span className="text-green-500 font-bold">Applied</span>}
                  </div>
                  {!snap.applied && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleRollback(snap.id)}
                      className="h-6 px-2"
                    >
                      <RotateCcw className="h-3 w-3 mr-1" />
                      Rollback
                    </Button>
                  )}
                </div>
              ))}
          </div>
        </div>
      )}
    </div>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import type { GridApi } from 'ag-grid-community'
import { cn } from '@/utils/cn'
import { Search, Replace, ChevronDown, ChevronUp, X, CaseSensitive, Regex } from 'lucide-react'

interface FindReplaceDialogProps {
  gridApi: GridApi | null
  isOpen: boolean
  onClose: () => void
}

interface MatchResult {
  rowIndex: number
  colId: string
  value: string
}

export function FindReplaceDialog({ gridApi, isOpen, onClose }: FindReplaceDialogProps) {
  const [findText, setFindText] = useState('')
  const [replaceText, setReplaceText] = useState('')
  const [matchCase, setMatchCase] = useState(false)
  const [useRegex, setUseRegex] = useState(false)
  const [searchInFormulas, setSearchInFormulas] = useState(false)
  const [matches, setMatches] = useState<MatchResult[]>([])
  const [currentMatchIdx, setCurrentMatchIdx] = useState(-1)
  const [replaceAllFeedback, setReplaceAllFeedback] = useState<string | null>(null)
  const findInputRef = useRef<HTMLInputElement>(null)

  // Focus input on open
  useEffect(() => {
    if (isOpen && findInputRef.current) {
      findInputRef.current.focus()
      findInputRef.current.select()
    }
  }, [isOpen])

  // Escape to close
  useEffect(() => {
    if (!isOpen) return
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    document.addEventListener('keydown', handler)
    return () => document.removeEventListener('keydown', handler)
  }, [isOpen, onClose])

  // Search for matches
  const handleFind = useCallback(() => {
    if (!gridApi || !findText) {
      setMatches([])
      setCurrentMatchIdx(-1)
      return
    }

    const results: MatchResult[] = []

    gridApi.forEachNode((node) => {
      if (!node.data) return
      const cols = gridApi.getColumns() ?? []
      for (const col of cols) {
        const colId = col.getColId()
        const rawValue = node.data[colId]
        if (rawValue == null) continue

        let cellStr: string
        if (searchInFormulas && typeof rawValue === 'string' && rawValue.startsWith('=')) {
          cellStr = rawValue
        } else {
          cellStr = String(rawValue)
        }

        const compareStr = matchCase ? cellStr : cellStr.toLowerCase()

        let isMatch = false
        if (useRegex) {
          try {
            const flags = matchCase ? 'g' : 'gi'
            const regex = new RegExp(findText, flags)
            isMatch = regex.test(cellStr)
          } catch {
            // Invalid regex — fall back to literal
            isMatch = compareStr.includes(matchCase ? findText : findText.toLowerCase())
          }
        } else {
          isMatch = compareStr.includes(matchCase ? findText : findText.toLowerCase())
        }

        if (isMatch) {
          results.push({
            rowIndex: node.rowIndex!,
            colId,
            value: cellStr,
          })
        }
      }
    })

    setMatches(results)
    setCurrentMatchIdx(results.length > 0 ? 0 : -1)

    // Navigate to first match
    if (results.length > 0) {
      navigateToMatch(results[0])
    }
  }, [gridApi, findText, matchCase, useRegex, searchInFormulas])

  const navigateToMatch = useCallback(
    (match: MatchResult) => {
      if (!gridApi) return
      gridApi.setFocusedCell(match.rowIndex, match.colId)
      gridApi.ensureIndexVisible(match.rowIndex, 'middle')
    },
    [gridApi]
  )

  const goToNext = useCallback(() => {
    if (matches.length === 0) return
    const next = (currentMatchIdx + 1) % matches.length
    setCurrentMatchIdx(next)
    navigateToMatch(matches[next])
  }, [matches, currentMatchIdx, navigateToMatch])

  const goToPrev = useCallback(() => {
    if (matches.length === 0) return
    const prev = (currentMatchIdx - 1 + matches.length) % matches.length
    setCurrentMatchIdx(prev)
    navigateToMatch(matches[prev])
  }, [matches, currentMatchIdx, navigateToMatch])

  // Replace current match
  const handleReplace = useCallback(() => {
    if (!gridApi || currentMatchIdx < 0 || !matches[currentMatchIdx]) return
    const match = matches[currentMatchIdx]
    const node = gridApi.getDisplayedRowAtIndex(match.rowIndex)
    if (node?.data) {
      const oldValue = String(node.data[match.colId] ?? '')
      let newValue: string
      if (useRegex) {
        try {
          const flags = matchCase ? 'g' : 'gi'
          const regex = new RegExp(findText, flags)
          newValue = oldValue.replace(regex, replaceText)
        } catch {
          newValue = oldValue.split(findText).join(replaceText)
        }
      } else {
        const idx = matchCase
          ? oldValue.indexOf(findText)
          : oldValue.toLowerCase().indexOf(findText)
        if (idx >= 0) {
          newValue =
            oldValue.substring(0, idx) + replaceText + oldValue.substring(idx + findText.length)
        } else {
          newValue = oldValue
        }
      }
      node.setDataValue(match.colId, newValue)
    }
    // Move to next match
    goToNext()
    // Re-search to update match positions
    handleFind()
  }, [
    gridApi,
    currentMatchIdx,
    matches,
    findText,
    replaceText,
    matchCase,
    useRegex,
    goToNext,
    handleFind,
  ])

  // Replace all matches
  const handleReplaceAll = useCallback(() => {
    if (!gridApi || !findText) return
    let count = 0

    gridApi.forEachNode((node) => {
      if (!node.data) return
      const cols = gridApi.getColumns() ?? []
      for (const col of cols) {
        const colId = col.getColId()
        const rawValue = node.data[colId]
        if (rawValue == null) continue

        const cellStr = String(rawValue)
        const compareStr = matchCase ? cellStr : cellStr.toLowerCase()

        let isMatch = false
        if (useRegex) {
          try {
            const flags = matchCase ? 'g' : 'gi'
            const regex = new RegExp(findText, flags)
            isMatch = regex.test(cellStr)
          } catch {
            isMatch = compareStr.includes(matchCase ? findText : findText.toLowerCase())
          }
        } else {
          isMatch = compareStr.includes(matchCase ? findText : findText.toLowerCase())
        }

        if (isMatch) {
          let newValue: string
          if (useRegex) {
            try {
              const flags = matchCase ? 'g' : 'gi'
              const regex = new RegExp(findText, flags)
              newValue = cellStr.replace(regex, replaceText)
            } catch {
              newValue = cellStr.split(findText).join(replaceText)
            }
          } else {
            if (matchCase) {
              newValue = cellStr.split(findText).join(replaceText)
            } else {
              const regex = new RegExp(findText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi')
              newValue = cellStr.replace(regex, replaceText)
            }
          }
          node.setDataValue(colId, newValue)
          count++
        }
      }
    })

    setReplaceAllFeedback(`Replaced ${count} occurrence${count !== 1 ? 's' : ''}`)
    setTimeout(() => setReplaceAllFeedback(null), 3000)
    handleFind()
  }, [gridApi, findText, replaceText, matchCase, useRegex, handleFind])

  // Enter to find next
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault()
        if (e.shiftKey) {
          goToPrev()
        } else if (currentMatchIdx >= 0 && matches.length > 0) {
          goToNext()
        } else {
          handleFind()
        }
      }
    },
    [goToNext, goToPrev, handleFind, currentMatchIdx, matches.length]
  )

  if (!isOpen) return null

  return (
    <div
      className="fixed top-4 right-4 z-50 w-[420px] bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-lg shadow-xl"
      role="dialog"
      aria-label="Find and Replace"
      onKeyDown={handleKeyDown}
    >
      {/* Header */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-[var(--border-subtle)]">
        <span className="text-sm font-semibold text-[var(--text-primary)]">Find and Replace</span>
        <button
          onClick={onClose}
          className="p-1 rounded hover:bg-[var(--bg-muted)] transition-colors"
          aria-label="Close"
        >
          <X className="w-4 h-4" />
        </button>
      </div>

      {/* Find row */}
      <div className="px-3 pt-3 pb-1">
        <div className="flex items-center gap-2">
          <Search className="w-4 h-4 text-[var(--text-tertiary)] flex-shrink-0" />
          <input
            ref={findInputRef}
            type="text"
            value={findText}
            onChange={(e) => setFindText(e.target.value)}
            placeholder="Find..."
            className="flex-1 px-2 py-1.5 text-sm border border-[var(--border-subtle)] rounded bg-[var(--bg-muted)] focus:outline-none focus:ring-2 focus:ring-blue-500/30"
            aria-label="Find text"
          />
          <div className="flex items-center gap-1">
            <button
              onClick={() => setMatchCase(!matchCase)}
              className={cn(
                'p-1.5 rounded transition-colors',
                matchCase
                  ? 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300'
                  : 'hover:bg-[var(--bg-muted)] text-[var(--text-tertiary)]'
              )}
              aria-label="Match case"
              title="Match Case"
            >
              <CaseSensitive className="w-4 h-4" />
            </button>
            <button
              onClick={() => setUseRegex(!useRegex)}
              className={cn(
                'p-1.5 rounded transition-colors',
                useRegex
                  ? 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300'
                  : 'hover:bg-[var(--bg-muted)] text-[var(--text-tertiary)]'
              )}
              aria-label="Use regex"
              title="Regular Expression"
            >
              <Regex className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Replace row */}
      <div className="px-3 pb-2">
        <div className="flex items-center gap-2">
          <Replace className="w-4 h-4 text-[var(--text-tertiary)] flex-shrink-0" />
          <input
            type="text"
            value={replaceText}
            onChange={(e) => setReplaceText(e.target.value)}
            placeholder="Replace..."
            className="flex-1 px-2 py-1.5 text-sm border border-[var(--border-subtle)] rounded bg-[var(--bg-muted)] focus:outline-none focus:ring-2 focus:ring-blue-500/30"
            aria-label="Replace text"
          />
          <label className="flex items-center gap-1.5 text-xs text-[var(--text-tertiary)] cursor-pointer select-none">
            <input
              type="checkbox"
              checked={searchInFormulas}
              onChange={(e) => setSearchInFormulas(e.target.checked)}
              className="rounded"
            />
            Formulas
          </label>
        </div>
      </div>

      {/* Actions row */}
      <div className="flex items-center justify-between px-3 py-2 border-t border-[var(--border-subtle)] bg-[var(--bg-muted)] rounded-b-lg">
        <div className="flex items-center gap-1">
          <button
            onClick={goToPrev}
            disabled={matches.length === 0}
            className="p-1.5 rounded hover:bg-[var(--bg-surface)] disabled:opacity-30 transition-colors"
            aria-label="Previous match"
            title="Previous (Shift+Enter)"
          >
            <ChevronUp className="w-4 h-4" />
          </button>
          <button
            onClick={goToNext}
            disabled={matches.length === 0}
            className="p-1.5 rounded hover:bg-[var(--bg-surface)] disabled:opacity-30 transition-colors"
            aria-label="Next match"
            title="Next (Enter)"
          >
            <ChevronDown className="w-4 h-4" />
          </button>
          <span className="ml-2 text-xs text-[var(--text-tertiary)]" aria-live="polite">
            {matches.length > 0
              ? `${currentMatchIdx + 1} of ${matches.length}`
              : findText
                ? 'No results'
                : ''}
          </span>
        </div>
        <div className="flex items-center gap-1.5">
          {replaceAllFeedback && (
            <span className="text-xs fin-positive mr-2" role="status">
              {replaceAllFeedback}
            </span>
          )}
          <button
            onClick={handleReplace}
            disabled={currentMatchIdx < 0}
            className="px-2.5 py-1 text-xs font-medium rounded border border-[var(--border-subtle)] hover:bg-[var(--bg-surface)] disabled:opacity-30 transition-colors"
          >
            Replace
          </button>
          <button
            onClick={handleReplaceAll}
            disabled={matches.length === 0}
            className="px-2.5 py-1 text-xs font-medium rounded bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-30 transition-colors"
          >
            Replace All
          </button>
        </div>
      </div>
    </div>
  )
}

import { useMemo, useState } from 'react'
import { Plus, Trash2, ArrowRight, AlertCircle } from 'lucide-react'
import { Button } from '@/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { useDriverStore } from '@/store/driverStore'
import type { Driver, CascadeRule, CascadeType, ImpactType } from '@/engines/DriverCascadeEngine'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const TARGET_CUBES = ['Budget', 'Forecast', 'Scenario', 'Actual'] as const
const TARGET_MEASURES = ['amount', 'quantity', 'rate', 'hours', 'units'] as const
const CASCADE_TYPES: CascadeType[] = ['direct', 'weighted', 'formula']
const IMPACT_TYPES: ImpactType[] = ['additive', 'multiplicative', 'replacement']

const CASCADE_TYPE_LABELS: Record<CascadeType, string> = {
  direct: 'Direct — proportional to driver change',
  weighted: 'Weighted — scaled by a weight factor',
  formula: 'Formula — custom calculation',
}

const IMPACT_TYPE_LABELS: Record<ImpactType, string> = {
  additive: 'Additive — adds delta to target',
  multiplicative: 'Multiplicative — scales target by ratio',
  replacement: 'Replacement — overwrites target value',
}

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

export interface CascadeRuleBuilderProps {
  driver: Driver
  onRuleAdded?: (rule: CascadeRule) => void
  onRuleRemoved?: (ruleId: string) => void
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function CascadeRuleBuilder({
  driver,
  onRuleAdded,
  onRuleRemoved,
}: CascadeRuleBuilderProps) {
  const { addRule, removeRule, getRulesForDriver } = useDriverStore()
  const rules = useMemo(() => getRulesForDriver(driver.id), [driver.id, getRulesForDriver])

  const [isAdding, setIsAdding] = useState(false)
  const [targetCube, setTargetCube] = useState<string>('Budget')
  const [targetAccount, setTargetAccount] = useState('')
  const [targetMeasure, setTargetMeasure] = useState('amount')
  const [cascadeType, setCascadeType] = useState<CascadeType>('direct')
  const [impactType, setImpactType] = useState<ImpactType>('multiplicative')
  const [weight, setWeight] = useState(1)
  const [formula, setFormula] = useState('')
  const [description, setDescription] = useState('')

  const handleAdd = () => {
    if (!targetAccount.trim()) return

    const rule = addRule({
      driverId: driver.id,
      targetCube,
      targetCoords: { Account: targetAccount },
      targetMeasure,
      cascadeType,
      impactType,
      weight,
      formula: cascadeType === 'formula' ? formula : undefined,
      description: description || undefined,
    })

    onRuleAdded?.(rule)

    // Reset form
    setTargetAccount('')
    setFormula('')
    setDescription('')
    setIsAdding(false)
  }

  const handleRemove = (ruleId: string) => {
    removeRule(ruleId)
    onRuleRemoved?.(ruleId)
  }

  const formatWeight = (w: number): string => {
    if (w >= 1) return `${w}x`
    return `${(w * 100).toFixed(0)}%`
  }

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-semibold" style={{ color: 'var(--text-primary)' }}>
          Cascade Rules
        </h4>
        <Button size="sm" variant="ghost" onClick={() => setIsAdding(!isAdding)}>
          <Plus className="w-3 h-3 mr-1" />
          Add Rule
        </Button>
      </div>

      {/* Existing Rules */}
      {rules.length > 0 && (
        <div className="space-y-2">
          {rules.map((rule) => (
            <div
              key={rule.id}
              className="flex items-center gap-2 p-2 rounded-md text-xs"
              style={{ background: 'var(--bg-secondary)' }}
            >
              <ArrowRight className="w-3 h-3 flex-shrink-0" style={{ color: 'var(--accent)' }} />
              <div className="flex-1 min-w-0">
                <div className="font-medium truncate" style={{ color: 'var(--text-primary)' }}>
                  {driver.name}
                </div>
                <div className="truncate" style={{ color: 'var(--text-secondary)' }}>
                  → {rule.targetCube} / {rule.targetCoords.Account} / {rule.targetMeasure}
                </div>
                <div className="truncate" style={{ color: 'var(--text-secondary)' }}>
                  {CASCADE_TYPE_LABELS[rule.cascadeType]} | Weight: {formatWeight(rule.weight)}
                </div>
                {rule.description && (
                  <div className="truncate mt-1" style={{ color: 'var(--text-secondary)' }}>
                    {rule.description}
                  </div>
                )}
              </div>
              <button
                onClick={() => handleRemove(rule.id)}
                className="p-1 rounded hover:opacity-80"
                style={{ color: 'var(--text-secondary)' }}
                aria-label={`Remove rule targeting ${rule.targetCoords.Account}`}
              >
                <Trash2 className="w-3 h-3" />
              </button>
            </div>
          ))}
        </div>
      )}

      {rules.length === 0 && !isAdding && (
        <div className="text-center py-3 text-xs" style={{ color: 'var(--text-secondary)' }}>
          No cascade rules defined. Add a rule to link this driver to budget cells.
        </div>
      )}

      {/* Add Rule Form */}
      {isAdding && (
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-xs">New Cascade Rule</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {/* Target Cube */}
            <div>
              <label
                className="text-xs font-medium block mb-1"
                style={{ color: 'var(--text-secondary)' }}
              >
                Target Cube
              </label>
              <select
                value={targetCube}
                onChange={(e) => setTargetCube(e.target.value)}
                className="w-full p-1.5 rounded text-sm border"
                style={{
                  background: 'var(--bg-primary)',
                  color: 'var(--text-primary)',
                  borderColor: 'var(--border)',
                }}
              >
                {TARGET_CUBES.map((cube) => (
                  <option key={cube} value={cube}>
                    {cube}
                  </option>
                ))}
              </select>
            </div>

            {/* Target Account */}
            <div>
              <label
                className="text-xs font-medium block mb-1"
                style={{ color: 'var(--text-secondary)' }}
              >
                Target Account
              </label>
              <input
                type="text"
                value={targetAccount}
                onChange={(e) => setTargetAccount(e.target.value)}
                placeholder="e.g. Account:Revenue"
                className="w-full p-1.5 rounded text-sm border"
                style={{
                  background: 'var(--bg-primary)',
                  color: 'var(--text-primary)',
                  borderColor: 'var(--border)',
                }}
              />
            </div>

            {/* Target Measure */}
            <div>
              <label
                className="text-xs font-medium block mb-1"
                style={{ color: 'var(--text-secondary)' }}
              >
                Target Measure
              </label>
              <select
                value={targetMeasure}
                onChange={(e) => setTargetMeasure(e.target.value)}
                className="w-full p-1.5 rounded text-sm border"
                style={{
                  background: 'var(--bg-primary)',
                  color: 'var(--text-primary)',
                  borderColor: 'var(--border)',
                }}
              >
                {TARGET_MEASURES.map((m) => (
                  <option key={m} value={m}>
                    {m}
                  </option>
                ))}
              </select>
            </div>

            {/* Cascade Type */}
            <div>
              <label
                className="text-xs font-medium block mb-1"
                style={{ color: 'var(--text-secondary)' }}
              >
                Cascade Type
              </label>
              <select
                value={cascadeType}
                onChange={(e) => setCascadeType(e.target.value as CascadeType)}
                className="w-full p-1.5 rounded text-sm border"
                style={{
                  background: 'var(--bg-primary)',
                  color: 'var(--text-primary)',
                  borderColor: 'var(--border)',
                }}
              >
                {CASCADE_TYPES.map((ct) => (
                  <option key={ct} value={ct}>
                    {CASCADE_TYPE_LABELS[ct]}
                  </option>
                ))}
              </select>
            </div>

            {/* Impact Type */}
            <div>
              <label
                className="text-xs font-medium block mb-1"
                style={{ color: 'var(--text-secondary)' }}
              >
                Impact Type
              </label>
              <select
                value={impactType}
                onChange={(e) => setImpactType(e.target.value as ImpactType)}
                className="w-full p-1.5 rounded text-sm border"
                style={{
                  background: 'var(--bg-primary)',
                  color: 'var(--text-primary)',
                  borderColor: 'var(--border)',
                }}
              >
                {IMPACT_TYPES.map((it) => (
                  <option key={it} value={it}>
                    {IMPACT_TYPE_LABELS[it]}
                  </option>
                ))}
              </select>
            </div>

            {/* Weight */}
            <div>
              <label
                className="text-xs font-medium block mb-1"
                style={{ color: 'var(--text-secondary)' }}
              >
                Weight: {formatWeight(weight)}
              </label>
              <input
                type="range"
                min={0}
                max={5}
                step={0.1}
                value={weight}
                onChange={(e) => setWeight(Number(e.target.value))}
                className="w-full"
              />
              <div
                className="flex justify-between text-xs"
                style={{ color: 'var(--text-secondary)' }}
              >
                <span>0</span>
                <span>5x</span>
              </div>
            </div>

            {/* Formula (only when cascadeType is formula) */}
            {cascadeType === 'formula' && (
              <div>
                <label
                  className="text-xs font-medium block mb-1"
                  style={{ color: 'var(--text-secondary)' }}
                >
                  Formula
                </label>
                <input
                  type="text"
                  value={formula}
                  onChange={(e) => setFormula(e.target.value)}
                  placeholder="e.g. x * 1000 + current * 0.5"
                  className="w-full p-1.5 rounded text-sm border font-mono"
                  style={{
                    background: 'var(--bg-primary)',
                    color: 'var(--text-primary)',
                    borderColor: 'var(--border)',
                  }}
                />
                <div
                  className="flex items-center gap-1 mt-1 text-xs"
                  style={{ color: 'var(--text-secondary)' }}
                >
                  <AlertCircle className="w-3 h-3" />
                  Variables: x (new driver), old_x (old driver), current (cell value)
                </div>
              </div>
            )}

            {/* Description */}
            <div>
              <label
                className="text-xs font-medium block mb-1"
                style={{ color: 'var(--text-secondary)' }}
              >
                Description (optional)
              </label>
              <input
                type="text"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="e.g. Revenue grows proportionally with growth rate"
                className="w-full p-1.5 rounded text-sm border"
                style={{
                  background: 'var(--bg-primary)',
                  color: 'var(--text-primary)',
                  borderColor: 'var(--border)',
                }}
              />
            </div>

            {/* Actions */}
            <div className="flex gap-2 pt-1">
              <Button
                size="sm"
                onClick={handleAdd}
                disabled={!targetAccount.trim()}
                className="flex-1"
              >
                Add Rule
              </Button>
              <Button size="sm" variant="outline" onClick={() => setIsAdding(false)}>
                Cancel
              </Button>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

