import { useCallback, useMemo, useState } from 'react';
import { Card } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import {
  ReportBookEngine,
  REPORT_TEMPLATE_PRESETS,
  type ReportBook,
  type ReportBookEntry,
  type Entity,
  type GenerationProgress,
} from '@/engines/ReportBookEngine';

// ---------------------------------------------------------------------------
// Mock data — replace with store selectors in production
// ---------------------------------------------------------------------------

const MOCK_ENTITIES: Entity[] = [
  { id: 'ent-1', name: 'Acme Corp (US)', currency: 'USD', parentId: null },
  { id: 'ent-2', name: 'Acme Europe (UK)', currency: 'GBP', parentId: 'ent-1' },
  { id: 'ent-3', name: 'Acme Asia (JP)', currency: 'JPY', parentId: 'ent-1' },
];

const PRESET_LIST = Object.values(REPORT_TEMPLATE_PRESETS);

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

interface PresetCardProps {
  preset: (typeof PRESET_LIST)[number];
  onAdd: (presetId: string, name: string) => void;
}

function PresetCard({ preset, onAdd }: PresetCardProps) {
  return (
    <button
      type="button"
      onClick={() => onAdd(preset.id, preset.name)}
      className="text-left w-full rounded-lg border border-slate-700 bg-slate-800/50 p-3 hover:border-blue-500 hover:bg-slate-800 transition-colors"
    >
      <p className="text-sm font-medium text-white">{preset.name}</p>
      <p className="text-xs text-slate-400 mt-1 line-clamp-2">{preset.description}</p>
    </button>
  );
}

interface EntryRowProps {
  entry: ReportBookEntry;
  entities: Entity[];
  onUpdate: (id: string, updates: Partial<ReportBookEntry>) => void;
  onRemove: (id: string) => void;
  onMoveUp: (id: string) => void;
  onMoveDown: (id: string) => void;
}

function EntryRow({ entry, entities, onUpdate, onRemove, onMoveUp, onMoveDown }: EntryRowProps) {
  return (
    <div className="flex items-start gap-3 rounded-lg border border-slate-700 bg-slate-800/30 p-3">
      {/* Drag handle / order controls */}
      <div className="flex flex-col gap-1 pt-1">
        <button
          type="button"
          onClick={() => onMoveUp(entry.id)}
          className="text-slate-500 hover:text-white text-xs"
          aria-label="Move up"
        >
          &#9650;
        </button>
        <span className="text-xs text-slate-500 text-center">{entry.order + 1}</span>
        <button
          type="button"
          onClick={() => onMoveDown(entry.id)}
          className="text-slate-500 hover:text-white text-xs"
          aria-label="Move down"
        >
          &#9660;
        </button>
      </div>

      {/* Report name + template */}
      <div className="flex-1 min-w-0 space-y-2">
        <input
          type="text"
          value={entry.reportName}
          onChange={(e) => onUpdate(entry.id, { reportName: e.target.value })}
          className="w-full bg-transparent border-b border-slate-600 text-white text-sm font-medium focus:border-blue-500 outline-none pb-1"
          placeholder="Report name"
        />
        <p className="text-xs text-slate-500">Template: {entry.templateId}</p>

        {/* Entity multi-select */}
        <div className="flex flex-wrap gap-1">
          {entities.map((entity) => (
            <button
              key={entity.id}
              type="button"
              onClick={() => {
                const next = entry.entityIds.includes(entity.id)
                  ? entry.entityIds.filter((id) => id !== entity.id)
                  : [...entry.entityIds, entity.id];
                onUpdate(entry.id, { entityIds: next });
              }}
              className={`text-xs px-2 py-0.5 rounded-full border transition-colors ${
                entry.entityIds.includes(entity.id)
                  ? 'bg-blue-600 border-blue-500 text-white'
                  : 'border-slate-600 text-slate-400 hover:border-slate-500'
              }`}
            >
              {entity.name}
            </button>
          ))}
        </div>

        {/* Variables */}
        {Object.keys(entry.variables).length > 0 && (
          <div className="flex flex-wrap gap-2">
            {Object.entries(entry.variables).map(([key, val]) => (
              <span key={key} className="text-xs text-slate-500">
                {`{${key}}`}:
                <input
                  type="text"
                  value={val}
                  onChange={(e) =>
                    onUpdate(entry.id, {
                      variables: { ...entry.variables, [key]: e.target.value },
                    })
                  }
                  className="ml-1 bg-transparent border-b border-slate-700 text-slate-300 w-20 text-xs focus:border-blue-500 outline-none"
                />
              </span>
            ))}
          </div>
        )}
      </div>

      {/* Actions */}
      <div className="flex items-center gap-2">
        <label className="flex items-center gap-1 text-xs text-slate-400">
          <input
            type="checkbox"
            checked={entry.enabled}
            onChange={(e) => onUpdate(entry.id, { enabled: e.target.checked })}
            className="rounded"
          />
          On
        </label>
        <button
          type="button"
          onClick={() => onRemove(entry.id)}
          className="text-red-400 hover:text-red-300 text-xs"
          aria-label="Remove entry"
        >
          &#10005;
        </button>
      </div>
    </div>
  );
}

interface ProgressBarProps {
  progress: GenerationProgress;
}

function ProgressBar({ progress }: ProgressBarProps) {
  const pct = progress.total > 0 ? Math.round((progress.completed / progress.total) * 100) : 0;

  return (
    <div className="space-y-2">
      <div className="flex justify-between text-xs text-slate-400">
        <span>
          {progress.currentReport && `${progress.currentReport} — ${progress.currentEntity}`}
        </span>
        <span>
          {progress.completed}/{progress.total} ({pct}%)
        </span>
      </div>
      <div className="h-2 rounded-full bg-slate-700 overflow-hidden">
        <div
          className={`h-full rounded-full transition-all duration-300 ${
            progress.status === 'error' ? 'bg-red-500' : 'bg-blue-500'
          }`}
          style={{ width: `${pct}%` }}
        />
      </div>
      {progress.errors.length > 0 && (
        <ul className="text-xs text-red-400 space-y-0.5">
          {progress.errors.map((err, i) => (
            <li key={i}>{err}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

export function ReportBookBuilder() {
  const [engine] = useState(() => new ReportBookEngine());
  const [book, setBook] = useState<ReportBook>(() =>
    engine.createBook('Board Pack', 'Monthly board pack with all entities'),
  );
  const [progress, setProgress] = useState<GenerationProgress | null>(null);
  const [previewEntry, setPreviewEntry] = useState<ReportBookEntry | null>(null);

  const availableVars = useMemo(() => engine.getAvailableVariables(), [engine]);

  // --- Entry operations ---

  const handleAddPreset = useCallback(
    (presetId: string, name: string) => {
      const preset = PRESET_LIST.find((p) => p.id === presetId);
      const defaultVars: Record<string, string> = {};
      if (preset) {
        for (const v of Object.entries(preset.defaultVariables)) {
          defaultVars[v[0]] = v[1];
        }
      }

      engine.addEntry(book.id, {
        reportName: name,
        templateId: presetId,
        entityIds: MOCK_ENTITIES.map((e) => e.id),
        variables: defaultVars,
        enabled: true,
      });
      setBook({ ...engine.getBook(book.id)! });
    },
    [book.id, engine],
  );

  const handleUpdateEntry = useCallback(
    (entryId: string, updates: Partial<ReportBookEntry>) => {
      engine.updateEntry(book.id, entryId, updates);
      setBook({ ...engine.getBook(book.id)! });
    },
    [book.id, engine],
  );

  const handleRemoveEntry = useCallback(
    (entryId: string) => {
      if (!window.confirm('Remove this report entry?')) return;
      engine.removeEntry(book.id, entryId);
      setBook({ ...engine.getBook(book.id)! });
    },
    [book.id, engine],
  );

  const handleMoveUp = useCallback(
    (entryId: string) => {
      const idx = book.entries.findIndex((e) => e.id === entryId);
      if (idx <= 0) return;
      const ids = book.entries.map((e) => e.id);
      [ids[idx - 1], ids[idx]] = [ids[idx], ids[idx - 1]];
      engine.reorderEntries(book.id, ids);
      setBook({ ...engine.getBook(book.id)! });
    },
    [book.id, book.entries, engine],
  );

  const handleMoveDown = useCallback(
    (entryId: string) => {
      const idx = book.entries.findIndex((e) => e.id === entryId);
      if (idx === -1 || idx >= book.entries.length - 1) return;
      const ids = book.entries.map((e) => e.id);
      [ids[idx], ids[idx + 1]] = [ids[idx + 1], ids[idx]];
      engine.reorderEntries(book.id, ids);
      setBook({ ...engine.getBook(book.id)! });
    },
    [book.id, book.entries, engine],
  );

  // --- Generation ---

  const handleGenerate = useCallback(async () => {
    setProgress({
      total: 0,
      completed: 0,
      currentEntity: '',
      currentReport: '',
      status: 'pending',
      errors: [],
    });

    try {
      const results = await engine.generateReports(book.id, MOCK_ENTITIES, setProgress);
      // Results available for export
    } catch {
      // errors are captured in progress
    }
  }, [book.id, engine]);

  // --- Preview ---

  const previewData = useMemo(() => {
    if (!previewEntry) return null;
    const entity = MOCK_ENTITIES.find((e) => previewEntry.entityIds.includes(e.id));
    if (!entity) return null;

    // Mock preview — in production, call the registered generator
    return {
      headers: ['Line Item', 'Actual', 'Budget', 'Variance'],
      rows: [
        [previewEntry.reportName, '', '', ''],
        ['Revenue', '1,250,000', '1,200,000', '50,000'],
        ['COGS', '750,000', '720,000', '(30,000)'],
        ['Gross Profit', '500,000', '480,000', '20,000'],
      ],
    };
  }, [previewEntry]);

  // --- Render ---

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
      {/* LEFT: Template catalog */}
      <div className="lg:col-span-3 space-y-4">
        <h3 className="text-sm font-semibold text-white">Report Templates</h3>
        <div className="space-y-2">
          {PRESET_LIST.map((preset) => (
            <PresetCard key={preset.id} preset={preset} onAdd={handleAddPreset} />
          ))}
        </div>

        <div className="pt-4 border-t border-slate-700">
          <h4 className="text-xs font-medium text-slate-400 mb-2">Available Variables</h4>
          <div className="space-y-1">
            {availableVars.map((v) => (
              <div key={v.key} className="text-xs text-slate-500">
                <code className="text-blue-400">{`{${v.key}}`}</code> — {v.description}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* CENTER: Book entries */}
      <div className="lg:col-span-5 space-y-4">
        <div className="flex items-center justify-between">
          <div>
            <input
              type="text"
              value={book.name}
              onChange={(e) => {
                book.name = e.target.value;
                setBook({ ...book });
              }}
              className="text-lg font-bold text-white bg-transparent border-none outline-none"
            />
            <p className="text-xs text-slate-400">
              {book.entries.length} report(s) &middot;{' '}
              {book.entries.reduce((s, e) => s + e.entityIds.length, 0)} generation(s)
            </p>
          </div>
          <Button
            onClick={handleGenerate}
            disabled={book.entries.length === 0 || progress?.status === 'running'}
          >
            {progress?.status === 'running' ? 'Generating...' : 'Generate All'}
          </Button>
        </div>

        {progress && <ProgressBar progress={progress} />}

        <div className="space-y-2">
          {book.entries.length === 0 ? (
            <div className="text-center py-12 text-slate-500 text-sm">
              Add reports from the template catalog on the left.
            </div>
          ) : (
            book.entries.map((entry) => (
              <div
                key={entry.id}
                onClick={() => setPreviewEntry(entry)}
                className={`cursor-pointer rounded-lg transition-all ${
                  previewEntry?.id === entry.id ? 'ring-1 ring-blue-500' : ''
                }`}
              >
                <EntryRow
                  entry={entry}
                  entities={MOCK_ENTITIES}
                  onUpdate={handleUpdateEntry}
                  onRemove={handleRemoveEntry}
                  onMoveUp={handleMoveUp}
                  onMoveDown={handleMoveDown}
                />
              </div>
            ))
          )}
        </div>
      </div>

      {/* RIGHT: Preview */}
      <div className="lg:col-span-4 space-y-4">
        <h3 className="text-sm font-semibold text-white">Preview</h3>
        {previewData ? (
          <Card className="p-4 bg-white dark:bg-gray-800 dark:bg-gray-800 text-slate-900 overflow-auto max-h-[600px]">
            <h4 className="font-bold text-sm mb-3">{previewEntry?.reportName}</h4>
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b-2 border-slate-300">
                  {previewData.headers.map((h, i) => (
                    <th key={i} className={`py-1 px-2 ${i > 0 ? 'text-right' : 'text-left'}`}>
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {previewData.rows.map((row, ri) => (
                  <tr key={ri} className="border-b border-slate-100">
                    {row.map((cell, ci) => (
                      <td
                        key={ci}
                        className={`py-1 px-2 ${ci > 0 ? 'text-right font-mono' : ''} ${
                          ri === 0 ? 'font-semibold' : ''
                        }`}
                      >
                        {String(cell)}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </Card>
        ) : (
          <div className="text-center py-12 text-slate-500 text-sm">
            Click a report entry to preview.
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useCallback, useMemo } from 'react';
import {
  GripVertical, Plus, Trash2, Settings, Eye, Save, Undo2, Redo2,
  Layers, Columns, Rows,
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { cn } from '@/utils/cn';
import { ReportGrid } from './ReportGrid';
import {
  ReportBuilderEngine,
  type ReportDefinition,
  type ReportLayout,
  type RowType,
  type ColumnType,
  type PeriodType,
  type CubeData,
} from '@/engines/ReportBuilderEngine';

/* ────────────────── props ────────────────── */

export interface ReportBuilderProps {
  initialReport?: ReportDefinition;
  cubeData?: CubeData;
  onSave?: (report: ReportDefinition) => void;
  onExportPDF?: (report: ReportDefinition) => void;
  onExportExcel?: (report: ReportDefinition) => void;
  onExportCSV?: (report: ReportDefinition) => void;
  className?: string;
}

/* ────────────────── draggable item ────────────────── */

interface DragItem {
  type: 'row-type' | 'column-type';
  value: string;
}

/* ────────────────── available items ────────────────── */

const ROW_TYPES: Array<{ type: RowType; label: string; icon: string }> = [
  { type: 'header', label: 'Header Row', icon: 'H' },
  { type: 'data', label: 'Data Row', icon: 'D' },
  { type: 'subtotal', label: 'Subtotal Row', icon: 'S' },
  { type: 'total', label: 'Total Row', icon: 'T' },
  { type: 'blank', label: 'Blank Row', icon: '—' },
];

const COLUMN_TYPES: Array<{ type: ColumnType; label: string; period?: PeriodType }> = [
  { type: 'label', label: 'Label Column' },
  { type: 'period', label: 'Actual Column', period: 'actual' },
  { type: 'period', label: 'Budget Column', period: 'budget' },
  { type: 'period', label: 'Forecast Column', period: 'forecast' },
  { type: 'period', label: 'Variance Column', period: 'variance' },
  { type: 'custom', label: 'Custom Column' },
];

/* ────────────────── main component ────────────────── */

export function ReportBuilder({
  initialReport,
  cubeData = {},
  onSave,
  onExportPDF,
  onExportExcel,
  onExportCSV,
  className,
}: ReportBuilderProps) {
  const [report, setReport] = useState<ReportDefinition>(() =>
    initialReport ?? ReportBuilderEngine.createReport('New Report', 'custom', 'user')
  );
  const [history, setHistory] = useState<ReportDefinition[]>([report]);
  const [historyIndex, setHistoryIndex] = useState(0);
  const [activePanel, setActivePanel] = useState<'rows' | 'columns' | 'properties'>('rows');
  const [previewMode, setPreviewMode] = useState(false);
  const [selectedRowIndex, setSelectedRowIndex] = useState<number | null>(null);
  const [selectedColIndex, setSelectedColIndex] = useState<number | null>(null);

  /* ── undo / redo ── */
  const pushHistory = useCallback(
    (next: ReportDefinition) => {
      setHistory((prev) => [...prev.slice(0, historyIndex + 1), next]);
      setHistoryIndex((i) => i + 1);
      setReport(next);
    },
    [historyIndex]
  );

  const undo = useCallback(() => {
    if (historyIndex > 0) {
      const next = historyIndex - 1;
      setHistoryIndex(next);
      setReport(history[next]);
    }
  }, [historyIndex, history]);

  const redo = useCallback(() => {
    if (historyIndex < history.length - 1) {
      const next = historyIndex + 1;
      setHistoryIndex(next);
      setReport(history[next]);
    }
  }, [historyIndex, history]);

  /* ── layout mutation helpers ── */
  const updateLayout = useCallback(
    (updater: (layout: ReportLayout) => ReportLayout) => {
      const newLayout = updater(report.layout);
      pushHistory({
        ...report,
        layout: newLayout,
        updatedAt: new Date().toISOString(),
        version: report.version + 1,
      });
    },
    [report, pushHistory]
  );

  /* ── row operations ── */
  const addRow = useCallback(
    (type: RowType) => {
      updateLayout((layout) => ReportBuilderEngine.addRow(layout, type));
    },
    [updateLayout]
  );

  const removeRow = useCallback(
    (rowId: string) => {
      updateLayout((layout) => ReportBuilderEngine.removeRow(layout, rowId));
      setSelectedRowIndex(null);
    },
    [updateLayout]
  );

  /* ── column operations ── */
  const addColumn = useCallback(
    (colType: ColumnType, period?: PeriodType) => {
      updateLayout((layout) =>
        ReportBuilderEngine.addColumn(layout, {
          type: colType,
          header: colType === 'label' ? 'Label' : period ? period.charAt(0).toUpperCase() + period.slice(1) : 'Custom',
          width: colType === 'label' ? 220 : 130,
          period,
        })
      );
    },
    [updateLayout]
  );

  const removeColumn = useCallback(
    (colId: string) => {
      updateLayout((layout) => ReportBuilderEngine.removeColumn(layout, colId));
      setSelectedColIndex(null);
    },
    [updateLayout]
  );

  /* ── row/column name editing ── */
  const updateRowLabel = useCallback(
    (rowIndex: number, text: string) => {
      updateLayout((layout) => {
        const row = layout.rows[rowIndex];
        if (!row) return layout;
        const labelColIdx = layout.columns.findIndex((c) => c.type === 'label');
        if (labelColIdx === -1) return layout;
        return ReportBuilderEngine.updateCell(layout, rowIndex, labelColIdx, {
          type: 'text',
          content: { text },
        });
      });
    },
    [updateLayout]
  );

  const updateColumnHeader = useCallback(
    (colIndex: number, header: string) => {
      updateLayout((layout) => {
        const columns = layout.columns.map((c, i) =>
          i === colIndex ? { ...c, header } : c
        );
        return { ...layout, columns };
      });
    },
    [updateLayout]
  );

  /* ── report metadata ── */
  const updateName = useCallback(
    (name: string) => {
      pushHistory(ReportBuilderEngine.updateReport(report, { name }));
    },
    [report, pushHistory]
  );

  /* ── save ── */
  const handleSave = useCallback(() => {
    onSave?.(report);
  }, [report, onSave]);

  /* ── drag and drop ── */
  const handleDragStart = useCallback(
    (e: React.DragEvent, item: DragItem) => {
      e.dataTransfer.setData('application/json', JSON.stringify(item));
      e.dataTransfer.effectAllowed = 'copy';
    },
    []
  );

  const handleDrop = useCallback(
    (e: React.DragEvent, target: 'rows' | 'columns') => {
      e.preventDefault();
      try {
        const item: DragItem = JSON.parse(e.dataTransfer.getData('application/json'));
        if (target === 'rows' && item.type === 'row-type') {
          addRow(item.value as RowType);
        } else if (target === 'columns' && item.type === 'column-type') {
          const colDef = COLUMN_TYPES.find((c) => c.label === item.value);
          if (colDef) addColumn(colDef.type, colDef.period);
        }
      } catch {
        // ignore invalid drag data
      }
    },
    [addRow, addColumn]
  );

  /* ── render ── */
  const validation = useMemo(() => ReportBuilderEngine.validateReport(report), [report]);
  const errors = validation.errors;

  return (
    <div className={cn('flex flex-col h-full', className)} role="region" aria-label="Report Builder">
      {/* Toolbar */}
      <div className="flex items-center justify-between px-4 py-2 border-b border-slate-800 bg-slate-900/50">
        <div className="flex items-center gap-3">
          <input
            type="text"
            value={report.name}
            onChange={(e) => updateName(e.target.value)}
            className="bg-transparent text-lg font-semibold text-white border-b border-transparent hover:border-slate-600 focus:border-blue-500 focus:outline-none px-1"
            aria-label="Report name"
          />
          {errors.length > 0 && (
            <span className="text-xs text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded">
              {errors.length} issue{errors.length > 1 ? 's' : ''}
            </span>
          )}
        </div>
        <div className="flex items-center gap-1">
          <Button size="sm" variant="ghost" onClick={undo} disabled={historyIndex === 0} aria-label="Undo">
            <Undo2 className="h-4 w-4" />
          </Button>
          <Button size="sm" variant="ghost" onClick={redo} disabled={historyIndex === history.length - 1} aria-label="Redo">
            <Redo2 className="h-4 w-4" />
          </Button>
          <div className="w-px h-5 bg-slate-700 mx-1" />
          <Button size="sm" variant="ghost" onClick={() => setPreviewMode(!previewMode)} aria-label={previewMode ? 'Switch to edit mode' : 'Switch to preview mode'}>
            <Eye className="h-4 w-4 mr-1.5" />
            {previewMode ? 'Edit' : 'Preview'}
          </Button>
          <Button size="sm" onClick={handleSave}>
            <Save className="h-4 w-4 mr-1.5" />
            Save
          </Button>
        </div>
      </div>

      {/* Body */}
      {previewMode ? (
        <div className="flex-1 overflow-auto p-6">
          <ReportGrid
            layout={report.layout}
            cubeData={cubeData}
            onExportPDF={() => onExportPDF?.(report)}
            onExportExcel={() => onExportExcel?.(report)}
            onExportCSV={() => onExportCSV?.(report)}
          />
        </div>
      ) : (
        <div className="flex flex-1 overflow-hidden">
          {/* Left Panel */}
          <div className="w-56 border-r border-slate-800 flex flex-col overflow-hidden">
            <div className="flex border-b border-slate-800">
              <button
                className={cn(
                  'flex-1 px-3 py-2 text-xs font-medium text-center transition-colors',
                  activePanel === 'rows' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-slate-400 hover:text-white'
                )}
                onClick={() => setActivePanel('rows')}
              >
                <Rows className="h-3.5 w-3.5 inline mr-1" />
                Rows
              </button>
              <button
                className={cn(
                  'flex-1 px-3 py-2 text-xs font-medium text-center transition-colors',
                  activePanel === 'columns' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-slate-400 hover:text-white'
                )}
                onClick={() => setActivePanel('columns')}
              >
                <Columns className="h-3.5 w-3.5 inline mr-1" />
                Cols
              </button>
              <button
                className={cn(
                  'flex-1 px-3 py-2 text-xs font-medium text-center transition-colors',
                  activePanel === 'properties' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-slate-400 hover:text-white'
                )}
                onClick={() => setActivePanel('properties')}
              >
                <Settings className="h-3.5 w-3.5 inline mr-1" />
                Props
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-3 space-y-2">
              {activePanel === 'rows' && (
                <>
                  <p className="text-xs text-slate-500 mb-2">Drag to add rows</p>
                  {ROW_TYPES.map((rt) => (
                    <div
                      key={rt.type}
                      draggable
                      onDragStart={(e) => handleDragStart(e, { type: 'row-type', value: rt.type })}
                      className="flex items-center gap-2 px-3 py-2 rounded-lg border border-slate-700 bg-slate-800/50 cursor-grab hover:border-blue-500 hover:bg-slate-800 transition-colors text-sm"
                    >
                      <GripVertical className="h-3.5 w-3.5 text-slate-500" />
                      <span className="text-xs font-mono bg-slate-700 px-1.5 py-0.5 rounded">{rt.icon}</span>
                      <span className="text-slate-300">{rt.label}</span>
                    </div>
                  ))}
                </>
              )}

              {activePanel === 'columns' && (
                <>
                  <p className="text-xs text-slate-500 mb-2">Drag to add columns</p>
                  {COLUMN_TYPES.map((ct) => (
                    <div
                      key={ct.label}
                      draggable
                      onDragStart={(e) => handleDragStart(e, { type: 'column-type', value: ct.label })}
                      className="flex items-center gap-2 px-3 py-2 rounded-lg border border-slate-700 bg-slate-800/50 cursor-grab hover:border-blue-500 hover:bg-slate-800 transition-colors text-sm"
                    >
                      <GripVertical className="h-3.5 w-3.5 text-slate-500" />
                      <span className="text-slate-300">{ct.label}</span>
                    </div>
                  ))}
                </>
              )}

              {activePanel === 'properties' && (
                <div className="space-y-4">
                  <div>
                    <label className="text-xs text-slate-400 block mb-1">Report Name</label>
                    <input
                      type="text"
                      value={report.name}
                      onChange={(e) => updateName(e.target.value)}
                      className="w-full bg-slate-800 border border-slate-700 rounded px-2 py-1.5 text-sm text-white"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-slate-400 block mb-1">Description</label>
                    <textarea
                      value={report.description}
                      onChange={(e) =>
                        pushHistory(ReportBuilderEngine.updateReport(report, { description: e.target.value }))
                      }
                      className="w-full bg-slate-800 border border-slate-700 rounded px-2 py-1.5 text-sm text-white resize-none"
                      rows={3}
                    />
                  </div>

                  {errors.length > 0 && (
                    <div className="mt-4 space-y-1">
                      <p className="text-xs font-medium text-amber-400">Validation Issues</p>
                      {errors.map((err: string, i: number) => (
                        <p key={i} className="text-xs text-amber-400/80">• {err}</p>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>

          {/* Center — Layout Editor */}
          <div className="flex-1 flex flex-col overflow-hidden">
            <div
              className="flex-1 overflow-y-auto"
              onDragOver={(e) => e.preventDefault()}
              onDrop={(e) => handleDrop(e, 'rows')}
            >
              <div className="p-4 space-y-1">
                <div className="flex items-center justify-between mb-2">
                  <h3 className="text-xs font-semibold text-slate-400 uppercase flex items-center gap-1.5">
                    <Rows className="h-3.5 w-3.5" />
                    Rows ({report.layout.rows.length})
                  </h3>
                  <Button size="sm" variant="ghost" onClick={() => addRow('data')}>
                    <Plus className="h-3.5 w-3.5 mr-1" />
                    Add Row
                  </Button>
                </div>

                {report.layout.rows.length === 0 ? (
                  <div className="text-center py-8 text-slate-500 text-sm border-2 border-dashed border-slate-700 rounded-lg">
                    Drag row types here or click Add Row
                  </div>
                ) : (
                  report.layout.rows.map((row, ri) => (
                    <div
                      key={row.id}
                      className={cn(
                        'flex items-center gap-2 px-3 py-1.5 rounded border text-sm transition-colors cursor-pointer',
                        selectedRowIndex === ri
                          ? 'border-blue-500 bg-blue-500/10'
                          : 'border-slate-700 bg-slate-800/30 hover:border-slate-600'
                      )}
                      onClick={() => setSelectedRowIndex(ri)}
                    >
                      <GripVertical className="h-3.5 w-3.5 text-slate-500 flex-shrink-0" />
                      <span
                        className={cn(
                          'text-xs font-mono px-1.5 py-0.5 rounded flex-shrink-0',
                          row.type === 'total' ? 'bg-green-500/20 text-green-400' :
                          row.type === 'subtotal' ? 'bg-blue-500/20 text-blue-400' :
                          row.type === 'header' ? 'bg-purple-500/20 text-purple-400' :
                          row.type === 'blank' ? 'bg-slate-600 text-slate-400' :
                          'bg-slate-700 text-slate-300'
                        )}
                      >
                        {row.type.charAt(0).toUpperCase()}
                      </span>
                      <span className="text-slate-300 truncate flex-1">
                        {(row.cells.find((_, ci) => report.layout.columns[ci]?.type === 'label')?.content as { content?: { text?: string } })?.content?.text ?? row.type}
                      </span>
                      {row.grouping && (
                        <Layers className="h-3 w-3 text-slate-500 flex-shrink-0" />
                      )}
                      <button
                        className="text-slate-500 hover:text-red-400 flex-shrink-0"
                        onClick={(e) => {
                          e.stopPropagation();
                          removeRow(row.id);
                        }}
                        aria-label={`Remove row ${ri + 1}`}
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </button>
                    </div>
                  ))
                )}
              </div>

              {/* Column list */}
              <div
                className="px-4 pb-4"
                onDragOver={(e) => e.preventDefault()}
                onDrop={(e) => handleDrop(e, 'columns')}
              >
                <div className="flex items-center justify-between mb-2">
                  <h3 className="text-xs font-semibold text-slate-400 uppercase flex items-center gap-1.5">
                    <Columns className="h-3.5 w-3.5" />
                    Columns ({report.layout.columns.length})
                  </h3>
                  <Button size="sm" variant="ghost" onClick={() => addColumn('period', 'actual')}>
                    <Plus className="h-3.5 w-3.5 mr-1" />
                    Add Column
                  </Button>
                </div>

                {report.layout.columns.length === 0 ? (
                  <div className="text-center py-6 text-slate-500 text-sm border-2 border-dashed border-slate-700 rounded-lg">
                    Drag column types here or click Add Column
                  </div>
                ) : (
                  <div className="flex flex-wrap gap-1">
                    {report.layout.columns.map((col, ci) => (
                      <div
                        key={col.id}
                        className={cn(
                          'flex items-center gap-1.5 px-2.5 py-1 rounded border text-xs transition-colors cursor-pointer',
                          selectedColIndex === ci
                            ? 'border-blue-500 bg-blue-500/10'
                            : 'border-slate-700 bg-slate-800/30 hover:border-slate-600'
                        )}
                        onClick={() => setSelectedColIndex(ci)}
                      >
                        <span
                          className={cn(
                            'font-mono px-1 py-0.5 rounded',
                            col.type === 'label' ? 'bg-purple-500/20 text-purple-400' :
                            col.period === 'actual' ? 'bg-green-500/20 text-green-400' :
                            col.period === 'budget' ? 'bg-blue-500/20 text-blue-400' :
                            col.period === 'variance' ? 'bg-amber-500/20 text-amber-400' :
                            'bg-slate-600 text-slate-400'
                          )}
                        >
                          {col.type === 'label' ? 'L' : col.period?.charAt(0).toUpperCase() ?? 'C'}
                        </span>
                        <span className="text-slate-300">{col.header}</span>
                        <button
                          className="text-slate-500 hover:text-red-400 ml-1"
                          onClick={(e) => {
                            e.stopPropagation();
                            removeColumn(col.id);
                          }}
                          aria-label={`Remove column ${col.header}`}
                        >
                          <Trash2 className="h-3 w-3" />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>

            {/* Selected item properties */}
            {(selectedRowIndex !== null || selectedColIndex !== null) && (
              <div className="border-t border-slate-800 p-4 bg-slate-900/30">
                {selectedRowIndex !== null && report.layout.rows[selectedRowIndex] && (
                  <div className="space-y-2">
                    <p className="text-xs font-medium text-slate-400">
                      Row {selectedRowIndex + 1} — {report.layout.rows[selectedRowIndex].type}
                    </p>
                    <div className="flex gap-2">
                      <input
                        type="text"
                        value={
                          (report.layout.rows[selectedRowIndex].cells.find(
                            (_, ci) => report.layout.columns[ci]?.type === 'label'
                          )?.content as { content?: { text?: string } })?.content?.text ?? ''
                        }
                        onChange={(e) => updateRowLabel(selectedRowIndex, e.target.value)}
                        placeholder="Row label..."
                        className="flex-1 bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                      />
                      <select
                        value={report.layout.rows[selectedRowIndex].type}
                        onChange={(e) => {
                          const newType = e.target.value as RowType;
                          updateLayout((layout) => {
                            const rows = layout.rows.map((r, i) =>
                              i === selectedRowIndex ? { ...r, type: newType } : r
                            );
                            return { ...layout, rows };
                          });
                        }}
                        className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                      >
                        {ROW_TYPES.map((rt) => (
                          <option key={rt.type} value={rt.type}>{rt.label}</option>
                        ))}
                      </select>
                    </div>
                  </div>
                )}
                {selectedColIndex !== null && report.layout.columns[selectedColIndex] && (
                  <div className="space-y-2">
                    <p className="text-xs font-medium text-slate-400">
                      Column {selectedColIndex + 1} — {report.layout.columns[selectedColIndex].type}
                    </p>
                    <div className="flex gap-2">
                      <input
                        type="text"
                        value={report.layout.columns[selectedColIndex].header}
                        onChange={(e) => updateColumnHeader(selectedColIndex, e.target.value)}
                        placeholder="Column header..."
                        className="flex-1 bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                      />
                      <input
                        type="number"
                        value={report.layout.columns[selectedColIndex].width}
                        onChange={(e) => {
                          const width = parseInt(e.target.value, 10) || 100;
                          updateLayout((layout) =>
                            ReportBuilderEngine.setColumnWidth(layout, report.layout.columns[selectedColIndex].id, width)
                          );
                        }}
                        className="w-20 bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                        min={40}
                        aria-label="Column width"
                      />
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Right Panel — Live Preview */}
          <div className="w-[420px] border-l border-slate-800 overflow-y-auto p-4 bg-slate-950/50">
            <h3 className="text-xs font-semibold text-slate-400 uppercase mb-3 flex items-center gap-1.5">
              <Eye className="h-3.5 w-3.5" />
              Live Preview
            </h3>
            <div className="origin-top-left scale-[0.65] w-[154%]">
              <ReportGrid
                layout={report.layout}
                cubeData={cubeData}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useCallback, useMemo } from 'react';
import { ChevronRight, ChevronDown, Download, FileText, Table as TableIcon } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { cn } from '@/utils/cn';
import {
  ReportBuilderEngine,
  type ReportLayout,
  type ReportRow,
  type ReportColumn,
  type CellContent,
  type MetricCellContent,
  type FormulaCellContent,
  type CubeData,
  type ConditionalFormat,
  type CellStyle,
} from '@/engines/ReportBuilderEngine';

/* ────────────────── props ────────────────── */

export interface ReportGridProps {
  layout: ReportLayout;
  cubeData?: CubeData;
  onCellClick?: (rowIndex: number, colIndex: number) => void;
  onDrillDown?: (row: ReportRow, column: ReportColumn) => void;
  onExportPDF?: () => void;
  onExportExcel?: () => void;
  onExportCSV?: () => void;
  className?: string;
}

/* ────────────────── helpers ────────────────── */

function mergeStyles(base: CellStyle, override?: Partial<CellStyle>): React.CSSProperties {
  const s = { ...base, ...override };
  return {
    fontWeight: s.bold ? 700 : 400,
    fontStyle: s.italic ? 'italic' : undefined,
    textDecoration: s.underline ? 'underline' : undefined,
    fontSize: s.fontSize,
    fontFamily: s.fontFamily,
    color: s.textColor,
    backgroundColor: s.backgroundColor === 'transparent' ? undefined : s.backgroundColor,
    textAlign: s.alignment,
    paddingLeft: `${8 + s.indent * 16}px`,
    whiteSpace: s.wrap ? 'pre-wrap' : undefined,
    borderTop: s.borderTop === 'none' ? undefined : `${s.borderTop === 'thin' ? 1 : s.borderTop === 'medium' ? 2 : 3}px solid #374151`,
    borderBottom: s.borderBottom === 'none' ? undefined : `${s.borderBottom === 'thin' ? 1 : s.borderBottom === 'medium' ? 2 : 3}px solid #374151`,
  };
}

function resolveMetricValue(content: MetricCellContent, cubeData: CubeData): string {
  const key = ReportBuilderEngine.buildMetricKey(content);
  const raw = cubeData[key];
  if (raw === undefined || raw === null) return '—';
  const num = typeof raw === 'number' ? raw : Number(raw);
  if (!Number.isFinite(num)) return String(raw);
  return ReportBuilderEngine.formatNumber(num, content.format, content.decimals);
}

function resolveCellDisplay(cellContent: CellContent, cubeData: CubeData): string {
  if (cellContent.type === 'text') {
    return cellContent.content.text;
  }
  if (cellContent.type === 'metric') {
    return resolveMetricValue(cellContent.content, cubeData);
  }
  if (cellContent.type === 'formula') {
    const fc = cellContent.content as FormulaCellContent;
    return fc.label ?? fc.expression;
  }
  if (cellContent.type === 'chart') return `[Chart]`;
  if (cellContent.type === 'table') return `[Table]`;
  return '';
}

function getConditionalStyle(
  formats: ConditionalFormat[] | undefined,
  value: string
): Partial<CellStyle> | null {
  if (!formats || formats.length === 0) return null;
  const num = Number(value.replace(/[^0-9.\-]/g, ''));
  if (!Number.isFinite(num)) return null;
  return ReportBuilderEngine.evaluateConditionalFormats(formats, num);
}

/* ────────────────── row component ────────────────── */

interface GridRowProps {
  row: ReportRow;
  rowIndex: number;
  visibleColumns: ReportColumn[];
  allColumns: ReportColumn[];
  cubeData: CubeData;
  expandedGroups: Set<string>;
  onToggleGroup: (rowId: string) => void;
  onCellClick?: (rowIndex: number, colIndex: number) => void;
}

function GridRow({
  row,
  rowIndex,
  visibleColumns,
  allColumns,
  cubeData,
  expandedGroups: _expandedGroups,
  onToggleGroup,
  onCellClick,
}: GridRowProps) {
  const isGrouped = !!row.grouping;
  const isExpanded = row.grouping?.state === 'expanded';
  const level = row.grouping?.level ?? 0;

  const rowBg =
    row.type === 'total'
      ? 'bg-slate-800/70 font-semibold'
      : row.type === 'subtotal'
      ? 'bg-slate-900/40 font-medium'
      : 'hover:bg-slate-900/30';

  return (
    <tr className={cn('border-b border-slate-800 transition-colors', rowBg)} role="row">
      {visibleColumns.map((col) => {
        const colIdx = allColumns.indexOf(col);
        const cell = row.cells[colIdx];
        if (!cell) return <td key={col.id} className="px-4 py-2" />;

        const display = resolveCellDisplay(cell.content, cubeData);
        const condStyle =
          cell.type === 'metric'
            ? getConditionalStyle(
                (cell.content as { content: MetricCellContent }).content.conditionalFormats,
                display
              )
            : cell.type === 'formula'
            ? getConditionalStyle(
                (cell.content as { content: FormulaCellContent }).content.conditionalFormats,
                display
              )
            : null;

        const cellStyle = condStyle ? mergeStyles(cell.style, condStyle) : mergeStyles(cell.style);
        const isLabel = col.type === 'label';
        const isNumber = cell.type === 'metric' || cell.type === 'formula';

        return (
          <td
            key={col.id}
            className={cn(
              'px-4 py-2 text-sm tabular-nums',
              isNumber && 'text-right',
              cell.type === 'metric' && display.startsWith('(') && 'text-red-400',
              cell.type === 'metric' && !display.startsWith('(') && display !== '—' && 'text-green-400'
            )}
            style={cellStyle}
            role="gridcell"
            onClick={() => onCellClick?.(rowIndex, colIdx)}
          >
            {isLabel && isGrouped && colIdx === allColumns.findIndex((c) => c.type === 'label') && (
              <button
                className="inline-flex items-center mr-1 text-slate-400 hover:text-white"
                onClick={(e) => {
                  e.stopPropagation();
                  onToggleGroup(row.id);
                }}
                aria-label={isExpanded ? 'Collapse group' : 'Expand group'}
              >
                {isExpanded ? (
                  <ChevronDown className="w-3.5 h-3.5" />
                ) : (
                  <ChevronRight className="w-3.5 h-3.5" />
                )}
              </button>
            )}
            {isLabel && level > 0 && (
              <span style={{ paddingLeft: `${level * 16}px` }} />
            )}
            {display}
          </td>
        );
      })}
    </tr>
  );
}

/* ────────────────── main grid ────────────────── */

export function ReportGrid({
  layout,
  cubeData = {},
  onCellClick,
  onDrillDown: _onDrillDown,
  onExportPDF,
  onExportExcel,
  onExportCSV,
  className,
}: ReportGridProps) {
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(() => {
    const initial = new Set<string>();
    layout.rows.forEach((r) => {
      if (r.grouping?.state === 'expanded') initial.add(r.id);
    });
    return initial;
  });

  const visibleColumns = useMemo(
    () => ReportBuilderEngine.getVisibleColumns(layout),
    [layout]
  );

  const visibleRows = useMemo(() => {
    const hiddenByGroup = new Set<string>();
    layout.rows.forEach((row) => {
      if (row.grouping?.parentId && !expandedGroups.has(row.grouping.parentId)) {
        hiddenByGroup.add(row.id);
      }
    });
    return layout.rows.filter((r) => r.isVisible && !hiddenByGroup.has(r.id));
  }, [layout, expandedGroups]);

  const handleToggleGroup = useCallback((rowId: string) => {
    setExpandedGroups((prev) => {
      const next = new Set(prev);
      if (next.has(rowId)) {
        next.delete(rowId);
      } else {
        next.add(rowId);
      }
      return next;
    });
  }, []);

  return (
    <div className={cn('space-y-3', className)}>
      {/* Export bar */}
      <div className="flex items-center justify-end gap-2">
        {onExportPDF && (
          <Button size="sm" variant="ghost" onClick={onExportPDF} aria-label="Export PDF">
            <FileText className="h-3.5 w-3.5 mr-1.5" />
            PDF
          </Button>
        )}
        {onExportExcel && (
          <Button size="sm" variant="ghost" onClick={onExportExcel} aria-label="Export Excel">
            <TableIcon className="h-3.5 w-3.5 mr-1.5" />
            Excel
          </Button>
        )}
        {onExportCSV && (
          <Button size="sm" variant="ghost" onClick={onExportCSV} aria-label="Export CSV">
            <Download className="h-3.5 w-3.5 mr-1.5" />
            CSV
          </Button>
        )}
      </div>

      {/* Grid */}
      <div className="overflow-x-auto rounded-lg border border-slate-800">
        <table className="w-full text-sm" role="grid" aria-label="Report grid">
          {/* Header */}
          <thead>
            <tr className="text-left text-slate-400 text-xs uppercase border-b border-slate-700 bg-slate-900/50">
              {visibleColumns.map((col) => (
                <th
                  key={col.id}
                  className={cn(
                    'px-4 py-3 font-semibold whitespace-nowrap',
                    col.type !== 'label' && 'text-right'
                  )}
                  style={{ width: col.width, minWidth: col.width }}
                  role="columnheader"
                >
                  {col.header}
                </th>
              ))}
            </tr>
          </thead>

          {/* Body */}
          <tbody className="divide-y divide-slate-800/50">
            {visibleRows.length === 0 ? (
              <tr>
                <td
                  colSpan={visibleColumns.length}
                  className="px-4 py-12 text-center text-[var(--text-secondary)]"
                >
                  No data to display. Add dimensions and measures to build the report.
                </td>
              </tr>
            ) : (
              visibleRows.map((row, ri) => (
                <GridRow
                  key={row.id}
                  row={row}
                  rowIndex={ri}
                  visibleColumns={visibleColumns}
                  allColumns={layout.columns}
                  cubeData={cubeData}
                  expandedGroups={expandedGroups}
                  onToggleGroup={handleToggleGroup}
                  onCellClick={onCellClick}
                />
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Footer info */}
      <div className="flex items-center justify-between text-xs text-[var(--text-secondary)]">
        <span>{visibleRows.length} rows × {visibleColumns.length} columns</span>
        <span>Generated by FinPlan Pro</span>
      </div>
    </div>
  );
}

import { useCallback, useState } from 'react';
import type { ExportTemplate, TemplateSection, TemplateStyle, TemplateType } from '@/engines/ExportTemplateEngine';

interface TemplateDesignerProps {
  template?: ExportTemplate;
  onSave: (template: ExportTemplate) => void;
  onCancel: () => void;
}

const SECTION_TYPES: Array<{ value: TemplateSection['type']; label: string }> = [
  { value: 'cover', label: 'Cover Page' },
  { value: 'kpi_summary', label: 'KPI Summary' },
  { value: 'table', label: 'Data Table' },
  { value: 'text', label: 'Text Block' },
  { value: 'page_break', label: 'Page Break' },
];

const TEMPLATE_TYPES: Array<{ value: TemplateType; label: string }> = [
  { value: 'board_pack', label: 'Board Pack' },
  { value: 'pl_statement', label: 'P&L Statement' },
  { value: 'balance_sheet', label: 'Balance Sheet' },
  { value: 'cash_flow', label: 'Cash Flow' },
  { value: 'budget_vs_actual', label: 'Budget vs Actual' },
  { value: 'kpi_summary', label: 'KPI Summary' },
];

let nextId = 1;

export function TemplateDesigner({ template, onSave, onCancel }: TemplateDesignerProps) {
  const [name, setName] = useState(template?.name ?? 'New Template');
  const [description, setDescription] = useState(template?.description ?? '');
  const [type, setType] = useState<TemplateType>(template?.type ?? 'board_pack');
  const [sections, setSections] = useState<TemplateSection[]>(template?.sections ?? []);
  const [style, setStyle] = useState<TemplateStyle>(template?.style ?? {
    primaryColor: '#1E3A5F',
    secondaryColor: '#4A90D9',
    fontFamily: 'helvetica',
    headerFontSize: 10,
    bodyFontSize: 8,
    companyName: 'FinPlan Pro',
  });
  const [selectedSection, setSelectedSection] = useState<string | null>(null);

  const addSection = useCallback((sectionType: TemplateSection['type']) => {
    const id = `section-${Date.now()}-${nextId++}`;
    const newSection: TemplateSection = {
      id,
      type: sectionType,
      title: sectionType === 'cover' ? 'Cover Page' : sectionType === 'page_break' ? '' : `New ${sectionType.replace(/_/g, ' ')}`,
      order: sections.length,
      config: sectionType === 'cover' ? { title: name, subtitle: '', confidential: true }
        : sectionType === 'kpi_summary' ? { kpis: [] }
        : sectionType === 'table' ? { headers: [], rows: [] }
        : sectionType === 'text' ? { content: '' }
        : {},
    };
    setSections((prev) => [...prev, newSection]);
    setSelectedSection(id);
  }, [sections.length, name]);

  const removeSection = useCallback((id: string) => {
    setSections((prev) => prev.filter((s) => s.id !== id));
    if (selectedSection === id) setSelectedSection(null);
  }, [selectedSection]);

  const moveSection = useCallback((id: string, direction: 'up' | 'down') => {
    setSections((prev) => {
      const idx = prev.findIndex((s) => s.id === id);
      if (idx < 0) return prev;
      const target = direction === 'up' ? idx - 1 : idx + 1;
      if (target < 0 || target >= prev.length) return prev;
      const next = [...prev];
      [next[idx], next[target]] = [next[target], next[idx]];
      return next.map((s, i) => ({ ...s, order: i }));
    });
  }, []);

  const updateSectionTitle = useCallback((id: string, title: string) => {
    setSections((prev) => prev.map((s) => (s.id === id ? { ...s, title } : s)));
  }, []);

  const handleSave = useCallback(() => {
    const now = new Date().toISOString();
    onSave({
      id: template?.id ?? `tpl-custom-${Date.now()}`,
      name,
      type,
      description,
      sections: sections.map((s, i) => ({ ...s, order: i })),
      style,
      variables: [
        { key: 'entity', label: 'Entity', defaultValue: 'Company Name' },
        { key: 'period', label: 'Period', defaultValue: 'FY 2026' },
        { key: 'currency', label: 'Currency', defaultValue: 'USD' },
        { key: 'date', label: 'Date', defaultValue: new Date().toLocaleDateString() },
        { key: 'preparedBy', label: 'Prepared By', defaultValue: 'Finance Team' },
      ],
      createdAt: template?.createdAt ?? now,
      updatedAt: now,
    });
  }, [name, type, description, sections, style, template, onSave]);

  const active = sections.find((s) => s.id === selectedSection);

  return (
    <div className="flex h-full">
      {/* Left: Section list */}
      <div className="w-64 border-r border-[var(--border-subtle)] dark:border-gray-700 p-4 overflow-y-auto">
        <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-3">Sections</h3>
        <div className="space-y-1 mb-4">
          {sections.map((section) => (
            <div
              key={section.id}
              className={`flex items-center gap-2 px-2 py-1.5 rounded cursor-pointer text-sm ${
                selectedSection === section.id
                  ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300'
                  : 'hover:bg-[var(--bg-hover)] dark:hover:bg-gray-800 text-[var(--text-secondary)] dark:text-gray-400 dark:text-gray-500'
              }`}
              onClick={() => setSelectedSection(section.id)}
            >
              <span className="flex-1 truncate">{section.title || section.type}</span>
              <button
                className="text-gray-400 dark:text-gray-500 hover:text-[var(--text-secondary)] dark:hover:text-gray-300"
                onClick={(e) => { e.stopPropagation(); moveSection(section.id, 'up'); }}
              >
                ↑
              </button>
              <button
                className="text-gray-400 dark:text-gray-500 hover:text-[var(--text-secondary)] dark:hover:text-gray-300"
                onClick={(e) => { e.stopPropagation(); moveSection(section.id, 'down'); }}
              >
                ↓
              </button>
              <button
                className="text-red-400 hover:fin-negative"
                onClick={(e) => { e.stopPropagation(); removeSection(section.id); }}
              >
                ×
              </button>
            </div>
          ))}
        </div>

        <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-2">Add Section</h3>
        <div className="space-y-1">
          {SECTION_TYPES.map((st) => (
            <button
              key={st.value}
              className="w-full text-left px-2 py-1.5 text-sm rounded bg-gray-50 dark:bg-gray-900 dark:bg-gray-800 hover:bg-[var(--bg-hover)] dark:hover:bg-gray-700 text-[var(--text-secondary)] dark:text-gray-400 dark:text-gray-500"
              onClick={() => addSection(st.value)}
            >
              + {st.label}
            </button>
          ))}
        </div>
      </div>

      {/* Center: Section editor */}
      <div className="flex-1 p-6 overflow-y-auto">
        <div className="max-w-2xl space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Template Name</label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full px-3 py-2 border border-[var(--border-default)] dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 dark:bg-gray-800 text-[var(--text-primary)] dark:text-gray-100"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Type</label>
              <select
                value={type}
                onChange={(e) => setType(e.target.value as TemplateType)}
                className="w-full px-3 py-2 border border-[var(--border-default)] dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 dark:bg-gray-800 text-[var(--text-primary)] dark:text-gray-100"
              >
                {TEMPLATE_TYPES.map((t) => (
                  <option key={t.value} value={t.value}>{t.label}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Company Name</label>
              <input
                type="text"
                value={style.companyName}
                onChange={(e) => setStyle((s) => ({ ...s, companyName: e.target.value }))}
                className="w-full px-3 py-2 border border-[var(--border-default)] dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 dark:bg-gray-800 text-[var(--text-primary)] dark:text-gray-100"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Description</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={2}
              className="w-full px-3 py-2 border border-[var(--border-default)] dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 dark:bg-gray-800 text-[var(--text-primary)] dark:text-gray-100"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Primary Color</label>
              <input
                type="color"
                value={style.primaryColor}
                onChange={(e) => setStyle((s) => ({ ...s, primaryColor: e.target.value }))}
                className="w-full h-10 border border-[var(--border-default)] dark:border-gray-600 rounded-md"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Secondary Color</label>
              <input
                type="color"
                value={style.secondaryColor}
                onChange={(e) => setStyle((s) => ({ ...s, secondaryColor: e.target.value }))}
                className="w-full h-10 border border-[var(--border-default)] dark:border-gray-600 rounded-md"
              />
            </div>
          </div>

          {/* Active section editor */}
          {active && (
            <div className="border border-[var(--border-subtle)] dark:border-gray-700 rounded-lg p-4 mt-4">
              <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-3">
                Edit: {active.type.replace(/_/g, ' ')}
              </h4>
              <div>
                <label className="block text-xs font-medium text-[var(--text-muted)] dark:text-gray-400 dark:text-gray-500 mb-1">Section Title</label>
                <input
                  type="text"
                  value={active.title}
                  onChange={(e) => updateSectionTitle(active.id, e.target.value)}
                  className="w-full px-3 py-2 border border-[var(--border-default)] dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 dark:bg-gray-800 text-[var(--text-primary)] dark:text-gray-100 text-sm"
                />
              </div>
              {active.type === 'table' && (
                <p className="mt-2 text-xs text-[var(--text-muted)]">
                  Configure table headers and rows in the template JSON or use the report builder for dynamic data binding.
                </p>
              )}
              {active.type === 'kpi_summary' && (
                <p className="mt-2 text-xs text-[var(--text-muted)]">
                  KPI cards are auto-populated from the data context. Customize labels in the template JSON.
                </p>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Right: Actions */}
      <div className="w-48 border-l border-[var(--border-subtle)] dark:border-gray-700 p-4 flex flex-col gap-2">
        <button
          onClick={handleSave}
          className="w-full px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 text-sm font-medium"
        >
          Save Template
        </button>
        <button
          onClick={onCancel}
          className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 dark:text-gray-300 rounded-md hover:bg-gray-200 dark:hover:bg-gray-700 text-sm"
        >
          Cancel
        </button>
        <div className="mt-4 text-xs text-[var(--text-muted)] dark:text-gray-400 dark:text-gray-500">
          <p className="font-medium mb-1">Variables:</p>
          <p>{'{entity}'} — Company name</p>
          <p>{'{period}'} — Reporting period</p>
          <p>{'{currency}'} — Currency code</p>
          <p>{'{date}'} — Current date</p>
          <p>{'{preparedBy}'} — Author name</p>
        </div>
      </div>
    </div>
  );
}

