import React, { useState, useCallback } from 'react'
import { Plus, Trash2, ArrowRight, Play, Settings2 } from 'lucide-react'
import { cn } from '@/utils/cn'
import type { AllocationMethod, AllocationRule, AllocationResult } from '@/engines/AllocationEngine'
import { AllocationEngine } from '@/engines/AllocationEngine'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface AllocationSource {
  id: string
  label: string
  amount: number
}

export interface AllocationDriver {
  id: string
  label: string
  values: Record<string, number>
}

export interface AllocationRuleBuilderProps {
  sources: AllocationSource[]
  drivers: AllocationDriver[]
  targetOptions: Array<{ id: string; label: string }>
  onPreview?: (result: AllocationResult) => void
  onSave?: (rule: AllocationRule) => void
  className?: string
}

interface TargetRow {
  id: string
  dimensionMember: string
  percentage: number
  driverWeight: number
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const METHOD_OPTIONS: Array<{ value: AllocationMethod; label: string; description: string }> = [
  { value: 'direct', label: 'Direct', description: 'Allocate by fixed percentages' },
  {
    value: 'driver',
    label: 'Driver-Based',
    description: 'Allocate by driver values (headcount, revenue, etc.)',
  },
  {
    value: 'step-down',
    label: 'Step-Down',
    description: 'Sequential service department allocation',
  },
  {
    value: 'reciprocal',
    label: 'Reciprocal',
    description: 'Simultaneous service department allocation',
  },
]

const PRESET_DRIVERS = [
  { id: 'headcount', label: 'Headcount' },
  { id: 'revenue', label: 'Revenue' },
  { id: 'square_footage', label: 'Square Footage' },
  { id: 'machine_hours', label: 'Machine Hours' },
  { id: 'custom', label: 'Custom' },
]

function generateId(): string {
  return `rule-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export const AllocationRuleBuilder: React.FC<AllocationRuleBuilderProps> = ({
  sources,
  drivers,
  targetOptions,
  onPreview,
  onSave,
  className,
}) => {
  const [ruleName, setRuleName] = useState('')
  const [selectedSource, setSelectedSource] = useState('')
  const [method, setMethod] = useState<AllocationMethod>('direct')
  const [selectedDriver, setSelectedDriver] = useState('')
  const [targets, setTargets] = useState<TargetRow[]>([])
  const [isRecurring, setIsRecurring] = useState(false)
  const [period, setPeriod] = useState(new Date().toISOString().slice(0, 7))
  const [error, setError] = useState<string | null>(null)

  // --- Target management ---

  const addTarget = useCallback(() => {
    const usedMembers = new Set(targets.map((t) => t.dimensionMember))
    const available = targetOptions.find((o) => !usedMembers.has(o.id))
    if (!available) return

    setTargets((prev) => [
      ...prev,
      {
        id: `target-${Date.now()}`,
        dimensionMember: available.id,
        percentage: 0,
        driverWeight: 1,
      },
    ])
  }, [targets, targetOptions])

  const removeTarget = useCallback((id: string) => {
    setTargets((prev) => prev.filter((t) => t.id !== id))
  }, [])

  const updateTarget = useCallback((id: string, field: keyof TargetRow, value: string | number) => {
    setTargets((prev) => prev.map((t) => (t.id === id ? { ...t, [field]: value } : t)))
  }, [])

  // --- Preview / Save ---

  const buildRule = useCallback(
    (): AllocationRule => ({
      id: generateId(),
      name: ruleName || 'Untitled Allocation',
      sourceAccount: selectedSource,
      method,
      targets: targets.map((t) => ({
        dimensionMember: t.dimensionMember,
        percentage: t.percentage,
        driverWeight: t.driverWeight,
      })),
      driverDimension: method === 'driver' ? selectedDriver : undefined,
      period,
      isRecurring,
    }),
    [ruleName, selectedSource, method, targets, selectedDriver, period, isRecurring]
  )

  const handlePreview = useCallback(() => {
    setError(null)
    try {
      const rule = buildRule()
      const sourceAmount = sources.find((s) => s.id === selectedSource)?.amount ?? 0
      const driverValues = drivers.find((d) => d.id === selectedDriver)?.values ?? {}
      const result =
        method === 'driver'
          ? AllocationEngine.allocateByDriver(rule, sourceAmount, driverValues)
          : AllocationEngine.allocateDirect(rule, sourceAmount)
      onPreview?.(result)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Allocation failed')
    }
  }, [buildRule, sources, selectedSource, drivers, selectedDriver, method, onPreview])

  const handleSave = useCallback(() => {
    setError(null)
    try {
      const rule = buildRule()
      if (method === 'direct') AllocationEngine.validateDirectRule(rule)
      onSave?.(rule)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Validation failed')
    }
  }, [buildRule, method, onSave])

  // --- Percentage total for direct method ---

  const percentageTotal = targets.reduce((sum, t) => sum + t.percentage, 0)
  const percentageValid = method !== 'direct' || Math.abs(percentageTotal - 100) < 0.01

  // --- Render ---

  return (
    <div
      className={cn(
        'flex flex-col gap-4 p-4 bg-[var(--bg-surface)] rounded-lg border border-[var(--border-subtle)]',
        className
      )}
    >
      {/* Header */}
      <div className="flex items-center gap-2">
        <Settings2 className="h-5 w-5 text-blue-500" />
        <h3 className="text-sm font-semibold text-[var(--text-primary)]">
          Allocation Rule Builder
        </h3>
      </div>

      {/* Rule Name */}
      <label className="flex flex-col gap-1">
        <span className="text-xs font-medium text-slate-400">Rule Name</span>
        <input
          type="text"
          value={ruleName}
          onChange={(e) => setRuleName(e.target.value)}
          placeholder="e.g., Allocate IT Costs by Headcount"
          className="h-9 rounded-md border border-[var(--border-subtle)] bg-[var(--bg-elevated)] px-3 text-sm text-[var(--text-primary)] outline-none focus:ring-2 focus:ring-blue-500"
        />
      </label>

      {/* Source Selection */}
      <label className="flex flex-col gap-1">
        <span className="text-xs font-medium text-slate-400">Source</span>
        <select
          value={selectedSource}
          onChange={(e) => setSelectedSource(e.target.value)}
          className="h-9 rounded-md border border-[var(--border-subtle)] bg-[var(--bg-elevated)] px-3 text-sm text-[var(--text-primary)] outline-none focus:ring-2 focus:ring-blue-500"
        >
          <option value="">Select source...</option>
          {sources.map((s) => (
            <option key={s.id} value={s.id}>
              {s.label} (${s.amount.toLocaleString()})
            </option>
          ))}
        </select>
      </label>

      {/* Method Selection */}
      <label className="flex flex-col gap-1">
        <span className="text-xs font-medium text-slate-400">Method</span>
        <div className="grid grid-cols-2 gap-2">
          {METHOD_OPTIONS.map((opt) => (
            <button
              key={opt.value}
              type="button"
              onClick={() => setMethod(opt.value)}
              className={cn(
                'flex flex-col items-start gap-0.5 rounded-md border p-2.5 text-left transition-colors',
                method === opt.value
                  ? 'border-blue-500 bg-blue-500/10 text-blue-400'
                  : 'border-[var(--border-subtle)] hover:border-gray-400 text-[var(--text-secondary)]'
              )}
            >
              <span className="text-xs font-medium">{opt.label}</span>
              <span className="text-[10px] opacity-70">{opt.description}</span>
            </button>
          ))}
        </div>
      </label>

      {/* Driver Selection (driver method only) */}
      {method === 'driver' && (
        <label className="flex flex-col gap-1">
          <span className="text-xs font-medium text-slate-400">Driver</span>
          <select
            value={selectedDriver}
            onChange={(e) => setSelectedDriver(e.target.value)}
            className="h-9 rounded-md border border-[var(--border-subtle)] bg-[var(--bg-elevated)] px-3 text-sm text-[var(--text-primary)] outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">Select driver...</option>
            {PRESET_DRIVERS.map((d) => (
              <option key={d.id} value={d.id}>
                {d.label}
              </option>
            ))}
            {drivers.map((d) => (
              <option key={d.id} value={d.id}>
                {d.label}
              </option>
            ))}
          </select>
        </label>
      )}

      {/* Targets */}
      <div className="flex flex-col gap-2">
        <div className="flex items-center justify-between">
          <span className="text-xs font-medium text-slate-400">Targets</span>
          <button
            type="button"
            onClick={addTarget}
            disabled={targets.length >= targetOptions.length}
            className="flex items-center gap-1 rounded-md bg-blue-600 px-2 py-1 text-xs font-medium text-white transition-colors hover:bg-blue-700 disabled:opacity-50"
          >
            <Plus className="h-3 w-3" />
            Add Target
          </button>
        </div>

        {targets.length === 0 && (
          <p className="text-xs text-slate-500 italic">
            No targets added yet. Click "Add Target" to begin.
          </p>
        )}

        {targets.map((target) => (
          <div
            key={target.id}
            className="flex items-center gap-2 rounded-md border border-[var(--border-subtle)] bg-[var(--bg-elevated)] p-2"
          >
            <ArrowRight className="h-4 w-4 text-slate-500 shrink-0" />

            {/* Target member select */}
            <select
              value={target.dimensionMember}
              onChange={(e) => updateTarget(target.id, 'dimensionMember', e.target.value)}
              className="flex-1 h-8 rounded border border-[var(--border-subtle)] bg-[var(--bg-surface)] px-2 text-xs text-[var(--text-primary)] outline-none"
            >
              {targetOptions.map((opt) => (
                <option key={opt.id} value={opt.id}>
                  {opt.label}
                </option>
              ))}
            </select>

            {/* Percentage (direct method) */}
            {method === 'direct' && (
              <div className="flex items-center gap-1">
                <input
                  type="number"
                  min={0}
                  max={100}
                  step={0.01}
                  value={target.percentage}
                  onChange={(e) =>
                    updateTarget(target.id, 'percentage', parseFloat(e.target.value) || 0)
                  }
                  className="w-20 h-8 rounded border border-[var(--border-subtle)] bg-[var(--bg-surface)] px-2 text-xs text-[var(--text-primary)] text-right outline-none"
                />
                <span className="text-xs text-slate-500">%</span>
              </div>
            )}

            {/* Driver weight (driver method) */}
            {method === 'driver' && (
              <div className="flex items-center gap-1">
                <span className="text-[10px] text-slate-500">Weight</span>
                <input
                  type="number"
                  min={0}
                  step={0.1}
                  value={target.driverWeight}
                  onChange={(e) =>
                    updateTarget(target.id, 'driverWeight', parseFloat(e.target.value) || 0)
                  }
                  className="w-16 h-8 rounded border border-[var(--border-subtle)] bg-[var(--bg-surface)] px-2 text-xs text-[var(--text-primary)] text-right outline-none"
                />
              </div>
            )}

            {/* Remove button */}
            <button
              type="button"
              onClick={() => removeTarget(target.id)}
              className="p-1 rounded text-slate-500 hover:text-red-500 hover:bg-red-500/10 transition-colors"
            >
              <Trash2 className="h-3.5 w-3.5" />
            </button>
          </div>
        ))}

        {/* Percentage total indicator (direct method) */}
        {method === 'direct' && targets.length > 0 && (
          <div
            className={cn(
              'text-xs font-medium',
              percentageValid ? 'text-green-500' : 'text-red-500'
            )}
          >
            Total: {percentageTotal.toFixed(2)}% {percentageValid ? '✓' : '(must equal 100%)'}
          </div>
        )}
      </div>

      {/* Period & Recurring */}
      <div className="flex items-center gap-4">
        <label className="flex flex-col gap-1 flex-1">
          <span className="text-xs font-medium text-slate-400">Period</span>
          <input
            type="month"
            value={period}
            onChange={(e) => setPeriod(e.target.value)}
            className="h-9 rounded-md border border-[var(--border-subtle)] bg-[var(--bg-elevated)] px-3 text-sm text-[var(--text-primary)] outline-none focus:ring-2 focus:ring-blue-500"
          />
        </label>
        <label className="flex items-center gap-2 mt-5">
          <input
            type="checkbox"
            checked={isRecurring}
            onChange={(e) => setIsRecurring(e.target.checked)}
            className="h-4 w-4 rounded border-[var(--border-default)]"
          />
          <span className="text-xs text-[var(--text-secondary)]">Recurring</span>
        </label>
      </div>

      {/* Error display */}
      {error && (
        <div className="rounded-md bg-red-500/10 border border-red-500/30 px-3 py-2 text-xs text-red-400">
          {error}
        </div>
      )}

      {/* Actions */}
      <div className="flex items-center gap-2 pt-2 border-t border-[var(--border-subtle)]">
        <button
          type="button"
          onClick={handlePreview}
          disabled={!selectedSource || targets.length === 0}
          className="flex items-center gap-1.5 rounded-md bg-blue-600 px-4 py-2 text-xs font-medium text-white transition-colors hover:bg-blue-700 disabled:opacity-50"
        >
          <Play className="h-3.5 w-3.5" />
          Preview
        </button>
        <button
          type="button"
          onClick={handleSave}
          disabled={!selectedSource || targets.length === 0 || !ruleName}
          className="rounded-md border border-[var(--border-subtle)] px-4 py-2 text-xs font-medium text-[var(--text-secondary)] transition-colors hover:border-gray-400 disabled:opacity-50"
        >
          Save Rule
        </button>
      </div>
    </div>
  )
}

import { useMemo, useState } from 'react'
import { cn } from '@/utils/cn'
import { Button } from './Button'
import { Card, CardContent, CardHeader, CardTitle } from './Card'
import { Input } from './Input'
import type { ApprovalRequest, ApprovalState, ApprovalEvent } from '@/engines/WorkflowEngine'

interface Props {
  requests: ApprovalRequest[]
  onApprove: (id: string, comment?: string) => void
  onReject: (id: string, comment?: string) => void
  onBulkApprove: (ids: string[]) => void
  currentUser: string
  className?: string
}

const STATE_BADGES: Record<ApprovalState, string> = {
  draft: 'bg-gray-100 text-gray-700 dark:text-gray-300',
  submitted: 'bg-blue-100 text-blue-700',
  in_review: 'bg-yellow-100 text-yellow-700',
  approved: 'bg-green-100 text-green-700',
  rejected: 'bg-red-100 text-red-700',
  locked: 'bg-purple-100 text-purple-700',
}

export function ApprovalQueue({
  requests,
  onApprove,
  onReject,
  onBulkApprove,
  currentUser: _currentUser,
  className,
}: Props) {
  const [filterState, setFilterState] = useState<ApprovalState | 'all'>('all')
  const [filterDate, setFilterDate] = useState('')
  const [filterRequester, setFilterRequester] = useState('')
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [commentMap, setCommentMap] = useState<Record<string, string>>({})
  const [showHistory, setShowHistory] = useState<string | null>(null)

  const filtered = useMemo(() => {
    return requests.filter((r) => {
      if (filterState !== 'all' && r.state !== filterState) return false
      if (filterDate && !r.createdAt.startsWith(filterDate)) return false
      if (filterRequester && !r.requester.toLowerCase().includes(filterRequester.toLowerCase()))
        return false
      return true
    })
  }, [requests, filterState, filterDate, filterRequester])

  const toggleSelect = (id: string) => {
    const next = new Set(selected)
    if (next.has(id)) next.delete(id)
    else next.add(id)
    setSelected(next)
  }

  const toggleAll = () => {
    if (selected.size === filtered.length) {
      setSelected(new Set())
    } else {
      setSelected(new Set(filtered.map((r) => r.id)))
    }
  }

  const pending = filtered.filter((r) => ['submitted', 'in_review'].includes(r.state))
  const showBulk = pending.length > 0 && selected.size > 0

  return (
    <Card className={cn('w-full', className)}>
      <CardHeader>
        <CardTitle className="flex items-center justify-between">
          <span>Approval Queue</span>
          {showBulk && (
            <Button
              size="sm"
              onClick={() => {
                onBulkApprove(Array.from(selected))
                setSelected(new Set())
              }}
            >
              Bulk Approve ({selected.size})
            </Button>
          )}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Filters */}
        <div className="grid grid-cols-3 gap-3">
          <div>
            <label className="text-xs font-medium">Status</label>
            <select
              value={filterState}
              onChange={(e) => setFilterState(e.target.value as ApprovalState | 'all')}
              className="w-full border rounded px-2 py-1 text-sm"
            >
              <option value="all">All</option>
              <option value="submitted">Submitted</option>
              <option value="in_review">In Review</option>
              <option value="approved">Approved</option>
              <option value="rejected">Rejected</option>
              <option value="locked">Locked</option>
            </select>
          </div>
          <div>
            <label className="text-xs font-medium">Date</label>
            <Input type="date" value={filterDate} onChange={(e) => setFilterDate(e.target.value)} />
          </div>
          <div>
            <label className="text-xs font-medium">Requester</label>
            <Input
              value={filterRequester}
              onChange={(e) => setFilterRequester(e.target.value)}
              placeholder="Search..."
            />
          </div>
        </div>

        {/* Select All */}
        {pending.length > 0 && (
          <label className="flex items-center gap-2 text-sm">
            <input
              type="checkbox"
              checked={selected.size === filtered.length && filtered.length > 0}
              onChange={toggleAll}
            />
            Select all pending
          </label>
        )}

        {/* Request List */}
        <div className="space-y-2 max-h-96 overflow-y-auto">
          {filtered.map((req) => (
            <div key={req.id} className="border rounded-lg p-3 space-y-2">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  {['submitted', 'in_review'].includes(req.state) && (
                    <input
                      type="checkbox"
                      checked={selected.has(req.id)}
                      onChange={() => toggleSelect(req.id)}
                    />
                  )}
                  <span className="font-medium">{req.title}</span>
                  <span className={cn('text-xs px-2 py-0.5 rounded-full', STATE_BADGES[req.state])}>
                    {req.state.replace('_', ' ')}
                  </span>
                </div>
                <div className="flex gap-1 text-xs text-[var(--text-muted)]">
                  <span>{req.requester}</span>
                  <span>&middot;</span>
                  <span>{new Date(req.createdAt).toLocaleDateString()}</span>
                </div>
              </div>

              {req.description && (
                <p className="text-sm text-[var(--text-secondary)]">{req.description}</p>
              )}

              {req.amount !== undefined && (
                <p className="text-sm font-medium">Amount: ${req.amount.toLocaleString()}</p>
              )}

              {/* Actions for pending */}
              {['submitted', 'in_review'].includes(req.state) && (
                <div className="flex items-center gap-2">
                  <Input
                    size={200}
                    value={commentMap[req.id] ?? ''}
                    onChange={(e) => setCommentMap({ ...commentMap, [req.id]: e.target.value })}
                    placeholder="Comment (optional)"
                    className="flex-1"
                  />
                  <Button
                    size="sm"
                    onClick={() => {
                      onApprove(req.id, commentMap[req.id])
                      setCommentMap({ ...commentMap, [req.id]: '' })
                    }}
                  >
                    Approve
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => {
                      onReject(req.id, commentMap[req.id])
                      setCommentMap({ ...commentMap, [req.id]: '' })
                    }}
                  >
                    Reject
                  </Button>
                </div>
              )}

              {/* History Toggle */}
              <button
                onClick={() => setShowHistory(showHistory === req.id ? null : req.id)}
                className="text-xs text-blue-500 hover:text-blue-700"
              >
                {showHistory === req.id ? 'Hide' : 'Show'} History ({req.history.length} events)
              </button>

              {showHistory === req.id && (
                <div className="pl-4 border-l-2 border-[var(--border-subtle)] space-y-1">
                  {req.history.map((evt: ApprovalEvent) => (
                    <div key={evt.id} className="text-xs text-[var(--text-secondary)]">
                      <span className="font-medium">{evt.actor}</span>
                      <span className="mx-1">&middot;</span>
                      <span>{evt.action}</span>
                      {evt.comment && (
                        <span className="ml-1 text-gray-400 dark:text-gray-500">
                          - {evt.comment}
                        </span>
                      )}
                      <span className="ml-1 text-gray-400 dark:text-gray-500">
                        {new Date(evt.timestamp).toLocaleString()}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}

          {filtered.length === 0 && (
            <div className="text-center py-8 text-gray-400 dark:text-gray-500">
              <p>No requests match your filters.</p>
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

import { useState } from 'react'
import { cn } from '@/utils/cn'
import { Button } from './Button'
import { Card, CardContent, CardHeader, CardTitle } from './Card'
import { Input } from './Input'
import type { WorkflowDefinition, WorkflowStep, StepType } from '@/engines/WorkflowEngine'

interface Props {
  onSave: (workflow: WorkflowDefinition) => void
  initial?: WorkflowDefinition
  className?: string
}

export function ApprovalWorkflowDesigner({ onSave, initial, className }: Props) {
  const [name, setName] = useState(initial?.name ?? '')
  const [description, setDescription] = useState(initial?.description ?? '')
  const [steps, setSteps] = useState<WorkflowStep[]>(initial?.steps ?? [])
  const [editingStep, setEditingStep] = useState<number | null>(null)

  const addStep = () => {
    const step: WorkflowStep = {
      id: 'step-' + Date.now(),
      name: 'Step ' + (steps.length + 1),
      type: 'sequential',
      approvers: [],
      order: steps.length,
    }
    setSteps([...steps, step])
    setEditingStep(steps.length)
  }

  const removeStep = (index: number) => {
    setSteps(steps.filter((_, i) => i !== index))
    if (editingStep === index) setEditingStep(null)
  }

  const moveStep = (index: number, dir: -1 | 1) => {
    const newIndex = index + dir
    if (newIndex < 0 || newIndex >= steps.length) return
    const newSteps = [...steps]
    ;[newSteps[index], newSteps[newIndex]] = [newSteps[newIndex], newSteps[index]]
    setSteps(newSteps.map((s, i) => ({ ...s, order: i })))
  }

  const updateStep = (index: number, updates: Partial<WorkflowStep>) => {
    setSteps(steps.map((s, i) => (i === index ? { ...s, ...updates } : s)))
  }

  const handleSave = () => {
    if (!name || steps.length === 0) return
    onSave({
      id: initial?.id ?? '',
      name,
      description,
      steps,
      createdBy: initial?.createdBy ?? 'user',
      createdAt: initial?.createdAt ?? '',
      isTemplate: false,
    })
  }

  return (
    <Card className={cn('w-full', className)}>
      <CardHeader>
        <CardTitle>Workflow Designer</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-sm font-medium">Name</label>
            <Input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Budget Approval"
            />
          </div>
          <div>
            <label className="text-sm font-medium">Description</label>
            <Input
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Approval workflow"
            />
          </div>
        </div>

        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-semibold">Steps</h3>
            <Button size="sm" onClick={addStep}>
              + Add Step
            </Button>
          </div>

          {steps.map((step, idx) => (
            <div
              key={step.id}
              className={cn(
                'border rounded-lg p-3',
                editingStep === idx
                  ? 'border-blue-500 bg-blue-50 dark:bg-blue-950'
                  : 'border-[var(--border-subtle)]'
              )}
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="w-6 h-6 rounded-full bg-blue-500 text-white text-xs flex items-center justify-center">
                    {idx + 1}
                  </span>
                  <span className="font-medium">{step.name}</span>
                  <span className="text-xs text-[var(--text-muted)]">({step.type})</span>
                </div>
                <div className="flex gap-1">
                  <button
                    onClick={() => moveStep(idx, -1)}
                    disabled={idx === 0}
                    className="text-gray-400 dark:text-gray-500 hover:text-[var(--text-secondary)] disabled:opacity-30"
                  >
                    &#8593;
                  </button>
                  <button
                    onClick={() => moveStep(idx, 1)}
                    disabled={idx === steps.length - 1}
                    className="text-gray-400 dark:text-gray-500 hover:text-[var(--text-secondary)] disabled:opacity-30"
                  >
                    &#8595;
                  </button>
                  <button
                    onClick={() => setEditingStep(editingStep === idx ? null : idx)}
                    className="text-blue-500 hover:text-blue-700"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => removeStep(idx)}
                    className="text-red-500 hover:text-red-700"
                  >
                    &times;
                  </button>
                </div>
              </div>

              {editingStep === idx && (
                <div className="mt-3 space-y-3">
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="text-xs font-medium">Step Name</label>
                      <Input
                        value={step.name}
                        onChange={(e) => updateStep(idx, { name: e.target.value })}
                      />
                    </div>
                    <div>
                      <label className="text-xs font-medium">Type</label>
                      <select
                        value={step.type}
                        onChange={(e) => updateStep(idx, { type: e.target.value as StepType })}
                        className="w-full border rounded px-2 py-1 text-sm"
                      >
                        <option value="sequential">Sequential</option>
                        <option value="parallel">Parallel (all must approve)</option>
                      </select>
                    </div>
                  </div>

                  <div>
                    <label className="text-xs font-medium">Approvers (comma-separated)</label>
                    <Input
                      value={step.approvers.join(', ')}
                      onChange={(e) =>
                        updateStep(idx, {
                          approvers: e.target.value
                            .split(',')
                            .map((s) => s.trim())
                            .filter(Boolean),
                        })
                      }
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="text-xs font-medium">Timeout (hours, optional)</label>
                      <Input
                        type="number"
                        value={step.timeoutHours ?? ''}
                        onChange={(e) =>
                          updateStep(idx, {
                            timeoutHours: e.target.value ? Number(e.target.value) : undefined,
                          })
                        }
                      />
                    </div>
                    <div>
                      <label className="text-xs font-medium">Amount Threshold</label>
                      <Input
                        type="number"
                        value={step.condition?.value ?? ''}
                        onChange={(e) =>
                          updateStep(idx, {
                            condition: e.target.value
                              ? { field: 'amount', operator: 'gt', value: Number(e.target.value) }
                              : undefined,
                          })
                        }
                        placeholder="> $10,000 needs VP"
                      />
                    </div>
                  </div>
                </div>
              )}
            </div>
          ))}

          {steps.length === 0 && (
            <div className="text-center py-8 text-gray-400 dark:text-gray-500">
              <p>No steps added yet.</p>
              <p className="text-sm">Click &quot;+ Add Step&quot; to begin.</p>
            </div>
          )}
        </div>

        <div className="flex justify-end gap-2">
          <Button
            variant="outline"
            onClick={() => {
              setSteps([])
              setName('')
              setDescription('')
            }}
          >
            Reset
          </Button>
          <Button onClick={handleSave} disabled={!name || steps.length === 0}>
            Save Workflow
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

import { describe, it, expect, vi } from 'vitest'
import { render, screen, waitFor } from '@testing-library/react'
import { Avatar } from './Avatar'

describe('Avatar', () => {
  it('renders initials when no src provided', () => {
    render(<Avatar fallback="TB" />)
    expect(screen.getByText('TB')).toBeInTheDocument()
  })

  it('renders uppercased initials', () => {
    render(<Avatar fallback="ab" />)
    expect(screen.getByText('AB')).toBeInTheDocument()
  })

  it('renders img when src is provided', () => {
    render(<Avatar src="https://example.com/photo.jpg" alt="User" fallback="U" />)
    const img = screen.getByRole('img')
    expect(img).toHaveAttribute('src', 'https://example.com/photo.jpg')
    expect(img).toHaveAttribute('alt', 'User')
  })

  it('does not render initials when img is shown', () => {
    render(<Avatar src="https://example.com/photo.jpg" fallback="TB" />)
    expect(screen.queryByText('TB')).not.toBeInTheDocument()
  })

  it('falls back to initials on img error', async () => {
    render(<Avatar src="https://example.com/broken.jpg" fallback="TB" />)
    const img = screen.getByRole('img')
    img.dispatchEvent(new Event('error'))
    await waitFor(() => {
      expect(screen.getByText('TB')).toBeInTheDocument()
    })
  })

  it('applies size classes', () => {
    const { rerender } = render(<Avatar fallback="TB" size="sm" />)
    const container = screen.getByText('TB').parentElement!
    expect(container.className).toContain('w-6')

    rerender(<Avatar fallback="TB" size="lg" />)
    expect(container.className).toContain('w-12')
  })

  it('applies custom className', () => {
    render(<Avatar fallback="X" className="my-custom-class" />)
    const container = screen.getByText('X').parentElement!
    expect(container.className).toContain('my-custom-class')
  })

  it('renders with default md size', () => {
    render(<Avatar fallback="TB" />)
    const container = screen.getByText('TB').parentElement!
    expect(container.className).toContain('w-8')
  })
})

import { useState } from 'react'
import { useCallback } from 'react'
import { cn } from '@/utils/cn'
import { Modal } from './Modal'
import { Button } from './Button'
import { Input } from './Input'
import { Select } from './Select'

export type NumberFormat =
  | 'general'
  | 'number'
  | 'currency'
  | 'percent'
  | 'date'
  | 'scientific'
  | 'text'

export interface CellFormat {
  format: NumberFormat
  decimals: number
  useThousandsSeparator: boolean
  currencySymbol: string
  dateFormat: string
  prefix: string
  suffix: string
  negativeStyle: 'minus' | 'parentheses' | 'red'
}

export interface CellFormatterProps {
  isOpen: boolean
  onClose: () => void
  onApply: (format: CellFormat) => void
  currentFormat?: CellFormat
  className?: string
}

const defaultFormat: CellFormat = {
  format: 'general',
  decimals: 2,
  useThousandsSeparator: true,
  currencySymbol: '$',
  dateFormat: 'MM/DD/YYYY',
  prefix: '',
  suffix: '',
  negativeStyle: 'minus',
}

const formatOptions = [
  { value: 'general', label: 'General' },
  { value: 'number', label: 'Number' },
  { value: 'currency', label: 'Currency' },
  { value: 'percent', label: 'Percentage' },
  { value: 'date', label: 'Date' },
  { value: 'scientific', label: 'Scientific' },
  { value: 'text', label: 'Text' },
]

const currencyOptions = [
  { value: '$', label: '$ USD' },
  { value: '€', label: '€ EUR' },
  { value: '£', label: '£ GBP' },
  { value: '¥', label: '¥ JPY' },
  { value: '₹', label: '₹ INR' },
  { value: 'A$', label: 'A$ AUD' },
  { value: 'C$', label: 'C$ CAD' },
  { value: 'CHF', label: 'CHF' },
]

const dateFormatOptions = [
  { value: 'MM/DD/YYYY', label: '12/31/2026' },
  { value: 'DD/MM/YYYY', label: '31/12/2026' },
  { value: 'YYYY-MM-DD', label: '2026-12-31' },
  { value: 'MMM DD, YYYY', label: 'Dec 31, 2026' },
  { value: 'DD MMM YYYY', label: '31 Dec 2026' },
  { value: 'MMMM DD, YYYY', label: 'December 31, 2026' },
]

const negativeStyleOptions = [
  { value: 'minus', label: '-1,234.56' },
  { value: 'parentheses', label: '(1,234.56)' },
  { value: 'red', label: '1,234.56 (red)' },
]

function formatPreview(format: CellFormat): string {
  const sample = 1234.56
  const negSample = -1234.56

  switch (format.format) {
    case 'general':
      return sample.toLocaleString()
    case 'number': {
      const opts: Intl.NumberFormatOptions = {
        minimumFractionDigits: format.decimals,
        maximumFractionDigits: format.decimals,
        useGrouping: format.useThousandsSeparator,
      }
      const formatted = sample.toLocaleString('en-US', opts)
      const negFormatted = negSample.toLocaleString('en-US', opts)
      if (format.negativeStyle === 'parentheses') return `(${negFormatted.replace('-', '')})`
      return formatted
    }
    case 'currency': {
      const opts: Intl.NumberFormatOptions = {
        style: 'currency',
        currency: 'USD',
        minimumFractionDigits: format.decimals,
        maximumFractionDigits: format.decimals,
      }
      return sample.toLocaleString('en-US', opts).replace('$', format.currencySymbol)
    }
    case 'percent':
      return `${(sample * 100).toFixed(format.decimals)}%`
    case 'date':
      return '12/31/2026'
    case 'scientific':
      return sample.toExponential(format.decimals)
    case 'text':
      return String(sample)
    default:
      return String(sample)
  }
}

export function CellFormatter({
  isOpen,
  onClose,
  onApply,
  currentFormat,
  className,
}: CellFormatterProps) {
  const [format, setFormat] = useState<CellFormat>(currentFormat || defaultFormat)

  const updateFormat = useCallback(<K extends keyof CellFormat>(key: K, value: CellFormat[K]) => {
    setFormat((prev) => ({ ...prev, [key]: value }))
  }, [])

  const handleApply = useCallback(() => {
    onApply(format)
    onClose()
  }, [format, onApply, onClose])

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Format Cells"
      className={cn('max-w-md', className)}
    >
      <div className="space-y-4 p-4">
        {/* Format Type */}
        <div>
          <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
            Category
          </label>
          <Select
            options={formatOptions}
            value={format.format}
            onChange={(v) => updateFormat('format', v as NumberFormat)}
          />
        </div>

        {/* Number options */}
        {(format.format === 'number' ||
          format.format === 'currency' ||
          format.format === 'percent' ||
          format.format === 'scientific') && (
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
                Decimal Places
              </label>
              <Input
                type="number"
                min={0}
                max={15}
                value={format.decimals}
                onChange={(e) => updateFormat('decimals', parseInt(e.target.value) || 0)}
              />
            </div>
            <div className="flex items-end">
              <label className="flex items-center gap-2 text-xs cursor-pointer">
                <input
                  type="checkbox"
                  checked={format.useThousandsSeparator}
                  onChange={(e) => updateFormat('useThousandsSeparator', e.target.checked)}
                  className="rounded border-[var(--border-default)]"
                  aria-label="Use thousands separator"
                />
                Thousands separator
              </label>
            </div>
          </div>
        )}

        {/* Currency symbol */}
        {format.format === 'currency' && (
          <div>
            <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
              Symbol
            </label>
            <Select
              options={currencyOptions}
              value={format.currencySymbol}
              onChange={(v) => updateFormat('currencySymbol', v)}
            />
          </div>
        )}

        {/* Date format */}
        {format.format === 'date' && (
          <div>
            <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
              Date Format
            </label>
            <Select
              options={dateFormatOptions}
              value={format.dateFormat}
              onChange={(v) => updateFormat('dateFormat', v)}
            />
          </div>
        )}

        {/* Negative style */}
        {(format.format === 'number' || format.format === 'currency') && (
          <div>
            <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
              Negative Numbers
            </label>
            <Select
              options={negativeStyleOptions}
              value={format.negativeStyle}
              onChange={(v) => updateFormat('negativeStyle', v as CellFormat['negativeStyle'])}
            />
          </div>
        )}

        {/* Prefix/Suffix */}
        {format.format !== 'date' && format.format !== 'text' && (
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
                Prefix
              </label>
              <Input
                value={format.prefix}
                onChange={(e) => updateFormat('prefix', e.target.value)}
                placeholder="e.g., ~"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
                Suffix
              </label>
              <Input
                value={format.suffix}
                onChange={(e) => updateFormat('suffix', e.target.value)}
                placeholder="e.g., units"
              />
            </div>
          </div>
        )}

        {/* Preview */}
        <div
          className="bg-gray-50 dark:bg-gray-900 rounded-md p-3 border border-[var(--border-subtle)]"
          role="status"
          aria-live="polite"
          aria-label="Format preview"
        >
          <div className="text-[10px] font-semibold text-gray-400 dark:text-gray-500 uppercase tracking-wider mb-1">
            Sample
          </div>
          <div className="text-lg font-mono text-[var(--text-primary)] tabular-nums">
            {format.prefix}
            {formatPreview(format)}
            {format.suffix}
          </div>
        </div>

        {/* Actions */}
        <div className="flex justify-end gap-2 pt-2">
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button onClick={handleApply}>Apply</Button>
        </div>
      </div>
    </Modal>
  )
}

import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts'

interface ComboBar {
  key: string
  color?: string
  name: string
}
interface ComboLine {
  key: string
  color?: string
  name: string
}

interface ComboChartProps {
  data: Record<string, unknown>[]
  bars?: ComboBar[]
  lines?: ComboLine[]
  xAxisKey?: string
  xKey?: string
  yKeys?: Array<{ key: string; color: string; name: string }>
  height?: number
  title?: string
  className?: string
  loading?: boolean
  error?: string
  onClick?: (data: Record<string, unknown>) => void
}

export function ComboChart({
  data,
  bars: barsProp,
  lines: linesProp,
  xAxisKey,
  xKey,
  yKeys,
  height = 300,
  title,
  className,
  loading = false,
  error,
  onClick,
}: ComboChartProps) {
  const effectiveXKey = xAxisKey ?? xKey ?? ''
  const bars =
    barsProp ?? (yKeys ? yKeys.map((y) => ({ key: y.key, color: y.color, name: y.name })) : [])
  const lines = linesProp ?? []
  if (loading) {
    return (
      <div className={className}>
        <div className="flex items-center justify-center h-48">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500" />
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className={className}>
        <div className="flex items-center justify-center h-48 text-red-500 text-sm">{error}</div>
      </div>
    )
  }
  if (!data || data.length === 0)
    return <div className="flex items-center justify-center h-48 text-slate-400">No data</div>

  return (
    <div className={className}>
      {title && (
        <h3 className="text-sm font-semibold mb-3" style={{ color: 'var(--text-primary)' }}>
          {title}
        </h3>
      )}
      <ResponsiveContainer width="100%" height={height}>
        <ComposedChart
          data={data}
          margin={{ top: 5, right: 20, left: 10, bottom: 5 }}
          onClick={
            onClick
              ? (e) => {
                  const p = e as unknown as { activePayload?: Array<{ payload?: unknown }> }
                  p?.activePayload?.[0]?.payload &&
                    onClick(p.activePayload[0].payload as Record<string, unknown>)
                }
              : undefined
          }
        >
          <CartesianGrid strokeDasharray="3 3" stroke="var(--border-subtle)" vertical={false} />
          <XAxis dataKey={effectiveXKey} tick={{ fontSize: 11, fill: 'var(--text-muted)' }} />
          <YAxis tick={{ fontSize: 11, fill: 'var(--text-muted)' }} />
          <Tooltip
            contentStyle={{
              borderRadius: '8px',
              border: '1px solid var(--border-default)',
              background: 'var(--bg-surface)',
              fontSize: '12px',
            }}
          />
          <Legend wrapperStyle={{ fontSize: '12px' }} />
          {bars.map((b) => (
            <Bar
              key={b.key}
              dataKey={b.key}
              name={b.name}
              fill={b.color || '#3B82F6'}
              radius={[2, 2, 0, 0]}
              maxBarSize={24}
            />
          ))}
          {lines.map((l) => (
            <Line
              key={l.key}
              dataKey={l.key}
              name={l.name}
              stroke={l.color || '#10B981'}
              strokeWidth={2}
              dot={{ r: 3 }}
            />
          ))}
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  )
}

