      expect(screen.getByLabelText('Replace all')).toBeInTheDocument()
    })

    it('shows close button', () => {
      render(<DataGrid rows={mockRows} columns={mockColumns} enableFindReplace />)
      fireEvent.click(screen.getByLabelText('Find and Replace'))
      expect(screen.getByLabelText('Close find and replace')).toBeInTheDocument()
    })

    it('closes find/replace bar via close button', () => {
      render(<DataGrid rows={mockRows} columns={mockColumns} enableFindReplace />)
      fireEvent.click(screen.getByLabelText('Find and Replace'))
      fireEvent.click(screen.getByLabelText('Close find and replace'))
      expect(screen.queryByRole('search')).not.toBeInTheDocument()
    })

    it('updates find text on input', () => {
      render(<DataGrid rows={mockRows} columns={mockColumns} enableFindReplace />)
      fireEvent.click(screen.getByLabelText('Find and Replace'))
      const input = screen.getByLabelText('Find text')
      fireEvent.change(input, { target: { value: 'Revenue' } })
      expect(input).toHaveValue('Revenue')
    })

    it('updates replace text on input', () => {
      render(<DataGrid rows={mockRows} columns={mockColumns} enableFindReplace />)
      fireEvent.click(screen.getByLabelText('Find and Replace'))
      const input = screen.getByLabelText('Replace text')
      fireEvent.change(input, { target: { value: 'Income' } })
      expect(input).toHaveValue('Income')
    })
  })

  describe('column visibility', () => {
    it('shows column menu when Columns button clicked', () => {
      render(<DataGrid rows={mockRows} columns={mockColumns} enableColumnHiding />)
      fireEvent.click(screen.getByLabelText('Show or hide columns'))
      expect(screen.getByRole('menu')).toBeInTheDocument()
    })

    it('shows all columns in the menu', () => {
      render(<DataGrid rows={mockRows} columns={mockColumns} enableColumnHiding />)
      fireEvent.click(screen.getByLabelText('Show or hide columns'))
      expect(screen.getByText('Name')).toBeInTheDocument()
      expect(screen.getByText('Amount')).toBeInTheDocument()
      expect(screen.getByText('Growth %')).toBeInTheDocument()
    })

    it('columns are checked by default', () => {
      render(<DataGrid rows={mockRows} columns={mockColumns} enableColumnHiding />)
      fireEvent.click(screen.getByLabelText('Show or hide columns'))
      const checkboxes = screen.getAllByRole('menuitemcheckbox')
      checkboxes.forEach((cb) => {
        expect(cb).toHaveAttribute('aria-checked', 'true')
      })
    })
  })

  describe('row grouping', () => {
    it('shows grouping options when Group button clicked', () => {
      render(<DataGrid rows={mockRows} columns={mockColumns} enableRowGrouping />)
      fireEvent.click(screen.getByLabelText('Group rows by column'))
      expect(screen.getByText('No Grouping')).toBeInTheDocument()
    })

    it('shows all columns as grouping options', () => {
      render(<DataGrid rows={mockRows} columns={mockColumns} enableRowGrouping />)
      fireEvent.click(screen.getByLabelText('Group rows by column'))
      expect(screen.getByText('Group by Name')).toBeInTheDocument()
      expect(screen.getByText('Group by Amount')).toBeInTheDocument()
    })
  })

  describe('callbacks', () => {
    it('accepts onCellValueChanged callback', () => {
      const onCellValueChanged = vi.fn()
      render(
        <DataGrid rows={mockRows} columns={mockColumns} onCellValueChanged={onCellValueChanged} />
      )
      expect(screen.getByRole('grid')).toBeInTheDocument()
    })

    it('accepts onSelectionChanged callback', () => {
      const onSelectionChanged = vi.fn()
      render(
        <DataGrid rows={mockRows} columns={mockColumns} onSelectionChanged={onSelectionChanged} />
      )
      expect(screen.getByRole('grid')).toBeInTheDocument()
    })

    it('accepts onUndo callback', () => {
      const onUndo = vi.fn()
      render(<DataGrid rows={mockRows} columns={mockColumns} onUndo={onUndo} />)
      expect(screen.getByRole('grid')).toBeInTheDocument()
    })

    it('accepts onRedo callback', () => {
      const onRedo = vi.fn()
      render(<DataGrid rows={mockRows} columns={mockColumns} onRedo={onRedo} />)
      expect(screen.getByRole('grid')).toBeInTheDocument()
    })
  })

  describe('edge cases', () => {
    it('handles large row count', () => {
      const manyRows = Array.from({ length: 1000 }, (_, i) => ({
        name: `Row ${i}`,
        amount: i * 100,
        growth: i * 0.1,
      }))
      render(<DataGrid rows={manyRows} columns={mockColumns} />)
      expect(screen.getByTestId('ag-grid-mock')).toHaveAttribute('data-row-count', '1000')
    })

    it('handles columns with custom valueFormatter', () => {
      const colsWithFormatter = [
        ...mockColumns,
        {
          field: 'custom',
          headerName: 'Custom',
          valueFormatter: (params: { value: unknown }) => `Formatted: ${params.value}`,
        },
      ]
      render(<DataGrid rows={mockRows} columns={colsWithFormatter} />)
      expect(screen.getByRole('grid')).toBeInTheDocument()
    })

    it('handles columns with pinned property', () => {
      const colsWithPinned = [
        { ...mockColumns[0], pinned: 'left' as const },
        ...mockColumns.slice(1),
      ]
      render(<DataGrid rows={mockRows} columns={colsWithPinned} />)
      expect(screen.getByRole('grid')).toBeInTheDocument()
    })

    it('handles columns with flex property', () => {
      const colsWithFlex = [{ ...mockColumns[0], flex: 1 }, ...mockColumns.slice(1)]
      render(<DataGrid rows={mockRows} columns={colsWithFlex} />)
      expect(screen.getByRole('grid')).toBeInTheDocument()
    })

    it('renders multiple toolbar features simultaneously', () => {
      render(
        <DataGrid
          rows={mockRows}
          columns={mockColumns}
          enableFindReplace
          enableExport
          enableColumnHiding
          enableRowGrouping
        />
      )
      expect(screen.getByLabelText('Find and Replace')).toBeInTheDocument()
      expect(screen.getByLabelText('Export to CSV')).toBeInTheDocument()
      expect(screen.getByLabelText('Show or hide columns')).toBeInTheDocument()
      expect(screen.getByLabelText('Group rows by column')).toBeInTheDocument()
    })

    it('handles rows with null/undefined values', () => {
      const rowsWithNulls = [
        { name: 'Test', amount: null, growth: undefined },
        { name: null, amount: 100, growth: 5 },
      ]
      render(<DataGrid rows={rowsWithNulls} columns={mockColumns} />)
      expect(screen.getByTestId('ag-grid-mock')).toHaveAttribute('data-row-count', '2')
    })
  })
})

import React, { useMemo, useRef, useCallback, useState } from 'react'
import { AgGridReact } from 'ag-grid-react'
import {
  AllCommunityModule,
  ModuleRegistry,
  type ColDef,
  type GridOptions,
  type CellValueChangedEvent,
  type SelectionChangedEvent,
} from 'ag-grid-community'
import { ExcelKeyboardEngine } from '@/engines/ExcelKeyboardEngine'
import { cn } from '@/utils/cn'

ModuleRegistry.registerModules([AllCommunityModule])

export interface DataGridColumn {
  field: string
  headerName: string
  width?: number
  editable?: boolean
  type?: 'number' | 'currency' | 'percent' | 'text'
  valueFormatter?: (params: { value: unknown }) => string
  cellRenderer?: React.ComponentType<unknown> | undefined
  pinned?: 'left' | 'right'
  flex?: number
}

export interface DataGridProps {
  rows: Record<string, unknown>[]
  columns: DataGridColumn[]
  onCellValueChanged?: (event: CellValueChangedEvent) => void
  onSelectionChanged?: (selectedRows: Record<string, unknown>[]) => void
  onUndo?: () => void
  onRedo?: () => void
  gridOptions?: GridOptions
  loading?: boolean
  className?: string
  enableFindReplace?: boolean
  enableExport?: boolean
  enableColumnHiding?: boolean
  enableRowGrouping?: boolean
}

export const DataGrid: React.FC<DataGridProps> = ({
  rows,
  columns,
  onCellValueChanged,
  onSelectionChanged,
  onUndo,
  onRedo,
  gridOptions,
  loading = false,
  className,
  enableFindReplace = false,
  enableExport = false,
  enableColumnHiding = false,
  enableRowGrouping = false,
}) => {
  const gridRef = useRef<AgGridReact>(null)
  const [selectedCell, setSelectedCell] = useState<{ row: number; col: number } | null>(null)
  const [isEditing, setIsEditing] = useState(false)
  const [showFindReplace, setShowFindReplace] = useState(false)
  const [findText, setFindText] = useState('')
  const [replaceText, setReplaceText] = useState('')
  const [showColumnMenu, setShowColumnMenu] = useState(false)
  const [hiddenColumns, setHiddenColumns] = useState<Set<string>>(new Set())
  const [groupColumn, setGroupColumn] = useState<string | null>(null)

  const defaultColDef = useMemo<ColDef>(
    () => ({
      sortable: true,
      filter: true,
      resizable: true,
      suppressMovable: false,
      headerClass: 'font-semibold text-[var(--text-secondary)]',
    }),
    []
  )

  const columnDefs = useMemo<ColDef[]>(() => {
    return columns.map((col) => {
      const colDef: ColDef = {
        field: col.field,
        headerName: col.headerName,
        headerTooltip: `Sort by ${col.headerName}`, // Fallback for aria-label in some ATs
        width: col.width,
        editable: col.editable,
        pinned: col.pinned,
        flex: col.flex,
        valueFormatter: col.valueFormatter,
        cellRenderer: col.cellRenderer,
      }

      if (col.type === 'currency' || col.type === 'number' || col.type === 'percent') {
        colDef.cellClass = 'text-right tabular-nums'
        colDef.headerClass = 'text-right font-semibold text-[var(--text-secondary)]'

        if (!col.valueFormatter) {
          if (col.type === 'currency') {
            colDef.valueFormatter = (params) => {
              if (params.value === null || params.value === undefined) return ''
              return new Intl.NumberFormat('en-US', {
                style: 'currency',
                currency: 'USD',
                minimumFractionDigits: 0,
                maximumFractionDigits: 0,
              }).format(params.value)
            }
          } else if (col.type === 'percent') {
            colDef.valueFormatter = (params) => {
              if (params.value === null || params.value === undefined) return ''
              return new Intl.NumberFormat('en-US', {
                style: 'percent',
                minimumFractionDigits: 1,
                maximumFractionDigits: 1,
              }).format(params.value / 100)
            }
            colDef.cellClassRules = {
              'fin-positive font-medium': (params) => {
                const val = Number(params.value)
                return !isNaN(val) && val > 0
              },
              'fin-negative font-medium': (params) => {
                const val = Number(params.value)
                return !isNaN(val) && val < 0
              },
            }
          }
        }
      }

      return colDef
    })
  }, [columns])

  // Selection aggregation (Sum/Avg/Count/Min/Max)
  const [selectionStats, setSelectionStats] = useState<{
    sum: number
    avg: number
    count: number
    min: number
    max: number
  } | null>(null)

  const updateSelectionStats = useCallback(() => {
    if (!gridRef.current) {
      setSelectionStats(null)
      return
    }
    const selected = gridRef.current.api.getSelectedRows()
    if (!selected.length) {
      setSelectionStats(null)
      return
    }
    const numericValues = selected
      .flatMap((row) =>
        columns
          .filter((c) => c.type === 'currency' || c.type === 'number' || c.type === 'percent')
          .map((c) => row[c.field])
      )
      .filter((v): v is number => typeof v === 'number' && Number.isFinite(v))
    if (!numericValues.length) {
      setSelectionStats(null)
      return
    }
    const sum = numericValues.reduce((a, b) => a + b, 0)
    setSelectionStats({
      sum,
      avg: sum / numericValues.length,
      count: numericValues.length,
      min: Math.min(...numericValues),
      max: Math.max(...numericValues),
    })
  }, [columns])

  const handleSelectionChanged = useCallback(
    (event: SelectionChangedEvent) => {
      if (onSelectionChanged) {
        onSelectionChanged(event.api.getSelectedRows())
      }
      updateSelectionStats()
    },
    [onSelectionChanged, updateSelectionStats]
  )

  // Find & Replace
  const escapeRegex = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

  const handleFind = useCallback(() => {
    if (!gridRef.current || !findText) return
    gridRef.current.api.setGridOption('quickFilterText', findText)
  }, [findText])

  const handleReplace = useCallback(() => {
    if (!gridRef.current || !findText) return
    const api = gridRef.current.api
    const escaped = escapeRegex(findText)
    api.forEachNode((node) => {
      if (node.data) {
        columns.forEach((col) => {
          const val = String(node.data[col.field] ?? '')
          if (val.toLowerCase().includes(findText.toLowerCase())) {
            node.setDataValue(col.field, val.replace(new RegExp(escaped, 'gi'), replaceText))
          }
        })
      }
    })
  }, [findText, replaceText, columns])

  // Export to CSV
  const handleExport = useCallback(() => {
    if (!gridRef.current) return
    const visibleCols = columns.filter((c) => !hiddenColumns.has(c.field))
    const header = visibleCols.map((c) => c.headerName).join(',')
    const dataRows = rows.map((row) =>
      visibleCols
        .map((c) => {
          const val = row[c.field]
          if (typeof val === 'string' && val.includes(',')) return `"${val}"`
          return String(val ?? '')
        })
        .join(',')
    )
    const csv = [header, ...dataRows].join('\n')
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = 'export.csv'
    a.click()
    URL.revokeObjectURL(url)
  }, [columns, rows, hiddenColumns])

  // Column hiding
  const toggleColumn = useCallback((field: string) => {
    setHiddenColumns((prev) => {
      const next = new Set(prev)
      if (next.has(field)) next.delete(field)
      else next.add(field)
      return next
    })
  }, [])

  // Row grouping
  const handleGroupBy = useCallback((field: string | null) => {
    setGroupColumn(field)
  }, [])

  const handleKeyDown = useCallback(
    async (e: React.KeyboardEvent) => {
      if (!gridRef.current || !selectedCell) return

      // Ctrl+F for find
      if ((e.ctrlKey || e.metaKey) && e.key === 'f' && enableFindReplace) {
        e.preventDefault()
        setShowFindReplace(true)
        return
      }

      // Escape to close find/replace
      if (e.key === 'Escape') {
        if (showFindReplace) {
          setShowFindReplace(false)
          gridRef.current.api.setGridOption('quickFilterText', '')
          return
        }
        if (showColumnMenu) {
          setShowColumnMenu(false)
          return
        }
      }

      const action = ExcelKeyboardEngine.handleKey(
        e.key,
        { ctrl: e.ctrlKey, shift: e.shiftKey, alt: e.altKey },
        {
          selectedCell,
          selectedRange: null,
          activeRow: selectedCell.row,
          activeCol: selectedCell.col,
          totalRows: rows.length,
          totalCols: columns.length,
          isEditing,
        }
      )

      switch (action.type) {
        case 'move': {
          const { row, col } = action.payload as { row: number; col: number }
          if (row >= 0 && row < rows.length && col >= 0 && col < columns.length) {
            setSelectedCell({ row, col })
            gridRef.current.api.setFocusedCell(row, columns[col].field)
          }
          break
        }
        case 'edit': {
          setIsEditing(true)
          gridRef.current.api.startEditingCell({
            rowIndex: selectedCell.row,
            colKey: columns[selectedCell.col].field,
          })
          break
        }
        case 'copy': {
          const selectedNodes = gridRef.current.api.getSelectedNodes()
          const tsv = selectedNodes
            .map((node) => columns.map((c) => node.data[c.field]).join('\t'))
            .join('\n')
          await navigator.clipboard.writeText(tsv)
          e.preventDefault()
          break
        }
        case 'paste': {
          const text = await navigator.clipboard.readText()
          if (!text) break
          // Paste handled by parent callback
          break
        }
        case 'undo':
          onUndo?.()
          break
        case 'redo':
          onRedo?.()
          break
      }
    },
    [
      selectedCell,
      rows.length,
      columns,
      isEditing,
      onUndo,
      onRedo,
      showFindReplace,
      showColumnMenu,
      enableFindReplace,
    ]
  )

  // Column definitions with hiding support
  const visibleColumnDefs = useMemo<ColDef[]>(() => {
    const defs = columnDefs.filter((col) => !hiddenColumns.has(col.field ?? ''))
    if (groupColumn) {
      return [
        { field: groupColumn, rowGroup: true, hide: true },
        ...defs.filter((c) => c.field !== groupColumn),
      ]
    }
    return defs
  }, [columnDefs, hiddenColumns, groupColumn])

  const mergedGridOptions = useMemo<GridOptions>(
    () => ({
      rowHeight: 32,
      headerHeight: 40,
      animateRows: true,
      rowSelection: { mode: 'multiRow' },
      suppressCellFocus: false,
      enableCellTextSelection: true,
      // Virtual scrolling configuration for large datasets
      suppressRowVirtualisation: false,
      suppressColumnVirtualisation: false,
      rowBuffer: 10,
      cacheBlockSize: 100,
      maxBlocksInCache: 10,
      suppressAnimationFrame: false,
      suppressBrowserResizeObserver: false,
      groupDisplayType: 'groupRows',
      onCellClicked: (params) => {
        if (params.rowIndex !== null) {
          const colIndex = columns.findIndex((c) => c.field === params.column.getColId())
          setSelectedCell({ row: params.rowIndex, col: colIndex })
        }
      },
      onCellEditingStarted: () => setIsEditing(true),
      onCellEditingStopped: () => setIsEditing(false),
      ...gridOptions,
    }),
    [gridOptions, columns]
  )

  return (
    <div
      className={cn(
        'data-grid w-full h-[500px] border border-[var(--border-subtle)] rounded-lg overflow-hidden shadow-sm relative focus:outline-none focus:ring-2 focus:ring-blue-500/20',
        loading && 'opacity-50 pointer-events-none grayscale',
        className
      )}
      tabIndex={0}
      onKeyDown={handleKeyDown}
      role="grid"
      aria-label="Financial Data Grid"
      aria-rowcount={rows.length}
      aria-colcount={columns.length}
      aria-busy={loading}
    >
      {/* Toolbar */}
      {(enableFindReplace || enableExport || enableColumnHiding || enableRowGrouping) && (
        <div className="flex items-center gap-2 px-2 py-1 bg-[var(--bg-muted)] border-b border-[var(--border-subtle)] text-xs">
          {enableFindReplace && (
            <button
              onClick={() => setShowFindReplace(!showFindReplace)}
              className="px-2 py-1 rounded hover:bg-[var(--bg-surface)] transition-colors"
              aria-label="Find and Replace"
              title="Find & Replace (Ctrl+F)"
            >
              Find
            </button>
          )}
          {enableExport && (
            <button
              onClick={handleExport}
              className="px-2 py-1 rounded hover:bg-[var(--bg-surface)] transition-colors"
              aria-label="Export to CSV"
              title="Export CSV"
            >
              Export
            </button>
          )}
          {enableColumnHiding && (
            <div className="relative">
              <button
                onClick={() => setShowColumnMenu(!showColumnMenu)}
                className="px-2 py-1 rounded hover:bg-[var(--bg-surface)] transition-colors"
                aria-label="Show or hide columns"
                aria-expanded={showColumnMenu}
                title="Column Visibility"
              >
                Columns
              </button>
              {showColumnMenu && (
                <div
                  className="absolute top-full left-0 z-50 mt-1 w-48 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-md shadow-lg"
                  role="menu"
                >
                  {columns.map((col) => (
                    <label
                      key={col.field}
                      className="flex items-center gap-2 px-3 py-1.5 hover:bg-[var(--bg-muted)] cursor-pointer"
                      role="menuitemcheckbox"
                      aria-checked={!hiddenColumns.has(col.field)}
                    >
                      <input
                        type="checkbox"
                        checked={!hiddenColumns.has(col.field)}
                        onChange={() => toggleColumn(col.field)}
                        className="rounded"
                      />
                      <span>{col.headerName}</span>
                    </label>
                  ))}
                </div>
              )}
            </div>
          )}
          {enableRowGrouping && (
            <div className="relative">
              <button
                onClick={() => setShowColumnMenu(!showColumnMenu)}
                className="px-2 py-1 rounded hover:bg-[var(--bg-surface)] transition-colors"
                aria-label="Group rows by column"
                title="Row Grouping"
              >
                Group {groupColumn ? `(${groupColumn})` : ''}
              </button>
              {showColumnMenu && (
                <div
                  className="absolute top-full left-0 z-50 mt-1 w-48 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-md shadow-lg"
                  role="menu"
                >
                  <button
                    onClick={() => {
                      handleGroupBy(null)
                      setShowColumnMenu(false)
                    }}
                    className="block w-full text-left px-3 py-1.5 hover:bg-[var(--bg-muted)]"
                    role="menuitem"
                  >
                    No Grouping
                  </button>
                  {columns.map((col) => (
                    <button
                      key={col.field}
                      onClick={() => {
                        handleGroupBy(col.field)
                        setShowColumnMenu(false)
                      }}
                      className="block w-full text-left px-3 py-1.5 hover:bg-[var(--bg-muted)]"
                      role="menuitem"
                    >
                      Group by {col.headerName}
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Find & Replace Bar */}
      {showFindReplace && enableFindReplace && (
        <div
          className="flex items-center gap-2 px-3 py-2 bg-[var(--bg-muted)] border-b border-[var(--border-subtle)]"
          role="search"
          aria-label="Find and Replace"
        >
          <input
            type="text"
            value={findText}
            onChange={(e) => setFindText(e.target.value)}
            placeholder="Find..."
            className="px-2 py-1 text-sm border border-[var(--border-subtle)] rounded w-40"
            aria-label="Find text"
            autoFocus
          />
          <button
            onClick={handleFind}
            className="px-2 py-1 text-sm bg-blue-600 text-white rounded hover:bg-blue-700"
            aria-label="Search"
          >
            Search
          </button>
          <input
            type="text"
            value={replaceText}
            onChange={(e) => setReplaceText(e.target.value)}
            placeholder="Replace..."
            className="px-2 py-1 text-sm border border-[var(--border-subtle)] rounded w-40"
            aria-label="Replace text"
          />
          <button
            onClick={handleReplace}
            className="px-2 py-1 text-sm bg-gray-600 text-white rounded hover:bg-gray-700"
            aria-label="Replace all"
          >
            Replace All
          </button>
          <button
            onClick={() => {
              setShowFindReplace(false)
              gridRef.current?.api.setGridOption('quickFilterText', '')
            }}
            className="px-2 py-1 text-sm hover:bg-[var(--bg-surface)] rounded"
            aria-label="Close find and replace"
          >
            ✕
          </button>
        </div>
      )}

      <AgGridReact
        ref={gridRef}
        rowData={rows}
        columnDefs={visibleColumnDefs}
        defaultColDef={defaultColDef}
        onCellValueChanged={onCellValueChanged}
        onSelectionChanged={handleSelectionChanged}
        gridOptions={mergedGridOptions}
      />
      {loading && (
        <div
          className="absolute inset-0 flex items-center justify-center bg-[var(--bg-overlay)] backdrop-blur-[1px] z-50"
          role="status"
          aria-live="polite"
        >
          <div className="flex flex-col items-center">
            <div
              className="w-8 h-8 border-4 border-[var(--border-subtle)] border-t-[var(--accent-primary)] rounded-full animate-spin"
              aria-hidden="true"
            />
            <span className="mt-2 text-xs font-semibold text-[var(--accent-primary)]">
              Loading Grid...
            </span>
          </div>
        </div>
      )}

      {/* Status Bar — Selection Aggregation */}
      {selectionStats && (
        <div
          className="flex items-center gap-4 px-3 py-1 bg-[var(--bg-muted)] border-t border-[var(--border-subtle)] text-xs text-[var(--text-secondary)]"
          role="status"
          aria-live="polite"
        >
          <span>
            Count: <strong>{selectionStats.count}</strong>
          </span>
          <span>
            Sum:{' '}
            <strong>
              {new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(
                selectionStats.sum
              )}
            </strong>
          </span>
          <span>
            Average:{' '}
            <strong>
              {new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(
                selectionStats.avg
              )}
            </strong>
          </span>
          <span>
            Min:{' '}
            <strong>
              {new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(
                selectionStats.min
              )}
            </strong>
          </span>
          <span>
            Max:{' '}
            <strong>
              {new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(
                selectionStats.max
              )}
            </strong>
          </span>
        </div>
      )}
    </div>
  )
}

import React, { useState, useMemo, useRef } from 'react'
import { ChevronUp, ChevronDown, AlertCircle, Search } from 'lucide-react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { cn } from '@/utils/cn'

import { Skeleton } from './Skeleton'

export interface Column {
  key: string
  header: string
  sortable?: boolean
  filterable?: boolean
  render?: (value: unknown, row: Record<string, unknown>) => React.ReactNode
  width?: string
  align?: 'left' | 'right' | 'center'
  frozen?: boolean
}

export interface DataTableProps {
  columns: Column[]
  data: unknown[]
  sortable?: boolean
  filterable?: boolean
  onRowClick?: (row: Record<string, unknown>) => void
  onReorder?: (fromIndex: number, toIndex: number) => void
  pageSize?: number
  emptyMessage?: string
  loading?: boolean
  error?: string
  className?: string
}

const VIRTUAL_THRESHOLD = 100
const ROW_HEIGHT = 40

export const DataTable: React.FC<DataTableProps> = ({
  columns,
  data: rawData,
  sortable: globalSortable = true,
  filterable: globalFilterable = false,
  onRowClick,
  pageSize = 50,
  emptyMessage = 'No data available',
  loading = false,
  error,
  className,
}) => {
  const data = rawData as Record<string, unknown>[]
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' } | null>(
    null
  )
  const [filters, setFilters] = useState<Record<string, string>>({})
  const [currentPage, setCurrentPage] = useState(1)
  const scrollRef = useRef<HTMLDivElement>(null)

  // Handle sorting
  const sortedData = useMemo(() => {
    const items = [...data]
    if (sortConfig !== null) {
      items.sort((a, b) => {
        const aValue = String(a[sortConfig.key] ?? '')
        const bValue = String(b[sortConfig.key] ?? '')

        if (aValue < bValue) {
          return sortConfig.direction === 'asc' ? -1 : 1
        }
        if (aValue > bValue) {
          return sortConfig.direction === 'asc' ? 1 : -1
        }
        return 0
      })
    }
    return items
  }, [data, sortConfig])

  // Handle filtering
  const filteredData = useMemo(() => {
    return sortedData.filter((item) => {
      return Object.entries(filters).every(([key, value]) => {
        if (!value) return true
        const itemValue = item[key]
        return String(itemValue).toLowerCase().includes(value.toLowerCase())
      })
    })
  }, [sortedData, filters])

  // Virtual scrolling for large datasets
  const useVirtual = filteredData.length > VIRTUAL_THRESHOLD

  const virtualizer = useVirtual
    ? useVirtualizer({
        count: filteredData.length,
        getScrollElement: () => scrollRef.current,
        estimateSize: () => ROW_HEIGHT,
        overscan: 10,
      })
    : null

  // Handle pagination (simple internal) — disabled when virtual scrolling
  const paginatedData = useMemo(() => {
    if (useVirtual) return filteredData
    const startIndex = (currentPage - 1) * pageSize
    return filteredData.slice(startIndex, startIndex + pageSize)
  }, [filteredData, currentPage, pageSize, useVirtual])

  const requestSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc'
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc'
    }
    setSortConfig({ key, direction })
  }

  const handleFilterChange = (key: string, value: string) => {
    setFilters((prev) => ({ ...prev, [key]: value }))
    setCurrentPage(1) // Reset to first page when filtering
  }

  if (error) {
    return (
      <div
        className={cn(
          'flex flex-col items-center justify-center p-8 rounded-lg border border-red-100 bg-red-50 fin-negative dark:border-red-900 dark:bg-red-950',
          className
        )}
      >
        <AlertCircle className="h-10 w-10 mb-2" />
        <h3 className="font-semibold text-lg">Error loading data</h3>
        <p className="text-sm opacity-90">{error}</p>
        <button
          onClick={() => window.location.reload()}
          className="mt-4 px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors text-sm font-medium"
        >
          Retry
        </button>
      </div>
    )
  }

  // Render a single row (shared between virtual and paginated modes)
  const renderRow = (row: Record<string, unknown>, rowIdx: number) => (
    <tr
      key={String(row.id ?? rowIdx)}
      className={cn(
        'transition-colors hover:bg-gray-50 dark:bg-gray-900/50 dark:hover:bg-gray-700/50 group',
        onRowClick && 'cursor-pointer'
      )}
      onClick={() => onRowClick?.(row)}
    >
      {columns.map((column) => (
        <td
          key={column.key}
          className={cn(
            'px-4 py-3 text-[var(--text-primary)] whitespace-nowrap',
            column.align === 'right' && 'text-right',
            column.align === 'center' && 'text-center'
          )}
        >
          {column.render ? column.render(row[column.key], row) : String(row[column.key] ?? '')}
        </td>
      ))}
    </tr>
  )

  // Virtual scrolling body
  const renderVirtualBody = () => {
    if (!virtualizer) return null
    const virtualItems = virtualizer.getVirtualItems()
    const totalSize = virtualizer.getTotalSize()
    const paddingTop = virtualItems.length > 0 ? virtualItems[0].start : 0
    const paddingBottom =
      virtualItems.length > 0 ? totalSize - virtualItems[virtualItems.length - 1].end : 0

    return (
      <tbody className="divide-y divide-[var(--border-subtle)]">
        {paddingTop > 0 && (
          <tr>
            <td colSpan={columns.length} style={{ height: paddingTop }} />
          </tr>
        )}
        {virtualItems.map((virtualRow) => {
          const row = filteredData[virtualRow.index]
          return (
            <tr
              key={String(row.id ?? virtualRow.index)}
              className={cn(
                'transition-colors hover:bg-gray-50 dark:bg-gray-900/50 dark:hover:bg-gray-700/50 group',
                onRowClick && 'cursor-pointer'
              )}
              onClick={() => onRowClick?.(row)}
              data-index={virtualRow.index}
            >
              {columns.map((column) => (
                <td
                  key={column.key}
                  className={cn(
                    'px-4 py-3 text-[var(--text-primary)] whitespace-nowrap',
                    column.align === 'right' && 'text-right',
                    column.align === 'center' && 'text-center'
                  )}
                >
                  {column.render
                    ? column.render(row[column.key], row)
                    : String(row[column.key] ?? '')}
                </td>
              ))}
            </tr>
          )
        })}
        {paddingBottom > 0 && (
          <tr>
            <td colSpan={columns.length} style={{ height: paddingBottom }} />
          </tr>
        )}
      </tbody>
    )
  }

  // Paginated body (original behavior)
  const renderPaginatedBody = () => (
    <tbody className="divide-y divide-[var(--border-subtle)]">
      {loading ? (
        Array.from({ length: 5 }).map((_, idx) => (
          <tr key={idx}>
            {columns.map((col) => (
              <td key={col.key} className="px-4 py-4">
                <Skeleton className="h-4 w-full" />
              </td>
            ))}
          </tr>
        ))
      ) : filteredData.length === 0 ? (
        <tr>
          <td
            colSpan={columns.length}
            className="px-4 py-12 text-center text-[var(--text-secondary)]"
          >
            <div className="flex flex-col items-center">
              <Search className="h-10 w-10 mb-2 opacity-20" />
              <p>{emptyMessage}</p>
            </div>
          </td>
        </tr>
      ) : (
        paginatedData.map((row, rowIdx) => renderRow(row, rowIdx))
      )}
    </tbody>
  )

  return (
    <div className={cn('w-full flex flex-col', className)}>
      <div
        ref={useVirtual ? scrollRef : undefined}
        className={cn(
          'overflow-x-auto rounded-lg border border-[var(--border-subtle)] shadow-sm',
          useVirtual && 'max-h-[600px] overflow-y-auto'
        )}
      >
        <table className="w-full text-sm text-left border-collapse bg-[var(--bg-surface)]">
          <thead className="bg-gray-50 dark:bg-gray-900/80 dark:bg-gray-800/80 border-b border-[var(--border-subtle)] sticky top-0 z-10">
            <tr>
              {columns.map((column) => {
                const isSortable = globalSortable && column.sortable !== false
                const isSorted = sortConfig?.key === column.key

                return (
                  <th
                    key={column.key}
                    style={{ width: column.width }}
                    className={cn(
                      'px-4 py-3 font-semibold text-[var(--text-secondary)] transition-colors',
                      isSortable &&
                        'cursor-pointer hover:bg-[var(--bg-hover)] dark:hover:bg-gray-700 select-none'
                    )}
                    onClick={() => isSortable && requestSort(column.key)}
                  >
                    <div
                      className={cn(
                        'flex items-center space-x-1',
                        column.align === 'right' && 'justify-end',
                        column.align === 'center' && 'justify-center'
                      )}
                    >
                      <span>{column.header}</span>
                      {isSortable && (
                        <div className="flex flex-col">
                          <ChevronUp
                            className={cn(
                              'h-3 w-3 -mb-1',
                              isSorted && sortConfig?.direction === 'asc'
                                ? 'text-blue-600'
                                : 'text-gray-300'
                            )}
                          />
                          <ChevronDown
                            className={cn(
                              'h-3 w-3',
                              isSorted && sortConfig?.direction === 'desc'
                                ? 'text-blue-600'
                                : 'text-gray-300'
                            )}
                          />
                        </div>
                      )}
                    </div>
                    {globalFilterable && column.filterable !== false && (
                      <div
                        className="mt-2"
                        onClick={(e) => e.stopPropagation()}
                        onKeyDown={(e) => e.stopPropagation()}
                        role="presentation"
                      >
                        <div className="relative">
                          <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3 w-3 text-gray-400 dark:text-gray-500" />
                          <input
                            type="text"
                            className="w-full pl-7 pr-2 py-1 bg-white dark:bg-gray-800 dark:bg-gray-800 border border-[var(--border-subtle)] rounded text-xs outline-none focus:ring-1 focus:ring-blue-500 font-normal dark:text-white"
                            placeholder="Filter..."
                            value={filters[column.key] || ''}
                            onChange={(e) => handleFilterChange(column.key, e.target.value)}
                          />
                        </div>
                      </div>
                    )}
                  </th>
                )
              })}
            </tr>
          </thead>
          {useVirtual ? renderVirtualBody() : renderPaginatedBody()}
        </table>
      </div>

      {useVirtual && !loading && (
        <div className="mt-2 text-xs text-[var(--text-secondary)] text-center">
          Showing all {filteredData.length.toLocaleString()} rows (virtual scrolling)
        </div>
      )}

      {!loading && !useVirtual && filteredData.length > pageSize && (
        <div className="mt-4 flex items-center justify-between text-xs text-[var(--text-secondary)]">
          <span>
            Showing {Math.min(filteredData.length, (currentPage - 1) * pageSize + 1)} to{' '}
            {Math.min(filteredData.length, currentPage * pageSize)} of {filteredData.length} entries
          </span>
          <div className="flex items-center space-x-1">
            <button
              disabled={currentPage === 1}
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              className="px-2 py-1 rounded border border-[var(--border-subtle)] hover:bg-gray-50 dark:bg-gray-900 dark:hover:bg-gray-700 disabled:opacity-50 transition-colors"
            >
              Previous
            </button>
            <span className="px-3 font-medium text-[var(--text-primary)]">
              Page {currentPage} of {Math.ceil(filteredData.length / pageSize)}
            </span>
            <button
              disabled={currentPage >= Math.ceil(filteredData.length / pageSize)}
              onClick={() => setCurrentPage((p) => p + 1)}
              className="px-2 py-1 rounded border border-[var(--border-subtle)] hover:bg-gray-50 dark:bg-gray-900 dark:hover:bg-gray-700 disabled:opacity-50 transition-colors"
            >
              Next
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

import React, { useState, useCallback, useRef, useEffect } from 'react'
import { cn } from '@/utils/cn'

export type FillMode = 'copy' | 'series' | 'linear' | 'growth'

export interface DragFillProps {
  /** Starting value(s) for the fill */
  values: (number | string)[]
  /** Called when fill completes with generated values */
  onFill: (values: (number | string)[], count: number) => void
  /** Number of cells to fill */
  fillCount?: number
  /** Direction of fill */
  direction?: 'down' | 'right'
  /** Visual position of the handle */
  className?: string
}

interface FillSuggestion {
  mode: FillMode
  label: string
  values: (number | string)[]
}

function detectFillPattern(values: (number | string)[]): FillMode {
  if (values.length < 2) return 'copy'

  const nums = values.filter((v): v is number => typeof v === 'number')
  if (nums.length < 2) return 'copy'

  // Check for arithmetic series (constant difference)
  const diffs: number[] = []
  for (let i = 1; i < nums.length; i++) {
    diffs.push(nums[i] - nums[i - 1])
  }
  const allSameDiff = diffs.every((d) => Math.abs(d - diffs[0]) < 0.0001)
  if (allSameDiff && diffs[0] !== 0) return 'linear'

  // Check for geometric series (constant ratio)
  const ratios: number[] = []
  for (let i = 1; i < nums.length; i++) {
    if (nums[i - 1] !== 0) {
      ratios.push(nums[i] / nums[i - 1])
    }
  }
  const allSameRatio = ratios.length > 0 && ratios.every((r) => Math.abs(r - ratios[0]) < 0.0001)
  if (allSameRatio && ratios[0] !== 1) return 'growth'

  return 'copy'
}

function generateFillValues(
  values: (number | string)[],
  mode: FillMode,
  count: number
): (number | string)[] {
  const result: (number | string)[] = []

  if (mode === 'copy') {
    for (let i = 0; i < count; i++) {
      result.push(values[i % values.length])
    }
  } else if (mode === 'linear' && values.length >= 2) {
    const nums = values.filter((v): v is number => typeof v === 'number')
    if (nums.length >= 2) {
      const diff = nums[nums.length - 1] - nums[nums.length - 2]
      const lastNum = nums[nums.length - 1]
      for (let i = 0; i < count; i++) {
        result.push(lastNum + diff * (i + 1))
      }
    }
  } else if (mode === 'growth' && values.length >= 2) {
    const nums = values.filter((v): v is number => typeof v === 'number')
    if (nums.length >= 2 && nums[nums.length - 2] !== 0) {
      const ratio = nums[nums.length - 1] / nums[nums.length - 2]
      const lastNum = nums[nums.length - 1]
      for (let i = 0; i < count; i++) {
        result.push(lastNum * Math.pow(ratio, i + 1))
      }
    }
  } else {
    // Fallback to copy
    for (let i = 0; i < count; i++) {
      result.push(values[i % values.length])
    }
  }

  return result
}

export function DragFill({
  values,
  onFill,
  fillCount = 10,
  direction = 'down',
  className,
}: DragFillProps) {
  const [isDragging, setIsDragging] = useState(false)
  const [showMenu, setShowMenu] = useState(false)
  const handleRef = useRef<HTMLDivElement>(null)

  const pattern = detectFillPattern(values)

  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      e.preventDefault()
      setIsDragging(true)

      // Quick drag = auto-fill with detected pattern
      const startX = e.clientX
      const startY = e.clientY

      const handleMouseMove = (moveE: MouseEvent) => {
        const distance =
          direction === 'down' ? Math.abs(moveE.clientY - startY) : Math.abs(moveE.clientX - startX)

        if (distance > 20) {
          // Threshold reached, auto-fill
          const generated = generateFillValues(values, pattern, fillCount)
          onFill(generated, fillCount)
          cleanup()
        }
      }

      const handleMouseUp = () => {
        // Short click = show mode menu
        setShowMenu(true)
        cleanup()
      }

      const cleanup = () => {
        setIsDragging(false)
        document.removeEventListener('mousemove', handleMouseMove)
        document.removeEventListener('mouseup', handleMouseUp)
      }

      document.addEventListener('mousemove', handleMouseMove)
      document.addEventListener('mouseup', handleMouseUp)
    },
    [values, fillCount, direction, pattern, onFill]
  )

  const handleModeSelect = useCallback(
    (mode: FillMode) => {
      const generated = generateFillValues(values, mode, fillCount)
      onFill(generated, fillCount)
      setShowMenu(false)
    },
    [values, fillCount, onFill]
  )

  // Close menu on outside click
  useEffect(() => {
    if (!showMenu) return
    const handleClick = () => setShowMenu(false)
    window.addEventListener('click', handleClick)
    return () => window.removeEventListener('click', handleClick)
  }, [showMenu])

  return (
    <div className={cn('relative inline-block', className)}>
      {/* Drag handle */}
      <div
        ref={handleRef}
        className={cn(
          'absolute w-3 h-3 bg-blue-600 border-2 border-white rounded-sm cursor-crosshair shadow-md z-10',
          'hover:bg-blue-500 hover:scale-125 transition-all',
          isDragging && 'bg-blue-500 scale-125',
          direction === 'down' ? '-bottom-1.5 right-0' : '-right-1.5 bottom-0'
        )}
        onMouseDown={handleMouseDown}
        role="button"
        aria-label="Drag to fill cells"
        aria-haspopup="menu"
      />

      {/* Fill mode menu */}
      {showMenu && (
        <div
          className="absolute z-50 bg-white dark:bg-gray-800 border border-[var(--border-subtle)] rounded-lg shadow-xl py-1.5 min-w-[160px] top-full right-0 mt-1"
          onClick={(e) => e.stopPropagation()}
        >
          <div className="px-3 py-1 text-[10px] font-semibold text-gray-400 dark:text-gray-500 uppercase tracking-wider">
            Fill Options
          </div>
          <button
            className="w-full px-3 py-1.5 text-left text-xs hover:bg-[var(--bg-hover)] flex items-center gap-2"
            onClick={() => handleModeSelect('copy')}
          >
            <span className="w-4 h-4 rounded bg-gray-200 flex items-center justify-center text-[9px] font-mono">
              C
            </span>
            Copy Cells
          </button>
          {pattern === 'linear' && (
            <button
              className="w-full px-3 py-1.5 text-left text-xs hover:bg-[var(--bg-hover)] flex items-center gap-2"
              onClick={() => handleModeSelect('linear')}
            >
              <span className="w-4 h-4 rounded bg-blue-100 flex items-center justify-center text-[9px] font-mono text-blue-600">
                L
              </span>
              Linear Trend
            </button>
          )}
          {pattern === 'growth' && (
            <button
              className="w-full px-3 py-1.5 text-left text-xs hover:bg-[var(--bg-hover)] flex items-center gap-2"
              onClick={() => handleModeSelect('growth')}
            >
              <span className="w-4 h-4 rounded bg-green-100 flex items-center justify-center text-[9px] font-mono fin-positive">
                G
              </span>
              Growth Trend
            </button>
          )}
          <button
            className="w-full px-3 py-1.5 text-left text-xs hover:bg-[var(--bg-hover)] flex items-center gap-2"
            onClick={() => handleModeSelect('series')}
          >
            <span className="w-4 h-4 rounded bg-amber-100 flex items-center justify-center text-[9px] font-mono text-amber-600">
              S
            </span>
            Fill Series
          </button>
        </div>
      )}
    </div>
  )
}

import { useMemo } from 'react'
import { useGLStore } from '@/store/glStore'
import { Modal } from './Modal'
import { DataTable } from './DataTable'
import { format } from 'date-fns'

interface DrillDownModalProps {
  isOpen: boolean
  onClose: () => void
  title: string
  accountPrefix?: string
  startDate?: string
  endDate?: string
}

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(n)
}

export function DrillDownModal({
  isOpen,
  onClose,
  title,
  accountPrefix,
  startDate,
  endDate,
}: DrillDownModalProps) {
  const { entries } = useGLStore()

  const filteredEntries = useMemo(() => {
    return entries.filter((e) => {
      const matchAccount = accountPrefix ? (e.accountCode || '').startsWith(accountPrefix) : true
      const matchStart = startDate ? e.date >= startDate : true
      const matchEnd = endDate ? e.date <= endDate : true
      return matchAccount && matchStart && matchEnd
    })
  }, [entries, accountPrefix, startDate, endDate])

  const columns = [
    {
      header: 'Date',
      key: 'date',
      render: (value: unknown) => format(new Date(value as string | number | Date), 'MMM d, yyyy'),
    },
    { header: 'Account', key: 'accountCode' },
    { header: 'Description', key: 'description' },
    {
      header: 'Debit',
      key: 'debit',
      render: (value: unknown) => formatCurrency(value as number),
    },
    {
      header: 'Credit',
      key: 'credit',
      render: (value: unknown) => formatCurrency(value as number),
    },
    {
      header: 'Net',
      key: 'net',
      render: (_value: unknown, row: Record<string, unknown>) =>
        formatCurrency((row.debit as number) - (row.credit as number)),
    },
  ]

  return (
    <Modal isOpen={isOpen} onClose={onClose} className="w-full max-w-xl">
      <div className="space-y-4">
        <div className="flex justify-between items-center text-sm text-slate-400">
          <span>{filteredEntries.length} transactions found</span>
          {accountPrefix && <span>Filtering by Account: {accountPrefix}*</span>}
        </div>
        <div className="border border-slate-800 rounded-lg overflow-hidden">
          <DataTable data={filteredEntries} columns={columns} pageSize={10} />
        </div>
      </div>
    </Modal>
  )
}

