export interface FormulaBarProps {
  value?: string
  onChange?: (value: string) => void
  onEvaluate?: (result: number) => void
  activeCell?: string
  disabled?: boolean
  className?: string
}

export function FormulaBar({
  value = '',
  onChange,
  onEvaluate,
  activeCell,
  disabled = false,
  className,
}: FormulaBarProps) {
  const [showAutocomplete, setShowAutocomplete] = useState(false)
  const [autocompleteIndex, setAutocompleteIndex] = useState(0)
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const listRef = useRef<HTMLDivElement>(null)

  // Detect if user is typing a function name
  const currentToken = useMemo(() => {
    if (!value.startsWith('=')) return ''
    const afterEquals = value.slice(1)
    const match = afterEquals.match(/([A-Z_]+)$/i)
    return match ? match[1].toUpperCase() : ''
  }, [value])

  // Filter functions based on what user is typing
  const filteredFunctions = useMemo(() => {
    if (!currentToken) return []
    return FUNCTIONS.filter(
      (fn) =>
        fn.name.startsWith(currentToken) && (!selectedCategory || fn.category === selectedCategory)
    ).slice(0, 10)
  }, [currentToken, selectedCategory])

  // Show autocomplete when typing a function
  useEffect(() => {
    setShowAutocomplete(currentToken.length >= 2 && filteredFunctions.length > 0)
    setAutocompleteIndex(0)
  }, [currentToken, filteredFunctions.length])

  // Scroll selected item into view
  useEffect(() => {
    if (listRef.current) {
      const selected = listRef.current.children[autocompleteIndex] as HTMLElement
      selected?.scrollIntoView({ block: 'nearest' })
    }
  }, [autocompleteIndex])

  const insertFunction = useCallback(
    (fn: FormulaFunction) => {
      const beforeToken = value.slice(0, value.length - currentToken.length)
      onChange?.(`${beforeToken}${fn.name}(`)
      setShowAutocomplete(false)
      inputRef.current?.focus()
    },
    [value, currentToken, onChange]
  )

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (showAutocomplete) {
        if (e.key === 'ArrowDown') {
          e.preventDefault()
          setAutocompleteIndex((prev) => Math.min(prev + 1, filteredFunctions.length - 1))
        } else if (e.key === 'ArrowUp') {
          e.preventDefault()
          setAutocompleteIndex((prev) => Math.max(prev - 1, 0))
        } else if (e.key === 'Tab' || e.key === 'Enter') {
          if (filteredFunctions[autocompleteIndex]) {
            e.preventDefault()
            insertFunction(filteredFunctions[autocompleteIndex])
          }
        } else if (e.key === 'Escape') {
          setShowAutocomplete(false)
        }
        return
      }

      if (e.key === 'Enter') {
        onEvaluate?.(0)
      } else if (e.key === 'Escape') {
        onChange?.('')
      }
    },
    [showAutocomplete, filteredFunctions, autocompleteIndex, insertFunction, onEvaluate, onChange]
  )

  const categories = useMemo(() => {
    const cats = new Set(FUNCTIONS.map((fn) => fn.category))
    return ['All', ...Array.from(cats)]
  }, [])

  return (
    <div className={cn('relative', className)}>
      <div
        className={cn(
          'flex items-center w-full border border-[var(--border-subtle)] bg-[var(--bg-surface)] rounded-t-lg overflow-hidden shadow-sm h-10',
          disabled && 'opacity-50 pointer-events-none'
        )}
      >
        {/* Active Cell Reference */}
        <div
          className="flex items-center justify-center px-4 border-r border-[var(--border-subtle)] bg-gray-50 dark:bg-gray-900 min-w-[80px]"
          aria-live="polite"
          aria-label={`Active cell: ${activeCell || 'none'}`}
        >
          <span className="text-xs font-bold text-blue-600 uppercase tabular-nums">
            {activeCell || '---'}
          </span>
        </div>

        {/* FX Icon */}
        <div className="flex items-center justify-center px-3 text-[var(--text-secondary)] italic font-serif select-none border-r border-gray-100 dark:border-gray-800">
          <span className="text-sm font-bold opacity-60">fx</span>
        </div>

        {/* Input Field */}
        <div className="flex-1 relative group">
          <input
            ref={inputRef}
            type="text"
            className="w-full h-full bg-transparent px-3 py-2 text-sm font-mono text-[var(--text-primary)] outline-none placeholder:italic placeholder:opacity-40"
            placeholder="Enter formula (e.g., =SUM(C2:C10) * 1.05)"
            aria-label="Formula input"
            role="combobox"
            aria-expanded={showAutocomplete}
            aria-controls="formula-autocomplete"
            aria-activedescendant={
              showAutocomplete && filteredFunctions[autocompleteIndex]
                ? `fn-${filteredFunctions[autocompleteIndex].name}`
                : undefined
            }
            value={value}
            onChange={(e) => onChange?.(e.target.value)}
            onKeyDown={handleKeyDown}
            onFocus={() => {
              if (currentToken.length >= 2 && filteredFunctions.length > 0) {
                setShowAutocomplete(true)
              }
            }}
            disabled={disabled}
          />
          {!value && (
            <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center space-x-1.5 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
              <FlaskConical className="h-3.5 w-3.5 text-amber-500" />
              <span className="text-[10px] font-medium text-amber-600">Pure Calculation</span>
            </div>
          )}
        </div>

        {/* Action Buttons */}
        <div className="flex items-center px-1 border-l border-[var(--border-subtle)] bg-gray-50 dark:bg-gray-900/50">
          <button
            onClick={() => onChange?.('')}
            className="p-1.5 rounded-md hover:bg-red-50 text-red-400 hover:fin-negative transition-colors"
            title="Cancel (Esc)"
          >
            <X className="h-4 w-4" />
          </button>
          <button
            onClick={() => onEvaluate?.(0)}
            className="p-1.5 rounded-md hover:bg-green-50 text-green-400 hover:fin-positive transition-colors"
            title="Evaluate (Enter)"
          >
            <Check className="h-4 w-4" />
          </button>
        </div>
      </div>

      {/* Autocomplete Dropdown */}
      {showAutocomplete && (
        <div
          id="formula-autocomplete"
          className="absolute z-50 w-full bg-white dark:bg-gray-800 border border-[var(--border-subtle)] rounded-b-lg shadow-xl max-h-[320px] overflow-hidden flex flex-col"
          role="listbox"
          aria-label="Formula suggestions"
        >
          {/* Category filter */}
          <div className="flex gap-1 px-2 py-1.5 border-b border-gray-100 dark:border-gray-800 overflow-x-auto flex-shrink-0">
            {categories.map((cat) => (
              <button
                key={cat}
                className={cn(
                  'px-2 py-0.5 text-[10px] font-medium rounded-full whitespace-nowrap transition-colors',
                  (cat === 'All' && !selectedCategory) || selectedCategory === cat
                    ? 'bg-blue-100 text-blue-700'
                    : 'text-[var(--text-muted)] hover:bg-[var(--bg-hover)]'
                )}
                onClick={(e) => {
                  e.stopPropagation()
                  setSelectedCategory(cat === 'All' ? null : cat)
                }}
              >
                {cat}
              </button>
            ))}
          </div>

          {/* Function list */}
          <div ref={listRef} className="overflow-y-auto max-h-[250px]">
            {filteredFunctions.map((fn, idx) => (
              <button
                key={fn.name}
                id={`fn-${fn.name}`}
                role="option"
                aria-selected={idx === autocompleteIndex}
                className={cn(
                  'w-full flex items-start gap-3 px-3 py-2 text-left transition-colors',
                  idx === autocompleteIndex ? 'bg-blue-50' : 'hover:bg-gray-50 dark:bg-gray-900'
                )}
                onMouseDown={(e) => {
                  e.preventDefault()
                  insertFunction(fn)
                }}
                onMouseEnter={() => setAutocompleteIndex(idx)}
              >
                <div className="flex-shrink-0 w-8 h-8 rounded bg-blue-100 flex items-center justify-center">
                  <span className="text-xs font-bold text-blue-600 font-mono">
                    {fn.name.slice(0, 2)}
                  </span>
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-bold text-[var(--text-primary)] font-mono">
                      {fn.name}
                    </span>
                    <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-gray-100 text-[var(--text-muted)]">
                      {fn.category}
                    </span>
                  </div>
                  <div className="text-[11px] text-[var(--text-muted)] mt-0.5">
                    {fn.description}
                  </div>
                  <div className="text-[10px] text-gray-400 dark:text-gray-500 mt-0.5 font-mono truncate">
                    {fn.syntax}
                  </div>
                </div>
              </button>
            ))}
          </div>

          {/* Selected function tooltip */}
          {filteredFunctions[autocompleteIndex] && (
            <div className="flex-shrink-0 px-3 py-2 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-800">
              <div className="text-[10px] font-semibold text-gray-400 dark:text-gray-500 uppercase tracking-wider mb-1">
                Parameters
              </div>
              <div className="flex flex-wrap gap-1">
                {filteredFunctions[autocompleteIndex].params.map((param, i) => (
                  <span
                    key={param}
                    className={cn(
                      'px-1.5 py-0.5 text-[10px] font-mono rounded',
                      i === 0
                        ? 'bg-blue-100 text-blue-700'
                        : 'bg-gray-100 text-[var(--text-secondary)]'
                    )}
                  >
                    {param}
                  </span>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import React from 'react'
import { cn } from '@/utils/cn'

export interface GanttTask {
  id: string
  name: string
  startDate: string
  endDate: string
  progress?: number
  color?: string
  dependencies?: string[]
}

export interface GanttChartProps {
  tasks: GanttTask[]
  className?: string
  loading?: boolean
  error?: string
  onClick?: (task: GanttTask) => void
}

export const GanttChart: React.FC<GanttChartProps> = ({
  tasks,
  className,
  loading = false,
  error,
  onClick,
}) => {
  if (loading) {
    return (
      <div className={cn('w-full overflow-x-auto', className)}>
        <div className="flex items-center justify-center h-48">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500" />
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className={cn('w-full overflow-x-auto', className)}>
        <div className="flex items-center justify-center h-48 text-red-500 text-sm">{error}</div>
      </div>
    )
  }
  if (!tasks || tasks.length === 0)
    return <div className="flex items-center justify-center h-48 text-slate-400">No data</div>

  const allDates = tasks.flatMap((t) => [new Date(t.startDate), new Date(t.endDate)])
  const minDate = new Date(Math.min(...allDates.map((d) => d.getTime())))
  const maxDate = new Date(Math.max(...allDates.map((d) => d.getTime())))
  const totalDays = Math.max(
    1,
    Math.ceil((maxDate.getTime() - minDate.getTime()) / (1000 * 60 * 60 * 24))
  )

  const defaultColors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899']

  const getBarStyle = (task: GanttTask) => {
    const start = new Date(task.startDate)
    const end = new Date(task.endDate)
    const left = ((start.getTime() - minDate.getTime()) / (1000 * 60 * 60 * 24) / totalDays) * 100
    const width = ((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24) / totalDays) * 100
    return { left: `${left}%`, width: `${width}%` }
  }

  return (
    <div className={cn('w-full overflow-x-auto', className)}>
      <div className="min-w-[600px]">
        {/* Header */}
        <div className="flex border-b pb-2 mb-2">
          <div className="w-48 shrink-0 font-medium text-sm">Task</div>
          <div className="flex-1 relative h-6">
            {/* Month markers */}
            {Array.from({ length: Math.ceil(totalDays / 30) }, (_, i) => {
              const date = new Date(minDate)
              date.setDate(date.getDate() + i * 30)
              const left = ((i * 30) / totalDays) * 100
              return (
                <div
                  key={i}
                  className="absolute text-xs text-[var(--text-muted)]"
                  style={{ left: `${left}%` }}
                >
                  {date.toLocaleString('default', { month: 'short' })}
                </div>
              )
            })}
          </div>
        </div>

        {/* Tasks */}
        {tasks.map((task, i) => {
          const barStyle = getBarStyle(task)
          const color = task.color ?? defaultColors[i % defaultColors.length]

          return (
            <div
              key={task.id}
              className="flex items-center h-8 mb-1 cursor-pointer"
              onClick={onClick ? () => onClick(task) : undefined}
            >
              <div className="w-48 shrink-0 text-sm truncate pr-2">{task.name}</div>
              <div className="flex-1 relative h-full bg-gray-100 rounded">
                <div
                  className="absolute h-full rounded opacity-80"
                  style={{ ...barStyle, backgroundColor: color }}
                />
                {task.progress !== undefined && (
                  <div
                    className="absolute h-full rounded"
                    style={{
                      ...barStyle,
                      width: `${(parseFloat(barStyle.width) * task.progress) / 100}%`,
                      backgroundColor: color,
                    }}
                  />
                )}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

interface GaugeChartProps {
  value: number
  min: number
  max: number
  threshold?: number
  critical?: number
  label: string
  width?: number
  height?: number
  className?: string
  loading?: boolean
  error?: string
  onClick?: () => void
}

export function GaugeChart({
  value,
  min,
  max,
  threshold,
  critical,
  label,
  width = 200,
  height = 160,
  className,
  loading = false,
  error,
  onClick,
}: GaugeChartProps) {
  if (loading) {
    return (
      <div className={className} style={{ width, height }}>
        <div className="flex items-center justify-center h-full">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500" />
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className={className} style={{ width, height }}>
        <div className="flex items-center justify-center h-full text-red-500 text-sm">{error}</div>
      </div>
    )
  }
  if (isNaN(value) || isNaN(min) || isNaN(max))
    return <div className="text-slate-400 text-xs p-4">Invalid data</div>

  const pct = Math.max(0, Math.min(100, ((value - min) / (max - min)) * 100))
  const angle = (pct / 100) * 180
  const radians = (angle * Math.PI) / 180
  const cx = width / 2
  const cy = height - 20
  const r = Math.min(width / 2 - 20, height - 40)
  const nx = cx + r * Math.sin(radians)
  const ny = cy - r * Math.cos(radians)
  const thresholdAngle = threshold !== undefined ? ((threshold - min) / (max - min)) * 180 : 0
  const criticalAngle = critical !== undefined ? ((critical - min) / (max - min)) * 180 : 0
  const thrRad = (thresholdAngle * Math.PI) / 180
  const criRad = (criticalAngle * Math.PI) / 180

  if (max <= min) return <div className="text-slate-400 text-xs p-4">Invalid range</div>

  const getColor = () => {
    if (critical !== undefined && pct >= critical) return 'var(--negative)'
    if (threshold !== undefined && pct >= threshold) return 'var(--warning)'
    return 'var(--positive)'
  }

  return (
    <div
      className={className}
      style={{ width, height }}
      onClick={onClick}
      role="img"
      aria-label={`${label}: ${value}`}
    >
      <svg width={width} height={height}>
        <path
          d={`M${cx - r} ${cy} A${r} ${r} 0 0 1 ${cx + r} ${cy}`}
          fill="none"
          stroke="var(--border-subtle)"
          strokeWidth={12}
          strokeLinecap="round"
        />
        {threshold !== undefined && (
          <line
            x1={cx}
            y1={cy}
            x2={cx + r * Math.sin(thrRad)}
            y2={cy - r * Math.cos(thrRad)}
            stroke="var(--warning)"
            strokeWidth={2}
            opacity={0.5}
            strokeDasharray="4 2"
          />
        )}
        {critical !== undefined && (
          <line
            x1={cx}
            y1={cy}
            x2={cx + r * Math.sin(criRad)}
            y2={cy - r * Math.cos(criRad)}
            stroke="var(--negative)"
            strokeWidth={2}
            opacity={0.5}
            strokeDasharray="4 2"
          />
        )}
        <path
          d={`M${cx - r} ${cy} A${r} ${r} 0 0 1 ${nx} ${ny}`}
          fill="none"
          stroke={getColor()}
          strokeWidth={12}
          strokeLinecap="round"
        />
        <line x1={cx} y1={cy} x2={nx} y2={ny} stroke="var(--text-primary)" strokeWidth={2} />
        <circle cx={cx} cy={cy} r={4} fill="var(--text-primary)" />
        <text
          x={cx}
          y={cy - r / 2 - 5}
          textAnchor="middle"
          fill="var(--text-primary)"
          fontSize={20}
          fontWeight={700}
        >
          {value.toLocaleString()}
        </text>
        <text x={cx} y={cy - 5} textAnchor="middle" fill="var(--text-muted)" fontSize={11}>
          {label}
        </text>
        <text x={12} y={cy + 12} fill="var(--text-muted)" fontSize={10}>
          {min}
        </text>
        <text x={width - 12} y={cy + 12} textAnchor="end" fill="var(--text-muted)" fontSize={10}>
          {max}
        </text>
      </svg>
    </div>
  )
}

import React, { useMemo } from 'react'
import { cn } from '@/utils/cn'

export interface HeatmapCell {
  row: string
  col: string
  value: number
}

export interface HeatmapProps {
  data: HeatmapCell[]
  width?: number | string
  height?: number | string
  colorScheme?: 'green' | 'blue' | 'red'
  title?: string
  className?: string
  loading?: boolean
  error?: string
  onClick?: (cell: HeatmapCell) => void
}

export const Heatmap: React.FC<HeatmapProps> = ({
  data,
  width = '100%',
  height = 400,
  colorScheme = 'blue',
  title,
  className,
  loading = false,
  error,
  onClick,
}) => {
  if (loading) {
    return (
      <div
        className={cn(
          'w-full flex flex-col p-4 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-xl shadow-sm',
          className
        )}
      >
        <div className="flex items-center justify-center h-48">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500" />
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div
        className={cn(
          'w-full flex flex-col p-4 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-xl shadow-sm',
          className
        )}
      >
        <div className="flex items-center justify-center h-48 text-red-500 text-sm">{error}</div>
      </div>
    )
  }

  if (!data || data.length === 0) {
    return (
      <div
        className={cn(
          'w-full flex flex-col p-4 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-xl shadow-sm',
          className
        )}
      >
        <div className="flex items-center justify-center h-48 text-slate-400">No data</div>
      </div>
    )
  }

  const { rows, cols, min, max, grid } = useMemo(() => {
    const rowSet = new Set<string>()
    const colSet = new Set<string>()
    let minVal = Infinity
    let maxVal = -Infinity

    data.forEach((cell) => {
      rowSet.add(cell.row)
      colSet.add(cell.col)
      if (cell.value < minVal) minVal = cell.value
      if (cell.value > maxVal) maxVal = cell.value
    })

    const uniqueRows = Array.from(rowSet).sort()
    const uniqueCols = Array.from(colSet).sort()

    const gridMap: Record<string, Record<string, number>> = {}
    data.forEach((cell) => {
      if (!gridMap[cell.row]) gridMap[cell.row] = {}
      gridMap[cell.row][cell.col] = cell.value
    })

    return {
      rows: uniqueRows,
      cols: uniqueCols,
      min: minVal,
      max: maxVal,
      grid: gridMap,
    }
  }, [data])

  const getColor = (value: number) => {
    if (value === undefined) return 'transparent'

    const ratio = (value - min) / (max - min || 1)
    const opacity = 0.1 + ratio * 0.9

    const colors = {
      blue: `rgba(37, 99, 235, ${opacity})`,
      green: `rgba(22, 163, 74, ${opacity})`,
      red: `rgba(220, 38, 38, ${opacity})`,
    }

    return colors[colorScheme]
  }

  return (
    <div
      className={cn(
        'w-full flex flex-col p-4 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-xl shadow-sm',
        className
      )}
    >
      {title && (
        <div className="mb-4">
          <h3 className="text-xs font-bold uppercase tracking-widest text-[var(--text-secondary)] opacity-60">
            {title}
          </h3>
        </div>
      )}

      <div style={{ width, height, overflow: 'auto' }} className="relative custom-scrollbar">
        <div
          className="grid"
          style={{
            gridTemplateColumns: `minmax(100px, auto) repeat(${cols.length}, 1fr)`,
            gap: '2px',
          }}
        >
          {/* Header Corner */}
          <div className="bg-transparent" />

          {/* Column Headers */}
          {cols.map((col) => (
            <div
              key={col}
              className="text-[10px] font-black text-[var(--text-secondary)] uppercase text-center p-2 truncate"
            >
              {col}
            </div>
          ))}

          {/* Rows */}
          {rows.map((row) => (
            <React.Fragment key={row}>
              {/* Row Header */}
              <div className="text-[10px] font-black text-[var(--text-secondary)] uppercase text-right pr-4 flex items-center justify-end">
                {row}
              </div>

              {/* Cells */}
              {cols.map((col) => {
                const val = grid[row]?.[col]
                return (
                  <div
                    key={`${row}-${col}`}
                    className="aspect-square min-w-[30px] rounded-[2px] transition-all hover:scale-110 hover:z-10 hover:shadow-lg cursor-pointer group relative"
                    style={{ backgroundColor: getColor(val) }}
                    onClick={
                      onClick && val !== undefined
                        ? () => onClick({ row, col, value: Number(val) })
                        : undefined
                    }
                    role={onClick ? 'button' : undefined}
                    aria-label={val !== undefined ? `${row} ${col}: ${String(val)}` : undefined}
                  >
                    <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                      <div className="bg-slate-900 text-white text-[9px] font-bold px-1.5 py-0.5 rounded shadow-xl whitespace-nowrap z-20">
                        {val?.toLocaleString()}
                      </div>
                    </div>
                  </div>
                )
              })}
            </React.Fragment>
          ))}
        </div>
      </div>

      <div className="mt-6 flex items-center justify-end space-x-4">
        <span className="text-[10px] font-bold text-[var(--text-secondary)] opacity-40 uppercase">
          Intensity Scale
        </span>
        <div className="flex items-center space-x-1">
          <span className="text-[9px] font-bold text-[var(--text-secondary)]">
            {min.toLocaleString()}
          </span>
          <div
            className="w-32 h-2 rounded-full"
            style={{
              background: `linear-gradient(to right, rgba(37, 99, 235, 0.1), rgba(37, 99, 235, 1))`,
            }}
          />
          <span className="text-[9px] font-bold text-[var(--text-secondary)]">
            {max.toLocaleString()}
          </span>
        </div>
      </div>
    </div>
  )
}

import { useCallback, useMemo, useState } from 'react'
import { Card, CardHeader, CardTitle, CardContent } from './Card'
import { Button } from './Button'
import { Badge } from './Badge'
import { Select } from './Select'
import { Input } from './Input'
import { DataTable } from './DataTable'
import { cn } from '@/utils/cn'
import {
  ICMatchingEngine,
  type ICTransaction,
  type MatchPair,
  type MatchSummary,
  type ToleranceSettings,
} from '@/engines/ICMatchingEngine'

// =============================================================================
// IC MATCHING DASHBOARD
// =============================================================================

interface ICMatchingDashboardProps {
  sourceTransactions: ICTransaction[]
  targetTransactions: ICTransaction[]
  allTransactions: ICTransaction[]
  entityNames: Record<string, string>
  onMatch?: (match: MatchPair) => void
  onUnmatch?: (matchId: string) => void
  onAutoMatch?: (matches: MatchPair[]) => void
  onGenerateEliminations?: (matches: MatchPair[]) => void
  className?: string
}

export function ICMatchingDashboard({
  sourceTransactions,
  targetTransactions,
  allTransactions,
  entityNames,
  onMatch,
  onUnmatch,
  onAutoMatch,
  onGenerateEliminations,
  className,
}: ICMatchingDashboardProps) {
  const [engine] = useState(() => new ICMatchingEngine())
  const [matches, setMatches] = useState<MatchPair[]>([])
  const [tolerance, setTolerance] = useState<ToleranceSettings>(engine.getTolerance())
  const [filterEntity, setFilterEntity] = useState<string>('all')
  const [filterAccount, setFilterAccount] = useState<string>('all')
  const [filterStatus, setFilterStatus] = useState<string>('all')
  const [isMatching, setIsMatching] = useState(false)
  const [selectedSource, setSelectedSource] = useState<ICTransaction | null>(null)
  const [selectedTarget, setSelectedTarget] = useState<ICTransaction | null>(null)

  // Unique entities and accounts for filters
  const entities = useMemo(() => {
    const set = new Set(allTransactions.map((t) => t.entityId))
    return Array.from(set)
  }, [allTransactions])

  const accounts = useMemo(() => {
    const set = new Set(allTransactions.map((t) => t.accountCode))
    return Array.from(set).sort()
  }, [allTransactions])

  // Summary stats
  const summary = useMemo<MatchSummary>(
    () => engine.getSummary(sourceTransactions, targetTransactions),
    [engine, sourceTransactions, targetTransactions, matches]
  )

  // Unmatched transactions
  const unmatched = useMemo(
    () => engine.getUnmatched(allTransactions),
    [engine, allTransactions, matches]
  )

  // Filtered matches
  const filteredMatches = useMemo(() => {
    let filtered = matches
    if (filterEntity !== 'all') {
      filtered = filtered.filter(
        (m) => m.source.entityId === filterEntity || m.target.entityId === filterEntity
      )
    }
    if (filterAccount !== 'all') {
      filtered = filtered.filter((m) => m.source.accountCode === filterAccount)
    }
    if (filterStatus !== 'all') {
      filtered = filtered.filter((m) => m.status === filterStatus)
    }
    return filtered
  }, [matches, filterEntity, filterAccount, filterStatus])

  // Auto-match handler
  const handleAutoMatch = useCallback(() => {
    setIsMatching(true)
    engine.setTolerance(tolerance)
    const newMatches = engine.autoMatch(sourceTransactions, targetTransactions)
    setMatches([...newMatches])
    onAutoMatch?.(newMatches)
    setIsMatching(false)
  }, [engine, sourceTransactions, targetTransactions, tolerance, onAutoMatch])

  // Manual match handler
  const handleManualMatch = useCallback(() => {
    if (!selectedSource || !selectedTarget) return
    const match = engine.manualMatch(selectedSource, selectedTarget)
    setMatches([...engine.getMatches()])
    onMatch?.(match)
    setSelectedSource(null)
    setSelectedTarget(null)
  }, [engine, selectedSource, selectedTarget, onMatch])

  // Unmatch handler
  const handleUnmatch = useCallback(
    (matchId: string) => {
      engine.unmatch(matchId)
      setMatches([...engine.getMatches()])
      onUnmatch?.(matchId)
    },
    [engine, onUnmatch]
  )

  // Generate eliminations
  const handleGenerateEliminations = useCallback(() => {
    const accountNames: Record<string, string> = {}
    for (const t of allTransactions) {
      accountNames[t.accountCode] = t.accountName
    }
    const eliminations = engine.generateEliminations(matches, accountNames)
    onGenerateEliminations?.(matches)
  }, [engine, matches, allTransactions, onGenerateEliminations])

  return (
    <div className={cn('space-y-6', className)}>
      {/* Summary Cards */}
      <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
        <SummaryCard
          label="Matched"
          count={summary.matchedCount}
          amount={summary.matchedAmount}
          variant="success"
        />
        <SummaryCard
          label="Partial"
          count={summary.partiallyMatchedCount}
          amount={summary.partiallyMatchedAmount}
          variant="warning"
        />
        <SummaryCard
          label="Unmatched"
          count={summary.unmatchedCount}
          amount={summary.unmatchedAmount}
          variant="error"
        />
        <SummaryCard
          label="Match Rate"
          count={null}
          amount={null}
          value={`${summary.matchRate.toFixed(1)}%`}
          variant="info"
        />
      </div>

      {/* Controls */}
      <Card>
        <CardHeader>
          <CardTitle>Matching Controls</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap items-end gap-4">
            {/* Tolerance Settings */}
            <div className="space-y-1">
              <label className="text-sm font-medium">Amount Tolerance</label>
              <Input
                type="number"
                value={tolerance.amountTolerance}
                onChange={(e) =>
                  setTolerance({ ...tolerance, amountTolerance: Number(e.target.value) })
                }
                className="w-32"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium">% Tolerance</label>
              <Input
                type="number"
                value={tolerance.percentageTolerance}
                onChange={(e) =>
                  setTolerance({ ...tolerance, percentageTolerance: Number(e.target.value) })
                }
                className="w-24"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium">Date Tolerance (days)</label>
              <Input
                type="number"
                value={tolerance.dateToleranceDays}
                onChange={(e) =>
                  setTolerance({ ...tolerance, dateToleranceDays: Number(e.target.value) })
                }
                className="w-24"
              />
            </div>

            <Button onClick={handleAutoMatch} disabled={isMatching}>
              {isMatching ? 'Matching...' : 'Auto-Match'}
            </Button>
            <Button
              variant="outline"
              onClick={handleManualMatch}
              disabled={!selectedSource || !selectedTarget}
            >
              Manual Match
            </Button>
            <Button variant="outline" onClick={handleGenerateEliminations}>
              Generate Eliminations
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Filters */}
      <div className="flex flex-wrap gap-4">
        <Select
          value={filterEntity}
          onChange={setFilterEntity}
          options={[
            { value: 'all', label: 'All Entities' },
            ...entities.map((id) => ({ value: id, label: entityNames[id] ?? id })),
          ]}
        />
        <Select
          value={filterAccount}
          onChange={setFilterAccount}
          options={[
            { value: 'all', label: 'All Accounts' },
            ...accounts.map((code) => ({ value: code, label: code })),
          ]}
        />
        <Select
          value={filterStatus}
          onChange={setFilterStatus}
          options={[
            { value: 'all', label: 'All Statuses' },
            { value: 'matched', label: 'Matched' },
            { value: 'partial', label: 'Partial' },
            { value: 'unmatched', label: 'Unmatched' },
          ]}
        />
      </div>

      {/* Matched Pairs Table */}
      <Card>
        <CardHeader>
          <CardTitle>Matched Pairs ({filteredMatches.length})</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b text-left">
                  <th className="p-2">Status</th>
                  <th className="p-2">Source Entity</th>
                  <th className="p-2">Target Entity</th>
                  <th className="p-2">Account</th>
                  <th className="p-2 text-right">Source Amt</th>
                  <th className="p-2 text-right">Target Amt</th>
                  <th className="p-2 text-right">Difference</th>
                  <th className="p-2 text-right">Confidence</th>
                  <th className="p-2">Method</th>
                  <th className="p-2">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredMatches.map((match) => (
                  <tr
                    key={match.id}
                    className={cn(
                      'border-b hover:bg-muted/50',
                      match.status === 'matched' && 'bg-green-50 dark:bg-green-950/20',
                      match.status === 'partial' && 'bg-yellow-50 dark:bg-yellow-950/20'
                    )}
                  >
                    <td className="p-2">
                      <MatchStatusBadge status={match.status} />
                    </td>
                    <td className="p-2">{match.source.entityName}</td>
                    <td className="p-2">{match.target.entityName}</td>
                    <td className="p-2 font-mono text-xs">{match.source.accountCode}</td>
                    <td className="p-2 text-right font-mono">
                      {formatAmount(match.source.amount)}
                    </td>
                    <td className="p-2 text-right font-mono">
                      {formatAmount(match.target.amount)}
                    </td>
                    <td className="p-2 text-right font-mono">
                      {formatAmount(match.amountDifference)}
                    </td>
                    <td className="p-2 text-right">{(match.confidence * 100).toFixed(0)}%</td>
                    <td className="p-2 text-xs capitalize">{match.method.replace('_', ' ')}</td>
                    <td className="p-2">
                      <Button variant="ghost" size="sm" onClick={() => handleUnmatch(match.id)}>
                        Unmatch
                      </Button>
                    </td>
                  </tr>
                ))}
                {filteredMatches.length === 0 && (
                  <tr>
                    <td colSpan={10} className="p-8 text-center text-muted-foreground">
                      No matches found. Run Auto-Match or select transactions for Manual Match.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Unmatched Transactions */}
      <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
        <UnmatchedPanel
          title="Source Transactions"
          transactions={sourceTransactions}
          unmatched={unmatched.filter((t) => sourceTransactions.some((s) => s.id === t.id))}
          selected={selectedSource}
          onSelect={setSelectedSource}
          entityNames={entityNames}
        />
        <UnmatchedPanel
          title="Target Transactions"
          transactions={targetTransactions}
          unmatched={unmatched.filter((t) => targetTransactions.some((s) => s.id === t.id))}
          selected={selectedTarget}
          onSelect={setSelectedTarget}
          entityNames={entityNames}
        />
      </div>
    </div>
  )
}

// =============================================================================
// SUB-COMPONENTS
// =============================================================================

function SummaryCard({
  label,
  count,
  amount,
  value,
  variant,
}: {
  label: string
  count: number | null
  amount: number | null
  value?: string
  variant: 'success' | 'warning' | 'error' | 'info'
}) {
  const colors = {
    success: 'border-green-200 bg-green-50 dark:border-green-800 dark:bg-green-950/30',
    warning: 'border-yellow-200 bg-yellow-50 dark:border-yellow-800 dark:bg-yellow-950/30',
    error: 'border-red-200 bg-red-50 dark:border-red-800 dark:bg-red-950/30',
    info: 'border-blue-200 bg-blue-50 dark:border-blue-800 dark:bg-blue-950/30',
  }

  return (
    <Card className={colors[variant]}>
      <CardContent className="p-4">
        <p className="text-sm text-muted-foreground">{label}</p>
        <p className="text-2xl font-bold">{value ?? count ?? 0}</p>
        {amount !== null && <p className="text-sm text-muted-foreground">{formatAmount(amount)}</p>}
      </CardContent>
    </Card>
  )
}

function MatchStatusBadge({ status }: { status: string }) {
  const variants: Record<string, 'default' | 'secondary' | 'destructive' | 'outline'> = {
    matched: 'default',
    partial: 'secondary',
    unmatched: 'destructive',
  }
  return <Badge variant={variants[status] ?? 'outline'}>{status}</Badge>
}

function UnmatchedPanel({
  title,
  transactions,
  unmatched,
  selected,
  onSelect,
  entityNames,
}: {
  title: string
  transactions: ICTransaction[]
  unmatched: ICTransaction[]
  selected: ICTransaction | null
  onSelect: (t: ICTransaction | null) => void
  entityNames: Record<string, string>
}) {
  return (
    <Card>
      <CardHeader>
        <CardTitle>
          {title} — {unmatched.length} unmatched / {transactions.length} total
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="max-h-64 overflow-y-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b text-left">
                <th className="p-2">Entity</th>
                <th className="p-2">Account</th>
                <th className="p-2 text-right">Amount</th>
                <th className="p-2">Date</th>
              </tr>
            </thead>
            <tbody>
              {unmatched.map((t) => (
                <tr
                  key={t.id}
                  className={cn(
                    'cursor-pointer border-b hover:bg-muted/50',
                    selected?.id === t.id && 'bg-blue-50 dark:bg-blue-950/20'
                  )}
                  onClick={() => onSelect(selected?.id === t.id ? null : t)}
                >
                  <td className="p-2">{entityNames[t.entityId] ?? t.entityId}</td>
                  <td className="p-2 font-mono text-xs">{t.accountCode}</td>
                  <td className="p-2 text-right font-mono">{formatAmount(t.amount)}</td>
                  <td className="p-2 text-xs">{t.date}</td>
                </tr>
              ))}
              {unmatched.length === 0 && (
                <tr>
                  <td colSpan={4} className="p-4 text-center text-muted-foreground">
                    All transactions matched
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </CardContent>
    </Card>
  )
}

