interface KeyboardShortcutOverlayProps {
  isOpen: boolean
  onClose: () => void
}

export function KeyboardShortcutOverlay({ isOpen, onClose }: KeyboardShortcutOverlayProps) {
  const { pathname } = useLocation()
  const pageContext = getPageContext(pathname)
  const [search, setSearch] = useState('')
  const [contextFilter, setContextFilter] = useState<PageContext | 'all'>('all')
  const searchRef = useRef<HTMLInputElement>(null)

  const allShortcuts = useMemo(() => buildUnifiedShortcuts(), [])

  // Filter shortcuts
  const filtered = useMemo(() => {
    let items = allShortcuts

    // Context filter
    if (contextFilter !== 'all') {
      items = items.filter((s) => s.contexts.includes(contextFilter))
    }

    // Search filter
    if (search.trim()) {
      const q = search.toLowerCase()
      items = items.filter(
        (s) =>
          s.description.toLowerCase().includes(q) ||
          s.keys.toLowerCase().includes(q) ||
          s.category.toLowerCase().includes(q)
      )
    }

    return items
  }, [allShortcuts, search, contextFilter])

  // Group by category preserving order
  const grouped = useMemo(() => {
    const order = [
      'Navigation',
      'Grid Navigation',
      'Grid Selection',
      'Grid Editing',
      'Clipboard',
      'Editing',
      'Formatting',
      'Formulas',
      'Data',
      'Sheets',
      'Actions',
      'Application',
      'Reports',
    ]
    const map = new Map<string, UnifiedShortcut[]>()
    for (const s of filtered) {
      const arr = map.get(s.category) ?? []
      arr.push(s)
      map.set(s.category, arr)
    }
    return order
      .filter((cat) => map.has(cat))
      .map((cat) => ({ name: cat, shortcuts: map.get(cat)! }))
  }, [filtered])

  // Focus search on open
  useEffect(() => {
    if (isOpen) {
      setSearch('')
      setContextFilter('all')
      requestAnimationFrame(() => searchRef.current?.focus())
    }
  }, [isOpen])

  // Escape to close
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) onClose()
    },
    [isOpen, onClose]
  )

  useEffect(() => {
    if (!isOpen) return
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [isOpen, handleKeyDown])

  // Print handler
  const handlePrint = useCallback(() => {
    window.print()
  }, [])

  if (!isOpen) return null

  return (
    <>
      <style>{PRINT_STYLES}</style>

      <div
        className="fixed inset-0 z-50 flex items-center justify-center p-4"
        role="dialog"
        aria-modal="true"
        aria-label="Keyboard shortcuts reference"
