/**
 * NLQ Input — Natural Language Query search bar.
 * Type a question like "show Q3 revenue by region" and get auto-generated charts.
 */

import { useCallback, useEffect, useRef, useState } from 'react'
import { Search, Sparkles, Loader2 } from 'lucide-react'
import { cn } from '@/utils/cn'

interface NLQInputProps {
  onSubmit: (query: string) => void
  isProcessing?: boolean
  placeholder?: string
  className?: string
}

const SUGGESTIONS = [
  'Show Q3 revenue by region',
  'Compare budget vs actual expenses',
  'What is total profit this year?',
  'Trend of sales over time',
  'Expenses by department',
  'Show cash flow by quarter',
]

export function NLQInput({
  onSubmit,
  isProcessing = false,
  placeholder,
  className,
}: NLQInputProps) {
  const [value, setValue] = useState('')
  const [showSuggestions, setShowSuggestions] = useState(false)
  const [selectedIndex, setSelectedIndex] = useState(-1)
  const inputRef = useRef<HTMLInputElement>(null)

  const filtered =
    value.length > 0
      ? SUGGESTIONS.filter((s) => s.toLowerCase().includes(value.toLowerCase()))
      : SUGGESTIONS

  const handleSubmit = useCallback(() => {
    const trimmed = value.trim()
    if (!trimmed || isProcessing) return
    onSubmit(trimmed)
    setShowSuggestions(false)
    setSelectedIndex(-1)
  }, [value, isProcessing, onSubmit])

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault()
        if (selectedIndex >= 0 && selectedIndex < filtered.length) {
          setValue(filtered[selectedIndex])
          onSubmit(filtered[selectedIndex])
          setShowSuggestions(false)
          setSelectedIndex(-1)
        } else {
          handleSubmit()
        }
      } else if (e.key === 'ArrowDown') {
        e.preventDefault()
        setSelectedIndex((prev) => Math.min(prev + 1, filtered.length - 1))
      } else if (e.key === 'ArrowUp') {
        e.preventDefault()
        setSelectedIndex((prev) => Math.max(prev - 1, -1))
      } else if (e.key === 'Escape') {
        setShowSuggestions(false)
        setSelectedIndex(-1)
      }
    },
    [filtered, selectedIndex, handleSubmit, onSubmit]
  )

  useEffect(() => {
    const handleGlobalKey = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault()
        inputRef.current?.focus()
      }
    }
    window.addEventListener('keydown', handleGlobalKey)
    return () => window.removeEventListener('keydown', handleGlobalKey)
  }, [])

  return (
    <div className={cn('relative w-full max-w-2xl', className)}>
      <div className="relative flex items-center">
        <Search className="absolute left-3 h-4 w-4 text-muted-foreground" />
        <input
          ref={inputRef}
          type="text"
          value={value}
          onChange={(e) => {
            setValue(e.target.value)
            setShowSuggestions(true)
            setSelectedIndex(-1)
          }}
          onFocus={() => setShowSuggestions(true)}
          onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder || 'Ask a question about your financial data...'}
          disabled={isProcessing}
          className={cn(
            'w-full pl-10 pr-20 py-3 text-sm',
            'border rounded-lg bg-background',
            'focus:outline-none focus:ring-2 focus:ring-primary/50',
            'disabled:opacity-50 disabled:cursor-not-allowed'
          )}
          aria-label="Natural language query input"
          aria-describedby="nlq-hint"
        />
        <div className="absolute right-2 flex items-center gap-1">
          {isProcessing ? (
            <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
          ) : (
            <Sparkles className="h-4 w-4 text-primary" />
          )}
          <kbd className="hidden sm:inline-flex h-5 items-center gap-1 rounded border bg-muted px-1.5 text-[10px] font-medium text-muted-foreground">
            Ctrl+K
          </kbd>
        </div>
      </div>

      {showSuggestions && filtered.length > 0 && (
        <div className="absolute z-50 mt-1 w-full rounded-lg border bg-popover shadow-md">
          {filtered.map((suggestion, i) => (
            <button
              key={suggestion}
              className={cn(
                'w-full px-4 py-2 text-left text-sm hover:bg-accent',
                i === selectedIndex && 'bg-accent'
              )}
              onMouseDown={(e) => {
                e.preventDefault()
                setValue(suggestion)
                onSubmit(suggestion)
                setShowSuggestions(false)
              }}
              onMouseEnter={() => setSelectedIndex(i)}
            >
              <Sparkles className="inline h-3 w-3 mr-2 text-primary" />
              {suggestion}
            </button>
          ))}
        </div>
      )}

      <p id="nlq-hint" className="mt-1 text-xs text-muted-foreground">
        Try: "show Q3 revenue by region" or "compare budget vs actual"
      </p>
    </div>
  )
}

import React from 'react'
import { Check, Circle, Dot } from 'lucide-react'
import { cn } from '@/utils/cn'

export interface Step {
  label: string
  status: 'done' | 'current' | 'pending'
  description?: string
}

export interface ProgressStepperProps {
  steps: Step[]
  currentStep: number
  orientation?: 'horizontal' | 'vertical'
}

export const ProgressStepper: React.FC<ProgressStepperProps> = ({
  steps,
  currentStep,
  orientation = 'horizontal',
}) => {
  const isVertical = orientation === 'vertical'

  return (
    <div
      className={cn('flex w-full', isVertical ? 'flex-col space-y-0' : 'flex-row items-start')}
      role="progressbar"
      aria-valuenow={currentStep + 1}
      aria-valuemin={1}
      aria-valuemax={steps.length}
      aria-label="Progress"
    >
      {steps.map((step, idx) => {
        const isLast = idx === steps.length - 1
        const isDone = step.status === 'done' || idx < currentStep
        const isCurrent = step.status === 'current' || idx === currentStep
        const isPending = !isDone && !isCurrent

        return (
          <div
            key={idx}
            className={cn(
              'flex group',
              isVertical ? 'flex-row min-h-[64px]' : 'flex-1 flex-col items-center'
            )}
            aria-current={isCurrent ? 'step' : undefined}
          >
            {/* Connection Line & Icon Container */}
            <div
              className={cn(
                'relative flex',
                isVertical ? 'flex-col items-center mr-4' : 'flex-row items-center w-full mb-2'
              )}
            >
              {/* Line before (except first) */}
              {!isVertical && idx > 0 && (
                <div
                  className={cn(
                    'h-0.5 w-full absolute right-1/2 top-1/2 -translate-y-1/2 z-0',
                    isDone || isCurrent ? 'bg-blue-600' : 'bg-gray-200'
                  )}
                />
              )}

              {/* Line after (except last) */}
              {!isVertical && !isLast && (
                <div
                  className={cn(
                    'h-0.5 w-full absolute left-1/2 top-1/2 -translate-y-1/2 z-0',
                    isDone ? 'bg-blue-600' : 'bg-gray-200'
                  )}
                />
              )}

              {/* Vertical Line after (except last) */}
              {isVertical && !isLast && (
                <div
                  className={cn(
                    'w-0.5 h-full absolute top-1/2 left-1/2 -translate-x-1/2 z-0',
                    isDone ? 'bg-blue-600' : 'bg-gray-200'
                  )}
                />
              )}

              {/* Icon Node */}
              <div
                className={cn(
                  'relative z-10 flex items-center justify-center w-8 h-8 rounded-full border-2 transition-all duration-300',
                  isDone
                    ? 'bg-blue-600 border-blue-600'
                    : isCurrent
                      ? 'bg-white dark:bg-gray-800 border-blue-600 shadow-md ring-4 ring-blue-50'
                      : 'bg-white dark:bg-gray-800 border-[var(--border-subtle)]'
                )}
              >
                {isDone ? (
                  <Check className="h-4 w-4 text-white" strokeWidth={3} />
                ) : isCurrent ? (
                  <div className="w-2.5 h-2.5 bg-blue-600 rounded-full animate-pulse" />
                ) : (
                  <span className="text-[10px] font-bold text-gray-400 dark:text-gray-500">
                    {idx + 1}
                  </span>
                )}
              </div>
            </div>

            {/* Label Container */}
            <div
              className={cn(
                'flex flex-col',
                isVertical ? 'pt-1.5' : 'items-center text-center px-2'
              )}
            >
              <span
                className={cn(
                  'text-xs font-bold uppercase tracking-wider transition-colors duration-300',
                  isCurrent
                    ? 'text-blue-700'
                    : isDone
                      ? 'text-[var(--text-primary)]'
                      : 'text-gray-400 dark:text-gray-500'
                )}
              >
                {step.label}
              </span>
              {step.description && (
                <span
                  className={cn(
                    'text-[10px] mt-0.5 font-medium leading-tight max-w-[120px]',
                    isCurrent ? 'text-blue-600/70' : 'text-[var(--text-secondary)] opacity-60'
                  )}
                >
                  {step.description}
                </span>
              )}
            </div>
          </div>
        )
      })}
    </div>
  )
}

import React, { useMemo } from 'react'
import { cn } from '@/utils/cn'

export interface SankeyLink {
  source: string
  target: string
  value: number
  color?: string
}

export interface SankeyChartProps {
  links: SankeyLink[]
  width?: number | string
  height?: number
  title?: string
  className?: string
  loading?: boolean
  error?: string
  onClick?: (link: SankeyLink) => void
}

export const SankeyChart: React.FC<SankeyChartProps> = ({
  links,
  width = '100%',
  height = 400,
  title,
  className,
  loading = false,
  error,
  onClick,
}) => {
  if (loading) {
    return (
      <div
        className={cn(
          'w-full flex flex-col p-4 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-xl shadow-sm',
          className
        )}
      >
        <div className="flex items-center justify-center h-48">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500" />
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div
        className={cn(
          'w-full flex flex-col p-4 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-xl shadow-sm',
          className
        )}
      >
        <div className="flex items-center justify-center h-48 text-red-500 text-sm">{error}</div>
      </div>
    )
  }
  const { sources, targets, totalValue, sourceNodes, targetNodes } = useMemo(() => {
    if (!links || links.length === 0)
      return { sources: [], targets: [], totalValue: 0, sourceNodes: {}, targetNodes: {} }
    const sMap: Record<string, number> = {}
    const tMap: Record<string, number> = {}
    let total = 0

    links.forEach((link) => {
      const val = Math.max(0, link.value) // Guard against negative values
      sMap[link.source] = (sMap[link.source] || 0) + val
      tMap[link.target] = (tMap[link.target] || 0) + val
      total += val
    })

    const sNodes = Object.entries(sMap).sort((a, b) => b[1] - a[1])
    const tNodes = Object.entries(tMap).sort((a, b) => b[1] - a[1])

    return {
      sources: sNodes,
      targets: tNodes,
      totalValue: total,
      sourceNodes: sMap,
      targetNodes: tMap,
    }
  }, [links])

  if (totalValue === 0)
    return <div className="flex items-center justify-center h-48 text-slate-400">No data</div>

  const NODE_WIDTH = 20
  const GAP = 10
  const VIEW_HEIGHT = height - 40

  // Calculate vertical offsets
  const getSourceY = (source: string) => {
    let offset = 0
    for (const [s, val] of sources) {
      if (s === source) break
      offset += (val / totalValue) * VIEW_HEIGHT + GAP
    }
    return offset
  }

  const getTargetY = (target: string) => {
    let offset = 0
    for (const [t, val] of targets) {
      if (t === target) break
      offset += (val / totalValue) * VIEW_HEIGHT + GAP
    }
    return offset
  }

  const colors = [
    '#2563eb',
    '#16a34a',
    '#dc2626',
    '#ca8a04',
    '#9333ea',
    '#0891b2',
    '#ea580c',
    '#475569',
    '#be185d',
  ]

  return (
    <div
      className={cn(
        'w-full flex flex-col p-4 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-xl shadow-sm',
        className
      )}
    >
      {title && (
        <div className="mb-6">
          <h3 className="text-xs font-bold uppercase tracking-widest text-[var(--text-secondary)] opacity-60">
            {title}
          </h3>
        </div>
      )}

      <div style={{ width, height }} className="relative">
        <svg width="100%" height="100%" viewBox={`0 0 800 ${height}`} preserveAspectRatio="none">
          {/* Flows */}
          {links.map((link, idx) => {
            const sY = getSourceY(link.source)
            const tY = getTargetY(link.target)

            // This is simplified: need to track how much of each node is already used
            // For a robust one, we'd need internal state for cumulative offsets per node
            // But let's stick to a clean visualization for now
            const linkHeight = (link.value / totalValue) * VIEW_HEIGHT
            const startY = sY + linkHeight / 2
            const endY = tY + linkHeight / 2

            const path = `M ${NODE_WIDTH} ${startY} 
                          C 400 ${startY}, 400 ${endY}, 780 ${endY}`

            return (
              <path
                key={`link-${idx}`}
                d={path}
                fill="none"
                stroke={link.color || colors[idx % colors.length]}
                strokeWidth={linkHeight}
                strokeOpacity={0.2}
                className="transition-all hover:stroke-opacity-50 cursor-pointer"
                onClick={onClick ? () => onClick(link) : undefined}
              />
            )
          })}

          {/* Source Nodes */}
          {sources.map(([name, val], idx) => {
            const y = getSourceY(name)
            const h = (val / totalValue) * VIEW_HEIGHT
            return (
              <g key={`source-${idx}`}>
                <rect x={0} y={y} width={NODE_WIDTH} height={h} fill="#475569" rx={2} />
                <text
                  x={NODE_WIDTH + 8}
                  y={y + h / 2}
                  fontSize="10"
                  fontWeight="bold"
                  alignmentBaseline="middle"
                  fill="#64748b"
                >
                  {name} ({((val / totalValue) * 100).toFixed(0)}%)
                </text>
              </g>
            )
          })}

          {/* Target Nodes */}
          {targets.map(([name, val], idx) => {
            const y = getTargetY(name)
            const h = (val / totalValue) * VIEW_HEIGHT
            return (
              <g key={`target-${idx}`}>
                <rect x={780} y={y} width={NODE_WIDTH} height={h} fill="#475569" rx={2} />
                <text
                  x={780 - 8}
                  y={y + h / 2}
                  fontSize="10"
                  fontWeight="bold"
                  textAnchor="end"
                  alignmentBaseline="middle"
                  fill="#64748b"
                >
                  {name}
                </text>
              </g>
            )
          })}
        </svg>
      </div>
    </div>
  )
}

