interface ScenarioTimelineProps {
  /** Time periods (e.g., months, quarters) */
  periods: string[]
  /** Base case values per period */
  baseValues: number[]
  /** Scenario lines: name, color, values per period */
  scenarios: {
    id: string
    name: string
    color: string
    values: number[]
  }[]
  /** Optional Monte Carlo confidence bands */
  confidenceBands?: {
    low: number[]
    high: number[]
  }
  /** Metric being displayed (for axis label) */
  metricLabel?: string
  /** Highlight inflection points where scenario diverges from base */
  showInflectionPoints?: boolean
  className?: string
}

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
    notation: 'compact',
    compactDisplay: 'short',
  }).format(n)
}

export function ScenarioTimeline({
  periods,
  baseValues,
  scenarios,
  confidenceBands,
  metricLabel = 'Value',
  showInflectionPoints = true,
  className,
}: ScenarioTimelineProps) {
  const chartData = useMemo(() => {
    return periods.map((period, i) => {
      const point: Record<string, number | string> = { period }
      point.Base = baseValues[i]
      scenarios.forEach((s) => {
        point[s.name] = s.values[i]
      })
      if (confidenceBands) {
        point.confidenceLow = confidenceBands.low[i]
        point.confidenceHigh = confidenceBands.high[i]
      }
      return point
    })
  }, [periods, baseValues, scenarios, confidenceBands])

  // Find inflection points: periods where any scenario diverges significantly
  const inflectionPoints = useMemo(() => {
    if (!showInflectionPoints) return []
    const points: { period: string; scenario: string; divergence: number }[] = []
    periods.forEach((period, i) => {
      const base = baseValues[i]
      if (base === 0) return
      scenarios.forEach((s) => {
        const divergence = ((s.values[i] - base) / base) * 100
        if (Math.abs(divergence) > 10) {
          // >10% divergence is inflection
          points.push({ period, scenario: s.name, divergence })
        }
      })
    })
    return points
  }, [periods, baseValues, scenarios, showInflectionPoints])

  const CustomTooltip = ({
    active,
    payload,
    label,
  }: {
    active?: boolean
    payload?: Array<{ dataKey: string; value: number; color: string }>
    label?: string
  }) => {
    if (!active || !payload) return null
    return (
      <div className="rounded-lg border border-[var(--border-subtle)] bg-white dark:bg-gray-800 p-3 shadow-lg dark:border-gray-700 dark:bg-gray-800">
        <p className="text-xs font-medium text-[var(--text-muted)] dark:text-gray-400 dark:text-gray-500 mb-2">
          {label}
        </p>
        {payload.map((entry: { dataKey: string; value: number; color: string }) => (
          <div key={entry.dataKey} className="flex items-center justify-between gap-4 text-xs">
            <div className="flex items-center gap-1.5">
              <div className="h-2 w-2 rounded-full" style={{ backgroundColor: entry.color }} />
              <span className="text-[var(--text-secondary)] dark:text-gray-300">
                {entry.dataKey}
              </span>
            </div>
            <span className="font-mono font-medium text-[var(--text-primary)] dark:text-gray-100">
              {formatCurrency(entry.value)}
            </span>
          </div>
        ))}
      </div>
    )
  }

  return (
    <Card className={className}>
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-medium">{metricLabel} — Timeline</CardTitle>
          {inflectionPoints.length > 0 && (
            <span className="text-[10px] text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 px-2 py-0.5 rounded-full">
              {inflectionPoints.length} inflection point
              {inflectionPoints.length > 1 ? 's' : ''}
            </span>
          )}
        </div>
      </CardHeader>
      <CardContent>
        <div className="h-64">
          <ResponsiveContainer width="100%" height="100%">
            {confidenceBands ? (
              <AreaChart data={chartData}>
                <CartesianGrid
                  strokeDasharray="3 3"
                  className="stroke-gray-200 dark:stroke-gray-700"
                />
                <XAxis
                  dataKey="period"
                  tick={{ fontSize: 10 }}
                  className="text-[var(--text-muted)]"
                />
                <YAxis
                  tickFormatter={(v) => formatCurrency(v)}
                  tick={{ fontSize: 10 }}
                  className="text-[var(--text-muted)]"
                />
                <Tooltip content={<CustomTooltip />} />
                <Legend wrapperStyle={{ fontSize: 11 }} iconType="circle" iconSize={8} />
                <Area
                  dataKey="confidenceHigh"
                  fill="transparent"
                  stroke="transparent"
                  name="Confidence Band"
                />
                <Area
                  dataKey="confidenceLow"
                  fill="#94A3B8"
                  fillOpacity={0.1}
                  stroke="transparent"
                  name=""
                />
                <Line
                  type="monotone"
                  dataKey="Base"
                  stroke="#6B7280"
                  strokeWidth={2}
                  strokeDasharray="4 4"
                  dot={false}
                />
                {scenarios.map((s) => (
                  <Line
                    key={s.id}
                    type="monotone"
                    dataKey={s.name}
                    stroke={s.color}
                    strokeWidth={2}
                    dot={false}
                    activeDot={{ r: 4 }}
                  />
                ))}
              </AreaChart>
            ) : (
              <LineChart data={chartData}>
                <CartesianGrid
                  strokeDasharray="3 3"
                  className="stroke-gray-200 dark:stroke-gray-700"
                />
                <XAxis
                  dataKey="period"
                  tick={{ fontSize: 10 }}
                  className="text-[var(--text-muted)]"
                />
                <YAxis
                  tickFormatter={(v) => formatCurrency(v)}
                  tick={{ fontSize: 10 }}
                  className="text-[var(--text-muted)]"
                />
                <Tooltip content={<CustomTooltip />} />
                <Legend wrapperStyle={{ fontSize: 11 }} iconType="circle" iconSize={8} />
                <Line
                  type="monotone"
                  dataKey="Base"
                  stroke="#6B7280"
                  strokeWidth={2}
                  strokeDasharray="4 4"
                  dot={false}
                />
                {scenarios.map((s) => (
                  <Line
                    key={s.id}
                    type="monotone"
                    dataKey={s.name}
                    stroke={s.color}
                    strokeWidth={2}
                    dot={false}
                    activeDot={{ r: 4 }}
                  />
                ))}
              </LineChart>
            )}
          </ResponsiveContainer>
        </div>

        {/* Inflection points legend */}
        {inflectionPoints.length > 0 && (
          <div className="mt-3 border-t border-gray-100 dark:border-gray-800 dark:border-gray-800 pt-3">
            <p className="text-[10px] font-medium text-[var(--text-muted)] dark:text-gray-400 dark:text-gray-500 mb-1.5">
              Inflection Points (&gt;10% divergence)
            </p>
            <div className="flex flex-wrap gap-2">
              {inflectionPoints.slice(0, 6).map((ip, i) => (
                <span
                  key={i}
                  className="inline-flex items-center gap-1 rounded bg-amber-50 dark:bg-amber-900/20 px-1.5 py-0.5 text-[10px]"
                >
                  <span className="font-medium">{ip.period}</span>
                  <span className="text-gray-400 dark:text-gray-500">·</span>
                  <span className="text-amber-700 dark:text-amber-400">{ip.scenario}</span>
                  <span className="text-gray-400 dark:text-gray-500">·</span>
                  <span className={ip.divergence > 0 ? 'fin-positive' : 'fin-negative'}>
                    {ip.divergence > 0 ? '+' : ''}
                    {ip.divergence.toFixed(1)}%
                  </span>
                </span>
              ))}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

import React, { useState, useRef, useCallback } from 'react'
import { Plus, X, GripVertical } from 'lucide-react'
import { cn } from '@/utils/cn'

export interface SheetTab {
  id: string
  name: string
}

export interface SheetTabsProps {
  sheets: SheetTab[]
  activeSheetId: string
  onSheetChange: (sheetId: string) => void
  onSheetAdd: () => void
  onSheetRename: (sheetId: string, name: string) => void
  onSheetDelete: (sheetId: string) => void
  onSheetReorder: (fromIndex: number, toIndex: number) => void
  className?: string
}

export function SheetTabs({
  sheets,
  activeSheetId,
  onSheetChange,
  onSheetAdd,
  onSheetRename,
  onSheetDelete,
  onSheetReorder,
  className,
}: SheetTabsProps) {
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editValue, setEditValue] = useState('')
  const [contextMenu, setContextMenu] = useState<{ x: number; sheetId: string } | null>(null)
  const [dragIndex, setDragIndex] = useState<number | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const handleDoubleClick = useCallback((sheet: SheetTab) => {
    setEditingId(sheet.id)
    setEditValue(sheet.name)
    setTimeout(() => inputRef.current?.select(), 0)
  }, [])

  const handleRenameSubmit = useCallback(
    (sheetId: string) => {
      if (editValue.trim()) {
        onSheetRename(sheetId, editValue.trim())
      }
      setEditingId(null)
    },
    [editValue, onSheetRename]
  )

  const handleContextMenu = useCallback((e: React.MouseEvent, sheetId: string) => {
    e.preventDefault()
    setContextMenu({ x: e.clientX, sheetId })
  }, [])

  const handleDragStart = useCallback((index: number) => {
    setDragIndex(index)
  }, [])

  const handleDragOver = useCallback(
    (e: React.DragEvent, index: number) => {
      e.preventDefault()
      if (dragIndex !== null && dragIndex !== index) {
        onSheetReorder(dragIndex, index)
        setDragIndex(index)
      }
    },
    [dragIndex, onSheetReorder]
  )

  const handleDragEnd = useCallback(() => {
    setDragIndex(null)
  }, [])

  return (
    <div
      className={cn(
        'flex items-center gap-0.5 px-2 py-1 bg-[var(--bg-muted)] border border-t-0 border-[var(--border-subtle)] rounded-b-lg overflow-x-auto',
        className
      )}
      role="tablist"
      aria-label="Spreadsheet Sheets"
    >
      {sheets.map((sheet, index) => (
        <div
          key={sheet.id}
          className={cn(
            'flex items-center gap-1 px-3 py-1.5 text-xs font-medium rounded-t-md cursor-pointer transition-colors select-none',
            'border border-b-0 border-transparent',
            sheet.id === activeSheetId
              ? 'bg-[var(--bg-surface)] text-[var(--text-primary)] border-[var(--border-subtle)] shadow-sm'
              : 'text-[var(--text-secondary)] hover:bg-[var(--bg-surface)]/50',
            dragIndex === index && 'opacity-50'
          )}
          role="tab"
          aria-selected={sheet.id === activeSheetId}
          onClick={() => onSheetChange(sheet.id)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault()
              onSheetChange(sheet.id)
            }
          }}
          onDoubleClick={() => handleDoubleClick(sheet)}
          onContextMenu={(e) => handleContextMenu(e, sheet.id)}
          draggable
          onDragStart={() => handleDragStart(index)}
          onDragOver={(e) => handleDragOver(e, index)}
          onDragEnd={handleDragEnd}
        >
          <GripVertical className="h-3 w-3 opacity-30 cursor-grab" />

          {editingId === sheet.id ? (
            <input
              ref={inputRef}
              type="text"
              value={editValue}
              onChange={(e) => setEditValue(e.target.value)}
              onBlur={() => handleRenameSubmit(sheet.id)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleRenameSubmit(sheet.id)
                if (e.key === 'Escape') setEditingId(null)
              }}
              className="w-20 px-1 py-0 text-xs bg-white dark:bg-gray-800 border border-blue-400 rounded outline-none"
              autoFocus
            />
          ) : (
            <span>{sheet.name}</span>
          )}

          {sheets.length > 1 && sheet.id === activeSheetId && (
            <button
              onClick={(e) => {
                e.stopPropagation()
                onSheetDelete(sheet.id)
              }}
              className="ml-1 p-0.5 rounded hover:bg-red-100 text-gray-400 dark:text-gray-500 hover:fin-negative transition-colors"
              aria-label={`Delete sheet ${sheet.name}`}
            >
              <X className="h-3 w-3" />
            </button>
          )}
        </div>
      ))}

      {/* Add Sheet Button */}
      <button
        onClick={onSheetAdd}
        className="flex items-center gap-1 px-2 py-1.5 text-xs font-medium text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-surface)]/50 rounded-t-md transition-colors"
        aria-label="Add new sheet"
      >
        <Plus className="h-3.5 w-3.5" />
      </button>

      {/* Context Menu */}
      {contextMenu && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setContextMenu(null)} />
          <div
            className="fixed z-50 bg-white dark:bg-gray-800 border border-[var(--border-subtle)] rounded-md shadow-lg py-1 min-w-[140px]"
            style={{ left: contextMenu.x, top: 'auto', bottom: 40 }}
            role="menu"
            aria-label="Sheet actions"
          >
            <button
              className="w-full px-3 py-1.5 text-left text-xs hover:bg-[var(--bg-hover)]"
              role="menuitem"
              onClick={() => {
                const sheet = sheets.find((s) => s.id === contextMenu.sheetId)
                if (sheet) handleDoubleClick(sheet)
                setContextMenu(null)
              }}
            >
              Rename
            </button>
            {sheets.length > 1 && (
              <button
                className="w-full px-3 py-1.5 text-left text-xs hover:bg-[var(--bg-hover)] fin-negative"
                role="menuitem"
                onClick={() => {
                  onSheetDelete(contextMenu.sheetId)
                  setContextMenu(null)
                }}
              >
                Delete
              </button>
            )}
          </div>
        </>
      )}
    </div>
  )
}

import React, { useMemo, useRef, useCallback, useState, useEffect } from 'react'
import { AgGridReact } from 'ag-grid-react'
import {
  AllCommunityModule,
  ModuleRegistry,
  type ColDef,
  type GridOptions,
  type CellValueChangedEvent,
  type CellClickedEvent,
  type CellKeyDownEvent,
  type SelectionChangedEvent,
} from 'ag-grid-community'
import { cn } from '@/utils/cn'
import { FormulaBar } from './FormulaBar'
import { SheetTabs } from './SheetTabs'
import { ContextMenu, type ContextMenuAction } from './ContextMenu'

ModuleRegistry.registerModules([AllCommunityModule])

// Constants extracted to avoid inline object creation on every render
const NOOP = () => {}
const GRID_STYLE: React.CSSProperties = { height: 'calc(100vh - 240px)', minHeight: 400 }

export interface SpreadsheetColumn {
  field: string
  headerName: string
  width?: number
  minWidth?: number
  type?: 'number' | 'currency' | 'percent' | 'text' | 'date'
  editable?: boolean
  pinned?: 'left' | 'right'
  flex?: number
  format?: string
}

export interface SpreadsheetSheet {
  id: string
  name: string
  rows: Record<string, unknown>[]
  columns: SpreadsheetColumn[]
}

export interface SpreadsheetGridProps {
  sheets: SpreadsheetSheet[]
  activeSheetId?: string
  onSheetChange?: (sheetId: string) => void
  onSheetAdd?: () => void
  onSheetRename?: (sheetId: string, name: string) => void
  onSheetDelete?: (sheetId: string) => void
  onSheetReorder?: (fromIndex: number, toIndex: number) => void
  onCellValueChanged?: (sheetId: string, row: number, field: string, value: unknown) => void
  onSelectionChanged?: (selectedCells: { row: number; col: string }[]) => void
  onUndo?: () => void
  onRedo?: () => void
  freezeRows?: number
  freezeCols?: number
  loading?: boolean
  className?: string
}

export function SpreadsheetGrid({
  sheets,
  activeSheetId,
  onSheetChange,
  onSheetAdd,
  onSheetRename,
  onSheetDelete,
  onSheetReorder,
  onCellValueChanged,
  onSelectionChanged,
  onUndo,
  onRedo,
  freezeRows = 0,
  freezeCols = 0,
  loading = false,
  className,
}: SpreadsheetGridProps) {
  const gridRef = useRef<AgGridReact>(null)
  const [activeCell, setActiveCell] = useState<{ row: number; col: string } | null>(null)
  const [formulaValue, setFormulaValue] = useState('')
  const [isEditing, setIsEditing] = useState(false)
  const [contextMenu, setContextMenu] = useState<{ x: number; y: number } | null>(null)
  const [copiedRange, setCopiedRange] = useState<Record<string, unknown>[] | null>(null)

  const currentSheet = useMemo(
    () => sheets.find((s) => s.id === activeSheetId) || sheets[0],
    [sheets, activeSheetId]
  )

  const columnDefs = useMemo<ColDef[]>(() => {
    if (!currentSheet) return []
    return currentSheet.columns.map((col, idx) => {
      const colDef: ColDef = {
        field: col.field,
        headerName: col.headerName,
        width: col.width || 120,
        minWidth: col.minWidth || 60,
        editable: col.editable ?? true,
        pinned: idx < freezeCols ? 'left' : col.pinned,
        flex: col.flex,
        sortable: true,
        filter: true,
        resizable: true,
        suppressMovable: false,
      }

      if (col.type === 'currency') {
        colDef.cellClass = 'text-right tabular-nums font-mono'
        colDef.valueFormatter = (params) => {
          if (params.value == null) return ''
          return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
            minimumFractionDigits: 2,
          }).format(params.value as number)
        }
      } else if (col.type === 'percent') {
        colDef.cellClass = 'text-right tabular-nums font-mono'
        colDef.valueFormatter = (params) => {
          if (params.value == null) return ''
          return `${(params.value as number).toFixed(1)}%`
        }
        colDef.cellClassRules = {
          'fin-positive font-medium': (params) => {
            const val = Number(params.value)
            return !isNaN(val) && val > 0
          },
          'fin-negative font-medium': (params) => {
            const val = Number(params.value)
            return !isNaN(val) && val < 0
          },
        }
      } else if (col.type === 'number') {
        colDef.cellClass = 'text-right tabular-nums font-mono'
      }

      return colDef
    })
  }, [currentSheet, freezeCols])

  const defaultColDef = useMemo<ColDef>(
    () => ({
      sortable: true,
      filter: true,
      resizable: true,
      editable: true,
    }),
    []
  )

  const handleCellClicked = useCallback((event: CellClickedEvent) => {
    if (event.rowIndex != null) {
      setActiveCell({ row: event.rowIndex, col: event.column.getColId() })
      const value = event.value
      setFormulaValue(value != null ? String(value) : '')
    }
  }, [])

  const handleCellValueChanged = useCallback(
    (event: CellValueChangedEvent) => {
      if (currentSheet && onCellValueChanged) {
        onCellValueChanged(currentSheet.id, event.rowIndex!, event.colDef.field!, event.newValue)
      }
    },
    [currentSheet, onCellValueChanged]
  )

  const handleFormulaChange = useCallback((value: string) => {
    setFormulaValue(value)
  }, [])

  const handleFormulaEvaluate = useCallback(
    (result: number) => {
      if (gridRef.current && activeCell) {
        gridRef.current.api.forEachNode((node) => {
          if (node.rowIndex === activeCell.row) {
            node.setDataValue(activeCell.col, result)
          }
        })
      }
      setIsEditing(false)
    },
    [activeCell]
  )

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (!gridRef.current || !activeCell) return

      if (e.ctrlKey || e.metaKey) {
        switch (e.key.toLowerCase()) {
          case 'c': {
            const selectedRows = gridRef.current.api.getSelectedRows()
            if (selectedRows.length) {
              setCopiedRange(selectedRows)
              const tsv = selectedRows
                .map((row) => currentSheet?.columns.map((c) => row[c.field] ?? '').join('\t'))
                .join('\n')
              navigator.clipboard.writeText(tsv)
            }
            e.preventDefault()
            break
          }
          case 'v': {
            if (copiedRange?.length && currentSheet) {
              const startRow = activeCell.row
              copiedRange.forEach((srcRow, i) => {
                const targetRowIndex = startRow + i
                currentSheet.columns.forEach((col) => {
                  if (srcRow[col.field] !== undefined) {
                    gridRef.current?.api.forEachNode((node) => {
                      if (node.rowIndex === targetRowIndex) {
                        node.setDataValue(col.field, srcRow[col.field])
                      }
                    })
                  }
                })
              })
            }
            e.preventDefault()
            break
          }
          case 'z':
            onUndo?.()
            e.preventDefault()
            break
          case 'y':
            onRedo?.()
            e.preventDefault()
            break
          case 'd':
            // Fill down — copy value from row above into active cell
            if (activeCell.row > 0 && currentSheet) {
              const col = activeCell.col
              const prevNode = gridRef.current.api.getDisplayedRowAtIndex(activeCell.row - 1)
              if (prevNode) {
                const value = prevNode.data[col]
                gridRef.current.api.forEachNode((node) => {
                  if (node.rowIndex === activeCell.row) {
                    node.setDataValue(col, value)
                  }
                })
              }
            }
            e.preventDefault()
            break
        }
      }

      if (e.key === 'F2') {
        setIsEditing(true)
        gridRef.current.api.startEditingCell({
          rowIndex: activeCell.row,
          colKey: activeCell.col,
        })
        e.preventDefault()
      }

      if (e.key === 'Delete' || e.key === 'Backspace') {
        const selectedRows = gridRef.current.api.getSelectedRows()
        selectedRows.forEach((row) => {
          if (activeCell.col) {
            gridRef.current?.api.forEachNode((node) => {
              if (node.data === row) {
                node.setDataValue(activeCell.col, null)
              }
            })
          }
        })
        e.preventDefault()
      }
    },
    [activeCell, currentSheet, copiedRange, onUndo, onRedo]
  )

  const handleContextMenu = useCallback((e: React.MouseEvent) => {
    e.preventDefault()
    setContextMenu({ x: e.clientX, y: e.clientY })
  }, [])

  const handleContextMenuAction = useCallback(
    (action: ContextMenuAction) => {
      if (!gridRef.current || !activeCell || !currentSheet) return

      switch (action) {
        case 'cut': {
          const selectedRows = gridRef.current.api.getSelectedRows()
          if (selectedRows.length) {
            setCopiedRange(selectedRows)
            const tsv = selectedRows
              .map((row) => currentSheet.columns.map((c) => row[c.field] ?? '').join('\t'))
              .join('\n')
            navigator.clipboard.writeText(tsv)
            selectedRows.forEach((row) => {
              currentSheet.columns.forEach((col) => {
                gridRef.current?.api.forEachNode((node) => {
                  if (node.data === row) {
                    node.setDataValue(col.field, null)
                  }
                })
              })
            })
          }
          break
        }
        case 'copy': {
          const selectedRows = gridRef.current.api.getSelectedRows()
          if (selectedRows.length) {
            setCopiedRange(selectedRows)
            const tsv = selectedRows
              .map((row) => currentSheet.columns.map((c) => row[c.field] ?? '').join('\t'))
              .join('\n')
            navigator.clipboard.writeText(tsv)
          }
          break
        }
        case 'paste':
          if (copiedRange?.length) {
            const startRow = activeCell.row
            copiedRange.forEach((srcRow, i) => {
              const targetRowIndex = startRow + i
              currentSheet.columns.forEach((col) => {
                if (srcRow[col.field] !== undefined) {
                  gridRef.current?.api.forEachNode((node) => {
                    if (node.rowIndex === targetRowIndex) {
                      node.setDataValue(col.field, srcRow[col.field])
                    }
                  })
                }
              })
            })
          }
          break
        case 'insertRowAbove':
          // Handled by parent via callback
          break
        case 'insertRowBelow':
          break
        case 'deleteRow':
          break
        case 'insertColLeft':
          break
        case 'insertColRight':
          break
        case 'deleteCol':
          break
        case 'clearContents': {
          const selectedRows = gridRef.current.api.getSelectedRows()
          selectedRows.forEach((row) => {
            currentSheet.columns.forEach((col) => {
              gridRef.current?.api.forEachNode((node) => {
                if (node.data === row) {
                  node.setDataValue(col.field, null)
                }
              })
            })
          })
          break
        }
        case 'sortAsc':
          gridRef.current.api.applyColumnState({
            state: [{ colId: activeCell.col, sort: 'asc' }],
          })
          break
        case 'sortDesc':
          gridRef.current.api.applyColumnState({
            state: [{ colId: activeCell.col, sort: 'desc' }],
          })
          break
      }
      setContextMenu(null)
    },
    [activeCell, currentSheet, copiedRange]
  )

  useEffect(() => {
    const handleClickOutside = () => setContextMenu(null)
    window.addEventListener('click', handleClickOutside)
    return () => window.removeEventListener('click', handleClickOutside)
  }, [])

  const cellRefLabel = activeCell ? `${activeCell.col}${activeCell.row + 1}` : '---'

  return (
    <div className={cn('flex flex-col w-full', className)}>
      {/* Formula Bar */}
      <FormulaBar
        value={formulaValue}
        onChange={handleFormulaChange}
        onEvaluate={handleFormulaEvaluate}
        activeCell={cellRefLabel}
        disabled={!activeCell}
      />

      {/* Grid */}
      <div
        className={cn(
          'relative w-full border border-t-0 border-[var(--border-subtle)] rounded-b-lg overflow-hidden',
          loading && 'opacity-50 pointer-events-none grayscale'
        )}
        onContextMenu={handleContextMenu}
        onKeyDown={handleKeyDown}
        tabIndex={0}
        role="grid"
        aria-label="Spreadsheet Grid"
        style={GRID_STYLE}
      >
        <AgGridReact
          ref={gridRef}
          rowData={currentSheet?.rows || []}
          columnDefs={columnDefs}
          defaultColDef={defaultColDef}
          onCellClicked={handleCellClicked}
          onCellValueChanged={handleCellValueChanged}
          onCellEditingStarted={() => setIsEditing(true)}
