          className
        )}
      >
        <div className="flex items-center justify-center h-48">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500" />
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div
        className={cn(
          'w-full flex flex-col p-4 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-xl shadow-sm',
          className
        )}
      >
        <div className="flex items-center justify-center h-48 text-red-500 text-sm">{error}</div>
      </div>
    )
  }

  if (!data || data.length === 0) {
    return (
      <div
        className={cn(
          'w-full flex flex-col p-4 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-xl shadow-sm',
          className
        )}
      >
        {title && (
          <div className="mb-4">
            <h3 className="text-xs font-bold uppercase tracking-widest text-[var(--text-secondary)] opacity-60">
              {title}
            </h3>
          </div>
        )}
        <div className="flex items-center justify-center h-48 text-slate-400">No data</div>
      </div>
    )
  }

  return (
    <div
      className={cn(
        'w-full flex flex-col p-4 bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-xl shadow-sm',
        className
      )}
    >
      {title && (
        <div className="mb-4">
          <h3 className="text-xs font-bold uppercase tracking-widest text-[var(--text-secondary)] opacity-60">
            {title}
          </h3>
        </div>
      )}
      <div style={{ height }} className="w-full">
        <ResponsiveContainer width="100%" height="100%">
          <Treemap
            data={data as unknown as import('recharts').TreemapProps['data']}
            dataKey="value"
            aspectRatio={4 / 3}
            stroke="#fff"
            content={<CustomizedContent />}
          >
            <Tooltip
              content={({ active, payload }) => {
                if (active && payload && payload.length) {
                  const d = payload[0].payload
                  return (
                    <div className="bg-slate-900 text-white p-2 rounded shadow-xl border border-slate-800 text-[10px]">
                      <div className="font-black uppercase tracking-wider mb-1">{d.name}</div>
                      <div className="font-medium opacity-80">
                        Value: {d.value.toLocaleString()}
                      </div>
                    </div>
                  )
                }
                return null
              }}
            />
          </Treemap>
        </ResponsiveContainer>
      </div>
    </div>
  )
}

import React from 'react'
import { cn } from '@/utils/cn'

export interface WaterfallItem {
  label: string
  value: number
  type: 'increase' | 'decrease' | 'total'
  color?: string
}

export interface WaterfallBridgeProps {
  items: WaterfallItem[]
  format?: (value: number) => string
  className?: string
}

export const WaterfallBridge: React.FC<WaterfallBridgeProps> = ({
  items,
  format = (v) => v.toLocaleString(),
  className,
}) => {
  if (!items || items.length === 0)
    return <div className="flex items-center justify-center h-48 text-slate-400">No data</div>

  const colors = {
    increase: '#10b981',
    decrease: '#ef4444',
    total: '#3b82f6',
  }

  // Calculate running totals
  let runningTotal = 0
  const processedItems = items.map((item) => {
    const start = item.type === 'total' ? 0 : runningTotal
    const end = item.type === 'total' ? item.value : start + item.value
    runningTotal = end
    return { ...item, start, end }
  })

  const allValues = processedItems.flatMap((i) => [i.start, i.end])
  const minVal = Math.min(...allValues)
  const maxVal = Math.max(...allValues)
  const range = maxVal - minVal || 1 // Guard against zero range

  return (
    <div className={cn('w-full', className)}>
      <div className="flex items-end gap-2 h-48">
        {processedItems.map((item, i) => {
          const color = item.color ?? colors[item.type]
          const bottom = ((Math.min(item.start, item.end) - minVal) / range) * 100
          const height = (Math.abs(item.end - item.start) / range) * 100

          return (
            <div key={i} className="flex-1 flex flex-col items-center">
              <div className="relative w-full h-full">
                <div
                  className="absolute w-full rounded"
                  style={{
                    bottom: `${bottom}%`,
                    height: `${Math.max(height, 2)}%`,
                    backgroundColor: color,
                  }}
                />
                {/* Connector line to next bar */}
                {i < processedItems.length - 1 && (
                  <div
                    className="absolute w-full h-px bg-gray-300"
                    style={{ bottom: `${((item.end - minVal) / range) * 100}%` }}
                  />
                )}
              </div>
              <div className="text-xs text-[var(--text-secondary)] mt-2 truncate w-full text-center">
                {item.label}
              </div>
              <div className="text-xs font-medium mt-0.5" style={{ color }}>
                {format(item.value)}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

