import { useCallback, useEffect, useMemo, useState } from 'react'
import { Modal } from '@/components/ui/Modal'
import { Button } from '@/components/ui/Button'
import { useGLStore } from '@/store/glStore'
import {
  DrillThroughEngine,
  type DrillBreadcrumb,
  type DrillContext,
} from '@/engines/DrillThroughEngine'
import { ChevronRight, ArrowLeft, Layers, Building2, FileText } from 'lucide-react'

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n)
}

function formatDate(d: string): string {
  if (!d) return '—'
  const date = new Date(d)
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
}

interface DrillRow {
  id: string
  date: string
  description: string
  amount: number
  department: string
  accountCode: string
  accountName: string
}

interface DepartmentGroup {
  department: string
  entries: DrillRow[]
  total: number
}

type DrillView = 'category' | 'department' | 'transaction'

interface VarianceDrillModalProps {
  isOpen: boolean
  onClose: () => void
  accountLabel: string
  accountPrefix: string
  variance: number
  budget: number
  actual: number
}

const engine = new DrillThroughEngine()

export function VarianceDrillModal({
  isOpen,
  onClose,
  accountLabel,
  accountPrefix,
  variance,
  budget,
  actual,
}: VarianceDrillModalProps) {
  const entries = useGLStore((s) => s.entries)
  const [breadcrumbs, setBreadcrumbs] = useState<DrillBreadcrumb[]>([])
  const [currentView, setCurrentView] = useState<DrillView>('category')
  const [selectedDepartment, setSelectedDepartment] = useState<string | null>(null)

  useEffect(() => {
    if (!isOpen) {
      engine.reset()
      setBreadcrumbs([])
      setCurrentView('category')
      setSelectedDepartment(null)
    }
  }, [isOpen])

  useEffect(() => {
    return engine.subscribe((path) => setBreadcrumbs([...path]))
  }, [])

  const filteredEntries = useMemo(() => {
    return entries
      .filter((e) => (e.accountCode || '').startsWith(accountPrefix))
      .map((e) => ({
        id: e.id,
        date: e.postDate || e.date,
        description: e.description || '—',
        amount: e.amount ?? e.debit - e.credit,
        department: e.departmentId || 'Unassigned',
        accountCode: e.accountCode,
        accountName: e.accountName,
      }))
  }, [entries, accountPrefix])

  const departmentGroups = useMemo((): DepartmentGroup[] => {
    const map = new Map<string, DrillRow[]>()
    for (const entry of filteredEntries) {
      const list = map.get(entry.department) ?? []
      list.push(entry)
      map.set(entry.department, list)
    }
    return Array.from(map.entries())
      .map(([dept, ents]) => ({
        department: dept,
        entries: ents.sort((a, b) => b.date.localeCompare(a.date)),
        total: ents.reduce((s, e) => s + e.amount, 0),
      }))
      .sort((a, b) => Math.abs(b.total) - Math.abs(a.total))
  }, [filteredEntries])

  const selectedEntries = useMemo(() => {
    if (!selectedDepartment) return []
    return filteredEntries
      .filter((e) => e.department === selectedDepartment)
      .sort((a, b) => b.date.localeCompare(a.date))
  }, [filteredEntries, selectedDepartment])

  const handleDrillToDepartment = useCallback(
    (dept: string) => {
      const ctx: DrillContext = {
        cellValue: filteredEntries.filter((e) => e.department === dept).length,
        account: accountLabel,
        metric: dept,
      }
      engine.drillDown(ctx)
      setSelectedDepartment(dept)
      setCurrentView('department')
    },
    [filteredEntries, accountLabel]
  )

  const handleDrillToTransaction = useCallback(() => {
    const ctx: DrillContext = {
      cellValue: selectedEntries.length,
      account: accountLabel,
      metric: selectedDepartment ?? 'Transactions',
    }
    engine.drillDown(ctx)
    setCurrentView('transaction')
  }, [selectedEntries, accountLabel, selectedDepartment])

  const handleBreadcrumbNav = useCallback((targetLevel: string) => {
    engine.drillToLevel(targetLevel as 'summary' | 'detail' | 'journal-entry' | 'source-document')
    if (targetLevel === 'summary') {
      setCurrentView('category')
      setSelectedDepartment(null)
    } else if (targetLevel === 'detail') {
      setCurrentView('department')
    }
  }, [])

  const handleBack = useCallback(() => {
    engine.goBack()
    if (currentView === 'transaction') {
      setCurrentView('department')
    } else if (currentView === 'department') {
      setCurrentView('category')
      setSelectedDepartment(null)
    }
  }, [currentView])

  return (
    <Modal isOpen={isOpen} onClose={onClose} className="sm:max-w-3xl">
      <div className="p-6">
        <div className="flex items-center gap-2 mb-1">
          <Layers className="h-5 w-5 text-blue-400" />
          <h2 className="text-lg font-semibold">{accountLabel} Variance Drill-Through</h2>
        </div>
        <p className="text-sm text-slate-400 mb-4">
          Budget: {formatCurrency(budget)} &middot; Actual: {formatCurrency(actual)} &middot;
          Variance:{' '}
          <span className={variance >= 0 ? 'text-green-400' : 'text-red-400'}>
            {formatCurrency(variance)}
          </span>
        </p>

        {breadcrumbs.length > 0 && (
          <div className="flex items-center gap-1 text-xs text-slate-400 mb-3 flex-wrap">
            <button
              onClick={() => handleBreadcrumbNav('summary')}
              className="hover:text-blue-400 transition-colors"
            >
              {accountLabel}
            </button>
            {breadcrumbs.map((crumb, i) => (
              <span key={i} className="flex items-center gap-1">
                <ChevronRight className="h-3 w-3" />
                <button
                  onClick={() => handleBreadcrumbNav(crumb.level)}
                  className="hover:text-blue-400 transition-colors"
                >
                  {crumb.label}
                </button>
              </span>
            ))}
          </div>
        )}

        {currentView !== 'category' && (
          <Button size="sm" variant="ghost" onClick={handleBack} className="mb-3">
            <ArrowLeft className="h-3.5 w-3.5 mr-1" />
            Back
          </Button>
        )}

        {currentView === 'category' && (
          <div className="space-y-2">
            <p className="text-sm text-slate-300 mb-3">
              {filteredEntries.length} entries across {departmentGroups.length} departments. Click a
              department to drill down.
            </p>
            <div className="overflow-hidden rounded-lg border border-slate-700">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-slate-800/50 text-left">
                    <th className="px-4 py-2.5 font-medium text-slate-300">Department</th>
                    <th className="px-4 py-2.5 font-medium text-slate-300 text-right">Entries</th>
                    <th className="px-4 py-2.5 font-medium text-slate-300 text-right">
                      Total Amount
                    </th>
                    <th className="px-4 py-2.5 font-medium text-slate-300 text-right">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-700/50">
                  {departmentGroups.map((group) => (
                    <tr
                      key={group.department}
                      className="hover:bg-slate-800/30 cursor-pointer transition-colors"
                      onClick={() => handleDrillToDepartment(group.department)}
                    >
                      <td className="px-4 py-2.5 flex items-center gap-2">
                        <Building2 className="h-4 w-4 text-slate-400" />
                        {group.department}
                      </td>
                      <td className="px-4 py-2.5 text-right text-slate-300">
                        {group.entries.length}
                      </td>
                      <td className="px-4 py-2.5 text-right">
                        <span className={group.total >= 0 ? 'text-green-400' : 'text-red-400'}>
                          {formatCurrency(group.total)}
                        </span>
                      </td>
                      <td className="px-4 py-2.5 text-right">
                        <ChevronRight className="h-4 w-4 text-slate-400 inline" />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {currentView === 'department' && selectedDepartment && (
          <div className="space-y-2">
            <div className="flex items-center justify-between mb-3">
              <p className="text-sm text-slate-300">
                <span className="font-medium text-white">{selectedDepartment}</span> &middot;{' '}
                {selectedEntries.length} entries
              </p>
              <Button size="sm" variant="ghost" onClick={handleDrillToTransaction}>
                <FileText className="h-3.5 w-3.5 mr-1" />
                View All Transactions
              </Button>
            </div>
            <div className="overflow-hidden rounded-lg border border-slate-700">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-slate-800/50 text-left">
                    <th className="px-4 py-2.5 font-medium text-slate-300">Date</th>
                    <th className="px-4 py-2.5 font-medium text-slate-300">Description</th>
                    <th className="px-4 py-2.5 font-medium text-slate-300 text-right">Amount</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-700/50">
                  {selectedEntries.slice(0, 50).map((entry) => (
                    <tr key={entry.id} className="hover:bg-slate-800/30 transition-colors">
                      <td className="px-4 py-2 text-slate-400 whitespace-nowrap">
                        {formatDate(entry.date)}
                      </td>
                      <td className="px-4 py-2">{entry.description}</td>
                      <td className="px-4 py-2 text-right">
                        <span className={entry.amount >= 0 ? 'text-green-400' : 'text-red-400'}>
                          {formatCurrency(entry.amount)}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {selectedEntries.length > 50 && (
              <p className="text-xs text-slate-500 text-center mt-2">
                Showing 50 of {selectedEntries.length} entries. Click &quot;View All
                Transactions&quot; for full list.
              </p>
            )}
          </div>
        )}

        {currentView === 'transaction' && selectedDepartment && (
          <div className="space-y-2">
            <p className="text-sm text-slate-300 mb-3">
              All transactions for{' '}
              <span className="font-medium text-white">{selectedDepartment}</span>
            </p>
            <div className="overflow-hidden rounded-lg border border-slate-700 max-h-[400px] overflow-y-auto">
              <table className="w-full text-sm">
                <thead className="sticky top-0 bg-slate-800 z-10">
                  <tr className="bg-slate-800/50 text-left">
                    <th className="px-4 py-2.5 font-medium text-slate-300">Date</th>
                    <th className="px-4 py-2.5 font-medium text-slate-300">Account</th>
                    <th className="px-4 py-2.5 font-medium text-slate-300">Description</th>
                    <th className="px-4 py-2.5 font-medium text-slate-300 text-right">Amount</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-700/50">
                  {selectedEntries.map((entry) => (
                    <tr key={entry.id} className="hover:bg-slate-800/30 transition-colors">
                      <td className="px-4 py-2 text-slate-400 whitespace-nowrap">
                        {formatDate(entry.date)}
                      </td>
                      <td className="px-4 py-2 text-slate-300 whitespace-nowrap">
                        {entry.accountCode}
                      </td>
                      <td className="px-4 py-2">{entry.description}</td>
                      <td className="px-4 py-2 text-right">
                        <span className={entry.amount >= 0 ? 'text-green-400' : 'text-red-400'}>
                          {formatCurrency(entry.amount)}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        <div className="flex justify-end mt-5">
          <Button variant="ghost" onClick={onClose}>
            Close
          </Button>
        </div>
      </div>
    </Modal>
  )
}

import { FinancialTable } from '@/components/ui/FinancialTable'
import { Badge } from '@/components/ui/Badge'
import type { VarianceAnalysis } from '@/types'

export interface VarianceTableProps {
  analyses: VarianceAnalysis[]
  onSelect: (accountId: string) => void
  onCommentaryEdit: (accountId: string, commentary: string) => void
  selectedAccountId?: string
}

export function VarianceTable({
  analyses,
  onSelect,
  onCommentaryEdit,
  selectedAccountId,
}: VarianceTableProps) {
  if (analyses.length === 0) {
    return (
      <div className="p-12 text-center text-slate-500 bg-slate-900 rounded-lg border border-slate-800">
        No variance data
      </div>
    )
  }

  return (
    <FinancialTable
      rows={analyses as unknown as import('@/components/ui/FinancialTable').FinancialTableRow[]}
      columns={[
        { key: 'accountName', header: 'Account', type: 'string', width: '200px' },
        { key: 'budget', header: 'Budget', type: 'currency' },
        { key: 'actual', header: 'Actual', type: 'currency' },
        {
          key: 'variance',
          header: 'Var $',
          type: 'currency',
          color: (val) => ((val as number) >= 0 ? 'text-green-400' : 'text-red-400'),
        },
        {
          key: 'variancePercent',
          header: 'Var %',
          type: 'percent',
          color: (val) => ((val as number) >= 0 ? 'text-green-400' : 'text-red-400'),
        },
        {
          key: 'status',
          header: 'Status',
          type: 'badge',
          render: (val) => (
            <Badge
              variant={val === 'Within' ? 'default' : val === 'Watch' ? 'secondary' : 'destructive'}
            >
              {String(val ?? '')}
            </Badge>
          ),
        },
        {
          key: 'commentary',
          header: 'Commentary',
          type: 'string',
          render: (val, row) => (
            <input
              defaultValue={val as string}
              onBlur={(e) => onCommentaryEdit(row.accountId as string, e.target.value)}
              className="bg-transparent border-none outline-none text-slate-400 text-sm w-full focus:text-white"
            />
          ),
        },
      ]}
    />
  )
}

