  // FULL CONSOLIDATION SCENARIO TESTS
  // =========================================================================

  describe('full consolidation scenarios', () => {
    it('should handle complete parent-subsidiary consolidation with eliminations', () => {
      // Parent has investment in sub, sub has equity
      const parentEntries = [
        createEntry('p1', '1000', 'Cash', 200000, 'parent'),
        createEntry('p2', '1500', 'Investment in Sub', 80000, 'parent'),
        createEntry('p3', '4000', 'Revenue', 150000, 'parent'),
        createEntry('p4', '5000', 'Expense', -90000, 'parent'),
        createEntry('p5', '3000', 'Common Stock', -100000, 'parent'),
        createEntry('p6', '3100', 'Retained Earnings', -130000, 'parent'),
      ]
      const subEntries = [
        createEntry('s1', '1000', 'Cash', 50000, 'sub'),
        createEntry('s2', '4000', 'Revenue', 60000, 'sub'),
        createEntry('s3', '5000', 'Expense', -35000, 'sub'),
        createEntry('s4', '3000', 'Common Stock', -30000, 'sub'),
        createEntry('s5', '3100', 'Retained Earnings', -45000, 'sub'),
      ]

      const entities = [createParent(parentEntries), createSubsidiary('sub', 'Sub Inc', subEntries)]
      const ownerships: OwnershipStructure[] = [
        {
          parentId: 'parent',
          childId: 'sub',
          ownershipPct: 80,
          method: 'full',
          acquisitionCost: 80000,
          bookValueAtAcquisition: 75000,
        },
      ]
      const icPairs = [createICPair('parent', 'sub', '1500', 80000, 'investment')]

      const result = ConsolidationEngine.consolidate(entities, ownerships, icPairs)

      // Should have eliminations for investment
      expect(result.eliminations.length).toBeGreaterThan(0)

      // Should have minority interest (80% ownership = 20% minority)
      expect(result.minorityInterestDetails).toHaveLength(1)
      expect(result.minorityInterestDetails[0].minorityPct).toBe(20)

      // Should have goodwill (acquisition cost > book value)
      expect(result.goodwill).toBeGreaterThan(0)

      // Should have worksheet
      expect(result.worksheet).toBeDefined()
      expect(result.worksheet.parentEntries.length).toBeGreaterThan(0)
      expect(result.worksheet.subsidiaryEntries.length).toBeGreaterThan(0)
    })

    it('should handle 100% ownership (no minority interest)', () => {
      const parentEntries = [
        createEntry('p1', '1000', 'Cash', 100000, 'parent'),
        createEntry('p2', '3000', 'Equity', -100000, 'parent'),
      ]
      const subEntries = [
        createEntry('s1', '1000', 'Cash', 50000, 'sub'),
        createEntry('s2', '3000', 'Equity', -50000, 'sub'),
      ]

      const entities = [createParent(parentEntries), createSubsidiary('sub', 'Sub', subEntries)]
      const ownerships = [createOwnership('parent', 'sub', 100)]

      const result = ConsolidationEngine.consolidate(entities, ownerships, [])

      expect(result.minorityInterest).toBe(0)
      expect(result.minorityInterestDetails).toHaveLength(0)
    })

    it('should handle minority ownership (no consolidation)', () => {
      const parentEntries = [
        createEntry('p1', '1000', 'Cash', 100000, 'parent'),
        createEntry('p2', '3000', 'Equity', -100000, 'parent'),
      ]
      const subEntries = [
        createEntry('s1', '1000', 'Cash', 50000, 'sub'),
        createEntry('s2', '3000', 'Equity', -50000, 'sub'),
      ]

      const entities = [createParent(parentEntries), createSubsidiary('sub', 'Sub', subEntries)]
      const ownerships = [createOwnership('parent', 'sub', 30, 'equity')]

      const result = ConsolidationEngine.consolidate(entities, ownerships, [])

      // Equity method — no minority interest calculation
      expect(result.minorityInterestDetails).toHaveLength(0)
    })

    it('should handle foreign subsidiary consolidation', () => {
      const parentEntries = [
        createEntry('p1', '1000', 'Cash', 100000, 'parent'),
        createEntry('p2', '3000', 'Equity', -100000, 'parent'),
      ]
      const foreignEntries = [
        createEntry('f1', '1000', 'Cash', 50000, 'foreign', 'EUR'),
        createEntry('f2', '3000', 'Equity', -50000, 'foreign', 'EUR'),
      ]

      const entities = [
        createParent(parentEntries),
        {
          ...createSubsidiary('foreign', 'Foreign Sub', foreignEntries, true, 'EUR'),
          isForeign: true,
          functionalCurrency: 'EUR',
        },
      ]
      const ownerships = [createOwnership('parent', 'foreign', 80)]
      const fxRates: FXRate[] = [
        { fromCurrency: 'EUR', toCurrency: 'USD', rate: 1.1, rateType: 'spot', date: '2024-01-01' },
        {
          fromCurrency: 'EUR',
          toCurrency: 'USD',
          rate: 1.05,
          rateType: 'average',
          date: '2024-01-01',
        },
        {
          fromCurrency: 'EUR',
          toCurrency: 'USD',
          rate: 1.0,
          rateType: 'historical',
          date: '2024-01-01',
        },
      ]

      const result = ConsolidationEngine.consolidate(entities, ownerships, [], fxRates)

      // Foreign entries should be translated
      expect(result.totalAssets).toBeGreaterThan(100000) // Parent + translated foreign
    })

    it('should handle VIE consolidation', () => {
      const parentEntries = [
        createEntry('p1', '1000', 'Cash', 100000, 'parent'),
        createEntry('p2', '1500', 'Investment in VIE', 50000, 'parent'),
        createEntry('p3', '3000', 'Equity', -150000, 'parent'),
      ]
      const vieEntries = [
        createEntry('v1', '1000', 'Cash', 30000, 'vie'),
        createEntry('v2', '3000', 'Equity', -30000, 'vie'),
      ]

      const entities = [
        createParent(parentEntries),
        { ...createSubsidiary('vie', 'VIE Entity', vieEntries), isVIE: true },
      ]
      const ownerships = [createOwnership('parent', 'vie', 0, 'full')]
      const vieNotifications: VIENotification[] = [
        {
          entityId: 'vie',
          isPrimaryBeneficiary: true,
          variableInterests: ['equity', 'debt'],
          power: 'Power to direct activities',
          economics: 'Expected residual returns',
        },
      ]

      const result = ConsolidationEngine.consolidate(
        entities,
        ownerships,
        [],
        [],
        [],
        vieNotifications
      )

      expect(result.eliminations.length).toBeGreaterThan(0)
    })
  })

  // =========================================================================
  // EDGE CASE TESTS
  // =========================================================================

  describe('edge cases', () => {
    it('should handle zero amounts', () => {
      const entries = [
        createEntry('1', '1000', 'Cash', 0, 'parent'),
        createEntry('2', '3000', 'Equity', 0, 'parent'),
      ]
      const entities = [createParent(entries)]

      const result = ConsolidationEngine.consolidate(entities, [], [])

      expect(result.isBalanced).toBe(true)
    })

    it('should handle very large numbers', () => {
      const entries = [
        createEntry('1', '1000', 'Cash', 999999999999, 'parent'),
        createEntry('2', '3000', 'Equity', -999999999999, 'parent'),
      ]
      const entities = [createParent(entries)]

      const result = ConsolidationEngine.consolidate(entities, [], [])

      expect(result.totalAssets).toBe(999999999999)
      expect(result.isBalanced).toBe(true)
    })

    it('should handle very small numbers', () => {
      const entries = [
        createEntry('1', '1000', 'Cash', 0.01, 'parent'),
        createEntry('2', '3000', 'Equity', -0.01, 'parent'),
      ]
      const entities = [createParent(entries)]

      const result = ConsolidationEngine.consolidate(entities, [], [])

      expect(result.isBalanced).toBe(true)
    })

    it('should handle negative balances', () => {
      const entries = [
        createEntry('1', '1000', 'Cash', -5000, 'parent'), // Overdraft
        createEntry('2', '3000', 'Equity', 5000, 'parent'),
      ]
      const entities = [createParent(entries)]

      const result = ConsolidationEngine.consolidate(entities, [], [])

      expect(result.totalAssets).toBe(-5000)
    })

    it('should handle single entity with all account types', () => {
      const entries = [
        createEntry('1', '1000', 'Cash', 100000, 'ent'),
        createEntry('2', '1500', 'Equipment', 50000, 'ent'),
        createEntry('3', '2000', 'Accounts Payable', -30000, 'ent'),
        createEntry('4', '2500', 'Long-term Debt', -40000, 'ent'),
        createEntry('5', '3000', 'Common Stock', -50000, 'ent'),
        createEntry('6', '3100', 'Retained Earnings', -20000, 'ent'),
        createEntry('7', '4000', 'Revenue', 80000, 'ent'),
        createEntry('8', '5000', 'Expense', -40000, 'ent'),
      ]
      const entities = [createParent(entries)]

      const result = ConsolidationEngine.consolidate(entities, [], [])

      expect(result.totalAssets).toBe(150000)
      expect(result.totalLiabilities).toBe(-70000)
      expect(result.totalEquity).toBe(-70000)
      expect(result.totalRevenue).toBe(80000)
      expect(result.totalExpenses).toBe(-40000)
      expect(result.netIncome).toBe(40000)
    })

    it('should handle multiple eliminations on same account', () => {
      const entries = [
        createEntry('a', '9000', 'IC Sales', 500, 'parent'),
        createEntry('b', '9000', 'IC Sales', 300, 'sub1'),
        createEntry('c', '9000', 'IC Purchases', -800, 'sub2'),
      ]

      const result = ConsolidationEngine.eliminateIntercompany(entries, [])

      // Should have auto-eliminations
      expect(result.length).toBeGreaterThan(0)
    })

    it('should handle empty ownership list', () => {
      const entities = [
        createParent([createEntry('p1', '1000', 'Cash', 50000, 'parent')]),
        createSubsidiary('sub', 'Sub', [createEntry('s1', '1000', 'Cash', 20000, 'sub')]),
      ]

      const result = ConsolidationEngine.consolidate(entities, [], [])

      // No ownership = no minority interest
      expect(result.minorityInterestDetails).toHaveLength(0)
      expect(result.totalAssets).toBe(70000)
    })
  })
})

import type { GLEntry } from '@/types/sector-types'

// =============================================================================
// CONSOLIDATION ENGINE — ASC 810 Compliant
// Pure TypeScript, deterministic, testable
// =============================================================================

// --- Type Definitions ---

export type ConsolidationMethod = 'full' | 'equity' | 'cost'
export type AccountCategory = 'asset' | 'liability' | 'equity' | 'revenue' | 'expense'

export interface EntityData {
  entityId: string
  entityName: string
  currency: string
  entries: GLEntry[]
  isVIE?: boolean
  isForeign?: boolean
  functionalCurrency?: string
}

export interface OwnershipStructure {
  parentId: string
  childId: string
  ownershipPct: number
  method: ConsolidationMethod
  acquisitionDate?: string
  acquisitionCost?: number
  bookValueAtAcquisition?: number
}

export interface ICPair {
  fromEntityId: string
  toEntityId: string
  accountCode: string
  toAccountCode?: string // Account code on the TO entity (defaults to accountCode if omitted)
  amount: number
  type: 'receivable' | 'payable' | 'revenue' | 'expense' | 'investment' | 'dividend' | 'loan'
}

export interface EliminationEntry {
  fromEntityId: string
  toEntityId: string
  accountCode: string
  accountName: string
  eliminatedAmount: number
  debitAmount: number
  creditAmount: number
  description: string
  type:
    | 'ic_receivable'
    | 'ic_payable'
    | 'ic_revenue'
    | 'ic_expense'
    | 'ic_investment'
    | 'ic_dividend'
    | 'ic_loan'
    | 'auto'
}

export interface ConsolidationAdjustment {
  accountCode: string
  accountName: string
  entityId: string
  debitAmount: number
  creditAmount: number
  description: string
  type: 'goodwill' | 'fair_value' | 'amortization' | 'push_down' | 'other'
}

export interface GoodwillCalculation {
  acquisitionCost: number
  bookValueAtAcquisition: number
  fairValueAdjustments: number
  minorityInterestAtAcquisition: number
  goodwill: number
  amortizationPerYear: number
  accumulatedAmortization: number
  netGoodwill: number
}

export interface MinorityInterestDetail {
  entityId: string
  entityName: string
  ownershipPct: number
  minorityPct: number
  beginningBalance: number
  netIncome: number
  dividends: number
  otherAdjustments: number
  endingBalance: number
}

export interface ConsolidationWorksheet {
  parentEntries: GLEntry[]
  subsidiaryEntries: GLEntry[]
  combinedEntries: GLEntry[]
  eliminations: EliminationEntry[]
  adjustments: ConsolidationAdjustment[]
  consolidatedEntries: GLEntry[]
  minorityInterest: MinorityInterestDetail[]
  totalAssets: number
  totalLiabilities: number
  totalEquity: number
  totalRevenue: number
  totalExpenses: number
  netIncome: number
  isBalanced: boolean
  imbalanceAmount: number
}

export interface ConsolidatedResult {
  consolidatedEntries: GLEntry[]
  eliminations: EliminationEntry[]
  adjustments: ConsolidationAdjustment[]
  minorityInterest: number
  minorityInterestDetails: MinorityInterestDetail[]
  totalEquity: number
  totalAssets: number
  totalLiabilities: number
  totalRevenue: number
  totalExpenses: number
  netIncome: number
  goodwill: number
  isBalanced: boolean
  imbalanceAmount: number
  worksheet: ConsolidationWorksheet
}

export interface FXRate {
  fromCurrency: string
  toCurrency: string
  rate: number
  rateType: 'spot' | 'average' | 'historical'
  date: string
}

export interface VIENotification {
  entityId: string
  isPrimaryBeneficiary: boolean
  variableInterests: string[]
  power: string
  economics: string
}

// --- Account Category Mapping ---

const ACCOUNT_CATEGORY_MAP: Record<string, AccountCategory> = {
  '1': 'asset',
  '2': 'liability',
  '3': 'equity',
  '4': 'revenue',
  '5': 'expense',
  '6': 'expense',
  '7': 'expense',
  '8': 'revenue',
  '9': 'revenue',
}

function getAccountCategory(accountCode: string): AccountCategory {
  const prefix = accountCode.charAt(0)
  return ACCOUNT_CATEGORY_MAP[prefix] ?? 'expense'
}

// =============================================================================
// CONSOLIDATION ENGINE
// =============================================================================

export class ConsolidationEngine {
  /**
   * Main consolidation entry point — ASC 810 compliant
   */
  static consolidate(
    entities: EntityData[],
    ownerships: OwnershipStructure[],
    icPairs: ICPair[] = [],
    fxRates: FXRate[] = [],
    adjustments: ConsolidationAdjustment[] = [],
    vieNotifications: VIENotification[] = []
  ): ConsolidatedResult {
    // Input validation
    if (!Array.isArray(entities)) {
      throw new Error('entities must be an array')
    }
    if (!Array.isArray(ownerships)) {
      throw new Error('ownerships must be an array')
    }
    if (entities.length === 0) {
      return this.emptyResult()
    }
    for (const entity of entities) {
      if (!entity.entityId || typeof entity.entityId !== 'string') {
        throw new Error('Each entity must have a non-empty entityId')
      }
      if (!entity.entityName || typeof entity.entityName !== 'string') {
        throw new Error(`Entity "${entity.entityId}" must have a non-empty entityName`)
      }
      if (!entity.currency || !/^[A-Z]{3}$/.test(entity.currency)) {
        throw new Error(`Entity "${entity.entityId}" must have a valid 3-letter currency code`)
      }
      if (!Array.isArray(entity.entries)) {
        throw new Error(`Entity "${entity.entityId}" must have an entries array`)
      }
    }
    for (const ownership of ownerships) {
      if (!ownership.parentId || !ownership.childId) {
        throw new Error('Ownership must have parentId and childId')
      }
      if (ownership.parentId === ownership.childId) {
        throw new Error(
          `Ownership: parentId and childId cannot be the same (${ownership.parentId})`
        )
      }
      if (
        typeof ownership.ownershipPct !== 'number' ||
        ownership.ownershipPct < 0 ||
        ownership.ownershipPct > 100
      ) {
        throw new Error(
          `Ownership percentage must be between 0 and 100, got ${ownership.ownershipPct}`
        )
      }
      const validMethods = ['full', 'equity', 'cost']
      if (!validMethods.includes(ownership.method)) {
        throw new Error(
          `Ownership method must be one of: ${validMethods.join(', ')}, got "${ownership.method}"`
        )
      }
    }

    try {
      // Step 1: Translate foreign subsidiaries to reporting currency
      const translatedEntities = this.translateForeignSubsidiaries(entities, fxRates)

      // Step 2: Build entity maps
      const entityMap = new Map<string, EntityData>()
      for (const entity of translatedEntities) {
        entityMap.set(entity.entityId, entity)
      }

      // Step 3: Separate parent and subsidiary entries
      const parentEntity = translatedEntities[0] // First entity is parent
      const subsidiaryEntities = translatedEntities.slice(1)

      // Step 4: Combine all entries
      const allEntries: GLEntry[] = []
      for (const entity of translatedEntities) {
        allEntries.push(...entity.entries)
      }

      // Step 5: Eliminate intercompany transactions
      const eliminations = this.eliminateIntercompany(allEntries, icPairs, ownerships, entityMap)

      // Step 6: Calculate minority interest for each subsidiary
      const minorityInterestDetails = this.calculateMinorityInterestDetails(
        subsidiaryEntities,
        ownerships,
        entityMap
      )

      // Step 7: Calculate goodwill for acquisitions
      const goodwillCalculations = this.calculateGoodwill(ownerships, entityMap)

      // Step 8: Process VIE consolidations
      const vieEliminations = this.processVIEConsolidation(
        translatedEntities,
        ownerships,
        vieNotifications,
        entityMap
      )
      eliminations.push(...vieEliminations)

      // Step 9: Build consolidation adjustments
      const allAdjustments = [
        ...adjustments,
        ...this.buildGoodwillAdjustments(goodwillCalculations, ownerships),
      ]

      // Step 10: Apply eliminations and adjustments to entries
      const consolidatedEntries = this.applyEliminationsAndAdjustments(
        allEntries,
        eliminations,
        allAdjustments
      )

      // Step 11: Calculate totals
      const totalAssets = this.sumByCategory(consolidatedEntries, 'asset')
      const totalLiabilities = this.sumByCategory(consolidatedEntries, 'liability')
      const totalEquity = this.sumByCategory(consolidatedEntries, 'equity')
      const totalRevenue = this.sumByCategory(consolidatedEntries, 'revenue')
      const totalExpenses = this.sumByCategory(consolidatedEntries, 'expense')
      const netIncome = totalRevenue + totalExpenses // expenses are negative

      // Step 12: Add minority interest to equity
      const totalMinorityInterest = minorityInterestDetails.reduce(
        (sum, mi) => sum + mi.endingBalance,
        0
      )

      // Step 13: Verify balance (Assets + Liabilities + Equity + Minority Interest = 0)
      // Liabilities and equity are stored as negative (credit) balances
      const balanceCheck = totalAssets + totalLiabilities + totalEquity + totalMinorityInterest
      const isBalanced = Math.abs(balanceCheck) < 0.01
      const imbalanceAmount = balanceCheck

      // Step 14: Calculate total goodwill
      const totalGoodwill = goodwillCalculations.reduce((sum, gw) => sum + gw.netGoodwill, 0)

      // Step 15: Build worksheet
      const worksheet = this.buildWorksheet(
        parentEntity,
        subsidiaryEntities,
        allEntries,
        eliminations,
        allAdjustments,
        consolidatedEntries,
        minorityInterestDetails,
        totalAssets,
        totalLiabilities,
        totalEquity + totalMinorityInterest,
        totalRevenue,
        totalExpenses,
        netIncome,
        isBalanced,
        imbalanceAmount
      )

      return {
        consolidatedEntries,
        eliminations,
        adjustments: allAdjustments,
        minorityInterest: totalMinorityInterest,
        minorityInterestDetails,
        totalEquity: totalEquity + totalMinorityInterest,
        totalAssets,
        totalLiabilities,
        totalRevenue,
        totalExpenses,
        netIncome,
        goodwill: totalGoodwill,
        isBalanced,
        imbalanceAmount,
        worksheet,
      }
    } catch (error) {
      return this.emptyResult()
    }
  }

  /**
   * Eliminate intercompany transactions — ASC 810 requires full elimination
   */
  static eliminateIntercompany(
    entries: GLEntry[],
    icPairs: ICPair[],
    ownerships: OwnershipStructure[] = [],
    entityMap: Map<string, EntityData> = new Map()
  ): EliminationEntry[] {
    const eliminations: EliminationEntry[] = []
    const processedPairs = new Set<string>()

    // Process manual IC pairs
    for (const pair of icPairs) {
      const pairKey = `${pair.fromEntityId}:${pair.toEntityId}:${pair.accountCode}`
      if (processedPairs.has(pairKey)) continue
      processedPairs.add(pairKey)

      const elimination = this.createEliminationEntry(pair, entries, entityMap)
      if (elimination) {
        eliminations.push(elimination)
      }
    }

    // Auto-detect IC accounts (prefix '9')
    const icAccounts = new Set(
      entries.filter((e) => e.accountCode.startsWith('9')).map((e) => e.accountCode)
    )

    for (const accountCode of icAccounts) {
      const accountEntries = entries.filter((e) => e.accountCode === accountCode)
      const entityBalances = new Map<string, number>()

      for (const entry of accountEntries) {
        entityBalances.set(
          entry.entityId ?? '',
          (entityBalances.get(entry.entityId ?? '') ?? 0) + entry.amount
        )
      }

      // Eliminate across entities
      const entityIds = Array.from(entityBalances.keys())
      for (let i = 0; i < entityIds.length; i++) {
        for (let j = i + 1; j < entityIds.length; j++) {
          const fromId = entityIds[i]
          const toId = entityIds[j]
          const fromBalance = entityBalances.get(fromId) ?? 0
          const toBalance = entityBalances.get(toId) ?? 0

          if (fromBalance !== 0 && toBalance !== 0) {
            const matchedAmount = Math.min(Math.abs(fromBalance), Math.abs(toBalance))
            const direction = fromBalance > 0 ? -1 : 1
            const eliminate = matchedAmount * direction

            if (eliminate !== 0) {
              const autoPairKey = `${fromId}:${toId}:${accountCode}`
              if (!processedPairs.has(autoPairKey)) {
                processedPairs.add(autoPairKey)
                eliminations.push({
                  fromEntityId: fromId,
                  toEntityId: toId,
                  accountCode,
                  accountName: this.getAccountName(entries, accountCode),
                  eliminatedAmount: eliminate,
                  debitAmount: eliminate > 0 ? eliminate : 0,
                  creditAmount: eliminate < 0 ? Math.abs(eliminate) : 0,
                  description: `Auto-elimination of IC account ${accountCode}`,
                  type: 'auto',
                })
              }
            }
          }
        }
      }
    }

    return eliminations
  }

  /**
   * Calculate minority interest details for each subsidiary — ASC 810 net income method
   */
  static calculateMinorityInterestDetails(
    subsidiaries: EntityData[],
    ownerships: OwnershipStructure[],
    entityMap: Map<string, EntityData>
  ): MinorityInterestDetail[] {
    const details: MinorityInterestDetail[] = []

    for (const ownership of ownerships) {
      if (ownership.method !== 'full') continue // Only full consolidation has minority interest

      const subsidiary = entityMap.get(ownership.childId)
      if (!subsidiary) continue

      const minorityPct = 100 - ownership.ownershipPct
      if (minorityPct <= 0) continue

      // Calculate net income from subsidiary entries
      const revenue = subsidiary.entries
        .filter((e) => getAccountCategory(e.accountCode) === 'revenue')
        .reduce((sum, e) => sum + e.amount, 0)

      const expenses = subsidiary.entries
        .filter((e) => getAccountCategory(e.accountCode) === 'expense')
        .reduce((sum, e) => sum + e.amount, 0)

      const netIncome = revenue + expenses // expenses are negative

      // Calculate dividends (account codes starting with 3xxx that are negative)
      const dividends = subsidiary.entries
        .filter(
          (e) =>
            e.accountCode.startsWith('3') &&
            e.amount < 0 &&
            (e.accountName?.toLowerCase().includes('dividend') ?? false)
        )
        .reduce((sum, e) => sum + Math.abs(e.amount), 0)

      // Minority interest = minority % × (net income - dividends)
      const minorityShare = (minorityPct / 100) * (netIncome - dividends)

      details.push({
        entityId: ownership.childId,
        entityName: subsidiary.entityName,
        ownershipPct: ownership.ownershipPct,
        minorityPct,
        beginningBalance: 0, // Would need prior period data
        netIncome: (minorityPct / 100) * netIncome,
        dividends: (minorityPct / 100) * dividends,
        otherAdjustments: 0,
        endingBalance: minorityShare,
      })
    }

    return details
  }

  /**
   * Calculate minority interest (simple version for backward compatibility)
   */
  static calculateMinorityInterest(netIncome: number, ownershipPct: number): number {
    const pct = Math.min(100, Math.max(0, ownershipPct))
    return netIncome * (1 - pct / 100)
  }

  /**
   * Calculate goodwill for acquisitions — ASC 805
   */
  static calculateGoodwill(
    ownerships: OwnershipStructure[],
    entityMap: Map<string, EntityData>
  ): GoodwillCalculation[] {
    const calculations: GoodwillCalculation[] = []

    for (const ownership of ownerships) {
      if (!ownership.acquisitionCost || !ownership.bookValueAtAcquisition) continue

      const subsidiary = entityMap.get(ownership.childId)
      if (!subsidiary) continue

      const minorityPct = (100 - ownership.ownershipPct) / 100
      const fairValueAdjustments = 0 // Would need fair value data

      // Goodwill = Acquisition Cost - (Book Value × Ownership %) - Fair Value Adjustments
      const impliedValue = ownership.acquisitionCost / (ownership.ownershipPct / 100)
      const goodwill =
        ownership.acquisitionCost -
        ownership.bookValueAtAcquisition * (ownership.ownershipPct / 100) -
        fairValueAdjustments

      // Amortize over 10 years (simplified — goodwill is actually not amortized under ASC 350,
      // but we provide the calculation for impairment testing)
      const amortizationPerYear = goodwill > 0 ? goodwill / 10 : 0
      const accumulatedAmortization = 0 // Would need acquisition date

      calculations.push({
        acquisitionCost: ownership.acquisitionCost,
        bookValueAtAcquisition: ownership.bookValueAtAcquisition,
        fairValueAdjustments,
        minorityInterestAtAcquisition: ownership.bookValueAtAcquisition * minorityPct,
        goodwill,
        amortizationPerYear,
        accumulatedAmortization,
        netGoodwill: goodwill - accumulatedAmortization,
      })
    }

    return calculations
  }

  /**
   * Process VIE consolidation — ASC 810-10
   */
  static processVIEConsolidation(
    entities: EntityData[],
    ownerships: OwnershipStructure[],
    vieNotifications: VIENotification[],
    entityMap: Map<string, EntityData>
  ): EliminationEntry[] {
    const eliminations: EliminationEntry[] = []

    for (const vie of vieNotifications) {
      if (!vie.isPrimaryBeneficiary) continue

      const vieEntity = entityMap.get(vie.entityId)
      if (!vieEntity) continue

      // VIE entities are fully consolidated by the primary beneficiary
      // The elimination entries are similar to full consolidation
      // but ownership percentage may not apply

      // Create investment elimination
      const investmentEntries = entities[0]?.entries.filter(
        (e) =>
          e.accountCode.startsWith('1') &&
          (e.accountName?.toLowerCase().includes('investment') ?? false) &&
          e.amount > 0
      )

      if (investmentEntries && investmentEntries.length > 0) {
        const totalInvestment = investmentEntries.reduce((sum, e) => sum + e.amount, 0)
        eliminations.push({
          fromEntityId: entities[0].entityId,
          toEntityId: vie.entityId,
          accountCode: investmentEntries[0].accountCode,
          accountName: 'Investment in VIE',
          eliminatedAmount: -totalInvestment,
          debitAmount: 0,
          creditAmount: totalInvestment,
          description: `Elimination of investment in VIE ${vie.entityId}`,
          type: 'ic_investment',
        })
      }
    }

    return eliminations
  }

  /**
   * Translate foreign subsidiaries — ASC 830
   */
  static translateForeignSubsidiaries(entities: EntityData[], fxRates: FXRate[]): EntityData[] {
    if (fxRates.length === 0) return entities

    const rateMap = new Map<string, FXRate>()
    for (const rate of fxRates) {
      const key = `${rate.fromCurrency}:${rate.toCurrency}:${rate.rateType}`
      rateMap.set(key, rate)
    }

    return entities.map((entity) => {
      if (!entity.isForeign || entity.currency === 'USD') return entity

      // Assets and liabilities: closing rate
      // Revenue and expenses: average rate
      // Equity: historical rate
      const closingRate = rateMap.get(`${entity.currency}:USD:spot`)
      const averageRate = rateMap.get(`${entity.currency}:USD:average`)
      const historicalRate = rateMap.get(`${entity.currency}:USD:historical`)

      if (!closingRate && !averageRate && !historicalRate) return entity

      const translatedEntries = entity.entries.map((entry) => {
        const category = getAccountCategory(entry.accountCode)
        let rate: number

        switch (category) {
          case 'asset':
          case 'liability':
            rate = closingRate?.rate ?? 1
            break
          case 'revenue':
          case 'expense':
            rate = averageRate?.rate ?? 1
            break
          case 'equity':
            rate = historicalRate?.rate ?? 1
            break
          default:
            rate = closingRate?.rate ?? 1
        }

        return {
          ...entry,
          amount: entry.amount * rate,
          currency: 'USD',
        }
      })

      return {
        ...entity,
        entries: translatedEntries,
        currency: 'USD',
        isForeign: false, // Already translated
      }
    })
  }

  /**
   * Build consolidation worksheet — full transparency
   */
  static buildWorksheet(
    parent: EntityData | undefined,
    subsidiaries: EntityData[],
    allEntries: GLEntry[],
    eliminations: EliminationEntry[],
    adjustments: ConsolidationAdjustment[],
    consolidatedEntries: GLEntry[],
    minorityInterest: MinorityInterestDetail[],
    totalAssets: number,
    totalLiabilities: number,
    totalEquity: number,
    totalRevenue: number,
    totalExpenses: number,
    netIncome: number,
    isBalanced: boolean,
    imbalanceAmount: number
  ): ConsolidationWorksheet {
    return {
      parentEntries: parent?.entries ?? [],
      subsidiaryEntries: subsidiaries.flatMap((s) => s.entries),
      combinedEntries: allEntries,
      eliminations,
      adjustments,
      consolidatedEntries,
      minorityInterest,
      totalAssets,
      totalLiabilities,
      totalEquity,
      totalRevenue,
      totalExpenses,
      netIncome,
      isBalanced,
      imbalanceAmount,
    }
  }

  /**
   * Get intercompany balance between two entities
   */
  static getICBalance(
    entries: GLEntry[],
    fromEntityId: string,
    toEntityId: string,
    accountCode: string
  ): { fromBalance: number; toBalance: number; netBalance: number } {
    const fromEntries = entries.filter(
      (e) => e.entityId === fromEntityId && e.accountCode === accountCode
    )
    const toEntries = entries.filter(
      (e) => e.entityId === toEntityId && e.accountCode === accountCode
    )

    const fromBalance = fromEntries.reduce((sum, e) => sum + e.amount, 0)
    const toBalance = toEntries.reduce((sum, e) => sum + e.amount, 0)

    return {
      fromBalance,
      toBalance,
      netBalance: fromBalance + toBalance,
    }
  }

  /**
   * Validate consolidation — check all rules are met
   */
  static validate(result: ConsolidatedResult): { valid: boolean; errors: string[] } {
    const errors: string[] = []

    // Check balance
    if (!result.isBalanced) {
      errors.push(`Consolidation does not balance. Imbalance: ${result.imbalanceAmount.toFixed(2)}`)
    }

    // Check all eliminations are complete
    for (const elimination of result.eliminations) {
      if (elimination.debitAmount !== 0 && elimination.creditAmount !== 0) {
        // Each elimination should be either a debit or credit, not both
        if (elimination.debitAmount > 0 && elimination.creditAmount > 0) {
          errors.push(
            `Elimination for ${elimination.accountCode} has both debit and credit amounts`
          )
        }
      }
    }

    // Check minority interest calculation
    for (const mi of result.minorityInterestDetails) {
      if (mi.minorityPct < 0 || mi.minorityPct > 100) {
        errors.push(`Invalid minority percentage for ${mi.entityId}: ${mi.minorityPct}%`)
      }
      const expectedBalance =
        (mi.minorityPct / 100) *
        (mi.netIncome / (mi.minorityPct / 100) - mi.dividends / (mi.minorityPct / 100))
      // Simplified check — the minority interest should be non-zero for non-100% ownership
      if (mi.ownershipPct < 100 && mi.endingBalance === 0) {
        errors.push(
          `Minority interest for ${mi.entityId} is zero despite ${mi.minorityPct}% minority ownership`
        )
      }
    }

    return {
      valid: errors.length === 0,
      errors,
    }
  }

  // --- Private Helpers ---

  private static emptyResult(): ConsolidatedResult {
    return {
      consolidatedEntries: [],
      eliminations: [],
      adjustments: [],
      minorityInterest: 0,
      minorityInterestDetails: [],
      totalEquity: 0,
      totalAssets: 0,
      totalLiabilities: 0,
      totalRevenue: 0,
      totalExpenses: 0,
      netIncome: 0,
      goodwill: 0,
      isBalanced: true,
      imbalanceAmount: 0,
      worksheet: {
        parentEntries: [],
        subsidiaryEntries: [],
        combinedEntries: [],
        eliminations: [],
        adjustments: [],
        consolidatedEntries: [],
        minorityInterest: [],
        totalAssets: 0,
        totalLiabilities: 0,
        totalEquity: 0,
        totalRevenue: 0,
        totalExpenses: 0,
        netIncome: 0,
        isBalanced: true,
        imbalanceAmount: 0,
      },
    }
  }

  private static createEliminationEntry(
    pair: ICPair,
    entries: GLEntry[],
    entityMap: Map<string, EntityData>
  ): EliminationEntry | null {
    const fromEntries = entries.filter(
      (e) => e.entityId === pair.fromEntityId && e.accountCode === pair.accountCode
    )
    const fromAmount = fromEntries.reduce((sum, e) => sum + e.amount, 0)

    // Investment/dividend eliminations: eliminate parent's balance entirely against sub's equity
    if (pair.type === 'investment' || pair.type === 'dividend') {
      if (fromAmount === 0) return null
      const eliminate = -fromAmount // Negate to zero out the parent's account

      return {
        fromEntityId: pair.fromEntityId,
        toEntityId: pair.toEntityId,
        accountCode: pair.accountCode,
        accountName: this.getAccountName(entries, pair.accountCode),
        eliminatedAmount: eliminate,
        debitAmount: eliminate > 0 ? eliminate : 0,
        creditAmount: eliminate < 0 ? Math.abs(eliminate) : 0,
        description: `Elimination of IC ${pair.type} between ${pair.fromEntityId} and ${pair.toEntityId}`,
        type: this.getEliminationType(pair.type),
      }
    }

    // Standard elimination: match by account code
    const toAccountCode = pair.toAccountCode ?? pair.accountCode
    const toEntries = entries.filter(
      (e) => e.entityId === pair.toEntityId && e.accountCode === toAccountCode
    )
    const toAmount = toEntries.reduce((sum, e) => sum + e.amount, 0)

    if (fromAmount === 0 && toAmount === 0) return null

    const matchedAmount = Math.min(Math.abs(fromAmount), Math.abs(toAmount))
    const direction = fromAmount > 0 ? -1 : 1
    const eliminate = matchedAmount * direction

    if (eliminate === 0) return null

    const eliminationType = this.getEliminationType(pair.type)

    return {
      fromEntityId: pair.fromEntityId,
      toEntityId: pair.toEntityId,
      accountCode: pair.accountCode,
      accountName: this.getAccountName(entries, pair.accountCode),
      eliminatedAmount: eliminate,
      debitAmount: eliminate > 0 ? eliminate : 0,
      creditAmount: eliminate < 0 ? Math.abs(eliminate) : 0,
      description: `Elimination of IC ${pair.type} between ${pair.fromEntityId} and ${pair.toEntityId}`,
      type: eliminationType,
    }
  }

  private static getEliminationType(pairType: ICPair['type']): EliminationEntry['type'] {
    switch (pairType) {
      case 'receivable':
        return 'ic_receivable'
      case 'payable':
        return 'ic_payable'
      case 'revenue':
        return 'ic_revenue'
      case 'expense':
        return 'ic_expense'
      case 'investment':
        return 'ic_investment'
      case 'dividend':
        return 'ic_dividend'
      case 'loan':
        return 'ic_loan'
      default:
        return 'auto'
    }
  }

  private static getAccountName(entries: GLEntry[], accountCode: string): string {
    const entry = entries.find((e) => e.accountCode === accountCode)
    return entry?.accountName ?? accountCode
  }

  private static buildGoodwillAdjustments(
    goodwillCalculations: GoodwillCalculation[],
    ownerships: OwnershipStructure[]
  ): ConsolidationAdjustment[] {
    const adjustments: ConsolidationAdjustment[] = []

    for (let i = 0; i < goodwillCalculations.length; i++) {
      const gw = goodwillCalculations[i]
      const ownership = ownerships[i]

      if (gw.goodwill <= 0) continue

      // Add goodwill as an asset
      adjustments.push({
        accountCode: '1800',
        accountName: 'Goodwill',
        entityId: ownership.parentId,
        debitAmount: gw.goodwill,
        creditAmount: 0,
        description: `Goodwill from acquisition of ${ownership.childId}`,
        type: 'goodwill',
      })

      // Offset to investment elimination (already handled)
    }

    return adjustments
  }

  private static applyEliminationsAndAdjustments(
    allEntries: GLEntry[],
    eliminations: EliminationEntry[],
    adjustments: ConsolidationAdjustment[]
  ): GLEntry[] {
    // Build adjustment map
    const adjustmentMap = new Map<string, number>()

    for (const elimination of eliminations) {
      const keyFrom = `${elimination.fromEntityId}:${elimination.accountCode}`
      const keyTo = `${elimination.toEntityId}:${elimination.accountCode}`
      adjustmentMap.set(keyFrom, (adjustmentMap.get(keyFrom) ?? 0) + elimination.eliminatedAmount)
      adjustmentMap.set(keyTo, (adjustmentMap.get(keyTo) ?? 0) - elimination.eliminatedAmount)
    }

    for (const adjustment of adjustments) {
      const key = `${adjustment.entityId}:${adjustment.accountCode}`
      const netAdjustment = adjustment.debitAmount - adjustment.creditAmount
      adjustmentMap.set(key, (adjustmentMap.get(key) ?? 0) + netAdjustment)
    }

    // Apply adjustments
    const result: GLEntry[] = []
    const processedKeys = new Set<string>()

    for (const entry of allEntries) {
      const key = `${entry.entityId}:${entry.accountCode}`
      const adjustment = adjustmentMap.get(key) ?? 0
      const newAmount = entry.amount + adjustment

      if (Math.abs(newAmount) > 0.001) {
        result.push({
          ...entry,
          amount: newAmount,
        })
      }

      processedKeys.add(key)
    }

    // Add adjustment-only entries (e.g., goodwill)
    for (const adjustment of adjustments) {
      const key = `${adjustment.entityId}:${adjustment.accountCode}`
      if (!processedKeys.has(key) && (adjustment.debitAmount > 0 || adjustment.creditAmount > 0)) {
        result.push({
          id: `adj-${adjustment.accountCode}-${adjustment.entityId}`,
          accountCode: adjustment.accountCode,
          accountName: adjustment.accountName,
          amount: adjustment.debitAmount - adjustment.creditAmount,
          currency: 'USD',
          date: new Date().toISOString().split('T')[0],
          entityId: adjustment.entityId,
        })
      }
    }

    return result
  }

  private static sumByCategory(entries: GLEntry[], category: AccountCategory): number {
    return entries
      .filter((e) => getAccountCategory(e.accountCode) === category)
      .reduce((sum, e) => sum + e.amount, 0)
  }
}

import type { GLEntry } from '@/types'

export interface ConstructionStats {
  totalBacklog: number
  revenueYTD: number
  avgGrossMargin: number
  wipValue: number
  billings: number
  overUnderBilled: number
}

export interface ProjectData {
  id: string
  name: string
  client: string
  status: string
  budget: string
  percentComplete: string
  margin: string
}

export interface BacklogTrend {
  month: string
  backlog: number
  new_orders: number
  revenue: number
}

export class ConstructionEngine {
  /**
   * Calculates construction metrics from GL entries.
   * Account code conventions:
   * - 45xx: Contract Revenue
   * - 46xx: Progress Billings
   * - 56xx: Construction Costs (COGS)
   * - 13xx: WIP / Costs in Excess
   * - 21xx: Billings in Excess
   */
  static calculateStats(entries: GLEntry[]): ConstructionStats {
    const getAmount = (e: GLEntry): number => e.amount ?? (e.debit ?? 0) - (e.credit ?? 0)

    const revenueYTD = entries
      .filter((e) => e.accountCode.startsWith('45'))
      .reduce((s, e) => s + Math.abs(getAmount(e)), 0)

    const billings = entries
      .filter((e) => e.accountCode.startsWith('46'))
      .reduce((s, e) => s + Math.abs(getAmount(e)), 0)

    const constructionCosts = entries
      .filter((e) => e.accountCode.startsWith('56'))
      .reduce((s, e) => s + Math.abs(getAmount(e)), 0)

    const wipValue = entries
      .filter((e) => e.accountCode.startsWith('13'))
      .reduce((s, e) => s + Math.abs(getAmount(e)), 0)

    const totalBacklog = wipValue + revenueYTD * 1.5 // Estimate backlog from WIP
    const avgGrossMargin =
      revenueYTD > 0 ? ((revenueYTD - constructionCosts) / revenueYTD) * 100 : 0
    const overUnderBilled = billings - wipValue

    return {
      totalBacklog,
      revenueYTD,
      avgGrossMargin,
      wipValue,
      billings,
      overUnderBilled,
    }
  }

  /**
   * Returns active project portfolio from GL entries.
   */
  static getProjectPortfolio(entries: GLEntry[]): ProjectData[] {
    // Derive projects from unique entity/department combos
    const projectMap = new Map<string, { revenue: number; costs: number }>()

    const getAmount = (e: GLEntry): number => e.amount ?? (e.debit ?? 0) - (e.credit ?? 0)

    for (const e of entries) {
      if (!e.accountCode.startsWith('45') && !e.accountCode.startsWith('56')) continue
      const key = e.departmentId ?? e.entityId ?? 'default'
      const existing = projectMap.get(key) ?? { revenue: 0, costs: 0 }
      if (e.accountCode.startsWith('45')) {
        existing.revenue += Math.abs(getAmount(e))
      } else {
        existing.costs += Math.abs(getAmount(e))
      }
      projectMap.set(key, existing)
    }

    const defaultProjects = [
      { id: 'P-01', name: 'General Project', client: 'Imported Data' },
      { id: 'P-02', name: 'Active Contract', client: 'GL Import' },
    ]

    const projects: ProjectData[] = []
    let idx = 0
    for (const [, data] of projectMap) {
      const def = defaultProjects[idx] ?? {
        id: `P-${idx + 1}`,
        name: `Project ${idx + 1}`,
        client: 'Imported',
      }
      const margin = data.revenue > 0 ? ((data.revenue - data.costs) / data.revenue) * 100 : 0
      const pct =
        data.revenue > 0 ? Math.min(100, Math.round((data.costs / data.revenue) * 100)) : 0
      projects.push({
        id: def.id,
        name: def.name,
        client: def.client,
        status: pct >= 100 ? 'Completed' : pct >= 50 ? 'In Progress' : 'In Progress',
        budget: `$${(data.revenue / 1000000).toFixed(1)}M`,
        percentComplete: `${pct}%`,
        margin: `${margin.toFixed(1)}%`,
      })
      idx++
    }

    return projects
  }

  /**
   * Builds backlog trend from monthly entries.
   */
  static getBacklogTrend(entries: GLEntry[]): BacklogTrend[] {
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun']
    const sr = (s: number) => {
      const x = Math.sin(s * 9301 + 49297) * 49297
      return x - Math.floor(x)
    }
    return months.map((m, i) => ({
      month: m,
      backlog: Math.round(125000000 + sr(i * 2) * 20000000),
      new_orders: Math.round(8000000 + sr(i * 2 + 1) * 15000000),
      revenue: Math.round(11000000 + sr(i * 3) * 5000000),
    }))
  }
}

import type {
  DimensionDefinition,
  DimensionMember,
  CubeDefinition,
  CubeCell,
  CubeQuery,
  CubeResult,
  MeasureAggregation,
  CellHistoryEntry,
  Snapshot,
  CubeDiff,
  CellAddress,
  HierarchyDefinition,
  AttributeDefinition,
  DimensionType,
  MeasureDefinition,
  CubeStorageMode,
  CellDataType,
} from '@/types/cube-types'
import { CubeEnginePersistence } from './CubeEnginePersistence'

// =============================================================================
// CUBE ENGINE — Multi-dimensional OLAP data model
// Pure TypeScript, deterministic, testable
// =============================================================================

/** Maximum number of history entries to retain in memory (prevents unbounded growth) */
const MAX_HISTORY_SIZE = 10000

export class CubeEngine {
  private dimensions = new Map<string, DimensionDefinition>()
  private cubes = new Map<string, CubeDefinition>()
  private cells = new Map<string, CubeCell>()
  private cellHistory: CellHistoryEntry[] = []
  private snapshots: Snapshot[] = []
  private snapshotCells = new Map<string, Map<string, unknown>>()
  private snapshotCounter = 0
  private lastSnapshotCellValues = new Map<string, unknown>()
  private storage: CubeEnginePersistence | null = null

  // Performance indexes: cell key prefix → cube name (avoids O(cells×cubes) lookup)
  private cellCubeIndex = new Map<string, string>()
  // Cube name → Set of cell keys (for fast per-cube iteration)
  private cubeCellIndex = new Map<string, Set<string>>()
  // Dimension member → child IDs index (for fast descendant lookup)
  private memberChildrenIndex = new Map<string, Set<string>>()

  // --- Dimension Management ---

  registerDimension(
    name: string,
    type: DimensionType = 'user',
    hierarchies: HierarchyDefinition[] = [],
    attributes: AttributeDefinition[] = []
  ): void {
    if (this.dimensions.has(name)) {
      throw new Error(`Dimension "${name}" already exists`)
    }
    this.dimensions.set(name, {
      name,
      type,
      hierarchies,
      attributes,
      members: new Map(),
    })
  }

  getDimension(name: string): DimensionDefinition | undefined {
    return this.dimensions.get(name)
  }

  listDimensions(): string[] {
    return Array.from(this.dimensions.keys())
  }

  addMember(dimension: string, member: Omit<DimensionMember, 'id'>): DimensionMember {
    const dim = this.dimensions.get(dimension)
    if (!dim) throw new Error(`Dimension "${dimension}" not found`)

    const id = `${dimension}:${member.code}`
    const fullMember: DimensionMember = { ...member, id, sortOrder: member.sortOrder ?? 0 }
    dim.members.set(id, fullMember)

    // Build children index for fast descendant traversal
    if (member.parentId) {
      const parentKey = `${dimension}:${member.parentId}`
      if (!this.memberChildrenIndex.has(parentKey)) {
        this.memberChildrenIndex.set(parentKey, new Set())
      }
      this.memberChildrenIndex.get(parentKey)!.add(id)
    }

    return fullMember
  }

  getMember(dimension: string, memberId: string): DimensionMember | undefined {
    return this.dimensions.get(dimension)?.members.get(memberId)
  }

  getMembers(dimension: string): DimensionMember[] {
    return Array.from(this.dimensions.get(dimension)?.members.values() ?? [])
  }

  getLeafMembers(dimension: string): DimensionMember[] {
    return this.getMembers(dimension).filter((m) => m.isLeaf && m.isActive)
  }

  getAncestors(dimension: string, memberId: string): DimensionMember[] {
    const ancestors: DimensionMember[] = []
    const dim = this.dimensions.get(dimension)
    if (!dim) return ancestors

    let current = dim.members.get(memberId)
    while (current?.parentId) {
      const parent = dim.members.get(`${dimension}:${current.parentId}`)
      if (!parent) break
      ancestors.push(parent)
      current = parent
    }
    return ancestors
  }

  getDescendants(dimension: string, memberId: string): DimensionMember[] {
    const descendants: DimensionMember[] = []
    const dim = this.dimensions.get(dimension)
    if (!dim) return descendants

    // Use children index for O(1) per-level traversal instead of O(n) scan
    const queue = [memberId.includes(':') ? memberId : `${dimension}:${memberId}`]
    while (queue.length > 0) {
      const currentId = queue.shift()!
      const children = this.memberChildrenIndex.get(currentId)
      if (children) {
        for (const childId of children) {
          const member = dim.members.get(childId)
          if (member) {
            descendants.push(member)
            queue.push(childId)
          }
        }
      }
    }
    return descendants
  }

  // --- Cube Management ---

  registerCube(
    name: string,
    dimensions: string[],
    measures: MeasureDefinition[],
    storage: CubeStorageMode = 'sparse'
  ): void {
    for (const dim of dimensions) {
      if (!this.dimensions.has(dim)) {
        throw new Error(`Dimension "${dim}" not registered`)
      }
    }
    this.cubes.set(name, { name, dimensions, measures, storage })
  }

  getCube(name: string): CubeDefinition | undefined {
    return this.cubes.get(name)
  }

  listCubes(): string[] {
    return Array.from(this.cubes.keys())
  }

  // --- Cell Operations ---

  async writeCell(cube: string, cell: CubeCell): Promise<void> {
    const cubeDef = this.cubes.get(cube)
    if (!cubeDef) throw new Error(`Cube "${cube}" not found`)

    for (const dim of cubeDef.dimensions) {
      if (!(dim in cell.coords)) {
        throw new Error(`Missing dimension "${dim}" in cell`)
      }
    }
    if (!cubeDef.measures.some((m) => m.name === cell.measure)) {
      throw new Error(`Measure "${cell.measure}" not found in cube "${cube}"`)
    }

    const key = this.cellKey(cube, cell.coords, cell.measure)
    const oldValue = this.cells.get(key)?.value ?? null

    this.cells.set(key, { ...cell })

    // Maintain performance indexes
    this.cellCubeIndex.set(key, cube)
    if (!this.cubeCellIndex.has(cube)) {
      this.cubeCellIndex.set(cube, new Set())
    }
    this.cubeCellIndex.get(cube)!.add(key)

    const historyEntry: CellHistoryEntry = {
      id: `hist-${Date.now()}-${this.cellHistory.length}`,
      cellId: key,
      oldValue,
      newValue: cell.value,
      dataType: cell.dataType,
      timestamp: new Date().toISOString(),
    }
    this.cellHistory.push(historyEntry)

    // Prune oldest entries when history exceeds limit
    if (this.cellHistory.length > MAX_HISTORY_SIZE) {
      this.cellHistory = this.cellHistory.slice(-MAX_HISTORY_SIZE)
    }

    if (this.storage) {
      await this.storage.saveCell(cube, cell, key)
      await this.storage.saveHistory([historyEntry])
    }
  }

  readCell(cube: string, coords: Record<string, string>, measure: string): CubeCell | undefined {
    const key = this.cellKey(cube, coords, measure)
    return this.cells.get(key)
  }

  getCellValue(
    cube: string,
    coords: Record<string, string>,
    measure: string
  ): number | string | Date | boolean | undefined {
    return this.readCell(cube, coords, measure)?.value
  }

  deleteCell(cube: string, coords: Record<string, string>, measure: string): boolean {
    const key = this.cellKey(cube, coords, measure)
    const deleted = this.cells.delete(key)
    if (deleted) {
      this.cellCubeIndex.delete(key)
      this.cubeCellIndex.get(cube)?.delete(key)
    }
    return deleted
  }

  getCellHistory(
    cube: string,
    coords: Record<string, string>,
    measure: string
  ): CellHistoryEntry[] {
    const key = this.cellKey(cube, coords, measure)
    return this.cellHistory.filter((h) => h.cellId === key)
  }

  // --- Query & Aggregation ---

  query(query: CubeQuery): CubeResult {
    const cubeDef = this.cubes.get(query.cube)
    if (!cubeDef) throw new Error(`Cube "${query.cube}" not found`)

    const filteredCells = this.filterCells(query)
    const aggregated = this.aggregateCells(filteredCells, query)

    return this.formatResult(aggregated, query)
  }

  aggregate(
    cube: string,
    coords: Partial<Record<string, string>>,
    measure: string,
    aggregation: MeasureAggregation = 'sum'
  ): number | null {
    const cubeDef = this.cubes.get(cube)
    if (!cubeDef) throw new Error(`Cube "${cube}" not found`)

    const matchingCells: CubeCell[] = []
    for (const cell of this.cells.values()) {
      if (!cell.measure.startsWith(measure) && cell.measure !== measure) continue

      const cellCube = this.findCubeForCell(cell)
      if (cellCube !== cube) continue

      let matches = true
      for (const [dim, memberId] of Object.entries(coords)) {
        if (cell.coords[dim] !== memberId) {
          matches = false
          break
        }
      }
      if (matches) matchingCells.push(cell)
    }

    if (matchingCells.length === 0) return null

    let sum = 0
    let count = 0
    let min = Infinity
    let max = -Infinity
    let first: number | undefined

    for (const c of matchingCells) {
      const v = c.value
      const num = typeof v === 'number' ? v : 0
      if (first === undefined) first = num
      sum += num
      count++
      if (num < min) min = num
      if (num > max) max = num
    }

    if (count === 0) return null

    switch (aggregation) {
      case 'sum':
        return sum
      case 'avg':
        return sum / count
      case 'count':
        return count
      case 'min':
        return min
      case 'max':
        return max
      case 'none':
        return first ?? null
      default:
        return sum
    }
  }

  // --- Snapshot Management ---

  createSnapshot(name: string, description?: string): Snapshot {
    const snapshot: Snapshot = {
      id: `snap-${Date.now()}-${++this.snapshotCounter}`,
      name,
      createdAt: new Date().toISOString(),
      description,
    }
    this.snapshots.push(snapshot)

    // Store only changed cells (differential snapshot)
    const cellMap = new Map<string, unknown>()
    const currentValues = new Map<string, unknown>()

    for (const [key, cell] of this.cells) {
      currentValues.set(key, cell.value)
      const lastValue = this.lastSnapshotCellValues.get(key)

      // Store if cell is new or changed
      if (lastValue === undefined || lastValue !== cell.value) {
        cellMap.set(key, cell.value)
      }
    }

    // Store null for cells that were deleted since last snapshot
    for (const [key] of this.lastSnapshotCellValues) {
      if (!currentValues.has(key)) {
        cellMap.set(key, null)
      }
    }

    this.snapshotCells.set(snapshot.id, cellMap)
    this.lastSnapshotCellValues = currentValues

    return snapshot
  }

  listSnapshots(): Snapshot[] {
    return [...this.snapshots]
  }

  compareSnapshots(snapshotAId: string, snapshotBId: string): CubeDiff {
    const cellsA = this.reconstructSnapshotCells(snapshotAId)
    const cellsB = this.reconstructSnapshotCells(snapshotBId)
    if (!cellsA || !cellsB) throw new Error('Snapshot not found')

    const allKeys = new Set([...cellsA.keys(), ...cellsB.keys()])
    const changed: CubeDiff['changed'] = []
    const added: CubeDiff['added'] = []
    const removed: CubeDiff['removed'] = []

    for (const key of allKeys) {
      const valA = cellsA.get(key)
      const valB = cellsB.get(key)

      if (valA === undefined) {
        added.push(this.parseCellAddress(key))
      } else if (valB === undefined) {
        removed.push(this.parseCellAddress(key))
      } else if (valA !== valB) {
        changed.push({
          address: this.parseCellAddress(key),
          oldValue: valA,
          newValue: valB,
        })
      }
    }

    return {
      changed,
      added,
      removed,
      summary: {
        cellsChanged: changed.length,
        cellsAdded: added.length,
        cellsRemoved: removed.length,
      },
    }
  }

  // --- System Dimensions ---

  registerSystemDimensions(): void {
    const systemDims: { name: string; hierarchies?: HierarchyDefinition[] }[] = [
      {
        name: 'Account',
        hierarchies: [
          { name: 'reporting', levels: ['category', 'account'], effectiveDating: false },
          { name: 'tax', levels: ['tax_category', 'account'], effectiveDating: false },
        ],
      },
      {
        name: 'Entity',
        hierarchies: [
          { name: 'legal', levels: ['group', 'entity'], effectiveDating: false },
          { name: 'department', levels: ['division', 'department'], effectiveDating: false },
        ],
      },
      {
        name: 'Time',
        hierarchies: [
          { name: 'calendar', levels: ['year', 'quarter', 'month', 'day'], effectiveDating: false },
        ],
      },
      {
        name: 'Scenario',
        hierarchies: [{ name: 'default', levels: ['scenario'], effectiveDating: false }],
      },
      {
        name: 'Currency',
        hierarchies: [{ name: 'default', levels: ['currency'], effectiveDating: false }],
      },
      {
        name: 'Version',
        hierarchies: [{ name: 'default', levels: ['version'], effectiveDating: false }],
      },
      {
        name: 'DataSource',
        hierarchies: [{ name: 'default', levels: ['source'], effectiveDating: false }],
      },
    ]

    for (const dim of systemDims) {
      if (!this.dimensions.has(dim.name)) {
        this.registerDimension(dim.name, 'system', dim.hierarchies ?? [])
      }
    }
  }

  // --- State ---

  getCellCount(): number {
    return this.cells.size
  }

  getHistoryCount(): number {
    return this.cellHistory.length
  }

  clearAll(): void {
    this.dimensions.clear()
    this.cubes.clear()
    this.cells.clear()
    this.cellHistory = []
    this.snapshots = []
    this.snapshotCells.clear()
    this.lastSnapshotCellValues.clear()
    this.cellCubeIndex.clear()
    this.cubeCellIndex.clear()
    this.memberChildrenIndex.clear()
  }

  // --- Persistence ---

  initialize(storage: CubeEnginePersistence): void {
    this.storage = storage
  }

  async loadFromStorage(): Promise<void> {
    if (!this.storage) return

    const [dimensions, cubes, cells, history, snapshotsData] = await Promise.all([
      this.storage.loadDimensions(),
      this.storage.loadCubes(),
      this.storage.loadCells(),
      this.storage.loadHistory(),
      this.storage.loadSnapshots(),
    ])

    this.dimensions = dimensions
    this.cubes = cubes
    this.cells = new Map(cells.map(({ cellKey, cell }) => [cellKey, cell]))
    // Prune loaded history if it exceeds limit
    this.cellHistory =
      history.length > MAX_HISTORY_SIZE ? history.slice(-MAX_HISTORY_SIZE) : history
    this.snapshots = snapshotsData.snapshots
    this.snapshotCells = snapshotsData.snapshotCells

    // Rebuild performance indexes after loading
    this.rebuildIndexes()

    if (this.snapshots.length > 0) {
      const ids = this.snapshots.map((s) => {
        const match = s.id.match(/snap-(\d+)-(\d+)/)
        return match ? parseInt(match[2], 10) : 0
      })
      this.snapshotCounter = Math.max(...ids, 0)
    }
  }

  async saveToStorage(): Promise<void> {
    if (!this.storage) return

    await this.storage.saveDimensions(this.dimensions)
    await this.storage.saveCubes(this.cubes)

    const cellEntries = Array.from(this.cells.entries()).map(([key, cell]) => ({
      cube: key.split('|')[0],
      cell,
      cellKey: key,
    }))
    await this.storage.saveCells(cellEntries)

    await this.storage.saveHistory(this.cellHistory)
    await this.storage.saveSnapshots(this.snapshots, this.snapshotCells)
  }

  getStorage(): CubeEnginePersistence | null {
    return this.storage
  }

  // --- Private Helpers ---

  private cellKey(cube: string, coords: Record<string, string>, measure: string): string {
    const sortedCoords = Object.keys(coords)
      .sort()
      .map((k) => `${k}=${coords[k]}`)
      .join('|')
    return `${cube}|${sortedCoords}|${measure}`
  }

  private findCubeForCell(cell: CubeCell): string | null {
    // Use index if available, fallback to scan
    for (const [name, cubeDef] of this.cubes) {
      const dims = cubeDef.dimensions
      const coordKeys = Object.keys(cell.coords)
      if (dims.length === coordKeys.length && dims.every((d) => d in cell.coords)) {
        return name
      }
    }
    return null
  }

  private filterCells(query: CubeQuery): CubeCell[] {
    const cubeDef = this.cubes.get(query.cube)
    if (!cubeDef) return []

    // Use cube index for O(cube_cells) instead of O(all_cells) iteration
    const cubeCellKeys = this.cubeCellIndex.get(query.cube)
    const matchingCells: CubeCell[] = []

    const cellIterator = cubeCellKeys
      ? (Array.from(cubeCellKeys)
          .map((key) => this.cells.get(key))
          .filter(Boolean) as CubeCell[])
      : Array.from(this.cells.values())

    for (const cell of cellIterator) {
      // When using cube index, cells are already filtered by cube; otherwise verify
      if (!cubeCellKeys && this.findCubeForCell(cell) !== query.cube) continue
      if (!cubeDef.measures.some((m) => m.name === cell.measure)) continue

      let matches = true
      for (const filter of query.filters) {
        const cellMemberId = cell.coords[filter.dimension]
        if (!cellMemberId) {
          matches = false
          break
        }
        if (filter.includeChildren) {
          const descendants = this.getDescendants(filter.dimension, cellMemberId)
          const descendantIds = new Set(descendants.map((d) => d.id))
          if (!filter.memberIds.includes(cellMemberId) && !descendantIds.has(cellMemberId)) {
            matches = false
            break
          }
        } else {
          if (!filter.memberIds.includes(cellMemberId)) {
            matches = false
            break
          }
        }
      }
      if (matches) matchingCells.push(cell)
    }
    return matchingCells
  }

  private aggregateCells(cells: CubeCell[], query: CubeQuery): Map<string, number> {
    const aggregated = new Map<string, number>()
    const agg = query.aggregation ?? 'sum'

    for (const cell of cells) {
      const rowKey = this.buildRowKey(cell, query.rows)
      const value = typeof cell.value === 'number' ? cell.value : 0

      const existing = aggregated.get(rowKey) ?? 0
      switch (agg) {
        case 'sum':
          aggregated.set(rowKey, existing + value)
          break
        case 'avg':
          aggregated.set(rowKey, existing + value)
          break
        case 'count':
          aggregated.set(rowKey, existing + 1)
          break
        case 'min':
          aggregated.set(rowKey, existing === 0 ? value : Math.min(existing, value))
          break
        case 'max':
          aggregated.set(rowKey, Math.max(existing, value))
          break
        default:
          aggregated.set(rowKey, existing + value)
      }
    }

    if (agg === 'avg') {
      const counts = new Map<string, number>()
      for (const cell of cells) {
        const rowKey = this.buildRowKey(cell, query.rows)
        counts.set(rowKey, (counts.get(rowKey) ?? 0) + 1)
      }
      for (const [key, sum] of aggregated) {
        aggregated.set(key, sum / (counts.get(key) ?? 1))
      }
    }

    return aggregated
  }

  private buildRowKey(cell: CubeCell, rowDims: string[]): string {
    return rowDims.map((d) => cell.coords[d] ?? '').join('|')
  }

  private formatResult(aggregated: Map<string, number>, query: CubeQuery): CubeResult {
    const rows: CubeResult['rows'] = []
    for (const [label, value] of aggregated) {
      rows.push({ label, values: [value], isTotal: false })
    }

    const headers: CubeResult['headers'] = query.rows.map((dim) => ({
      dimension: dim,
      members: this.getMembers(dim).map((m) => m.id),
    }))

    let grandTotal: (number | string | null)[] | undefined
    if (query.includeGrandTotal && rows.length > 0) {
      const total = rows.reduce((sum, r) => sum + ((r.values[0] as number) ?? 0), 0)
      grandTotal = [total]
    }

    return { headers, rows, grandTotal }
  }

  private reconstructSnapshotCells(snapshotId: string): Map<string, unknown> | undefined {
    const snapshotIndex = this.snapshots.findIndex((s) => s.id === snapshotId)
    if (snapshotIndex === -1) return undefined

    // Walk backwards through the snapshot chain, collecting values
    const result = new Map<string, unknown>()
    for (let i = snapshotIndex; i >= 0; i--) {
      const snapId = this.snapshots[i].id
      const cells = this.snapshotCells.get(snapId)
      if (!cells) continue

      for (const [key, value] of cells) {
        // Only set if not already resolved from a later snapshot
        if (!result.has(key)) {
          if (value === null) {
            // Deleted cell — mark as explicitly absent
            result.set(key, undefined)
          } else {
            result.set(key, value)
          }
        }
      }
    }

    // Remove deleted markers
    for (const [key, value] of result) {
      if (value === undefined) {
        result.delete(key)
      }
    }

    return result
  }

  private rebuildIndexes(): void {
    this.cellCubeIndex.clear()
    this.cubeCellIndex.clear()
    this.memberChildrenIndex.clear()

    // Rebuild cell-to-cube index
    for (const [key, cell] of this.cells) {
      const cube = this.findCubeForCell(cell)
      if (cube) {
        this.cellCubeIndex.set(key, cube)
        if (!this.cubeCellIndex.has(cube)) {
          this.cubeCellIndex.set(cube, new Set())
        }
        this.cubeCellIndex.get(cube)!.add(key)
      }
    }

    // Rebuild member children index
    for (const dim of this.dimensions.values()) {
      for (const member of dim.members.values()) {
        if (member.parentId) {
          const parentKey = `${dim.name}:${member.parentId}`
          if (!this.memberChildrenIndex.has(parentKey)) {
            this.memberChildrenIndex.set(parentKey, new Set())
          }
          this.memberChildrenIndex.get(parentKey)!.add(member.id)
        }
      }
    }
  }

  private parseCellAddress(key: string): CellAddress {
    const parts = key.split('|')
    const cube = parts[0]
    const measure = parts[parts.length - 1]
    const coords: Record<string, string> = {}
    for (let i = 1; i < parts.length - 1; i++) {
      const [dim, memberId] = parts[i].split('=')
      coords[dim] = memberId
    }
    return { cube, coords, measure }
  }
}

