  })

  it('should return undefined for non-existent template', () => {
    expect(engine.getTemplate('non-existent')).toBeUndefined()
  })

  it('should register a custom template', () => {
    const custom: ExportTemplate = {
      id: 'custom-report',
      name: 'Custom Report',
      type: 'kpi_summary',
      description: 'A custom report',
      sections: [{ id: 's1', type: 'text', title: 'Intro', order: 0, config: {} }],
      style: {
        primaryColor: '#000',
        secondaryColor: '#fff',
        fontFamily: 'helvetica',
        headerFontSize: 14,
        bodyFontSize: 10,
        companyName: 'Test',
      },
      variables: [{ key: 'entity', label: 'Entity', defaultValue: 'ACME' }],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    }
    engine.register(custom)
    const tpl = engine.getTemplate('custom-report')
    expect(tpl).toBeDefined()
    expect(tpl!.name).toBe('Custom Report')
  })

  it('should list templates', () => {
    const templates = engine.listTemplates()
    expect(templates.length).toBeGreaterThanOrEqual(5)
    const names = templates.map((t) => t.name)
    expect(names.length).toBeGreaterThan(0)
  })

  it('should get template types', () => {
    const templates = engine.listTemplates()
    const types = new Set(templates.map((t) => t.type))
    expect(types.size).toBeGreaterThan(1)
  })

  it('should have variables on templates', () => {
    const templates = engine.listTemplates()
    for (const tpl of templates) {
      expect(tpl.variables).toBeDefined()
      expect(Array.isArray(tpl.variables)).toBe(true)
    }
  })

  it('should have sections on templates', () => {
    const templates = engine.listTemplates()
    for (const tpl of templates) {
      expect(tpl.sections).toBeDefined()
      expect(Array.isArray(tpl.sections)).toBe(true)
    }
  })
})

import type { ExchangeRate } from '@/types'

export type RateType = 'closing' | 'average' | 'historical' | 'transaction'

export interface FXRateEntry {
  from: string
  to: string
  rate: number
  date: string
  source: 'manual' | 'api' | 'feed'
}

export interface HistoricalRate {
  date: string
  rate: number
}

export interface TranslationInput {
  amount: number
  rateType: RateType
  entityCurrency: string
  parentCurrency: string
  period: string
}

export class FXEngine {
  private static rates: Map<string, FXRateEntry[]> = new Map()

  private static rateKey(from: string, to: string): string {
    return `${from}_${to}`
  }

  static getRate(from: string, to: string, date?: string): number {
    if (from === to) return 1
    const key = this.rateKey(from, to)
    const entries = this.rates.get(key) ?? []
    if (entries.length === 0) return 0
    if (date) {
      const entry = entries.find((e) => e.date <= date) ?? entries[entries.length - 1]
      return entry.rate
    }
    return entries[entries.length - 1].rate
  }

  static convert(amount: number, from: string, to: string, date?: string): number {
    if (!Number.isFinite(amount)) return 0
    const rate = this.getRate(from, to, date)
    return rate === 0 ? 0 : amount * rate
  }

  static setRate(
    from: string,
    to: string,
    rate: number,
    date: string,
    source: FXRateEntry['source'] = 'manual'
  ): void {
    if (!Number.isFinite(rate) || rate < 0) return
    const key = this.rateKey(from, to)
    const entries = this.rates.get(key) ?? []
    entries.push({ from, to, rate, date, source })
    entries.sort((a, b) => a.date.localeCompare(b.date))
    this.rates.set(key, entries)
  }

  static getHistoricalRates(
    from: string,
    to: string,
    startDate: string,
    endDate: string
  ): HistoricalRate[] {
    const key = this.rateKey(from, to)
    const entries = this.rates.get(key) ?? []
    return entries
      .filter((e) => e.date >= startDate && e.date <= endDate)
      .map((e) => ({ date: e.date, rate: e.rate }))
  }

  static translateForConsolidation(input: TranslationInput): {
    translated: number
    rateUsed: number
    rateType: RateType
  } {
    const { amount, rateType, entityCurrency, parentCurrency, period } = input
    let rate = 0

    switch (rateType) {
      case 'closing':
        rate = this.getRate(entityCurrency, parentCurrency, period)
        break
      case 'average':
        rate = this.getAverageRate(entityCurrency, parentCurrency, period)
        break
      case 'historical':
        rate = this.getRate(entityCurrency, parentCurrency)
        break
      case 'transaction':
        rate = this.getRate(entityCurrency, parentCurrency, period)
        break
    }

    return {
      translated: rate === 0 ? 0 : amount * rate,
      rateUsed: rate,
      rateType,
    }
  }

  static getAverageRate(from: string, to: string, period?: string): number {
    const key = this.rateKey(from, to)
    const entries = this.rates.get(key) ?? []
    if (entries.length === 0) return 0

    let filtered = entries
    if (period) {
      const year = period.substring(0, 4)
      filtered = entries.filter((e) => e.date.startsWith(year))
    }

    if (filtered.length === 0) return entries[entries.length - 1].rate
    const sum = filtered.reduce((acc, e) => acc + e.rate, 0)
    return sum / filtered.length
  }

  static calculateFXGainLoss(
    baseAmount: number,
    functionalAmount: number,
    currentRate: number,
    historicalRate: number
  ): number {
    if (!Number.isFinite(baseAmount) || !Number.isFinite(functionalAmount)) return 0
    const translatedAtCurrent = baseAmount * currentRate
    const translatedAtHistorical = baseAmount * historicalRate
    return translatedAtCurrent - translatedAtHistorical
  }

  static loadRates(rates: ExchangeRate[]): void {
    for (const r of rates) {
      this.setRate(
        r.fromCurrency ?? 'USD',
        r.toCurrency ?? 'EUR',
        r.rate,
        (r as any).date ?? new Date().toISOString(),
        'api'
      )
    }
  }

  static clearRates(): void {
    this.rates.clear()
  }

  static getAllRates(): FXRateEntry[] {
    const all: FXRateEntry[] = []
    for (const entries of this.rates.values()) {
      all.push(...entries)
    }
    return all.sort((a, b) => a.date.localeCompare(b.date))
  }
}

/**
 * FinanceCopilotEngine — AI copilot for financial analysis
 * Answers natural language questions about financial data
 */

import type { GLState, BudgetState } from '@/types'

interface CopilotQuestion {
  question: string
  context: 'budget' | 'forecast' | 'actual' | 'variance' | 'general'
  entity?: string
  period?: string
}

interface CopilotAnswer {
  answer: string
  confidence: number
  data?: unknown
  chartType?: 'bar' | 'line' | 'pie' | 'table'
  sources: string[]
}

export class FinanceCopilotEngine {
  /**
   * Answer a natural language financial question
   */
  static answer(question: string, stores: { gl?: GLState; budget?: BudgetState }): CopilotAnswer {
    const q = question.toLowerCase()

    // Revenue questions
    if (q.includes('revenue') || q.includes('sales')) {
      return this.answerRevenue(question, stores)
    }

    // Expense questions
    if (q.includes('expense') || q.includes('cost') || q.includes('spend')) {
      return this.answerExpense(question, stores)
    }

    // Variance questions
    if (q.includes('variance') || q.includes('difference') || q.includes('vs')) {
      return this.answerVariance(question, stores)
    }

    // Budget questions
    if (q.includes('budget') || q.includes('plan') || q.includes('forecast')) {
      return this.answerBudget(question, stores)
    }

    return {
      answer:
        'I can help with revenue, expenses, variance, and budget questions. Try asking about specific metrics.',
      confidence: 0.5,
      sources: [],
    }
  }

  private static answerRevenue(q: string, stores: { gl?: GLState }): CopilotAnswer {
    const entries = stores.gl?.entries?.filter((e) => e.credit > 0) ?? []
    const total = entries.reduce((sum, e) => sum + e.amount, 0)

    return {
      answer: `Total revenue: $${(total / 1000).toFixed(0)}K across ${entries.length} entries.`,
      confidence: 0.9,
      data: { total, count: entries.length },
      chartType: 'bar',
      sources: ['GL Entries'],
    }
  }

  private static answerExpense(q: string, stores: { gl?: GLState }): CopilotAnswer {
    const entries = stores.gl?.entries?.filter((e) => e.debit > 0) ?? []
    const total = entries.reduce((sum, e) => sum + e.amount, 0)

    return {
      answer: `Total expenses: $${(total / 1000).toFixed(0)}K across ${entries.length} entries.`,
      confidence: 0.9,
      data: { total, count: entries.length },
      chartType: 'bar',
      sources: ['GL Entries'],
    }
  }

  private static answerVariance(
    q: string,
    stores: { gl?: GLState; budget?: BudgetState }
  ): CopilotAnswer {
    return {
      answer:
        'Variance analysis compares actual vs budget. Positive = favorable for revenue, unfavorable for expenses.',
      confidence: 0.7,
      sources: ['GL Entries', 'Budget Store'],
    }
  }

  private static answerBudget(q: string, stores: { budget?: BudgetState }): CopilotAnswer {
    const budgets = stores.budget?.budgets ?? []
    return {
      answer: `${budgets.length} budgets loaded. Status: ${budgets.map((b) => b.status).join(', ')}.`,
      confidence: 0.8,
      data: { count: budgets.length },
      sources: ['Budget Store'],
    }
  }

  /**
   * Generate chart suggestion from question
   */
  static suggestChart(question: string): { type: string; config: unknown } | null {
    const q = question.toLowerCase()

    if (q.includes('trend') || q.includes('over time')) {
      return { type: 'line', config: { xAxis: 'period', yAxis: 'value' } }
    }
    if (q.includes('breakdown') || q.includes('by category')) {
      return { type: 'pie', config: { nameKey: 'category', valueKey: 'value' } }
    }
    if (q.includes('compare') || q.includes('vs')) {
      return { type: 'bar', config: { xAxis: 'name', yAxis: ['actual', 'budget'] } }
    }

    return null
  }
}

// =============================================================================
// FINANCIAL INSTRUMENTS ENGINE
// Bond pricing, loan amortization, option pricing, DCF valuation
// Pure TypeScript, deterministic, testable
// =============================================================================

export interface BondPricingResult {
  price: number
  yield: number
  duration: number
  convexity: number
  accruedInterest: number
}

export interface AmortizationEntry {
  period: number
  payment: number
  principal: number
  interest: number
  balance: number
}

export interface OptionGreeks {
  delta: number
  gamma: number
  theta: number
  vega: number
  rho: number
}

export interface OptionPricingResult {
  callPrice: number
  putPrice: number
  greeks: OptionGreeks
}

export interface DCFResult {
  freeCashFlows: number[]
  terminalValue: number
  enterpriseValue: number
  equityValue: number
  wacc: number
}

export class FinancialInstrumentsEngine {
  // ---------------------------------------------------------------------------
  // Bond Pricing
  // ---------------------------------------------------------------------------

  static bondPrice(
    faceValue: number,
    couponRate: number,
    yieldToMaturity: number,
    periodsToMaturity: number,
    periodsPerYear: number = 2
  ): number {
    const coupon = (faceValue * couponRate) / periodsPerYear
    const ytm = yieldToMaturity / periodsPerYear
    const n = periodsToMaturity * periodsPerYear

    let price = 0
    for (let t = 1; t <= n; t++) {
      price += coupon / Math.pow(1 + ytm, t)
    }
    price += faceValue / Math.pow(1 + ytm, n)
    return price
  }

  static bondYTM(
    faceValue: number,
    couponRate: number,
    price: number,
    periodsToMaturity: number,
    periodsPerYear: number = 2,
    tolerance: number = 1e-8,
    maxIterations: number = 100
  ): number {
    let ytm = couponRate
    for (let i = 0; i < maxIterations; i++) {
      const calcPrice = this.bondPrice(
        faceValue,
        couponRate,
        ytm,
        periodsToMaturity,
        periodsPerYear
      )
      const diff = calcPrice - price
      if (Math.abs(diff) < tolerance) break

      const derivative = this.bondPriceDerivative(
        faceValue,
        couponRate,
        ytm,
        periodsToMaturity,
        periodsPerYear
      )
      ytm -= diff / derivative
    }
    return ytm
  }

  private static bondPriceDerivative(
    faceValue: number,
    couponRate: number,
    ytm: number,
    periodsToMaturity: number,
    periodsPerYear: number
  ): number {
    const h = 1e-6
    const p1 = this.bondPrice(faceValue, couponRate, ytm + h, periodsToMaturity, periodsPerYear)
    const p2 = this.bondPrice(faceValue, couponRate, ytm - h, periodsToMaturity, periodsPerYear)
    return (p1 - p2) / (2 * h)
  }

  static bondDuration(
    faceValue: number,
    couponRate: number,
    ytm: number,
    periodsToMaturity: number,
    periodsPerYear: number = 2
  ): number {
    const coupon = (faceValue * couponRate) / periodsPerYear
    const rate = ytm / periodsPerYear
    const n = periodsToMaturity * periodsPerYear
    const price = this.bondPrice(faceValue, couponRate, ytm, periodsToMaturity, periodsPerYear)

    let weightedCF = 0
    for (let t = 1; t <= n; t++) {
      weightedCF += (t * coupon) / Math.pow(1 + rate, t)
    }
    weightedCF += (n * faceValue) / Math.pow(1 + rate, n)

    return weightedCF / price / periodsPerYear
  }

  static bondConvexity(
    faceValue: number,
    couponRate: number,
    ytm: number,
    periodsToMaturity: number,
    periodsPerYear: number = 2
  ): number {
    const coupon = (faceValue * couponRate) / periodsPerYear
    const rate = ytm / periodsPerYear
    const n = periodsToMaturity * periodsPerYear
    const price = this.bondPrice(faceValue, couponRate, ytm, periodsToMaturity, periodsPerYear)

    let convexity = 0
    for (let t = 1; t <= n; t++) {
      convexity += (coupon * t * (t + 1)) / Math.pow(1 + rate, t + 2)
    }
    convexity += (faceValue * n * (n + 1)) / Math.pow(1 + rate, n + 2)

    return convexity / (price * periodsPerYear * periodsPerYear)
  }

  static accruedInterest(
    faceValue: number,
    couponRate: number,
    daysSinceLastCoupon: number,
    daysInCouponPeriod: number,
    periodsPerYear: number = 2
  ): number {
    return ((faceValue * couponRate) / periodsPerYear) * (daysSinceLastCoupon / daysInCouponPeriod)
  }

  // ---------------------------------------------------------------------------
  // Loan Amortization
  // ---------------------------------------------------------------------------

  static loanAmortization(
    principal: number,
    annualRate: number,
    termMonths: number,
    startDate?: Date
  ): AmortizationEntry[] {
    const monthlyRate = annualRate / 12
    const payment =
      (principal * (monthlyRate * Math.pow(1 + monthlyRate, termMonths))) /
      (Math.pow(1 + monthlyRate, termMonths) - 1)

    const schedule: AmortizationEntry[] = []
    let balance = principal

    for (let period = 1; period <= termMonths; period++) {
      const interest = balance * monthlyRate
      const principalPaid = payment - interest
      balance -= principalPaid

      schedule.push({
        period,
        payment,
        principal: principalPaid,
        interest,
        balance: Math.max(0, balance),
      })
    }

    return schedule
  }

  static loanPayment(principal: number, annualRate: number, termMonths: number): number {
    const monthlyRate = annualRate / 12
    return (
      (principal * (monthlyRate * Math.pow(1 + monthlyRate, termMonths))) /
      (Math.pow(1 + monthlyRate, termMonths) - 1)
    )
  }

  // ---------------------------------------------------------------------------
  // Option Pricing (Black-Scholes)
  // ---------------------------------------------------------------------------

  static blackScholes(
    spot: number,
    strike: number,
    timeToExpiry: number,
    riskFreeRate: number,
    volatility: number
  ): OptionPricingResult {
    const d1 =
      (Math.log(spot / strike) + (riskFreeRate + (volatility * volatility) / 2) * timeToExpiry) /
      (volatility * Math.sqrt(timeToExpiry))
    const d2 = d1 - volatility * Math.sqrt(timeToExpiry)

    const callPrice =
      spot * this.normCDF(d1) - strike * Math.exp(-riskFreeRate * timeToExpiry) * this.normCDF(d2)
    const putPrice =
      strike * Math.exp(-riskFreeRate * timeToExpiry) * this.normCDF(-d2) - spot * this.normCDF(-d1)

    const delta = this.normCDF(d1)
    const gamma = this.normPDF(d1) / (spot * volatility * Math.sqrt(timeToExpiry))
    const theta =
      -(spot * this.normPDF(d1) * volatility) / (2 * Math.sqrt(timeToExpiry)) -
      riskFreeRate * strike * Math.exp(-riskFreeRate * timeToExpiry) * this.normCDF(d2)
    const vega = spot * this.normPDF(d1) * Math.sqrt(timeToExpiry)
    const rho = strike * timeToExpiry * Math.exp(-riskFreeRate * timeToExpiry) * this.normCDF(d2)

    return {
      callPrice,
      putPrice,
      greeks: { delta, gamma, theta, vega, rho },
    }
  }

  private static normCDF(x: number): number {
    const a1 = 0.254829592
    const a2 = -0.284496736
    const a3 = 1.421413741
    const a4 = -1.453152027
    const a5 = 1.061405429
    const p = 0.3275911

    const sign = x < 0 ? -1 : 1
    x = Math.abs(x) / Math.sqrt(2)

    const t = 1.0 / (1.0 + p * x)
    const y = 1.0 - ((((a5 * t + a4) * t + a3) * t + a2) * t + a1) * t * Math.exp(-x * x)

    return 0.5 * (1.0 + sign * y)
  }

  private static normPDF(x: number): number {
    return Math.exp(-0.5 * x * x) / Math.sqrt(2 * Math.PI)
  }

  // ---------------------------------------------------------------------------
  // DCF Valuation
  // ---------------------------------------------------------------------------

  static dcfValuation(
    freeCashFlows: number[],
    terminalGrowthRate: number,
    wacc: number,
    netDebt: number,
    sharesOutstanding: number
  ): DCFResult {
    const lastFCF = freeCashFlows[freeCashFlows.length - 1]
    const terminalValue = (lastFCF * (1 + terminalGrowthRate)) / (wacc - terminalGrowthRate)

    let pvFCFs = 0
    for (let i = 0; i < freeCashFlows.length; i++) {
      pvFCFs += freeCashFlows[i] / Math.pow(1 + wacc, i + 1)
    }

    const pvTerminal = terminalValue / Math.pow(1 + wacc, freeCashFlows.length)
    const enterpriseValue = pvFCFs + pvTerminal
    const equityValue = (enterpriseValue - netDebt) / sharesOutstanding

    return {
      freeCashFlows,
      terminalValue,
      enterpriseValue,
      equityValue,
      wacc,
    }
  }

  static wacc(
    equityValue: number,
    debtValue: number,
    costOfEquity: number,
    costOfDebt: number,
    taxRate: number
  ): number {
    const total = equityValue + debtValue
    const equityWeight = equityValue / total
    const debtWeight = debtValue / total
    return equityWeight * costOfEquity + debtWeight * costOfDebt * (1 - taxRate)
  }

  // ---------------------------------------------------------------------------
  // Comparable Analysis
  // ---------------------------------------------------------------------------

  static comparableMultiples(
    enterpriseValue: number,
    revenue: number,
    ebitda: number,
    netIncome: number,
    sharesOutstanding: number,
    stockPrice: number
  ): Record<string, number> {
    return {
      evRevenue: enterpriseValue / revenue,
      evEbitda: enterpriseValue / ebitda,
      peRatio: (stockPrice * sharesOutstanding) / netIncome,
      priceToSales: (stockPrice * sharesOutstanding) / revenue,
    }
  }

  // ---------------------------------------------------------------------------
  // Yield Curve
  // ---------------------------------------------------------------------------

  static linearInterpolation(x: number[], y: number[], targetX: number): number {
    for (let i = 0; i < x.length - 1; i++) {
      if (targetX >= x[i] && targetX <= x[i + 1]) {
        const t = (targetX - x[i]) / (x[i + 1] - x[i])
        return y[i] + t * (y[i + 1] - y[i])
      }
    }
    return targetX <= x[0] ? y[0] : y[y.length - 1]
  }

  // ---------------------------------------------------------------------------
  // Credit Risk
  // ---------------------------------------------------------------------------

  static expectedLoss(
    probabilityOfDefault: number,
    lossGivenDefault: number,
    exposureAtDefault: number
  ): number {
    return probabilityOfDefault * lossGivenDefault * exposureAtDefault
  }
}

// ForecastMethodEngine — Pure time-series forecasting algorithms
// All methods accept number[] time series and return forecasts + confidence intervals + accuracy metrics

export interface ForecastResult {
  forecast: number[]
  fitted: number[]
  confidenceLower: number[]
  confidenceUpper: number[]
  metrics: AccuracyMetrics
}

export interface AccuracyMetrics {
  mape: number
  rmse: number
  mae: number
  r2: number
}

export interface MovingAverageOptions {
  type: 'simple' | 'weighted' | 'exponential'
  window: number
  weights?: number[]
  alpha?: number
}

export interface LinearRegressionResult {
  slope: number
  intercept: number
  r2: number
  predict: (x: number) => number
  forecast: number[]
  residuals: number[]
  metrics: AccuracyMetrics
}

export interface SeasonalDecompositionResult {
  trend: number[]
  seasonal: number[]
  residual: number[]
  deseasonalized: number[]
  seasonalIndices: number[]
  metrics: AccuracyMetrics
}

export interface HoltWintersResult extends ForecastResult {
  level: number[]
  trend: number[]
  seasonal: number[]
  alpha: number
  beta: number
  gamma: number
}

// ─── Internal helpers ───────────────────────────────────────────────────────────

function mean(values: number[]): number {
  return values.reduce((a, b) => a + b, 0) / values.length
}

function standardDeviation(values: number[]): number {
  const m = mean(values)
  return Math.sqrt(values.reduce((sum, v) => sum + (v - m) ** 2, 0) / values.length)
}

function calcMAPE(actual: number[], predicted: number[]): number {
  let sum = 0
  let count = 0
  for (let i = 0; i < actual.length; i++) {
    if (actual[i] !== 0) {
      sum += Math.abs((actual[i] - predicted[i]) / actual[i])
      count++
    }
  }
  return count > 0 ? (sum / count) * 100 : 0
}

function calcRMSE(actual: number[], predicted: number[]): number {
  let sum = 0
  for (let i = 0; i < actual.length; i++) {
    sum += (actual[i] - predicted[i]) ** 2
  }
  return Math.sqrt(sum / actual.length)
}

function calcMAE(actual: number[], predicted: number[]): number {
  let sum = 0
  for (let i = 0; i < actual.length; i++) {
    sum += Math.abs(actual[i] - predicted[i])
  }
  return sum / actual.length
}

function calcR2(actual: number[], predicted: number[]): number {
  const m = mean(actual)
  let ssRes = 0
  let ssTot = 0
  for (let i = 0; i < actual.length; i++) {
    ssRes += (actual[i] - predicted[i]) ** 2
    ssTot += (actual[i] - m) ** 2
  }
  return ssTot === 0 ? 0 : 1 - ssRes / ssTot
}

function buildMetrics(actual: number[], predicted: number[]): AccuracyMetrics {
  return {
    mape: calcMAPE(actual, predicted),
    rmse: calcRMSE(actual, predicted),
    mae: calcMAE(actual, predicted),
    r2: calcR2(actual, predicted),
  }
}

function buildConfidenceIntervals(
  residuals: number[],
  forecastLength: number,
  multiplier = 1.96
): { lower: number[]; upper: number[] } {
  const sigma = standardDeviation(residuals)
  const lower: number[] = []
  const upper: number[] = []
  for (let i = 0; i < forecastLength; i++) {
    const widen = sigma * multiplier * Math.sqrt(1 + i * 0.1)
    lower.push(-widen)
    upper.push(widen)
  }
  return { lower, upper }
}

// ─── Main engine ────────────────────────────────────────────────────────────────

export class ForecastMethodEngine {
  // ──────────────────────────────────────────────────────────────────────────────
  // Moving Average methods
  // ──────────────────────────────────────────────────────────────────────────────

  static simpleMovingAverage(data: number[], window: number): ForecastResult {
    if (window < 1 || window > data.length) {
      throw new Error(`Window ${window} must be between 1 and data length ${data.length}`)
    }

    const fitted: number[] = new Array(data.length).fill(NaN)
    for (let i = window - 1; i < data.length; i++) {
      let sum = 0
      for (let j = i - window + 1; j <= i; j++) {
        sum += data[j]
      }
      fitted[i] = sum / window
    }

    const forecast: number[] = []
    const lastWindow = data.slice(-window)
    const lastAvg = mean(lastWindow)
    forecast.push(lastAvg)

    const validFitted = fitted.filter((v) => !isNaN(v))
    const correspondingActual = data.slice(window - 1)
    const residuals = correspondingActual.map((v, i) => v - validFitted[i])
    const ci = buildConfidenceIntervals(residuals, forecast.length)

    return {
      forecast,
      fitted,
      confidenceLower: ci.lower,
      confidenceUpper: ci.upper,
      metrics: buildMetrics(correspondingActual, validFitted),
    }
  }

  static weightedMovingAverage(data: number[], weights: number[]): ForecastResult {
    const window = weights.length
    if (window < 1 || window > data.length) {
      throw new Error(`Weights length ${window} must be between 1 and data length ${data.length}`)
    }

    const weightSum = weights.reduce((a, b) => a + b, 0)
    const normalizedWeights = weights.map((w) => w / weightSum)

    const fitted: number[] = new Array(data.length).fill(NaN)
    for (let i = window - 1; i < data.length; i++) {
      let sum = 0
      for (let j = 0; j < window; j++) {
        sum += data[i - window + 1 + j] * normalizedWeights[j]
      }
      fitted[i] = sum
    }

    const forecast: number[] = []
    const lastWindow = data.slice(-window)
    let fSum = 0
    for (let j = 0; j < window; j++) {
      fSum += lastWindow[j] * normalizedWeights[j]
    }
    forecast.push(fSum)

    const validFitted = fitted.filter((v) => !isNaN(v))
    const correspondingActual = data.slice(window - 1)
    const residuals = correspondingActual.map((v, i) => v - validFitted[i])
    const ci = buildConfidenceIntervals(residuals, forecast.length)

    return {
      forecast,
      fitted,
      confidenceLower: ci.lower,
      confidenceUpper: ci.upper,
      metrics: buildMetrics(correspondingActual, validFitted),
    }
  }

  static exponentialSmoothing(data: number[], alpha: number): ForecastResult {
    if (alpha <= 0 || alpha > 1) {
      throw new Error(`Alpha must be between 0 (exclusive) and 1, got ${alpha}`)
    }
    if (data.length < 2) {
      throw new Error('Need at least 2 data points')
    }

    const fitted: number[] = [data[0]]
    for (let i = 1; i < data.length; i++) {
      fitted.push(alpha * data[i] + (1 - alpha) * fitted[i - 1])
    }

    const lastFitted = fitted[fitted.length - 1]
    const forecast = [lastFitted]

    const residuals = data.slice(1).map((v, i) => v - fitted[i])
    const ci = buildConfidenceIntervals(residuals, forecast.length)

    return {
      forecast,
      fitted,
      confidenceLower: ci.lower,
      confidenceUpper: ci.upper,
      metrics: buildMetrics(data.slice(1), fitted.slice(1)),
    }
  }

  static movingAverage(data: number[], options: MovingAverageOptions): ForecastResult {
    switch (options.type) {
      case 'simple':
        return this.simpleMovingAverage(data, options.window)
      case 'weighted': {
        const weights = options.weights ?? Array.from({ length: options.window }, (_, i) => i + 1)
        return this.weightedMovingAverage(data, weights)
      }
      case 'exponential': {
        const alpha = options.alpha ?? 2 / (options.window + 1)
        return this.exponentialSmoothing(data, alpha)
      }
      default:
        throw new Error(`Unknown moving average type: ${options.type}`)
    }
  }

  // ──────────────────────────────────────────────────────────────────────────────
  // Linear Regression
  // ──────────────────────────────────────────────────────────────────────────────

  static linearRegression(data: number[], periodsToForecast = 1): LinearRegressionResult {
    if (data.length < 2) {
      throw new Error('Need at least 2 data points for linear regression')
    }

    const n = data.length
    const xMean = (n - 1) / 2
    const yMean = mean(data)

    let ssXY = 0
    let ssXX = 0
    for (let i = 0; i < n; i++) {
      ssXY += (i - xMean) * (data[i] - yMean)
      ssXX += (i - xMean) ** 2
    }

    const slope = ssXX === 0 ? 0 : ssXY / ssXX
    const intercept = yMean - slope * xMean

    const predict = (x: number) => intercept + slope * x

    const fitted = Array.from({ length: n }, (_, i) => predict(i))
    const forecast = Array.from({ length: periodsToForecast }, (_, i) => predict(n + i))
    const residuals = data.map((v, i) => v - fitted[i])

    const metrics = buildMetrics(data, fitted)

    const ci = buildConfidenceIntervals(residuals, periodsToForecast)

    return {
      slope,
      intercept,
      r2: metrics.r2,
      predict,
      forecast,
      residuals,
      metrics,
    }
  }

  // ──────────────────────────────────────────────────────────────────────────────
  // Seasonal Decomposition (additive & multiplicative)
  // ──────────────────────────────────────────────────────────────────────────────

  static seasonalDecomposition(
    data: number[],
    period: number,
    mode: 'additive' | 'multiplicative' = 'additive'
  ): SeasonalDecompositionResult {
    if (period < 2 || period > Math.floor(data.length / 2)) {
      throw new Error(
        `Period ${period} must be between 2 and half data length ${Math.floor(data.length / 2)}`
      )
    }

    const n = data.length

    // Step 1: Compute trend via centered moving average
    const trend: number[] = new Array(n).fill(NaN)
    const halfP = Math.floor(period / 2)

    for (let i = halfP; i < n - halfP; i++) {
      let sum = 0
      for (let j = i - halfP; j <= i + halfP; j++) {
        sum += data[j]
      }
      trend[i] = sum / period
    }

    // Fill edges by extending nearest valid trend value
    for (let i = 0; i < halfP; i++) {
      trend[i] = trend[halfP]
    }
    for (let i = n - halfP; i < n; i++) {
      trend[i] = trend[n - halfP - 1]
    }

    // Step 2: Detrend to get seasonal component
    const detrended: number[] = []
    for (let i = 0; i < n; i++) {
      if (mode === 'additive') {
        detrended.push(data[i] - trend[i])
      } else {
        detrended.push(trend[i] !== 0 ? data[i] / trend[i] : 1)
      }
    }

    // Step 3: Average seasonal indices per position in cycle
    const seasonalIndices: number[] = new Array(period).fill(0)
    const counts: number[] = new Array(period).fill(0)

    for (let i = 0; i < n; i++) {
      seasonalIndices[i % period] += detrended[i]
      counts[i % period]++
    }

    for (let i = 0; i < period; i++) {
      seasonalIndices[i] /= counts[i]
    }

    // Normalize: additive should sum to 0, multiplicative should multiply to 1
    if (mode === 'additive') {
      const sMean = mean(seasonalIndices)
      for (let i = 0; i < period; i++) {
        seasonalIndices[i] -= sMean
      }
    } else {
      const sMean = mean(seasonalIndices)
      if (sMean !== 0) {
        for (let i = 0; i < period; i++) {
          seasonalIndices[i] /= sMean
        }
      }
    }

    // Step 4: Build full seasonal array
    const seasonal: number[] = Array.from({ length: n }, (_, i) => seasonalIndices[i % period])

    // Step 5: Compute residual
    const residual: number[] = []
    for (let i = 0; i < n; i++) {
      if (mode === 'additive') {
        residual.push(data[i] - trend[i] - seasonal[i])
      } else {
        const denom = trend[i] * seasonal[i]
        residual.push(denom !== 0 ? data[i] / denom : 0)
      }
    }

    // Deseasonalized
    const deseasonalized: number[] = []
    for (let i = 0; i < n; i++) {
      if (mode === 'additive') {
        deseasonalized.push(data[i] - seasonal[i])
      } else {
        deseasonalized.push(seasonal[i] !== 0 ? data[i] / seasonal[i] : data[i])
      }
    }

    // Reconstruct for metrics
    const reconstructed: number[] = []
    for (let i = 0; i < n; i++) {
      if (mode === 'additive') {
        reconstructed.push(trend[i] + seasonal[i])
      } else {
        reconstructed.push(trend[i] * seasonal[i])
      }
    }

    return {
      trend,
      seasonal,
      residual,
      deseasonalized,
      seasonalIndices,
      metrics: buildMetrics(data, reconstructed),
    }
  }

  // ──────────────────────────────────────────────────────────────────────────────
  // Holt-Winters Triple Exponential Smoothing
  // ──────────────────────────────────────────────────────────────────────────────

  static holtWinters(
    data: number[],
    alpha: number,
    beta: number,
    gamma: number,
    period: number,
    periodsToForecast = 1,
    mode: 'additive' | 'multiplicative' = 'additive'
  ): HoltWintersResult {
    if (data.length < period * 2) {
      throw new Error(
        `Need at least ${period * 2} data points (2 full seasons), got ${data.length}`
      )
    }
    if (alpha < 0 || alpha > 1) throw new Error(`Alpha must be 0..1, got ${alpha}`)
    if (beta < 0 || beta > 1) throw new Error(`Beta must be 0..1, got ${beta}`)
    if (gamma < 0 || gamma > 1) throw new Error(`Gamma must be 0..1, got ${gamma}`)

    const n = data.length

    // Initialize level as mean of first season
    let levelInit = 0
    for (let i = 0; i < period; i++) {
      levelInit += data[i]
    }
    levelInit /= period

    // Initialize trend as average slope across first two seasons
    let trendInit = 0
    for (let i = 0; i < period; i++) {
      if (mode === 'additive') {
        trendInit += data[period + i] - data[i]
      } else {
        trendInit += data[i] !== 0 ? data[period + i] / data[i] : 1
      }
    }
    trendInit /= period
    if (mode === 'multiplicative') {
      trendInit = trendInit / period
    }

    // Initialize seasonal indices
    const seasonalInit: number[] = new Array(period)
    for (let i = 0; i < period; i++) {
      if (mode === 'additive') {
        seasonalInit[i] = data[i] - levelInit
      } else {
        seasonalInit[i] = levelInit !== 0 ? data[i] / levelInit : 1
      }
    }

    // Arrays for level, trend, seasonal
    const level: number[] = [levelInit]
    const trend: number[] = [trendInit]
    const seasonal: number[] = [...seasonalInit]

    const fitted: number[] = new Array(n).fill(NaN)

    // First season: use initial values
    for (let i = 0; i < period; i++) {
      if (mode === 'additive') {
        fitted[i] = levelInit + trendInit * 0 + seasonalInit[i]
      } else {
        fitted[i] = levelInit * trendInit ** 0 * seasonalInit[i]
      }
    }

    // Run HW from period onwards
    for (let i = period; i < n; i++) {
      const prevLevel = level[level.length - 1]
      const prevTrend = trend[trend.length - 1]
      const seasonIdx = i % period
      const prevSeason = seasonal[((i - period) % period) + (i - period >= 0 ? 0 : period)]

      let newLevel: number
      let newTrend: number
      let newSeason: number
      let forecastVal: number

      if (mode === 'additive') {
        forecastVal = prevLevel + prevTrend + seasonalInit[seasonIdx]
        newLevel = alpha * (data[i] - seasonal[seasonIdx]) + (1 - alpha) * (prevLevel + prevTrend)
        newTrend = beta * (newLevel - prevLevel) + (1 - beta) * prevTrend
        newSeason = gamma * (data[i] - newLevel) + (1 - gamma) * seasonal[seasonIdx]
      } else {
        forecastVal = prevLevel * prevTrend * seasonal[seasonIdx]
        newLevel =
          alpha * (seasonal[seasonIdx] !== 0 ? data[i] / seasonal[seasonIdx] : data[i]) +
          (1 - alpha) * (prevLevel * prevTrend)
        newTrend = beta * (prevLevel !== 0 ? newLevel / prevLevel : 1) + (1 - beta) * prevTrend
        newSeason =
          gamma * (newLevel !== 0 ? data[i] / newLevel : 1) + (1 - gamma) * seasonal[seasonIdx]
      }

      level.push(newLevel)
      trend.push(newTrend)
      seasonal[seasonIdx] = newSeason
      fitted[i] = forecastVal
    }

    // Generate forecasts
    const lastLevel = level[level.length - 1]
    const lastTrend = trend[trend.length - 1]
    const forecast: number[] = []

    for (let h = 1; h <= periodsToForecast; h++) {
      const seasonIdx = (n + h - 1) % period
      if (mode === 'additive') {
        forecast.push(lastLevel + lastTrend * h + seasonal[seasonIdx])
      } else {
        forecast.push(lastLevel * lastTrend ** h * seasonal[seasonIdx])
      }
    }

    // Accuracy
    const validFitted = fitted.filter((_, i) => i >= period)
    const correspondingActual = data.slice(period)
    const residuals = correspondingActual.map((v, i) => v - validFitted[i])
    const ci = buildConfidenceIntervals(residuals, periodsToForecast)

    return {
      forecast,
      fitted,
      confidenceLower: ci.lower,
      confidenceUpper: ci.upper,
      metrics: buildMetrics(correspondingActual, validFitted),
      level,
      trend,
      seasonal,
      alpha,
      beta,
      gamma,
    }
  }

  // ──────────────────────────────────────────────────────────────────────────────
  // Ensemble Forecast — Combines top-3 methods weighted by back-test accuracy
  // ──────────────────────────────────────────────────────────────────────────────

  static ensembleForecast(data: number[], periodsToForecast = 1, period = 4): ForecastResult {
    if (data.length < period * 2) {
      throw new Error(`Need at least ${period * 2} data points for ensemble, got ${data.length}`)
    }

    const splitIdx = Math.max(Math.floor(data.length * 0.8), period * 2)
    const train = data.slice(0, splitIdx)
    const test = data.slice(splitIdx)

    // Define candidate methods
    type CandidateMethod = {
      name: string
      forecast: (train: number[], horizon: number) => number[]
      fitted: (train: number[], full: number[]) => number[]
    }

    const candidates: CandidateMethod[] = [
      {
        name: 'LinearRegression',
        forecast: (t, h) => {
          const lr = ForecastMethodEngine.linearRegression(t, h)
          return lr.forecast
        },
        fitted: (t, full) => {
          const lr = ForecastMethodEngine.linearRegression(full, 0)
          return lr.forecast.length > 0 ? lr.forecast : full.map((_, i) => lr.predict(i))
        },
      },
      {
        name: 'SimpleMA',
        forecast: (t) => {
          const win = Math.min(Math.floor(t.length / 3), 12)
          return ForecastMethodEngine.simpleMovingAverage(t, Math.max(win, 2)).forecast
        },
        fitted: (t) => {
          const win = Math.min(Math.floor(t.length / 3), 12)
          return ForecastMethodEngine.simpleMovingAverage(t, Math.max(win, 2)).fitted
        },
      },
      {
        name: 'ExponentialSmoothing',
        forecast: (t) => ForecastMethodEngine.exponentialSmoothing(t, 0.3).forecast,
        fitted: (t) => ForecastMethodEngine.exponentialSmoothing(t, 0.3).fitted,
      },
      {
        name: 'HoltWinters',
        forecast: (t, h) => {
          try {
            return ForecastMethodEngine.holtWinters(t, 0.3, 0.1, 0.1, period, h).forecast
          } catch {
            return ForecastMethodEngine.exponentialSmoothing(t, 0.3).forecast
          }
        },
        fitted: (t) => {
          try {
            return ForecastMethodEngine.holtWinters(t, 0.3, 0.1, 0.1, period, 0).fitted
          } catch {
            return ForecastMethodEngine.exponentialSmoothing(t, 0.3).fitted
          }
        },
      },
      {
        name: 'WeightedMA',
        forecast: (t) => {
          const win = Math.min(Math.floor(t.length / 3), 8)
          const w = Array.from({ length: Math.max(win, 2) }, (_, i) => i + 1)
          return ForecastMethodEngine.weightedMovingAverage(t, w).forecast
        },
        fitted: (t) => {
          const win = Math.min(Math.floor(t.length / 3), 8)
          const w = Array.from({ length: Math.max(win, 2) }, (_, i) => i + 1)
          return ForecastMethodEngine.weightedMovingAverage(t, w).fitted
        },
      },
    ]

    // Back-test each method on the held-out portion
    const scores: { idx: number; rmse: number }[] = []

    for (let idx = 0; idx < candidates.length; idx++) {
      const method = candidates[idx]
      try {
        const testForecast = method.forecast(train, test.length)
        const rmse = calcRMSE(test, testForecast.slice(0, test.length))
        if (isFinite(rmse)) {
          scores.push({ idx, rmse })
        }
      } catch {
        // Method failed — skip
      }
    }

    if (scores.length === 0) {
      throw new Error('All candidate methods failed during back-testing')
    }

    // Sort by RMSE ascending, pick top 3
    scores.sort((a, b) => a.rmse - b.rmse)
    const top = scores.slice(0, 3)

    // Compute inverse-RMSE weights
    const invRmses = top.map((s) => 1 / (s.rmse + 1e-10))
    const weightSum = invRmses.reduce((a, b) => a + b, 0)
    const weights = invRmses.map((w) => w / weightSum)

    // Generate full-data forecasts from top methods and combine
    const forecasts: number[][] = []
    const fittedArrays: number[][] = []

    for (const { idx } of top) {
      const method = candidates[idx]
      forecasts.push(method.forecast(data, periodsToForecast))
      fittedArrays.push(method.fitted(data, data))
    }

    // Weighted ensemble
    const forecast: number[] = []
    for (let h = 0; h < periodsToForecast; h++) {
      let sum = 0
      for (let m = 0; m < top.length; m++) {
        sum += (forecasts[m][h] ?? forecasts[m][forecasts[m].length - 1]) * weights[m]
      }
      forecast.push(sum)
    }

    const fitted: number[] = []
    for (let i = 0; i < data.length; i++) {
      let sum = 0
      let validCount = 0
      for (let m = 0; m < top.length; m++) {
        const val = fittedArrays[m][i]
        if (val !== undefined && isFinite(val)) {
          sum += val * weights[m]
          validCount++
        }
      }
      fitted.push(
        validCount > 0
          ? sum /
              weights.slice(0, top.length).reduce((a, _, j) => {
                const val = fittedArrays[j][i]
                return val !== undefined && isFinite(val) ? a + weights[j] : a
              }, 0)
          : NaN
      )
    }

    // Compute residuals on valid fitted values
    const validPairs: { actual: number; predicted: number }[] = []
    for (let i = 0; i < data.length; i++) {
      if (isFinite(fitted[i])) {
        validPairs.push({ actual: data[i], predicted: fitted[i] })
      }
    }

    const residuals = validPairs.map((p) => p.actual - p.predicted)
    const ci = buildConfidenceIntervals(residuals, periodsToForecast)

    const actualArr = validPairs.map((p) => p.actual)
    const predictedArr = validPairs.map((p) => p.predicted)

    return {
      forecast,
      fitted,
      confidenceLower: ci.lower,
      confidenceUpper: ci.upper,
      metrics: buildMetrics(actualArr, predictedArr),
    }
  }

  // ──────────────────────────────────────────────────────────────────────────────
  // Utility: auto-select best single method via cross-validation
  // ──────────────────────────────────────────────────────────────────────────────

  static autoSelectBestMethod(
    data: number[],
    period = 4
  ): {
    methodName: string
    result: ForecastResult
  } {
    const methods: { name: string; run: () => ForecastResult }[] = [
      {
        name: 'LinearRegression',
        run: (): ForecastResult => {
          const lr = ForecastMethodEngine.linearRegression(data, 1)
          const ci = buildConfidenceIntervals(lr.residuals, lr.forecast.length)
          return {
            forecast: lr.forecast,
            fitted: Array.from({ length: data.length }, (_, i) => lr.predict(i)),
            confidenceLower: ci.lower,
            confidenceUpper: ci.upper,
            metrics: lr.metrics,
          }
        },
      },
      {
        name: 'ExponentialSmoothing',
        run: () => ForecastMethodEngine.exponentialSmoothing(data, 0.3),
      },
      {
        name: 'SimpleMovingAverage',
        run: () =>
          ForecastMethodEngine.simpleMovingAverage(
            data,
            Math.min(Math.max(Math.floor(data.length / 4), 2), 12)
          ),
      },
    ]

    if (data.length >= period * 2) {
      methods.push({
        name: 'HoltWinters',
        run: () => ForecastMethodEngine.holtWinters(data, 0.3, 0.1, 0.1, period),
      })
    }

    let best = { name: '', rmse: Infinity, result: null as unknown as ForecastResult }

    for (const method of methods) {
      try {
        const result = method.run()
        if (result.metrics.rmse < best.rmse) {
          best = { name: method.name, rmse: result.metrics.rmse, result }
        }
      } catch {
        // Skip failed methods
      }
    }

    if (!best.result) {
      throw new Error('All forecasting methods failed')
    }

    return { methodName: best.name, result: best.result }
  }
}

import { describe, it, expect } from 'vitest'
import { FormulaEngine } from './FormulaEngine'

describe('FormulaEngine', () => {
  // =========================================================================
  // PARSE FORMULA
  // =========================================================================
  describe('parseFormula', () => {
    describe('valid formulas', () => {
      it('should parse simple addition', () => {
        const result = FormulaEngine.parseFormula('1+2')
        expect(result.valid).toBe(true)
        expect(result.nodes).toHaveLength(1)
        expect(result.nodes[0].type).toBe('op')
        expect(result.nodes[0].value).toBe('+')
      })

      it('should parse simple subtraction', () => {
        const result = FormulaEngine.parseFormula('10-5')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].value).toBe('-')
      })

      it('should parse simple multiplication', () => {
        const result = FormulaEngine.parseFormula('3*4')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].value).toBe('*')
      })

      it('should parse simple division', () => {
        const result = FormulaEngine.parseFormula('10/2')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].value).toBe('/')
      })

      it('should handle leading equals sign', () => {
        const result = FormulaEngine.parseFormula('=1+1')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('op')
      })

      it('should parse empty string as valid', () => {
        const result = FormulaEngine.parseFormula('')
        expect(result.valid).toBe(true)
        expect(result.nodes).toEqual([])
      })

      it('should parse whitespace-only string as valid', () => {
        const result = FormulaEngine.parseFormula('   ')
        expect(result.valid).toBe(true)
        expect(result.nodes).toEqual([])
      })

      it('should parse cell references', () => {
        const result = FormulaEngine.parseFormula('A1')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('ref')
        expect(result.nodes[0].value).toBe('A1')
      })

      it('should parse multi-letter column references', () => {
        const result = FormulaEngine.parseFormula('AA1')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('ref')
        expect(result.nodes[0].value).toBe('AA1')
      })

      it('should parse underscore references', () => {
        const result = FormulaEngine.parseFormula('_var1')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('ref')
      })

      it('should parse floating point numbers', () => {
        const result = FormulaEngine.parseFormula('3.14')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('number')
        expect(result.nodes[0].value).toBe('3.14')
      })

      it('should parse numbers with multiple digits', () => {
        const result = FormulaEngine.parseFormula('12345.67')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].value).toBe('12345.67')
      })

      it('should parse function calls', () => {
        const result = FormulaEngine.parseFormula('SUM(A1:A5)')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('func')
        expect(result.nodes[0].value).toBe('SUM')
      })

      it('should parse function with multiple arguments', () => {
        const result = FormulaEngine.parseFormula('SUM(1,2,3)')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('func')
        expect(result.nodes[0].children).toHaveLength(3)
      })

      it('should parse function with no arguments', () => {
        const result = FormulaEngine.parseFormula('NOW()')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('func')
        expect(result.nodes[0].children).toHaveLength(0)
      })

      it('should parse range references', () => {
        const result = FormulaEngine.parseFormula('A1:B5')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('range')
        expect(result.nodes[0].value).toBe('A1:B5')
      })

      it('should parse nested parentheses', () => {
        const result = FormulaEngine.parseFormula('((1+2)*3)')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('op')
      })

      it('should parse deeply nested parentheses', () => {
        const result = FormulaEngine.parseFormula('(((1+2)*(3+4))/(5-1))')
        expect(result.valid).toBe(true)
      })

      it('should parse complex formula with mixed operations', () => {
        const result = FormulaEngine.parseFormula('A1+B2*C3-D4/E5')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('op')
      })

      it('should parse formula with function inside expression', () => {
        const result = FormulaEngine.parseFormula('SUM(A1:A5)+10')
        expect(result.valid).toBe(true)
      })

      it('should parse nested function calls', () => {
        const result = FormulaEngine.parseFormula('SUM(COUNT(A1:A5),B1)')
        expect(result.valid).toBe(true)
      })

      it('should parse IF function with literals', () => {
        const result = FormulaEngine.parseFormula('IF(1,100,200)')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('func')
        expect(result.nodes[0].value).toBe('IF')
        expect(result.nodes[0].children).toHaveLength(3)
      })

      it('should parse IF function with cell reference condition', () => {
        const result = FormulaEngine.parseFormula('IF(A1,100,200)')
        expect(result.valid).toBe(true)
      })

      it('should parse NPV function', () => {
        const result = FormulaEngine.parseFormula('NPV(0.1,100,200,300)')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].value).toBe('NPV')
      })

      it('should parse CAGR function', () => {
        const result = FormulaEngine.parseFormula('CAGR(150,100,3)')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].value).toBe('CAGR')
      })

      it('should parse comparison operators as op nodes', () => {
        // parseComparison handles >=, so A1>=B1 becomes an op node with children [A1, B1]
        const result = FormulaEngine.parseFormula('A1>=B1')
        expect(result.valid).toBe(true)
        expect(result.nodes[0].type).toBe('op')
        expect(result.nodes[0].value).toBe('>=')
        expect(result.nodes[0].children).toHaveLength(2)
      })
    })

    describe('invalid formulas', () => {
      it('should reject double operators', () => {
        const result = FormulaEngine.parseFormula('1++2')
        expect(result.valid).toBe(false)
        expect(result.error).toBeDefined()
      })

      it('should reject trailing operator', () => {
        const result = FormulaEngine.parseFormula('1+')
        expect(result.valid).toBe(false)
        expect(result.error).toBeDefined()
      })

      it('should reject unbalanced open parenthesis', () => {
        const result = FormulaEngine.parseFormula('(1+2')
        expect(result.valid).toBe(false)
        expect(result.error).toBeDefined()
      })

      it('should reject unbalanced close parenthesis', () => {
        const result = FormulaEngine.parseFormula('1+2)')
        // Actually, this might parse 1+2 and leave ) unconsumed
        // Let me check — parseExpression returns 1+2, then tokenizeAndParse returns [1+2]
        // The ) is left over but not checked
        // Actually the code just returns [parseExpression()] — no check for remaining tokens
        // So it might be valid
        // Let's test what actually happens
        const parsed = FormulaEngine.parseFormula('1+2)')
        // If valid, it parsed 1+2 and ignored the )
        if (parsed.valid) {
          expect(parsed.nodes).toHaveLength(1)
        } else {
          expect(parsed.valid).toBe(false)
        }
      })

      it('should reject lone operator', () => {
        const result = FormulaEngine.parseFormula('+')
        expect(result.valid).toBe(false)
        expect(result.error).toBeDefined()
      })
    })

    describe('edge cases', () => {
      it('should handle null input gracefully', () => {
        const result = FormulaEngine.parseFormula(null as unknown as string)
        expect(result.valid).toBe(false)
      })

      it('should handle undefined input gracefully', () => {
        const result = FormulaEngine.parseFormula(undefined as unknown as string)
        expect(result.valid).toBe(false)
      })

      it('should handle numeric zero input', () => {
        const result = FormulaEngine.parseFormula(0 as unknown as string)
        expect(result.valid).toBe(false)
      })

      it('should handle boolean input gracefully', () => {
        const result = FormulaEngine.parseFormula(true as unknown as string)
        expect(result.valid).toBe(false)
      })

      it('should handle object input gracefully', () => {
        const result = FormulaEngine.parseFormula({} as unknown as string)
        expect(result.valid).toBe(false)
      })

      it('should handle array input gracefully', () => {
        const result = FormulaEngine.parseFormula([] as unknown as string)
        expect(result.valid).toBe(false)
      })

      it('should trim whitespace before parsing', () => {
        const result = FormulaEngine.parseFormula('  1+2  ')
        expect(result.valid).toBe(true)
      })

      it('should handle formula with only equals sign', () => {
        const result = FormulaEngine.parseFormula('=')
        expect(result.valid).toBe(true)
        expect(result.nodes).toEqual([])
      })
    })
  })

  // =========================================================================
  // EVALUATE
  // =========================================================================
  describe('evaluate', () => {
    const mockGetCellValue = (ref: string): number => {
