        expect(result.value).toBe(105)
      })
    })

    describe('range evaluation', () => {
      it('should evaluate single-column range', () => {
        const rangeCellValue = (ref: string): number => {
          const values: Record<string, number> = { A1: 10, A2: 20, A3: 30 }
