import { describe, it, expect, beforeEach } from 'vitest'
import { ICMatchingEngine, type ICTransaction, type ToleranceSettings } from './ICMatchingEngine'

const makeSource = (overrides: Partial<ICTransaction> = {}): ICTransaction => ({
  id: 't1',
  entityId: 'E1',
  entityName: 'Entity 1',
  accountCode: '1000',
  accountName: 'IC Receivable',
  counterpartyEntityId: 'E2',
  amount: 1000,
  currency: 'USD',
  date: '2026-01-15',
  ...overrides,
})

const makeTarget = (overrides: Partial<ICTransaction> = {}): ICTransaction => ({
  id: 't2',
  entityId: 'E2',
  entityName: 'Entity 2',
  accountCode: '1000',
  accountName: 'IC Payable',
  counterpartyEntityId: 'E1',
  amount: -1000,
  currency: 'USD',
  date: '2026-01-15',
  ...overrides,
})

describe('ICMatchingEngine', () => {
  let engine: ICMatchingEngine

  beforeEach(() => {
    engine = new ICMatchingEngine()
  })

  it('should initialize with default tolerance', () => {
    expect(engine).toBeDefined()
  })

  it('should auto-match exact pairs', () => {
    const source = makeSource()
    const target = makeTarget()
    const pairs = engine.autoMatch([source], [target])
    expect(pairs.length).toBe(1)
    expect(pairs[0].status).toBe('matched')
    expect(pairs[0].amountDifference).toBe(0)
  })

  it('should auto-match partial pairs (amount difference)', () => {
    const source = makeSource({ amount: 1000 })
    const target = makeTarget({ amount: -990 })
    const pairs = engine.autoMatch([source], [target])
    expect(pairs.length).toBe(1)
    expect(pairs[0].amountDifference).toBe(10)
  })

  it('should not match when amounts are same sign', () => {
    const source = makeSource({ amount: 1000 })
    const target = makeTarget({ id: 't2', amount: 1000 })
    const pairs = engine.autoMatch([source], [target])
    expect(pairs.length).toBe(0)
  })

  it('should get match summary', () => {
    const source = makeSource()
    const target = makeTarget()
    engine.autoMatch([source], [target])
    const summary = engine.getSummary([source], [target])
    expect(summary.totalTransactions).toBe(2)
    expect(summary.matchedCount).toBeGreaterThanOrEqual(1)
  })

  it('should set tolerance settings', () => {
    engine.setTolerance({ amountTolerance: 100, percentageTolerance: 5, dateToleranceDays: 3 })
    // No assertion needed — just verify it doesn't throw
  })

  it('should manually match transactions', () => {
    const source = makeSource()
    const target = makeTarget({ amount: -990 })
    const pair = engine.manualMatch(source, target)
    expect(pair).toBeDefined()
    expect(pair.source.id).toBe('t1')
    expect(pair.target.id).toBe('t2')
    expect(pair.method).toBe('manual')
  })

  it('should get unmatched transactions', () => {
    const source = makeSource()
    const target = makeTarget()
    engine.autoMatch([source], [target])
    const unmatched = engine.getUnmatched([source, target])
    expect(unmatched.length).toBe(0) // both matched
  })

  it('should get unmatched when no matching', () => {
    const source = makeSource()
    const unmatched = engine.getUnmatched([source])
    expect(unmatched.length).toBe(1)
  })

  it('should unmatch a pair', () => {
    const source = makeSource()
    const target = makeTarget()
    engine.autoMatch([source], [target])
    // Get matches from autoMatch result, then unmatch
    const pairs = engine.autoMatch([source], [target])
    if (pairs.length > 0) {
      expect(engine.unmatch(pairs[0].id)).toBe(true)
    }
  })

  it('should generate elimination entries', () => {
    const source = makeSource()
    const target = makeTarget()
    const pairs = engine.autoMatch([source], [target])
    const eliminations = engine.generateEliminations(pairs, { '1000': 'IC Receivable' })
    expect(Array.isArray(eliminations)).toBe(true)
  })
})

import type { GLEntry } from '@/types/sector-types'
import type { ICPair, EliminationEntry } from './ConsolidationEngine'

// =============================================================================
// INTERCOMPANY MATCHING ENGINE
// Auto-detect, match, and reconcile IC transactions across entities
// =============================================================================

// --- Type Definitions ---

export type MatchStatus = 'matched' | 'partial' | 'unmatched'

export type MatchMethod = 'exact' | 'fuzzy_amount' | 'fuzzy_date' | 'manual'

export interface ICTransaction {
  id: string
  entityId: string
  entityName: string
  accountCode: string
  accountName: string
  counterpartyEntityId: string
  amount: number
  currency: string
  date: string
  description?: string
  reference?: string
}

export interface MatchPair {
  id: string
  source: ICTransaction
  target: ICTransaction
  status: MatchStatus
  method: MatchMethod
  amountDifference: number
  percentageDifference: number
  dateDifferenceDays: number
  confidence: number // 0-1
  matchedAt: string
  matchedBy: 'auto' | 'manual'
}

export interface ToleranceSettings {
  amountTolerance: number // absolute amount difference
  percentageTolerance: number // 0-100 percentage
  dateToleranceDays: number
}

export interface MatchSummary {
  totalTransactions: number
  matchedCount: number
  partiallyMatchedCount: number
  unmatchedCount: number
  matchedAmount: number
  partiallyMatchedAmount: number
  unmatchedAmount: number
  matchRate: number // 0-100
}

export interface ReconciliationLine {
  entityA: string
  entityB: string
  accountCode: string
  accountName: string
  balanceA: number
  balanceB: number
  difference: number
  percentageDifference: number
  withinTolerance: boolean
  matchStatus: MatchStatus
}

export interface ReconciliationReport {
  entityPairs: ReconciliationLine[]
  generatedAt: string
  period: string
  totalDifferences: number
  withinToleranceCount: number
  outsideToleranceCount: number
}

// --- Default Tolerance ---

const DEFAULT_TOLERANCE: ToleranceSettings = {
  amountTolerance: 100,
  percentageTolerance: 5,
  dateToleranceDays: 5,
}

// =============================================================================
// IC MATCHING ENGINE
// =============================================================================

export class ICMatchingEngine {
  private tolerance: ToleranceSettings
  private matches: MatchPair[] = []

  constructor(tolerance: Partial<ToleranceSettings> = {}) {
    this.tolerance = { ...DEFAULT_TOLERANCE, ...tolerance }
  }

  // ---------------------------------------------------------------------------
  // Auto-detect IC pairs from GL entries
  // ---------------------------------------------------------------------------
  static detectICTransactions(
    entries: GLEntry[],
    entityNames: Record<string, string>,
    tolerance: ToleranceSettings = DEFAULT_TOLERANCE
  ): ICTransaction[] {
    const transactions: ICTransaction[] = []
    const byAccount = new Map<string, GLEntry[]>()

    // Group by account code
    for (const entry of entries) {
      const key = entry.accountCode
      if (!byAccount.has(key)) byAccount.set(key, [])
      byAccount.get(key)!.push(entry)
    }

    // Find entries that reference other entities
    for (const entry of entries) {
      if (!entry.entityId) continue

      // Look for counterpart entries in other entities with same account
      const accountEntries = byAccount.get(entry.accountCode) ?? []
      for (const other of accountEntries) {
        if (!other.entityId || other.entityId === entry.entityId) continue

        // Check if amounts are roughly opposite (IC pattern)
        const amount = entry.amount ?? 0
        const otherAmount = other.amount ?? 0
        const isOpposite = Math.sign(amount) !== Math.sign(otherAmount)

        if (
          isOpposite &&
          Math.abs(Math.abs(amount) - Math.abs(otherAmount)) <= tolerance.amountTolerance
        ) {
          transactions.push({
            id: `ic-${entry.id}`,
            entityId: entry.entityId,
            entityName: entityNames[entry.entityId] ?? entry.entityId,
            accountCode: entry.accountCode,
            accountName: entry.accountName,
            counterpartyEntityId: other.entityId,
            amount,
            currency: entry.currency ?? '',
            date: entry.date,
            description: entry.description,
          })
        }
      }
    }

    // Deduplicate by entity+account+counterparty
    const seen = new Set<string>()
    return transactions.filter((t) => {
      const key = `${t.entityId}:${t.accountCode}:${t.counterpartyEntityId}`
      if (seen.has(key)) return false
      seen.add(key)
      return true
    })
  }

  // ---------------------------------------------------------------------------
  // Auto-match transactions across entities
  // ---------------------------------------------------------------------------
  autoMatch(sourceTransactions: ICTransaction[], targetTransactions: ICTransaction[]): MatchPair[] {
    const matches: MatchPair[] = []
    const usedTargets = new Set<string>()

    for (const source of sourceTransactions) {
      let bestMatch: { target: ICTransaction; score: number; method: MatchMethod } | null = null

      for (const target of targetTransactions) {
        if (usedTargets.has(target.id)) continue
        if (source.entityId === target.entityId) continue

        // Must be same account code
        if (source.accountCode !== target.accountCode) continue

        // Check if amounts are opposite
        const isOpposite = Math.sign(source.amount) !== Math.sign(target.amount)
        if (!isOpposite) continue

        const absSource = Math.abs(source.amount)
        const absTarget = Math.abs(target.amount)
        const amountDiff = Math.abs(absSource - absTarget)
        const pctDiff = absSource > 0 ? (amountDiff / absSource) * 100 : 0
        const dateDiff = Math.abs(
          Math.floor((new Date(source.date).getTime() - new Date(target.date).getTime()) / 86400000)
        )

        // Exact match
        if (
          amountDiff <= this.tolerance.amountTolerance &&
          pctDiff <= this.tolerance.percentageTolerance &&
          dateDiff <= this.tolerance.dateToleranceDays
        ) {
          const score = 1 - amountDiff / (absSource || 1) - dateDiff * 0.01
          if (!bestMatch || score > bestMatch.score) {
            bestMatch = { target, score: Math.max(0, score), method: 'exact' }
          }
        }
        // Fuzzy amount match
        else if (amountDiff <= this.tolerance.amountTolerance * 2) {
          const score = 0.5 - (amountDiff / (absSource || 1)) * 0.5
          if (!bestMatch || score > bestMatch.score) {
            bestMatch = { target, score: Math.max(0, score), method: 'fuzzy_amount' }
          }
        }
      }

      if (bestMatch) {
        const absSource = Math.abs(source.amount)
        const absTarget = Math.abs(bestMatch.target.amount)
        const amountDiff = Math.abs(absSource - absTarget)
        const pctDiff = absSource > 0 ? (amountDiff / absSource) * 100 : 0

        const status: MatchStatus = amountDiff === 0 ? 'matched' : 'partial'

        matches.push({
          id: `match-${source.id}-${bestMatch.target.id}`,
          source,
          target: bestMatch.target,
          status,
          method: bestMatch.method,
          amountDifference: amountDiff,
          percentageDifference: pctDiff,
          dateDifferenceDays: Math.abs(
            Math.floor(
              (new Date(source.date).getTime() - new Date(bestMatch.target.date).getTime()) /
                86400000
            )
          ),
          confidence: bestMatch.score,
          matchedAt: new Date().toISOString(),
          matchedBy: 'auto',
        })

        usedTargets.add(bestMatch.target.id)
      }
    }

    this.matches = matches
    return matches
  }

  // ---------------------------------------------------------------------------
  // Manual match two transactions
  // ---------------------------------------------------------------------------
  manualMatch(source: ICTransaction, target: ICTransaction): MatchPair {
    const absSource = Math.abs(source.amount)
    const absTarget = Math.abs(target.amount)
    const amountDiff = Math.abs(absSource - absTarget)
    const pctDiff = absSource > 0 ? (amountDiff / absSource) * 100 : 0
    const dateDiff = Math.abs(
      Math.floor((new Date(source.date).getTime() - new Date(target.date).getTime()) / 86400000)
    )

    const pair: MatchPair = {
      id: `match-manual-${source.id}-${target.id}`,
      source,
      target,
      status: amountDiff === 0 ? 'matched' : 'partial',
      method: 'manual',
      amountDifference: amountDiff,
      percentageDifference: pctDiff,
      dateDifferenceDays: dateDiff,
      confidence: 1,
      matchedAt: new Date().toISOString(),
      matchedBy: 'manual',
    }

    this.matches.push(pair)
    return pair
  }

  // ---------------------------------------------------------------------------
  // Unmatch a pair
  // ---------------------------------------------------------------------------
  unmatch(matchId: string): boolean {
    const idx = this.matches.findIndex((m) => m.id === matchId)
    if (idx === -1) return false
    this.matches.splice(idx, 1)
    return true
  }

  // ---------------------------------------------------------------------------
  // Get match summary statistics
  // ---------------------------------------------------------------------------
  getSummary(
    sourceTransactions: ICTransaction[],
    targetTransactions: ICTransaction[]
  ): MatchSummary {
    const matched = this.matches.filter((m) => m.status === 'matched')
    const partial = this.matches.filter((m) => m.status === 'partial')
    const total = sourceTransactions.length + targetTransactions.length
    const matchedIds = new Set(this.matches.flatMap((m) => [m.source.id, m.target.id]))
    const unmatchedCount = total - matchedIds.size

    return {
      totalTransactions: total,
      matchedCount: matched.length,
      partiallyMatchedCount: partial.length,
      unmatchedCount,
      matchedAmount: matched.reduce((s, m) => s + Math.abs(m.source.amount), 0),
      partiallyMatchedAmount: partial.reduce((s, m) => s + Math.abs(m.source.amount), 0),
      unmatchedAmount: 0, // computed from unmatched transactions
      matchRate: total > 0 ? (matchedIds.size / total) * 100 : 0,
    }
  }

  // ---------------------------------------------------------------------------
  // Get unmatched transactions
  // ---------------------------------------------------------------------------
  getUnmatched(allTransactions: ICTransaction[]): ICTransaction[] {
    const matchedIds = new Set(this.matches.flatMap((m) => [m.source.id, m.target.id]))
    return allTransactions.filter((t) => !matchedIds.has(t.id))
  }

  // ---------------------------------------------------------------------------
  // Generate reconciliation report
  // ---------------------------------------------------------------------------
  generateReconciliation(
    entities: { entityId: string; entityName: string; entries: GLEntry[] }[],
    period: string
  ): ReconciliationReport {
    const lines: ReconciliationLine[] = []
    const entityPairs = this.getEntityPairs(entities)

    for (const { entityA, entityB, accountCode, accountName } of entityPairs) {
      const entriesA = entities
        .find((e) => e.entityId === entityA)!
        .entries.filter((e) => e.accountCode === accountCode && e.entityId === entityA)
      const entriesB = entities
        .find((e) => e.entityId === entityB)!
        .entries.filter((e) => e.accountCode === accountCode && e.entityId === entityB)

      const balanceA = entriesA.reduce((s, e) => s + (e.amount ?? 0), 0)
      const balanceB = entriesB.reduce((s, e) => s + (e.amount ?? 0), 0)
      const diff = Math.abs(balanceA + balanceB) // IC should net to 0
      const pctDiff = Math.abs(balanceA) > 0 ? (diff / Math.abs(balanceA)) * 100 : 0
      const withinTolerance =
        diff <= this.tolerance.amountTolerance && pctDiff <= this.tolerance.percentageTolerance

      lines.push({
        entityA,
        entityB,
        accountCode,
        accountName,
        balanceA,
        balanceB,
        difference: diff,
        percentageDifference: pctDiff,
        withinTolerance,
        matchStatus: withinTolerance ? 'matched' : diff > 0 ? 'partial' : 'unmatched',
      })
    }

    return {
      entityPairs: lines,
      generatedAt: new Date().toISOString(),
      period,
      totalDifferences: lines.filter((l) => l.difference > 0).length,
      withinToleranceCount: lines.filter((l) => l.withinTolerance).length,
      outsideToleranceCount: lines.filter((l) => !l.withinTolerance && l.difference > 0).length,
    }
  }

  // ---------------------------------------------------------------------------
  // Generate elimination journal entries from matches
  // ---------------------------------------------------------------------------
  generateEliminations(
    matches: MatchPair[],
    accountNames: Record<string, string>
  ): EliminationEntry[] {
    const eliminations: EliminationEntry[] = []

    for (const match of matches) {
      if (match.status === 'unmatched') continue

      const sourceAmount = match.source.amount
      const elimAmount = Math.min(Math.abs(sourceAmount), Math.abs(match.target.amount))

      // Eliminate the receivable/payable
      eliminations.push({
        fromEntityId: match.source.entityId,
        toEntityId: match.target.entityId,
        accountCode: match.source.accountCode,
        accountName: accountNames[match.source.accountCode] ?? match.source.accountName,
        eliminatedAmount: elimAmount,
        debitAmount: sourceAmount > 0 ? elimAmount : 0,
        creditAmount: sourceAmount < 0 ? elimAmount : 0,
        description: `IC elimination: ${match.source.entityName} ↔ ${match.target.entityName}`,
        type: 'auto',
      })
    }

    return eliminations
  }

  // ---------------------------------------------------------------------------
  // Get current matches
  // ---------------------------------------------------------------------------
  getMatches(): MatchPair[] {
    return [...this.matches]
  }

  // ---------------------------------------------------------------------------
  // Update tolerance
  // ---------------------------------------------------------------------------
  setTolerance(tolerance: Partial<ToleranceSettings>): void {
    this.tolerance = { ...this.tolerance, ...tolerance }
  }

  getTolerance(): ToleranceSettings {
    return { ...this.tolerance }
  }

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------
  private getEntityPairs(
    entities: { entityId: string }[]
  ): { entityA: string; entityB: string; accountCode: string; accountName: string }[] {
    const pairs: {
      entityA: string
      entityB: string
      accountCode: string
      accountName: string
    }[] = []
    const seen = new Set<string>()

    for (const match of this.matches) {
      const key = [match.source.entityId, match.target.entityId].sort().join(':')
      const acctKey = `${key}:${match.source.accountCode}`
      if (seen.has(acctKey)) continue
      seen.add(acctKey)
      pairs.push({
        entityA: match.source.entityId,
        entityB: match.target.entityId,
        accountCode: match.source.accountCode,
        accountName: match.source.accountName,
      })
    }

    return pairs
  }
}

/**
 * IntercompanyMatchingEngine — Match and eliminate intercompany transactions
 * Critical for multi-entity consolidation (ASC 810)
 */

export interface ICTransaction {
  id: string
  fromEntity: string
  toEntity: string
  amount: number
  currency: string
  accountCode: string
  description: string
  date: string
  status: 'pending' | 'matched' | 'eliminated' | 'disputed'
}

export interface ICMatch {
  id: string
  debitTransaction: ICTransaction
  creditTransaction: ICTransaction
  matchedAmount: number
  variance: number
  tolerance: number
  status: 'auto_matched' | 'manual_matched' | 'unmatched' | 'disputed'
  matchedBy: string
  matchedAt: string
}

export interface ICElimination {
  id: string
  matchId: string
  eliminationAmount: number
  debitAccount: string
  creditAccount: string
  entityPair: [string, string]
  period: string
  createdBy: string
  createdAt: string
}

export class IntercompanyMatchingEngine {
  private static transactions: ICTransaction[] = []
  private static matches: ICMatch[] = []
  private static eliminations: ICElimination[] = []

  /**
   * Add IC transactions for matching
   */
  static addTransactions(transactions: ICTransaction[]): void {
    this.transactions.push(...transactions)
  }

  /**
   * Auto-match transactions by entity pair, amount, and date
   */
  static autoMatch(tolerance: number = 0.01): ICMatch[] {
    const pending = this.transactions.filter((t) => t.status === 'pending')
    const newMatches: ICMatch[] = []

    for (const debit of pending) {
      if (debit.status !== 'pending') continue

      // Find matching credit transaction
      const credit = pending.find(
        (c) =>
          c.id !== debit.id &&
          c.fromEntity === debit.toEntity &&
          c.toEntity === debit.fromEntity &&
          c.accountCode === debit.accountCode &&
          Math.abs(c.amount - debit.amount) <= tolerance * Math.max(c.amount, debit.amount) &&
          c.status === 'pending'
      )

      if (credit) {
        const match: ICMatch = {
          id: `icm-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
          debitTransaction: debit,
          creditTransaction: credit,
          matchedAmount: Math.min(debit.amount, credit.amount),
          variance: Math.abs(debit.amount - credit.amount),
          tolerance,
          status: 'auto_matched',
          matchedBy: 'system',
          matchedAt: new Date().toISOString(),
        }

        debit.status = 'matched'
        credit.status = 'matched'
        this.matches.push(match)
        newMatches.push(match)
      }
    }

    return newMatches
  }

  /**
   * Manual match two transactions
   */
  static manualMatch(debitId: string, creditId: string, userId: string): ICMatch | null {
    const debit = this.transactions.find((t) => t.id === debitId)
    const credit = this.transactions.find((t) => t.id === creditId)

    if (!debit || !credit) return null
    if (debit.status !== 'pending' || credit.status !== 'pending') return null

    const match: ICMatch = {
      id: `icm-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      debitTransaction: debit,
      creditTransaction: credit,
      matchedAmount: Math.min(debit.amount, credit.amount),
      variance: Math.abs(debit.amount - credit.amount),
      tolerance: 0,
      status: 'manual_matched',
      matchedBy: userId,
      matchedAt: new Date().toISOString(),
    }

    debit.status = 'matched'
    credit.status = 'matched'
    this.matches.push(match)
    return match
  }

  /**
   * Create elimination entries for matched pairs
   */
  static createEliminations(period: string, userId: string): ICElimination[] {
    const matched = this.matches.filter(
      (m) => m.status === 'auto_matched' || m.status === 'manual_matched'
    )

    const newEliminations: ICElimination[] = []

    for (const match of matched) {
      // Check if already eliminated
      if (this.eliminations.some((e) => e.matchId === match.id)) continue

      const elimination: ICElimination = {
        id: `ice-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        matchId: match.id,
        eliminationAmount: match.matchedAmount,
        debitAccount: match.creditTransaction.accountCode,
        creditAccount: match.debitTransaction.accountCode,
        entityPair: [match.debitTransaction.fromEntity, match.debitTransaction.toEntity],
        period,
        createdBy: userId,
        createdAt: new Date().toISOString(),
      }

      match.debitTransaction.status = 'eliminated'
      match.creditTransaction.status = 'eliminated'
      this.eliminations.push(elimination)
      newEliminations.push(elimination)
    }

    return newEliminations
  }

  /**
   * Get unmatched transactions
   */
  static getUnmatched(): ICTransaction[] {
    return this.transactions.filter((t) => t.status === 'pending')
  }

  /**
   * Get all matches
   */
  static getMatches(): ICMatch[] {
    return [...this.matches]
  }

  /**
   * Get all eliminations
   */
  static getEliminations(): ICElimination[] {
    return [...this.eliminations]
  }

  /**
   * Get summary by entity pair
   */
  static getSummaryByPair(): Map<
    string,
    {
      totalDebits: number
      totalCredits: number
      matched: number
      unmatched: number
      eliminated: number
    }
  > {
    const summary = new Map<
      string,
      ReturnType<typeof IntercompanyMatchingEngine.getSummaryByPair> extends Map<string, infer V>
        ? V
        : never
    >()

    for (const tx of this.transactions) {
      const key = [tx.fromEntity, tx.toEntity].sort().join('↔')
      const existing = summary.get(key) ?? {
        totalDebits: 0,
        totalCredits: 0,
        matched: 0,
        unmatched: 0,
        eliminated: 0,
      }

      if (tx.fromEntity < tx.toEntity) {
        existing.totalDebits += tx.amount
      } else {
        existing.totalCredits += tx.amount
      }

      if (tx.status === 'matched') existing.matched++
      if (tx.status === 'pending') existing.unmatched++
      if (tx.status === 'eliminated') existing.eliminated++

      summary.set(key, existing)
    }

    return summary
  }

  /**
   * Net intercompany balances between two entities
   * Returns net position: positive = entityA owes entityB, negative = entityB owes entityA
   */
  static netICBalances(
    entityA: string,
    entityB: string
  ): { netAmount: string; currency: string; transactions: ICTransaction[] } {
    const pairTransactions = this.transactions.filter(
      (t) =>
        (t.fromEntity === entityA && t.toEntity === entityB) ||
        (t.fromEntity === entityB && t.toEntity === entityA)
    )

    let netAmount = 0
    for (const tx of pairTransactions) {
      if (tx.fromEntity === entityA) {
        netAmount += tx.amount
      } else {
        netAmount -= tx.amount
      }
    }

    return {
      netAmount: netAmount.toFixed(2),
      currency: pairTransactions[0]?.currency ?? 'USD',
      transactions: pairTransactions,
    }
  }

  /**
   * Calculate intercompany interest on outstanding balances
   */
  static calculateICInterest(
    entityA: string,
    entityB: string,
    annualRate: number,
    days: number
  ): { interestAmount: number; principal: number; rate: number; days: number } {
    const { netAmount } = this.netICBalances(entityA, entityB)
    const principal = Math.abs(parseFloat(netAmount))
    const interestAmount = principal * (annualRate / 365) * days

    return {
      interestAmount: Math.round(interestAmount * 100) / 100,
      principal,
      rate: annualRate,
      days,
    }
  }

  /**
   * Eliminate intercompany profit on inventory/assets
   * Creates elimination entry for unrealized profit
   */
  static eliminateICProfit(
    sellerEntity: string,
    buyerEntity: string,
    profitAmount: number,
    accountCode: string,
    userId: string
  ): ICElimination {
    const elimination: ICElimination = {
      id: `ice-profit-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      matchId: 'profit-elimination',
      eliminationAmount: profitAmount,
      debitAccount: 'Cost of Goods Sold',
      creditAccount: accountCode,
      entityPair: [sellerEntity, buyerEntity].sort() as [string, string],
      period: new Date().toISOString().slice(0, 7),
      createdBy: userId,
      createdAt: new Date().toISOString(),
    }

    this.eliminations.push(elimination)
    return elimination
  }

  /**
   * Allocate minority interest in subsidiary earnings
   */
  static allocateMinorityInterest(
    totalEarnings: number,
    ownershipPercentage: number,
    parentEntity: string,
    subsidiaryEntity: string
  ): { parentShare: number; minorityShare: number; ownershipPct: number } {
    const parentShare = totalEarnings * (ownershipPercentage / 100)
    const minorityShare = totalEarnings - parentShare

    return {
      parentShare: Math.round(parentShare * 100) / 100,
      minorityShare: Math.round(minorityShare * 100) / 100,
      ownershipPct: ownershipPercentage,
    }
  }

  /**
   * Reconcile intercompany accounts across entities
   * Identifies discrepancies and generates reconciliation report
   */
  static reconcileICAccounts(
    accounts: Array<{ entityId: string; accountCode: string; balance: number }>
  ): {
    reconciled: boolean
    discrepancies: Array<{
      accountCode: string
      entityBalances: Record<string, number>
      variance: number
    }>
  } {
    const grouped = new Map<string, Array<{ entityId: string; balance: number }>>()

    for (const acc of accounts) {
      const existing = grouped.get(acc.accountCode) ?? []
      existing.push({ entityId: acc.entityId, balance: acc.balance })
      grouped.set(acc.accountCode, existing)
    }

    const discrepancies: Array<{
      accountCode: string
      entityBalances: Record<string, number>
      variance: number
    }> = []

    for (const [accountCode, entries] of grouped) {
      if (entries.length < 2) continue

      const entityBalances: Record<string, number> = {}
      for (const e of entries) {
        entityBalances[e.entityId] = e.balance
      }

      const netBalance = entries.reduce((sum, e) => sum + e.balance, 0)
      if (Math.abs(netBalance) > 0.01) {
        discrepancies.push({ accountCode, entityBalances, variance: netBalance })
      }
    }

    return { reconciled: discrepancies.length === 0, discrepancies }
  }

  /**
   * Generate intercompany transactions from templates
   */
  static generateICTransactions(
    entities: Array<{ id: string; name: string }>,
    template: { accountCode: string; description: string; baseAmount: number }
  ): ICTransaction[] {
    const transactions: ICTransaction[] = []

    for (let i = 0; i < entities.length; i++) {
      for (let j = i + 1; j < entities.length; j++) {
        const tx: ICTransaction = {
          id: `ictx-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
          fromEntity: entities[i].id,
          toEntity: entities[j].id,
          amount: template.baseAmount,
          currency: 'USD',
          accountCode: template.accountCode,
          description: `${template.description} - ${entities[i].name} → ${entities[j].name}`,
          date: new Date().toISOString().slice(0, 10),
          status: 'pending',
        }
        transactions.push(tx)
        this.transactions.push(tx)
      }
    }

    return transactions
  }

  /**
   * Match generated IC transactions with GL entries
   */
  static matchICTransactions(
    glEntries: Array<{ id: string; entityId: string; amount: number; accountCode: string }>
  ): Array<{ transaction: ICTransaction; glEntry: (typeof glEntries)[0]; confidence: number }> {
    const matches: Array<{
      transaction: ICTransaction
      glEntry: (typeof glEntries)[0]
      confidence: number
    }> = []
    const pending = this.transactions.filter((t) => t.status === 'pending')

    for (const tx of pending) {
      for (const gl of glEntries) {
        if (gl.entityId !== tx.fromEntity && gl.entityId !== tx.toEntity) continue

        const amountMatch = Math.abs(gl.amount - tx.amount) / Math.max(tx.amount, 1) < 0.01
        const accountMatch = gl.accountCode === tx.accountCode

        let confidence = 0
        if (amountMatch) confidence += 0.5
        if (accountMatch) confidence += 0.5

        if (confidence >= 0.5) {
          matches.push({ transaction: tx, glEntry: gl, confidence })
        }
      }
    }

    return matches.sort((a, b) => b.confidence - a.confidence)
  }

  /**
   * Validate intercompany balance — must net to zero across all entities
   */
  static validateICBalance(): {
    valid: boolean
    totalImbalance: number
    imbalances: Array<{ entity: string; netAmount: number }>
  } {
    const entityBalances = new Map<string, number>()

    for (const tx of this.transactions) {
      if (tx.status === 'eliminated') continue

      const fromBal = entityBalances.get(tx.fromEntity) ?? 0
      entityBalances.set(tx.fromEntity, fromBal - tx.amount)

      const toBal = entityBalances.get(tx.toEntity) ?? 0
      entityBalances.set(tx.toEntity, toBal + tx.amount)
    }

    const imbalances: Array<{ entity: string; netAmount: number }> = []
    let totalImbalance = 0

    for (const [entity, netAmount] of entityBalances) {
      if (Math.abs(netAmount) > 0.01) {
        imbalances.push({ entity, netAmount })
        totalImbalance += Math.abs(netAmount)
      }
    }

    return {
      valid: imbalances.length === 0,
      totalImbalance: Math.round(totalImbalance * 100) / 100,
      imbalances,
    }
  }

  /**
   * Clear all data (for testing)
   */
  static clear(): void {
    this.transactions = []
    this.matches = []
    this.eliminations = []
  }
}

import { describe, it, expect, beforeEach } from 'vitest'
import {
  buildDependencyGraph,
  detectCircularReferences,
  getCircularCells,
  solveIteratively,
  analyzeFormulas,
  DEFAULT_ITERATIVE_CONFIG,
  type IterativeConfig,
  type DependencyGraph,
  type CellValueAccessor,
} from './IterativeCalculationEngine'

describe('IterativeCalculationEngine', () => {
  it('should build dependency graph', () => {
    const formulas = new Map<string, string>([
      ['A1', '=B1+1'],
      ['B1', '=C1+2'],
      ['C1', '=10'],
    ])
    const getDeps = (formula: string) => {
      const matches = formula.match(/[A-Z]\d+/g)
      return matches ?? []
    }

    const graph = buildDependencyGraph(formulas, getDeps)
    expect(graph.dependencies.size).toBe(3)
    expect(graph.dependencies.get('A1')).toContain('B1')
    expect(graph.dependencies.get('B1')).toContain('C1')
  })

  it('should detect circular references', () => {
    const graph: DependencyGraph = {
      dependencies: new Map([
        ['A1', new Set(['B1'])],
        ['B1', new Set(['A1'])],
      ]),
    }

    const cycles = detectCircularReferences(graph)
    expect(cycles.length).toBeGreaterThan(0)
    expect(cycles[0].cells).toContain('A1')
    expect(cycles[0].cells).toContain('B1')
  })

  it('should detect no circular references in acyclic graph', () => {
    const graph: DependencyGraph = {
      dependencies: new Map([
        ['A1', new Set(['B1'])],
        ['B1', new Set(['C1'])],
        ['C1', new Set()],
      ]),
    }

    const cycles = detectCircularReferences(graph)
    expect(cycles.length).toBe(0)
  })

  it('should get circular cells from cycles', () => {
    const graph: DependencyGraph = {
      dependencies: new Map([
        ['A1', new Set(['B1'])],
        ['B1', new Set(['A1'])],
      ]),
    }

    const cycles = detectCircularReferences(graph)
    const cells = getCircularCells(cycles)
    expect(cells.size).toBe(2)
    expect(cells.has('A1')).toBe(true)
    expect(cells.has('B1')).toBe(true)
  })

  it('should analyze formulas for circular references', () => {
    const formulas = new Map<string, string>([
      ['A1', '=B1+1'],
      ['B1', '=A1+1'],
    ])
    const getDeps = (formula: string) => {
      const matches = formula.match(/[A-Z]\d+/g)
      return matches ?? []
    }

    const result = analyzeFormulas(formulas, getDeps)
    expect(result.hasCircular).toBe(true)
    expect(result.cycles.length).toBeGreaterThan(0)
    expect(result.circularCells.size).toBeGreaterThan(0)
  })

  it('should solve iteratively for convergent formulas', () => {
    const config: IterativeConfig = {
      maxIterations: 100,
      maxChange: 0.001,
      enableIterativeCalc: true,
    }
    const cellValues = new Map<string, number>([
      ['A1', 0],
      ['B1', 0],
    ])

    const accessor: CellValueAccessor = {
      getCellValue: (ref: string) => cellValues.get(ref) ?? 0,
      setCellValue: (ref: string, value: number) => {
        cellValues.set(ref, value)
      },
      recalcCell: (ref: string) => {
        if (ref === 'A1') {
          const val = (cellValues.get('B1') ?? 0) + 1
          cellValues.set('A1', val)
          return val
        } else {
          const val = (cellValues.get('A1') ?? 0) * 0.5
          cellValues.set('B1', val)
          return val
        }
      },
    }

    const circularCells = new Set(['A1', 'B1'])
    const result = solveIteratively(circularCells, accessor, config)
    expect(result.status).toBeDefined()
    expect(result.iterations).toBeGreaterThan(0)
  })

  it('should return not-started when iterative calc disabled', () => {
    const config: IterativeConfig = { ...DEFAULT_ITERATIVE_CONFIG, enableIterativeCalc: false }
    const circularCells = new Set(['A1'])

    const accessor: CellValueAccessor = {
      getCellValue: () => 0,
      setCellValue: () => {},
      recalcCell: () => 0,
    }

    const result = solveIteratively(circularCells, accessor, config)
    expect(result.status).toBe('not-started')
    expect(result.iterations).toBe(0)
  })
})

// Loan Amortization Engine — Full schedules, balloon payments, prepayment

export interface AmortizationRow {
  month: number
  payment: number
  principal: number
  interest: number
  balance: number
}

export interface AmortizationResult {
  schedule: AmortizationRow[]
  totalInterest: number
  totalPayment: number
  monthlyPayment: number
}

export class LoanAmortizationEngine {
  static monthlyPayment(principal: number, annualRate: number, months: number): number {
    if (annualRate === 0) return principal / months
    const r = annualRate / 12
    return (principal * r * Math.pow(1 + r, months)) / (Math.pow(1 + r, months) - 1)
  }

  static schedule(
    principal: number,
    annualRate: number,
    months: number,
    startDate?: string
  ): AmortizationResult {
    const pmt = this.monthlyPayment(principal, annualRate, months)
    const r = annualRate / 12
    const rows: AmortizationRow[] = []
    let balance = principal
    let totalInterest = 0

    for (let m = 1; m <= months; m++) {
      const interest = balance * r
      const principalPaid = pmt - interest
      balance = Math.max(0, balance - principalPaid)
      totalInterest += interest
      rows.push({ month: m, payment: pmt, principal: principalPaid, interest, balance })
    }

    return { schedule: rows, totalInterest, totalPayment: pmt * months, monthlyPayment: pmt }
  }

  static totalInterest(schedule: AmortizationRow[]): number {
    return schedule.reduce((sum, row) => sum + row.interest, 0)
  }

  static withPrepayment(
    schedule: AmortizationRow[],
    prepaymentAmount: number,
    month: number
  ): AmortizationRow[] {
    const result: AmortizationRow[] = []
    let balance = schedule[0].balance + schedule[0].principal
    for (const row of schedule) {
      if (row.month === month) {
        balance = Math.max(0, row.balance - prepaymentAmount)
      }
      if (row.month < month) {
        result.push({ ...row })
      } else {
        const interest = balance * (row.interest / row.balance || 0)
        const principalPaid = row.payment - interest
        balance = Math.max(0, balance - principalPaid)
        result.push({
          month: row.month,
          payment: row.payment,
          principal: principalPaid,
          interest,
          balance,
        })
      }
    }
    return result
  }

  static balloonPayment(
    principal: number,
    annualRate: number,
    months: number,
    balloonMonth: number
  ): AmortizationResult {
    const r = annualRate / 12
    const pmt = this.monthlyPayment(principal, annualRate, months)
    const rows: AmortizationRow[] = []
    let balance = principal
    let totalInterest = 0

    for (let m = 1; m <= balloonMonth; m++) {
      const interest = balance * r
      const principalPaid = pmt - interest
      balance = Math.max(0, balance - principalPaid)
      totalInterest += interest
      rows.push({
        month: m,
        payment: m === balloonMonth ? balance + interest : pmt,
        principal: m === balloonMonth ? balance : principalPaid,
        interest,
        balance: m === balloonMonth ? 0 : balance,
      })
    }

    return {
      schedule: rows,
      totalInterest,
      totalPayment: rows.reduce((s, r) => s + r.payment, 0),
      monthlyPayment: pmt,
    }
  }
}

import { describe, it, expect, beforeEach } from 'vitest'
import * as XLSX from 'xlsx'
