// =============================================================================
// MONTE CARLO SIMULATION ENGINE — Full-featured probabilistic analysis
// Integrates with ScenarioEngine for financial scenario generation
// Pure TypeScript, deterministic with seeded PRNG, testable
// =============================================================================

import type { ScenarioMetrics } from '@/types'
import { ScenarioEngine } from './ScenarioEngine'
import type { Distribution, ScenarioDriver } from './ScenarioEngine'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type DistributionType =
  | 'normal'
  | 'uniform'
  | 'triangular'
  | 'lognormal'
  | 'beta'
  | 'exponential'
  | 'poisson'

export interface DistributionConfig {
  readonly name: string
  readonly type: DistributionType
  /** Normal / Lognormal: mean of the distribution (or underlying normal for lognormal) */
  readonly mean?: number
  /** Normal / Lognormal: standard deviation */
  readonly stdDev?: number
  /** Uniform / Triangular: lower bound */
  readonly min?: number
  /** Uniform / Triangular: upper bound */
  readonly max?: number
  /** Triangular: mode (most likely value) */
  readonly mode?: number
  /** Beta: alpha shape parameter */
  readonly alpha?: number
  /** Beta: beta shape parameter */
  readonly betaParam?: number
  /** Exponential / Poisson: rate parameter */
  readonly lambda?: number
}

export interface MonteCarloConfig {
  /** Number of simulation iterations */
  readonly iterations: number
  /** Confidence level for intervals (e.g. 0.95 for 95%) */
  readonly confidenceLevel: number
  /** Distribution assumptions for each variable */
  readonly assumptions: DistributionConfig[]
  /** Model function: takes sampled values, returns a single output */
  readonly model: (samples: Record<string, number>) => number
  /** Optional seed for reproducible PRNG */
  readonly seed?: number
}

export interface ConfidenceInterval {
  readonly lower: number
  readonly upper: number
  readonly level: number
}

export interface HistogramBin {
  readonly lower: number
  readonly upper: number
  readonly count: number
  readonly density: number
}

export interface MonteCarloResult {
  readonly iterations: number
  readonly mean: number
  readonly median: number
  readonly stdDev: number
  readonly variance: number
  readonly min: number
  readonly max: number
  readonly skewness: number
  readonly kurtosis: number
  readonly percentiles: Record<number, number>
  readonly confidenceInterval: ConfidenceInterval
  readonly histogram: HistogramBin[]
  readonly values: readonly number[]
  readonly rawSamples: ReadonlyArray<Record<string, number>>
}

export interface MonteCarloDriver {
  readonly name: string
  readonly distribution: DistributionConfig
  /** Which ScenarioMetric this driver affects */
  readonly targetMetric: keyof ScenarioMetrics
  /** Whether the distribution value is a percentage change or absolute value */
  readonly impactType: 'percentage' | 'absolute'
}

export interface ScenarioMonteCarloConfig {
  /** Base financial metrics to simulate around */
  readonly baseMetrics: ScenarioMetrics
  /** Drivers that define how variables affect the base metrics */
  readonly drivers: MonteCarloDriver[]
  /** Number of simulation iterations */
  readonly iterations: number
  /** Confidence level for intervals */
  readonly confidenceLevel: number
  /** Optional seed for reproducibility */
  readonly seed?: number
}

export interface ScenarioMonteCarloResult {
  readonly iterations: number
  /** Per-metric simulation results */
  readonly metrics: Record<keyof ScenarioMetrics, MonteCarloResult>
  /** Overall net income distribution */
  readonly netIncome: MonteCarloResult
  /** Probability of profit (net income > 0) */
  readonly probabilityOfProfit: number
  /** Value at Risk at the given confidence level */
  readonly valueAtRisk: number
  /** Conditional Value at Risk (expected shortfall) */
  readonly conditionalValueAtRisk: number
}

// ---------------------------------------------------------------------------
// Seeded PRNG (Mulberry32)
// ---------------------------------------------------------------------------

function createPRNG(seed: number): () => number {
  let state = seed | 0
  return () => {
    state = (state + 0x6d2b79f5) | 0
    let t = Math.imul(state ^ (state >>> 15), 1 | state)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

// ---------------------------------------------------------------------------
// Distribution Sampling
// ---------------------------------------------------------------------------

function sampleDistribution(config: DistributionConfig, randomFn: () => number): number {
  switch (config.type) {
    case 'normal': {
      // Box-Muller transform
      const u1 = randomFn()
      const u2 = randomFn()
      const z0 = Math.sqrt(-2.0 * Math.log(u1)) * Math.cos(2.0 * Math.PI * u2)
      return (config.mean ?? 0) + z0 * (config.stdDev ?? 1)
    }
    case 'uniform': {
      const min = config.min ?? 0
      const max = config.max ?? 1
      return min + randomFn() * (max - min)
    }
    case 'triangular': {
      const a = config.min ?? 0
      const b = config.max ?? 1
      const c = config.mode ?? 0.5
      const fc = (c - a) / (b - a)
      const r = randomFn()
      if (r < fc) return a + Math.sqrt(r * (b - a) * (c - a))
      return b - Math.sqrt((1 - r) * (b - a) * (b - c))
    }
    case 'lognormal': {
      // Sample from underlying normal, exponentiate
      const mu = config.mean ?? 0
      const sigma = config.stdDev ?? 1
      const u1 = randomFn()
      const u2 = randomFn()
      const z0 = Math.sqrt(-2.0 * Math.log(u1)) * Math.cos(2.0 * Math.PI * u2)
      return Math.exp(mu + z0 * sigma)
    }
    case 'beta': {
      // Johnk's algorithm using gamma variates
      const a = config.alpha ?? 2
      const b = config.betaParam ?? 5
      const ga = sampleGamma(a, randomFn)
      const gb = sampleGamma(b, randomFn)
      return ga / (ga + gb)
    }
    case 'exponential': {
      const lambda = config.lambda ?? 1
      const u = randomFn()
      return -Math.log(1 - u) / lambda
    }
    case 'poisson': {
      // Knuth's algorithm
      const lambda = config.lambda ?? 1
      const limit = Math.exp(-lambda)
      let k = 0
      let p = 1
      do {
        k++
        p *= randomFn()
      } while (p > limit)
      return k - 1
    }
    default:
      return config.mean ?? 0
  }
}

/** Sample from Gamma(shape, 1) using Marsaglia and Tsang's method */
function sampleGamma(shape: number, randomFn: () => number): number {
  if (shape < 1) {
    // For shape < 1, use the relation: Gamma(a) = Gamma(a+1) * U^(1/a)
    return sampleGamma(shape + 1, randomFn) * Math.pow(randomFn(), 1 / shape)
  }

  const d = shape - 1 / 3
  const c = 1 / Math.sqrt(9 * d)

  while (true) {
    let x: number
    let v: number
    do {
      // Box-Muller for normal variate
      const u1 = randomFn()
      const u2 = randomFn()
      x = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2)
      v = 1 + c * x
    } while (v <= 0)

    v = v * v * v
    const u = randomFn()

    if (u < 1 - 0.0331 * x * x * x * x) return d * v
    if (Math.log(u) < 0.5 * x * x + d * (1 - v + Math.log(v))) return d * v
  }
}

// ---------------------------------------------------------------------------
// Statistical Utilities
// ---------------------------------------------------------------------------

function computeMean(values: readonly number[]): number {
  if (values.length === 0) return 0
  let sum = 0
  for (const v of values) sum += v
  return sum / values.length
}

function computeVariance(values: readonly number[], mean: number): number {
  if (values.length < 2) return 0
  let sumSq = 0
  for (const v of values) {
    const diff = v - mean
    sumSq += diff * diff
  }
  return sumSq / (values.length - 1)
}

function computeStdDev(variance: number): number {
  return Math.sqrt(variance)
}

function computeMedian(sorted: readonly number[]): number {
  const n = sorted.length
  if (n === 0) return 0
  if (n % 2 === 1) return sorted[(n - 1) / 2]
  return (sorted[n / 2 - 1] + sorted[n / 2]) / 2
}

function computePercentile(sorted: readonly number[], p: number): number {
  if (sorted.length === 0) return 0
  if (p <= 0) return sorted[0]
  if (p >= 100) return sorted[sorted.length - 1]
  const index = (p / 100) * (sorted.length - 1)
  const lower = Math.floor(index)
  const upper = Math.ceil(index)
  if (lower === upper) return sorted[lower]
  const fraction = index - lower
  return sorted[lower] * (1 - fraction) + sorted[upper] * fraction
}

function computeSkewness(values: readonly number[], mean: number, stdDev: number): number {
  if (values.length < 3 || stdDev === 0) return 0
  let sumCubed = 0
  for (const v of values) {
    sumCubed += Math.pow((v - mean) / stdDev, 3)
  }
  return sumCubed / values.length
}

function computeKurtosis(values: readonly number[], mean: number, stdDev: number): number {
  if (values.length < 4 || stdDev === 0) return 0
  let sumFourth = 0
  for (const v of values) {
    sumFourth += Math.pow((v - mean) / stdDev, 4)
  }
  return sumFourth / values.length - 3 // excess kurtosis
}

function computeHistogram(values: readonly number[], bins: number = 30): HistogramBin[] {
  if (values.length === 0) return []

  const min = Math.min(...values)
  const max = Math.max(...values)
  if (min === max) {
    return [{ lower: min, upper: max, count: values.length, density: 1 }]
  }

  const binWidth = (max - min) / bins
  const histogram: HistogramBin[] = []

  for (let i = 0; i < bins; i++) {
    const lower = min + i * binWidth
    const upper = min + (i + 1) * binWidth
    const count = values.filter((v) =>
      i === bins - 1 ? v >= lower && v <= upper : v >= lower && v < upper
    ).length
    histogram.push({
      lower,
      upper,
      count,
      density: count / (values.length * binWidth),
    })
  }

  return histogram
}

// ---------------------------------------------------------------------------
// MonteCarloEngine
// ---------------------------------------------------------------------------

export class MonteCarloEngine {
  /**
   * Run a general-purpose Monte Carlo simulation.
   *
   * @param config - Simulation configuration
   * @returns Full statistical results including confidence intervals and histogram
   */
  static simulate(config: MonteCarloConfig): MonteCarloResult {
    // --- Validation ---
    if (!config || typeof config !== 'object') {
      throw new Error('config must be an object')
    }
    if (!Array.isArray(config.assumptions)) {
      throw new Error('assumptions must be an array')
    }
    if (typeof config.iterations !== 'number' || !Number.isFinite(config.iterations)) {
      throw new Error('iterations must be a finite number')
    }
    if (config.iterations < 1) {
      throw new Error('iterations must be at least 1')
    }
    if (config.iterations > 1_000_000) {
      throw new Error('iterations cannot exceed 1,000,000')
    }
    if (
      typeof config.confidenceLevel !== 'number' ||
      config.confidenceLevel <= 0 ||
      config.confidenceLevel >= 1
    ) {
      throw new Error('confidenceLevel must be between 0 and 1 (exclusive)')
    }
    if (typeof config.model !== 'function') {
      throw new Error('model must be a function')
    }

    // Validate each distribution config
    for (const assumption of config.assumptions) {
      MonteCarloEngine.validateDistribution(assumption)
    }

    // --- Setup PRNG ---
    const randomFn = config.seed !== undefined ? createPRNG(config.seed) : Math.random

    // --- Run simulation ---
    const values: number[] = []
    const rawSamples: Record<string, number>[] = []

    for (let i = 0; i < config.iterations; i++) {
      const samples: Record<string, number> = {}
      for (const assumption of config.assumptions) {
        samples[assumption.name] = sampleDistribution(assumption, randomFn)
      }
      const output = config.model(samples)
      if (!Number.isFinite(output)) {
        throw new Error(`Model returned non-finite value at iteration ${i + 1}: ${output}`)
      }
      values.push(output)
      rawSamples.push(samples)
    }

    // --- Compute statistics ---
    return MonteCarloEngine.computeStatistics(
      values,
      rawSamples,
      config.iterations,
      config.confidenceLevel
    )
  }

  /**
   * Run a Monte Carlo simulation on financial ScenarioMetrics.
   * Each driver specifies a distribution and which metric it affects.
   *
   * @param config - Scenario simulation configuration
   * @returns Per-metric distributions, probability of profit, VaR, and CVaR
   */
  static simulateScenario(config: ScenarioMonteCarloConfig): ScenarioMonteCarloResult {
    // --- Validation ---
    if (!config || typeof config !== 'object') {
      throw new Error('config must be an object')
    }
    if (!config.baseMetrics || typeof config.baseMetrics !== 'object') {
      throw new Error('baseMetrics must be an object')
    }
    if (!Array.isArray(config.drivers)) {
      throw new Error('drivers must be an array')
    }
    if (config.drivers.length === 0) {
      throw new Error('drivers must not be empty')
    }
    if (typeof config.iterations !== 'number' || config.iterations < 1) {
      throw new Error('iterations must be at least 1')
    }
    if (config.iterations > 1_000_000) {
      throw new Error('iterations cannot exceed 1,000,000')
    }

    const validMetrics: (keyof ScenarioMetrics)[] = [
      'revenue',
      'ebitda',
      'netIncome',
      'cashFlow',
      'headcount',
      'burnRate',
      'runway',
      'grossMargin',
      'ebitdaMargin',
    ]

    for (const driver of config.drivers) {
      if (!driver.name || typeof driver.name !== 'string') {
        throw new Error('Each driver must have a non-empty name')
      }
      MonteCarloEngine.validateDistribution(driver.distribution)
      if (!validMetrics.includes(driver.targetMetric)) {
        throw new Error(
          `targetMetric "${driver.targetMetric}" must be one of: ${validMetrics.join(', ')}`
        )
      }
      if (!['percentage', 'absolute'].includes(driver.impactType)) {
        throw new Error('impactType must be "percentage" or "absolute"')
      }
    }

    // --- Setup PRNG ---
    const randomFn = config.seed !== undefined ? createPRNG(config.seed) : Math.random

    // --- Build per-metric value arrays ---
    const metricValues: Record<keyof ScenarioMetrics, number[]> = {
      revenue: [],
      ebitda: [],
      netIncome: [],
      cashFlow: [],
      headcount: [],
      burnRate: [],
      runway: [],
      grossMargin: [],
      ebitdaMargin: [],
    }

    for (let i = 0; i < config.iterations; i++) {
      // Start with base metrics
      const metrics: ScenarioMetrics = { ...config.baseMetrics }

      // Apply each driver's sampled value
      for (const driver of config.drivers) {
        const sample = sampleDistribution(driver.distribution, randomFn)
        const base = config.baseMetrics[driver.targetMetric]

        if (driver.impactType === 'percentage') {
          ;(metrics as unknown as Record<string, number>)[driver.targetMetric] =
            base * (1 + sample / 100)
        } else {
          ;(metrics as unknown as Record<string, number>)[driver.targetMetric] = base + sample
        }
      }

      // Recalculate derived metrics
      ;(metrics as unknown as Record<string, number>).netIncome = metrics.ebitda
      ;(metrics as unknown as Record<string, number>).ebitdaMargin =
        metrics.revenue !== 0 ? (metrics.ebitda / metrics.revenue) * 100 : 0

      // Store values
      for (const key of validMetrics) {
        metricValues[key].push(metrics[key])
      }
    }

    // --- Compute per-metric statistics ---
    const metricResults = {} as Record<keyof ScenarioMetrics, MonteCarloResult>
    for (const key of validMetrics) {
      const sorted = [...metricValues[key]].sort((a, b) => a - b)
      metricResults[key] = MonteCarloEngine.computeStatistics(
        metricValues[key],
        [],
        config.iterations,
        config.confidenceLevel
      )
    }

    // --- Compute risk metrics from net income distribution ---
    const niSorted = [...metricValues.netIncome].sort((a, b) => a - b)
    const niMean = computeMean(metricValues.netIncome)
    const niStdDev = computeStdDev(computeVariance(metricValues.netIncome, niMean))

    // Probability of profit
    const profitCount = metricValues.netIncome.filter((v) => v > 0).length
    const probabilityOfProfit = profitCount / config.iterations

    // Value at Risk (loss at the confidence level)
    const alpha = 1 - config.confidenceLevel
    const varIndex = Math.floor(alpha * niSorted.length)
    const valueAtRisk = -niSorted[Math.min(varIndex, niSorted.length - 1)]

    // Conditional VaR (expected shortfall)
    const tailValues = niSorted.slice(0, varIndex + 1)
    const conditionalValueAtRisk = tailValues.length > 0 ? -computeMean(tailValues) : 0

    return {
      iterations: config.iterations,
      metrics: metricResults,
      netIncome: metricResults.netIncome,
      probabilityOfProfit,
      valueAtRisk,
      conditionalValueAtRisk,
    }
  }

  /**
   * Generate correlation-adjusted samples.
   * Uses Cholesky decomposition of a correlation matrix.
   *
   * @param distributions - Array of distribution configs
   * @param correlationMatrix - Lower-triangular correlation matrix (must be positive semi-definite)
   * @param iterations - Number of samples to generate
   * @param seed - Optional seed for reproducibility
   * @returns Array of correlated sample records
   */
  static generateCorrelatedSamples(
    distributions: DistributionConfig[],
    correlationMatrix: number[][],
    iterations: number,
    seed?: number
  ): ReadonlyArray<Record<string, number>> {
    const n = distributions.length

    if (correlationMatrix.length !== n) {
      throw new Error('correlationMatrix rows must match distributions length')
    }
    for (const row of correlationMatrix) {
      if (row.length !== n) {
        throw new Error('correlationMatrix must be square')
      }
    }

    // Cholesky decomposition
    const L: number[][] = Array.from({ length: n }, () => Array(n).fill(0))
    for (let i = 0; i < n; i++) {
      for (let j = 0; j <= i; j++) {
        let sum = 0
        for (let k = 0; k < j; k++) {
          sum += L[i][k] * L[j][k]
        }
        if (i === j) {
          const val = correlationMatrix[i][i] - sum
          L[i][j] = val > 0 ? Math.sqrt(val) : 0
        } else {
          L[i][j] = L[j][j] !== 0 ? (correlationMatrix[i][j] - sum) / L[j][j] : 0
        }
      }
    }

    const randomFn = seed !== undefined ? createPRNG(seed) : Math.random
    const results: Record<string, number>[] = []

    for (let iter = 0; iter < iterations; iter++) {
      // Generate independent standard normals via Box-Muller
      const independents: number[] = []
      for (let i = 0; i < n; i++) {
        const u1 = randomFn()
        const u2 = randomFn()
        independents.push(Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2))
      }

      // Apply Cholesky to get correlated normals
      const correlated: number[] = []
      for (let i = 0; i < n; i++) {
        let sum = 0
        for (let j = 0; j <= i; j++) {
          sum += L[i][j] * independents[j]
        }
        correlated.push(sum)
      }

      // Transform to target distributions using inverse CDF (percent-point function)
      const sample: Record<string, number> = {}
      for (let i = 0; i < n; i++) {
        const dist = distributions[i]
        const u = 0.5 * (1 + erf(correlated[i] / Math.sqrt(2))) // normal CDF
        sample[dist.name] = inverseCDF(dist, u, randomFn)
      }

      results.push(sample)
    }

    return results
  }

  /**
   * Create a reusable simulation runner for a given configuration.
   * Useful for running multiple simulations with the same setup but different seeds.
   */
  static createRunner(config: Omit<MonteCarloConfig, 'seed'>): {
    run: (seed?: number) => MonteCarloResult
  } {
    return {
      run: (seed?: number) => MonteCarloEngine.simulate({ ...config, seed }),
    }
  }

  // ---------------------------------------------------------------------------
  // Internal helpers
  // ---------------------------------------------------------------------------

  /** Validate a distribution configuration */
  static validateDistribution(config: DistributionConfig): void {
    if (!config.name || typeof config.name !== 'string') {
      throw new Error('Each distribution must have a non-empty name')
    }
    const validTypes: DistributionType[] = [
      'normal',
      'uniform',
      'triangular',
      'lognormal',
      'beta',
      'exponential',
      'poisson',
    ]
    if (!validTypes.includes(config.type)) {
      throw new Error(`Distribution "${config.name}" type must be one of: ${validTypes.join(', ')}`)
    }

    switch (config.type) {
      case 'normal':
      case 'lognormal':
        if (config.mean !== undefined && !Number.isFinite(config.mean)) {
          throw new Error(`Distribution "${config.name}" mean must be finite`)
        }
        if (
          config.stdDev !== undefined &&
          (typeof config.stdDev !== 'number' || config.stdDev < 0)
        ) {
          throw new Error(`Distribution "${config.name}" stdDev must be non-negative`)
        }
        break
      case 'uniform':
        if (typeof config.min !== 'number' || typeof config.max !== 'number') {
          throw new Error(`Distribution "${config.name}" must have min and max`)
        }
        if (config.min >= config.max) {
          throw new Error(`Distribution "${config.name}" min must be less than max`)
        }
        break
      case 'triangular':
        if (typeof config.min !== 'number' || typeof config.max !== 'number') {
          throw new Error(`Distribution "${config.name}" must have min and max`)
        }
        if (config.min >= config.max) {
          throw new Error(`Distribution "${config.name}" min must be less than max`)
        }
        break
      case 'beta':
        if (typeof config.alpha !== 'number' || config.alpha <= 0) {
          throw new Error(`Distribution "${config.name}" alpha must be positive`)
        }
        if (typeof config.betaParam !== 'number' || config.betaParam <= 0) {
          throw new Error(`Distribution "${config.name}" betaParam must be positive`)
        }
        break
      case 'exponential':
      case 'poisson':
        if (typeof config.lambda !== 'number' || config.lambda <= 0) {
          throw new Error(`Distribution "${config.name}" lambda must be positive`)
        }
        break
    }
  }

  /** Compute full statistics from a values array */
  static computeStatistics(
    values: number[],
    rawSamples: Record<string, number>[],
    iterations: number,
    confidenceLevel: number
  ): MonteCarloResult {
    const sorted = [...values].sort((a, b) => a - b)
    const mean = computeMean(values)
    const variance = computeVariance(values, mean)
    const stdDev = computeStdDev(variance)
    const median = computeMedian(sorted)
    const skewness = computeSkewness(values, mean, stdDev)
    const kurtosis = computeKurtosis(values, mean, stdDev)

    // Percentiles
    const percentileLevels = [1, 5, 10, 25, 50, 75, 90, 95, 99]
    const percentiles: Record<number, number> = {}
    for (const p of percentileLevels) {
      percentiles[p] = computePercentile(sorted, p)
    }

    // Confidence interval
    const alpha = (1 - confidenceLevel) / 2
    const lowerPct = alpha * 100
    const upperPct = (1 - alpha) * 100
    const confidenceInterval: ConfidenceInterval = {
      lower: computePercentile(sorted, lowerPct),
      upper: computePercentile(sorted, upperPct),
      level: confidenceLevel,
    }

    // Histogram
    const histogram = computeHistogram(values, 30)

    return {
      iterations,
      mean,
      median,
      stdDev,
      variance,
      min: sorted[0],
      max: sorted[sorted.length - 1],
      skewness,
      kurtosis,
      percentiles,
      confidenceInterval,
      histogram,
      values,
      rawSamples,
    }
  }
}

// ---------------------------------------------------------------------------
// Error function (erf) approximation for correlated sampling
// ---------------------------------------------------------------------------

function erf(x: number): number {
  const sign = x >= 0 ? 1 : -1
  const absX = Math.abs(x)

  // Abramowitz and Stegun approximation 7.1.26
  const a1 = 0.254829592
  const a2 = -0.284496736
  const a3 = 1.421413741
  const a4 = -1.453152027
  const a5 = 1.061405429
  const p = 0.3275911

  const t = 1 / (1 + p * absX)
  const y = 1 - ((((a5 * t + a4) * t + a3) * t + a2) * t + a1) * t * Math.exp(-absX * absX)

  return sign * y
}

/** Inverse CDF: transform uniform [0,1] to target distribution */
function inverseCDF(config: DistributionConfig, u: number, randomFn: () => number): number {
  switch (config.type) {
    case 'normal': {
      // Inverse normal CDF approximation (rational)
      const z = inverseNormalCDF(u)
      return (config.mean ?? 0) + z * (config.stdDev ?? 1)
    }
    case 'uniform':
      return (config.min ?? 0) + u * ((config.max ?? 1) - (config.min ?? 0))
    case 'triangular': {
      const a = config.min ?? 0
      const b = config.max ?? 1
      const c = config.mode ?? 0.5
      const fc = (c - a) / (b - a)
      if (u < fc) return a + Math.sqrt(u * (b - a) * (c - a))
      return b - Math.sqrt((1 - u) * (b - a) * (b - c))
    }
    case 'lognormal': {
      const z = inverseNormalCDF(u)
      return Math.exp((config.mean ?? 0) + z * (config.stdDev ?? 1))
    }
    case 'beta':
    case 'exponential':
    case 'poisson':
      // For these, fall back to direct sampling (inverse CDF is complex)
      return sampleDistribution(config, randomFn)
    default:
      return config.mean ?? 0
  }
}

/** Approximate inverse normal CDF (Beasley-Springer-Moro) */
function inverseNormalCDF(p: number): number {
  if (p <= 0) return -Infinity
  if (p >= 1) return Infinity
  if (p === 0.5) return 0

  const a = [
    -3.969683028665376e1, 2.209460984245205e2, -2.759285104469687e2, 1.38357751867269e2,
    -3.066479806614716e1, 2.506628277459239,
  ]
  const b = [
    -5.447609879822406e1, 1.615858368580409e2, -1.556989798598866e2, 6.680131188771972e1,
    -1.328068155288572e1,
  ]
  const c = [
    -7.784894002430293e-3, -3.223964580411365e-1, -2.400758277161838, -2.549732539343734,
    4.374664141464968, 2.938163982698783,
  ]
  const d = [7.784695709041462e-3, 3.224671290700398e-1, 2.445134137142996, 3.754408661907416]

  const pLow = 0.02425
  const pHigh = 1 - pLow
  let q: number
  let r: number

  if (p < pLow) {
    q = Math.sqrt(-2 * Math.log(p))
    return (
      (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
      ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
    )
  } else if (p <= pHigh) {
    q = p - 0.5
    r = q * q
    return (
      ((((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q) /
      (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1)
    )
  } else {
    q = Math.sqrt(-2 * Math.log(1 - p))
    return (
      -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
      ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
    )
  }
}

/**
 * MultiBookEngine — Multi-book accounting for GAAP, IFRS, Tax
 * Manages parallel accounting books with cross-book consolidation
 */

export interface AccountingBook {
  id: string
  name: string
  gaap: 'us-gaap' | 'ifrs' | 'tax' | 'statutory' | 'custom'
  currency: string
  entityId: string
  createdAt: string
  closedPeriods: string[]
  status: 'active' | 'closed' | 'archived'
}

export interface BookEntry {
  id: string
  bookId: string
  accountId: string
  debit: number
  credit: number
  description: string
  period: string
  date: string
  userId: string
  adjusted: boolean
  adjustmentOf?: string
  metadata?: Record<string, unknown>
}

export interface ConsolidatedEntry {
  accountId: string
  books: Array<{ bookId: string; bookName: string; debit: number; credit: number }>
  totalDebit: number
  totalCredit: number
  netAmount: number
  gaapDifferences: Array<{ account: string; gaap1: number; gaap2: number; difference: number }>
}

export class MultiBookEngine {
  private static books = new Map<string, AccountingBook>()
  private static entries = new Map<string, BookEntry[]>()

  static createBook(
    name: string,
    gaap: AccountingBook['gaap'],
    currency: string,
    entityId: string
  ): AccountingBook {
    const book: AccountingBook = {
      id: `book-${Date.now()}`,
      name,
      gaap,
      currency,
      entityId,
      createdAt: new Date().toISOString(),
      closedPeriods: [],
      status: 'active',
    }
    this.books.set(book.id, book)
    this.entries.set(book.id, [])
    return book
  }

  static getBook(bookId: string): AccountingBook | undefined {
    return this.books.get(bookId)
  }

  static listBooks(entityId?: string): AccountingBook[] {
    const all = Array.from(this.books.values())
    return entityId ? all.filter((b) => b.entityId === entityId) : all
  }

  static postEntry(
    bookId: string,
    entry: Omit<BookEntry, 'id' | 'bookId' | 'adjusted' | 'date'>
  ): BookEntry {
    const book = this.books.get(bookId)
    if (!book) throw new Error(`Book ${bookId} not found`)
    if (book.status !== 'active') throw new Error(`Book ${bookId} is not active`)
    if (book.closedPeriods.includes(entry.period)) {
      throw new Error(`Period ${entry.period} is closed in book ${bookId}`)
    }

    const fullEntry: BookEntry = {
      ...entry,
      id: `entry-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      bookId,
      adjusted: false,
      date: new Date().toISOString(),
    }

    const bookEntries = this.entries.get(bookId) ?? []
    bookEntries.push(fullEntry)
    this.entries.set(bookId, bookEntries)

    return fullEntry
  }

  static getEntries(
    bookId: string,
    filters?: { period?: string; accountId?: string; startDate?: string; endDate?: string }
  ): BookEntry[] {
    let entries = this.entries.get(bookId) ?? []

    if (filters?.period) {
      entries = entries.filter((e) => e.period === filters.period)
    }
    if (filters?.accountId) {
      entries = entries.filter((e) => e.accountId === filters.accountId)
    }
    if (filters?.startDate) {
      entries = entries.filter((e) => e.date >= filters.startDate!)
    }
    if (filters?.endDate) {
      entries = entries.filter((e) => e.date <= filters.endDate!)
    }

    return entries
  }

  static adjustEntry(
    bookId: string,
    entryId: string,
    adjustment: { debit?: number; credit?: number; description: string; userId: string }
  ): BookEntry {
    const bookEntries = this.entries.get(bookId) ?? []
    const original = bookEntries.find((e) => e.id === entryId)
    if (!original) throw new Error(`Entry ${entryId} not found`)

    const adjusted: BookEntry = {
      id: `adj-${Date.now()}`,
      bookId,
      accountId: original.accountId,
      debit: adjustment.debit ?? original.debit,
      credit: adjustment.credit ?? original.credit,
      description: adjustment.description,
      period: original.period,
      date: new Date().toISOString(),
      userId: adjustment.userId,
      adjusted: true,
      adjustmentOf: entryId,
    }

    bookEntries.push(adjusted)
    this.entries.set(bookId, bookEntries)

    return adjusted
  }

  static closeBook(bookId: string, period: string): void {
    const book = this.books.get(bookId)
    if (!book) throw new Error(`Book ${bookId} not found`)
    if (book.closedPeriods.includes(period)) {
      throw new Error(`Period ${period} already closed`)
    }
    book.closedPeriods.push(period)
  }

  static reopenBook(bookId: string, period: string, userId: string): void {
    const book = this.books.get(bookId)
    if (!book) throw new Error(`Book ${bookId} not found`)
    book.closedPeriods = book.closedPeriods.filter((p) => p !== period)
  }

  static consolidateBooks(bookIds: string[]): ConsolidatedEntry[] {
    const accountMap = new Map<string, ConsolidatedEntry>()

    for (const bookId of bookIds) {
      const book = this.books.get(bookId)
      if (!book) continue

      const entries = this.entries.get(bookId) ?? []
      for (const entry of entries) {
        const existing = accountMap.get(entry.accountId)
        if (existing) {
          existing.books.push({
            bookId,
            bookName: book.name,
            debit: entry.debit,
            credit: entry.credit,
          })
          existing.totalDebit += entry.debit
          existing.totalCredit += entry.credit
          existing.netAmount = existing.totalDebit - existing.totalCredit
        } else {
          accountMap.set(entry.accountId, {
            accountId: entry.accountId,
            books: [{ bookId, bookName: book.name, debit: entry.debit, credit: entry.credit }],
            totalDebit: entry.debit,
            totalCredit: entry.credit,
            netAmount: entry.debit - entry.credit,
            gaapDifferences: [],
          })
        }
      }
    }

    // Calculate GAAP differences
    const entries = Array.from(accountMap.values())
    for (const entry of entries) {
      if (entry.books.length >= 2) {
        for (let i = 0; i < entry.books.length - 1; i++) {
          for (let j = i + 1; j < entry.books.length; j++) {
            const diff = entry.books[i].debit - entry.books[j].debit
            if (Math.abs(diff) > 0.01) {
              entry.gaapDifferences.push({
                account: entry.accountId,
                gaap1: entry.books[i].debit,
                gaap2: entry.books[j].debit,
                difference: diff,
              })
            }
          }
        }
      }
    }

    return entries
  }

  static compareBooks(bookIds: string[]): Array<{
    accountId: string
    values: Array<{ bookId: string; bookName: string; amount: number }>
    maxDifference: number
  }> {
    const accountMap = new Map<
      string,
      Array<{ bookId: string; bookName: string; amount: number }>
    >()

    for (const bookId of bookIds) {
      const book = this.books.get(bookId)
      if (!book) continue

      const entries = this.entries.get(bookId) ?? []
      const accountTotals = new Map<string, number>()

      for (const entry of entries) {
        const current = accountTotals.get(entry.accountId) ?? 0
        accountTotals.set(entry.accountId, current + entry.debit - entry.credit)
      }

      for (const [accountId, amount] of accountTotals) {
        const existing = accountMap.get(accountId) ?? []
        existing.push({ bookId, bookName: book.name, amount })
        accountMap.set(accountId, existing)
      }
    }

    return Array.from(accountMap.entries()).map(([accountId, values]) => ({
      accountId,
      values,
      maxDifference:
        Math.max(...values.map((v) => v.amount)) - Math.min(...values.map((v) => v.amount)),
    }))
  }

  static deleteBook(bookId: string): boolean {
    if (!this.books.has(bookId)) return false
    this.books.delete(bookId)
    this.entries.delete(bookId)
    return true
  }
}

/**
 * Natural Language Query (NLQ) Engine
 *
 * Parses natural language queries into structured financial data requests.
 * Supports: charts, tables, KPIs, comparisons, trends.
 *
 * Competitive advantage: First offline FP&A tool with NLQ (Vena, Cube, Oracle, SAP, Mosaic have it).
 */

import type { GLEntry, GLAccount } from '@/types'

// ─── Types ──────────────────────────────────────────────────────────────────

export type NLQIntent = 'chart' | 'table' | 'kpi' | 'comparison' | 'trend'
export type NLQChartType = 'bar' | 'line' | 'area' | 'pie' | 'composed'
export type NLQTimeGranularity = 'month' | 'quarter' | 'year'

export interface NLQEntities {
  metrics: string[]
  dimensions: string[]
  timePeriod: NLQTimePeriod | null
  filters: NLQFilter[]
  aggregation: 'sum' | 'avg' | 'count' | 'min' | 'max'
}

export interface NLQTimePeriod {
  type: 'quarter' | 'month' | 'year' | 'range'
  value: string // "Q3", "2026", "Jan", "Q1-Q3"
  year?: number
}

export interface NLQFilter {
  field: string
  operator: 'eq' | 'neq' | 'gt' | 'lt' | 'gte' | 'lte' | 'contains'
  value: string | number
}

export interface NLQQuery {
  raw: string
  intent: NLQIntent
  entities: NLQEntities
  chartType: NLQChartType
  confidence: number
}

export interface NLQResult {
  query: NLQQuery
  data: NLQDataPoint[]
  summary: string
  chartConfig: NLQChartConfig | null
}

export interface NLQDataPoint {
  label: string
  value: number
  dimension?: string
  period?: string
}

export interface NLQChartConfig {
  type: NLQChartType
  dataKey: string
  labelKey: string
  title: string
  colors?: string[]
}

// ─── Pattern Definitions ────────────────────────────────────────────────────

const METRIC_PATTERNS: Record<string, string[]> = {
  revenue: ['revenue', 'sales', 'income', 'top line'],
  expenses: ['expenses', 'costs', 'spending', 'expenditure', 'outgoings'],
  profit: ['profit', 'earnings', 'net income', 'bottom line', 'margin'],
  budget: ['budget', 'planned', 'allocated', 'forecast'],
  actual: ['actual', 'realized', 'actuals'],
  variance: ['variance', 'difference', 'delta', 'deviation'],
  assets: ['assets', 'total assets'],
  liabilities: ['liabilities', 'debts', 'obligations'],
  equity: ['equity', 'shareholders equity'],
  cashflow: ['cash flow', 'cashflow', 'cash'],
  headcount: ['headcount', 'employees', 'staff', 'fte'],
  arr: ['arr', 'annual recurring revenue'],
  mrr: ['mrr', 'monthly recurring revenue'],
  churn: ['churn', 'attrition', 'retention'],
}

const DIMENSION_PATTERNS: Record<string, string[]> = {
  region: ['region', 'territory', 'area', 'geography'],
  department: ['department', 'dept', 'division', 'business unit'],
  product: ['product', 'line', 'offering', 'service'],
  entity: ['entity', 'subsidiary', 'company'],
  account: ['account', 'gl', 'ledger'],
  period: ['period', 'month', 'quarter', 'year'],
}

const TIME_PATTERNS = {
  quarters: /Q([1-4])/i,
  months: /\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)\w*\b/i,
  years: /\b(20\d{2})\b/,
  fy: /\bFY\s*(20\d{2})\b/i,
  lastQuarter: /\blast\s+quarter\b/i,
  thisQuarter: /\bthis\s+quarter\b/i,
  thisYear: /\bthis\s+year\b/i,
  lastYear: /\blast\s+year\b/i,
  ytd: /\bYTD\b/i,
  mtd: /\bMTD\b/i,
  qtd: /\bQTD\b/i,
}

const INTENT_PATTERNS: { pattern: RegExp; intent: NLQIntent; chartType: NLQChartType }[] = [
  { pattern: /\b(compare|vs|versus|against)\b/i, intent: 'comparison', chartType: 'bar' },
  { pattern: /\b(trend|over time|history|historical)\b/i, intent: 'trend', chartType: 'line' },
  { pattern: /\b(show|display|visualize|chart|graph)\b/i, intent: 'chart', chartType: 'bar' },
  { pattern: /\b(what is|total|sum|how much|amount)\b/i, intent: 'kpi', chartType: 'bar' },
  { pattern: /\b(list|table|details|breakdown)\b/i, intent: 'table', chartType: 'bar' },
  { pattern: /\b(by|per|across|grouped)\b/i, intent: 'chart', chartType: 'bar' },
]

const CHART_TYPE_PATTERNS: { pattern: RegExp; type: NLQChartType }[] = [
  { pattern: /\b(pie|donut)\b/i, type: 'pie' },
  { pattern: /\b(line|trend)\b/i, type: 'line' },
  { pattern: /\b(area|stacked)\b/i, type: 'area' },
  { pattern: /\b(bar|column)\b/i, type: 'bar' },
]

// ─── Parser ─────────────────────────────────────────────────────────────────

export class NLQEngine {
  /**
   * Parse natural language query into structured NLQQuery.
   */
  static parseQuery(text: string): NLQQuery {
    const normalized = text.toLowerCase().trim()
    const intent = this.classifyIntent(normalized)
    const entities = this.extractEntities(normalized)
    const chartType = this.detectChartType(normalized) || this.defaultChartType(intent)
    const confidence = this.calculateConfidence(intent, entities)

    return { raw: text, intent, entities, chartType, confidence }
  }

  /**
   * Classify query intent.
   */
  static classifyIntent(text: string): NLQIntent {
    for (const { pattern, intent } of INTENT_PATTERNS) {
      if (pattern.test(text)) return intent
    }
    // Default: if has dimension → chart, else → kpi
    return this.hasDimensionKeyword(text) ? 'chart' : 'kpi'
  }

  /**
   * Extract entities: metrics, dimensions, time period, filters.
   */
  static extractEntities(text: string): NLQEntities {
    return {
      metrics: this.extractMetrics(text),
      dimensions: this.extractDimensions(text),
      timePeriod: this.extractTimePeriod(text),
      filters: this.extractFilters(text),
      aggregation: this.detectAggregation(text),
    }
  }

  /**
   * Execute query against GL entries and return data points.
   */
  static executeQuery(
    query: NLQQuery,
    entries: readonly GLEntry[],
    accounts?: readonly GLAccount[]
  ): NLQResult {
    const { metrics, dimensions, timePeriod, filters, aggregation } = query.entities

    // Filter entries by time period
    let filtered = this.filterByTimePeriod(entries, timePeriod)

    // Apply additional filters
    filtered = this.applyFilters(filtered, filters)

    // Group by dimension
    const grouped = this.groupEntries(filtered, dimensions, accounts)

    // Aggregate
    const data = this.aggregateGrouped(grouped, metrics, aggregation)

    // Generate summary
    const summary = this.generateSummary(query, data)

    // Generate chart config
    const chartConfig = query.intent === 'kpi' ? null : this.generateChartConfig(query, data)

    return { query, data, summary, chartConfig }
  }

  // ─── Metric Extraction ──────────────────────────────────────────────────

  private static extractMetrics(text: string): string[] {
    const found: string[] = []
    for (const [metric, patterns] of Object.entries(METRIC_PATTERNS)) {
      if (patterns.some((p) => text.includes(p))) {
        found.push(metric)
      }
    }
    return found.length > 0 ? found : ['revenue'] // default
  }

  // ─── Dimension Extraction ───────────────────────────────────────────────

  private static extractDimensions(text: string): string[] {
    const found: string[] = []
    for (const [dim, patterns] of Object.entries(DIMENSION_PATTERNS)) {
      if (patterns.some((p) => text.includes(p))) {
        found.push(dim)
      }
    }
    return found
  }

  private static hasDimensionKeyword(text: string): boolean {
    return /\b(by|per|across|grouped|for each)\b/i.test(text)
  }

  // ─── Time Period Extraction ─────────────────────────────────────────────

  private static extractTimePeriod(text: string): NLQTimePeriod | null {
    // Quarter
    const qMatch = text.match(TIME_PATTERNS.quarters)
    if (qMatch) {
      const yearMatch = text.match(TIME_PATTERNS.years)
      return {
        type: 'quarter',
        value: `Q${qMatch[1]}`,
        year: yearMatch ? parseInt(yearMatch[1]) : undefined,
      }
    }

    // FY year
    const fyMatch = text.match(TIME_PATTERNS.fy)
    if (fyMatch) return { type: 'year', value: fyMatch[1], year: parseInt(fyMatch[1]) }

    // Year
    const yMatch = text.match(TIME_PATTERNS.years)
    if (yMatch && !text.match(TIME_PATTERNS.quarters)) {
      return { type: 'year', value: yMatch[1], year: parseInt(yMatch[1]) }
    }

    // Month
    const mMatch = text.match(TIME_PATTERNS.months)
    if (mMatch) {
      const months = [
        'jan',
        'feb',
        'mar',
        'apr',
        'may',
        'jun',
        'jul',
        'aug',
        'sep',
        'oct',
        'nov',
        'dec',
      ]
      const idx = months.indexOf(mMatch[1].toLowerCase())
      return {
        type: 'month',
        value: mMatch[1].charAt(0).toUpperCase() + mMatch[1].slice(1, 3),
        year: undefined,
      }
    }

    // Relative
    if (TIME_PATTERNS.thisYear.test(text)) return { type: 'year', value: 'thisYear' }
    if (TIME_PATTERNS.lastYear.test(text)) return { type: 'year', value: 'lastYear' }
    if (TIME_PATTERNS.thisQuarter.test(text)) return { type: 'quarter', value: 'thisQuarter' }
    if (TIME_PATTERNS.lastQuarter.test(text)) return { type: 'quarter', value: 'lastQuarter' }
    if (TIME_PATTERNS.ytd.test(text)) return { type: 'year', value: 'YTD' }
    if (TIME_PATTERNS.mtd.test(text)) return { type: 'month', value: 'MTD' }
    if (TIME_PATTERNS.qtd.test(text)) return { type: 'quarter', value: 'QTD' }

    return null
  }

  // ─── Filter Extraction ──────────────────────────────────────────────────

  private static extractFilters(text: string): NLQFilter[] {
    const filters: NLQFilter[] = []

    // "where field = value" or "for field value"
    const whereMatch = text.match(/\bwhere\s+(\w+)\s*(=|is|equals?)\s*(\w[\w\s]*)/i)
    if (whereMatch) {
      filters.push({ field: whereMatch[1], operator: 'eq', value: whereMatch[3].trim() })
    }

    // "department sales" or "region north"
    for (const [dim, patterns] of Object.entries(DIMENSION_PATTERNS)) {
      if (patterns.some((p) => text.includes(p))) {
        // Check if there's a value after the dimension keyword
        const dimPattern = new RegExp(`\\b${patterns[0]}\\s+(\\w+)`, 'i')
        const match = text.match(dimPattern)
        if (match && !['by', 'per', 'in', 'for'].includes(match[1].toLowerCase())) {
          filters.push({ field: dim, operator: 'eq', value: match[1] })
        }
      }
    }

    return filters
  }

  // ─── Aggregation Detection ──────────────────────────────────────────────

  private static detectAggregation(text: string): 'sum' | 'avg' | 'count' | 'min' | 'max' {
    if (/\b(average|avg|mean)\b/i.test(text)) return 'avg'
    if (/\b(count|number|how many)\b/i.test(text)) return 'count'
    if (/\b(min|minimum|lowest|smallest)\b/i.test(text)) return 'min'
    if (/\b(max|maximum|highest|largest|biggest)\b/i.test(text)) return 'max'
    return 'sum'
  }

  // ─── Chart Type Detection ───────────────────────────────────────────────

  private static detectChartType(text: string): NLQChartType | null {
    for (const { pattern, type } of CHART_TYPE_PATTERNS) {
      if (pattern.test(text)) return type
    }
    return null
  }

  private static defaultChartType(intent: NLQIntent): NLQChartType {
    switch (intent) {
      case 'trend':
        return 'line'
      case 'comparison':
        return 'bar'
      case 'chart':
        return 'bar'
      case 'table':
        return 'bar'
      case 'kpi':
        return 'bar'
    }
  }

  // ─── Confidence ─────────────────────────────────────────────────────────

  private static calculateConfidence(intent: NLQIntent, entities: NLQEntities): number {
    let confidence = 0.5
    if (entities.metrics.length > 0) confidence += 0.2
    if (entities.dimensions.length > 0) confidence += 0.15
    if (entities.timePeriod) confidence += 0.1
    if (intent !== 'kpi') confidence += 0.05
    return Math.min(confidence, 1)
  }

  // ─── Filtering ──────────────────────────────────────────────────────────

  private static filterByTimePeriod(
    entries: readonly GLEntry[],
    period: NLQTimePeriod | null
  ): readonly GLEntry[] {
    if (!period) return entries

    const now = new Date()
    const currentYear = now.getFullYear()
    const currentMonth = now.getMonth() + 1
    const currentQuarter = Math.ceil(currentMonth / 3)

    return entries.filter((e) => {
      const entryDate = new Date(e.date)
      const entryYear = entryDate.getFullYear()
      const entryMonth = entryDate.getMonth() + 1
      const entryQuarter = Math.ceil(entryMonth / 3)

      switch (period.value) {
        case 'thisYear':
          return entryYear === currentYear
        case 'lastYear':
          return entryYear === currentYear - 1
        case 'YTD':
          return entryYear === currentYear
        case 'MTD':
          return entryYear === currentYear && entryMonth === currentMonth
        case 'QTD':
          return entryYear === currentYear && entryQuarter === currentQuarter
        case 'thisQuarter':
          return entryYear === currentYear && entryQuarter === currentQuarter
        case 'lastQuarter': {
          const lastQ = currentQuarter === 1 ? 4 : currentQuarter - 1
          const lastQYear = currentQuarter === 1 ? currentYear - 1 : currentYear
          return entryYear === lastQYear && entryQuarter === lastQ
        }
        default: {
          // Specific quarter or year
          if (period.type === 'quarter') {
            const q = parseInt(period.value.replace('Q', ''))
            return entryQuarter === q && (!period.year || entryYear === period.year)
          }
          if (period.type === 'year') {
            const y = parseInt(period.value)
            return entryYear === y
          }
          return true
        }
      }
    })
  }

  private static applyFilters(
    entries: readonly GLEntry[],
    filters: readonly NLQFilter[]
  ): readonly GLEntry[] {
    return entries.filter((e) => {
      return filters.every((f) => {
        const value = this.getEntryField(e, f.field)
        if (value === undefined) return true
        switch (f.operator) {
          case 'eq':
            return String(value).toLowerCase() === String(f.value).toLowerCase()
          case 'neq':
            return String(value).toLowerCase() !== String(f.value).toLowerCase()
          case 'gt':
            return Number(value) > Number(f.value)
          case 'lt':
            return Number(value) < Number(f.value)
          case 'gte':
            return Number(value) >= Number(f.value)
          case 'lte':
            return Number(value) <= Number(f.value)
          case 'contains':
            return String(value).toLowerCase().includes(String(f.value).toLowerCase())
          default:
            return true
        }
      })
    })
  }

  private static getEntryField(entry: GLEntry, field: string): string | number | undefined {
    switch (field) {
      case 'account':
      case 'accountName':
        return entry.accountName
      case 'accountCode':
        return entry.accountCode
      case 'description':
        return entry.description
      case 'period':
        return entry.period
      case 'amount':
      case 'netChange':
        return entry.netChange
      case 'debit':
        return entry.debit
      case 'credit':
        return entry.credit
      case 'entityId':
        return entry.entityId
      case 'departmentId':
        return entry.departmentId
      default:
        return undefined
    }
  }

  // ─── Grouping ───────────────────────────────────────────────────────────

  private static groupEntries(
    entries: readonly GLEntry[],
    dimensions: readonly string[],
    accounts?: readonly GLAccount[]
  ): Map<string, GLEntry[]> {
    const groups = new Map<string, GLEntry[]>()

    if (dimensions.length === 0) {
      groups.set('total', [...entries])
      return groups
    }

    const dim = dimensions[0] // primary dimension

    for (const entry of entries) {
      let key: string
      switch (dim) {
        case 'region':
        case 'entity':
          key = entry.entityId || 'Unknown'
          break
        case 'department':
          key = entry.departmentId || 'Unknown'
          break
        case 'account':
          key = entry.accountName
          break
        case 'period':
          key = entry.periodName || entry.period
          break
        case 'product':
          key = entry.accountName || 'General'
          break
        default:
          key = entry.accountName
      }

      if (!groups.has(key)) groups.set(key, [])
      groups.get(key)!.push(entry)
    }

    return groups
  }

  // ─── Aggregation ────────────────────────────────────────────────────────

  private static aggregateGrouped(
    grouped: Map<string, GLEntry[]>,
    metrics: readonly string[],
    aggregation: 'sum' | 'avg' | 'count' | 'min' | 'max'
  ): NLQDataPoint[] {
    const points: NLQDataPoint[] = []
    const useMetric = metrics[0] || 'revenue'

    for (const [key, entries] of grouped) {
      const values = entries.map((e) => {
        // Map metric to entry field
        switch (useMetric) {
          case 'revenue':
          case 'sales':
          case 'income':
            return e.netChange > 0 ? e.netChange : 0
          case 'expenses':
          case 'costs':
            return e.netChange < 0 ? Math.abs(e.netChange) : 0
          case 'profit':
            return e.netChange
          case 'debit':
            return e.debit
          case 'credit':
            return e.credit
          default:
            return e.netChange
        }
      })

      let value: number
      switch (aggregation) {
        case 'sum':
          value = values.reduce((a, b) => a + b, 0)
          break
        case 'avg':
          value = values.length > 0 ? values.reduce((a, b) => a + b, 0) / values.length : 0
          break
        case 'count':
          value = values.length
          break
        case 'min':
          value = values.length > 0 ? Math.min(...values) : 0
          break
        case 'max':
          value = values.length > 0 ? Math.max(...values) : 0
          break
      }

      points.push({ label: key, value, dimension: key })
    }

    return points.sort((a, b) => Math.abs(b.value) - Math.abs(a.value))
  }

  // ─── Summary Generation ─────────────────────────────────────────────────

  private static generateSummary(query: NLQQuery, data: readonly NLQDataPoint[]): string {
    if (data.length === 0) return 'No data found for this query.'

    const total = data.reduce((sum, d) => sum + d.value, 0)
    const metric = query.entities.metrics[0] || 'value'
    const top = data[0]

    const formatted = new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    }).format(total)

    switch (query.intent) {
      case 'kpi':
        return `Total ${metric}: ${formatted}`
      case 'comparison':
        return `${metric}: ${data.length} items. Top: ${top.label} (${new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(top.value)})`
      case 'trend':
        return `${metric} trend over ${data.length} periods. Total: ${formatted}`
      case 'chart':
        return `${metric} by ${query.entities.dimensions[0] || 'category'}. Total: ${formatted}. ${data.length} items.`
      case 'table':
        return `${data.length} rows of ${metric} data. Total: ${formatted}`
      default:
        return `Found ${data.length} results. Total: ${formatted}`
    }
  }

  // ─── Chart Config ───────────────────────────────────────────────────────

  static generateChartConfig(query: NLQQuery, data: readonly NLQDataPoint[]): NLQChartConfig {
    const metric = query.entities.metrics[0] || 'value'
    const dim = query.entities.dimensions[0] || 'category'

    return {
      type: query.chartType,
      dataKey: 'value',
      labelKey: 'label',
      title: `${metric} by ${dim}`,
      colors: ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4'],
    }
  }
}

/**
 * @vitest-environment jsdom
 */
import { describe, it, expect, beforeEach, vi } from 'vitest'
import { PluginEngine } from './PluginEngine'
import type { PluginManifest, Plugin, PluginAPI, PluginType } from '@/types/plugin'

function makeManifest(overrides: Partial<PluginManifest> = {}): PluginManifest {
  return {
    id: 'test-plugin',
    name: 'Test Plugin',
    version: '1.0.0',
    description: 'A test plugin',
    author: 'Test',
    license: 'MIT',
    type: 'formula',
    entry: './test-plugin',
    permissions: ['read-data'],
    dependencies: [],
    conflicts: [],
    tags: [],
    minFinPlanVersion: undefined,
    maxFinPlanVersion: undefined,
    ...overrides,
  }
}

class TestPlugin implements Plugin {
  id = 'test-plugin'
  name = 'Test Plugin'
  version = '1.0.0'
  api!: PluginAPI
  initCalls = 0
  destroyCalls = 0

  init(api: PluginAPI): void {
    this.api = api
    this.initCalls++
  }

  destroy(): void {
    this.destroyCalls++
  }
}

describe('PluginEngine', () => {
  let engine: PluginEngine

  beforeEach(() => {
    engine = new PluginEngine()
  })

  const pluginModule = { default: TestPlugin as unknown as new () => Plugin }

  describe('discover', () => {
    it('returns empty array (manual registration only)', async () => {
      const result = await engine.discover(['/some/path'])
      expect(result).toEqual([])
    })
  })

  describe('install', () => {
    it('installs a valid plugin', async () => {
      const manifest = makeManifest()
      const instance = await engine.install(manifest, pluginModule)
      expect(instance.status).toBe('initialized')
      expect(instance.manifest.id).toBe('test-plugin')
    })

    it('calls plugin.init on install', async () => {
      const manifest = makeManifest()
      const instance = await engine.install(manifest, pluginModule)
      expect((instance.plugin as unknown as TestPlugin).initCalls).toBe(1)
    })

    it('rejects plugin with missing id', async () => {
      const manifest = makeManifest({ id: '' })
      await expect(engine.install(manifest, pluginModule)).rejects.toThrow(
        'Missing required fields'
      )
    })

    it('rejects plugin with invalid id format', async () => {
      const manifest = makeManifest({ id: 'INVALID_ID!' })
      await expect(engine.install(manifest, pluginModule)).rejects.toThrow('lowercase')
    })

    it('rejects plugin with missing type', async () => {
      const manifest = makeManifest({ type: '' as unknown as PluginType })
