      }
      let report = createTestReport()
      report = ReportBuilderEngine.addParameter(report, param)

      expect(ReportBuilderEngine.getParameters(report)).toHaveLength(1)
    })
  })

  // =========================================================================
  // SECTION MANAGEMENT
  // =========================================================================

  describe('getSections', () => {
