  // ---------------------------------------------------------------------------
  // Data Binding — Resolve Cell Values from Cube Data
  // ---------------------------------------------------------------------------

  /**
   * Build a composite lookup key from a cell binding
   */
  static buildBindingKey(binding: CellBinding): string {
    const parts = [binding.coords, binding.measure]
    if (binding.entityId) parts.push(binding.entityId)
    if (binding.scenarioId) parts.push(binding.scenarioId)
    if (binding.periodId) parts.push(binding.periodId)
    return parts.join('.')
  }

  /**
   * Resolve a single cell's value from cube data
   */
  static resolveCellValue(cell: ReportCell, cubeData: CubeData): ResolvedCell {
    const base: ResolvedCell = {
      cellId: cell.id,
      rawValue: null,
      formattedValue: '',
      binding: null,
    }

    if (cell.type === 'text') {
      const textContent = cell.content as { content: { text: string } }
      base.rawValue = textContent.content.text
      base.formattedValue = textContent.content.text
      return base
    }

    if (cell.type === 'metric') {
      const metricContent = cell.content as { content: MetricCellContent }
      const mc = metricContent.content
      const binding: CellBinding = {
        coords: mc.coords,
        measure: mc.measure,
        entityId: mc.entityId,
        scenarioId: mc.scenarioId,
        periodId: mc.periodId,
      }
      base.binding = binding

      const key = this.buildBindingKey(binding)
      const value = cubeData[key]

      if (value !== undefined && value !== null) {
        const numValue = typeof value === 'number' ? value : Number(value)
        if (Number.isFinite(numValue)) {
          base.rawValue = numValue
          base.formattedValue = this.formatNumber(numValue, mc.format, mc.decimals)
        } else {
          base.rawValue = String(value)
          base.formattedValue = String(value)
        }
      } else {
        base.rawValue = null
        base.formattedValue = '—'
      }
      return base
    }

    if (cell.type === 'formula') {
      const formulaContent = cell.content as { content: FormulaCellContent }
      base.rawValue = null
      base.formattedValue = formulaContent.content.label ?? formulaContent.content.expression
      return base
    }

    if (cell.type === 'chart') {
      const chartContent = cell.content as { content: ChartElementContent }
      base.rawValue = null
      base.formattedValue = `[Chart: ${chartContent.content.title}]`
      return base
    }

    if (cell.type === 'table') {
      base.rawValue = null
      base.formattedValue = '[Table]'
      return base
    }

    return base
  }

  /**
   * Resolve all metric cells in a layout using cube data
   */
  static resolveLayout(layout: ReportLayout, cubeData: CubeData): ResolvedCell[][] {
    return layout.rows.map((row) => row.cells.map((cell) => this.resolveCellValue(cell, cubeData)))
  }

  /**
   * Build a lookup key from metric cell content
   */
  static buildMetricKey(content: MetricCellContent): string {
    const binding: CellBinding = {
      coords: content.coords,
      measure: content.measure,
      entityId: content.entityId,
      scenarioId: content.scenarioId,
      periodId: content.periodId,
    }
    return this.buildBindingKey(binding)
  }

  // ---------------------------------------------------------------------------
  // Subtotal / Total Calculations
  // ---------------------------------------------------------------------------

  /**
   * Calculate the sum of numeric values from resolved cells in a column
   */
  static calculateColumnSum(
    resolvedCells: ResolvedCell[][],
    columnIndex: number,
    startRow: number,
    endRow: number
  ): number {
    let sum = 0
    for (let i = startRow; i <= endRow && i < resolvedCells.length; i++) {
      const cell = resolvedCells[i]?.[columnIndex]
      if (cell && typeof cell.rawValue === 'number' && Number.isFinite(cell.rawValue)) {
        sum += cell.rawValue
      }
    }
    return sum
  }

  /**
   * Identify subtotal/total row ranges in a layout
   * Returns groups of consecutive 'data' rows followed by a 'subtotal' or 'total' row
   */
  static identifySectionRanges(layout: ReportLayout): Array<{
    type: 'data' | 'subtotal' | 'total'
    startIndex: number
    endIndex: number
  }> {
    const sections: Array<{
      type: 'data' | 'subtotal' | 'total'
      startIndex: number
      endIndex: number
    }> = []
    let currentType: 'data' | 'subtotal' | 'total' | null = null
    let startIndex = 0

    for (let i = 0; i < layout.rows.length; i++) {
      const rowType = layout.rows[i].type
      const normalizedType: 'data' | 'subtotal' | 'total' =
        rowType === 'data' || rowType === 'header'
          ? 'data'
          : rowType === 'subtotal'
            ? 'subtotal'
            : rowType === 'total'
              ? 'total'
              : 'data'

      if (normalizedType !== currentType) {
        if (currentType !== null) {
          sections.push({ type: currentType, startIndex, endIndex: i - 1 })
        }
        currentType = normalizedType
        startIndex = i
      }
    }

    if (currentType !== null) {
      sections.push({ type: currentType, startIndex, endIndex: layout.rows.length - 1 })
    }

    return sections
  }

  /**
   * Auto-populate subtotal/total rows by summing preceding data rows
   */
  static autoPopulateTotals(
    layout: ReportLayout,
    cubeData: CubeData,
    numberFormat: NumberFormat = 'currency',
    decimals = 0
  ): ReportLayout {
    const resolved = this.resolveLayout(layout, cubeData)
    const sections = this.identifySectionRanges(layout)

    const rows = layout.rows.map((row) => ({ ...row, cells: [...row.cells] }))

    for (const section of sections) {
      if (section.type !== 'subtotal' && section.type !== 'total') continue

      // Find the preceding data section
      const precedingData = sections.filter(
        (s) => s.type === 'data' && s.endIndex < section.startIndex
      )
      if (precedingData.length === 0) continue

      const dataSection = precedingData[precedingData.length - 1]

      for (let colIdx = 0; colIdx < layout.columns.length; colIdx++) {
        const col = layout.columns[colIdx]
        if (col.type === 'label') continue

        const sum = this.calculateColumnSum(
          resolved,
          colIdx,
          dataSection.startIndex,
          dataSection.endIndex
        )
        const existingCell = rows[section.startIndex].cells[colIdx]

        if (existingCell.type === 'metric') {
          rows[section.startIndex].cells[colIdx] = {
            ...existingCell,
            content: {
              type: 'metric' as const,
              content: {
                coords: `Auto.${section.type}.${colIdx}`,
                measure: 'sum',
                format: numberFormat,
                decimals,
                showSign: false,
              },
            },
          }
        }
      }
    }

    return { ...layout, rows }
  }

  // ---------------------------------------------------------------------------
  // Formula Evaluation
  // ---------------------------------------------------------------------------

  /**
   * Parse formula references (e.g., "A1+B2*2" -> ["A1", "B2"])
   */
  static parseFormulaReferences(expression: string): string[] {
    const refPattern = /[A-Z]+\d+/g
    return [...new Set(expression.match(refPattern) ?? [])]
  }

  /**
   * Evaluate a simple arithmetic formula with cell references
   * Supports: +, -, *, /, parentheses, and cell references (e.g., A1, B2)
   */
  static evaluateFormula(expression: string, cellValues: Record<string, number>): number {
    // Replace cell references with their values
    let resolved = expression
    const refs = this.parseFormulaReferences(expression)

    for (const ref of refs) {
      const value = cellValues[ref]
      if (value === undefined) {
        throw new Error(`Missing value for cell reference: ${ref}`)
      }
      if (!Number.isFinite(value)) {
        throw new Error(`Non-finite value for cell reference: ${ref}`)
      }
      resolved = resolved.replace(new RegExp(ref, 'g'), String(value))
    }

    // Safe arithmetic evaluation (no eval)
    return this.safeEvaluate(resolved)
  }

  /**
   * Safe arithmetic evaluator — supports +, -, *, /, parentheses, decimals, negatives
   */
  static safeEvaluate(expression: string): number {
    const tokens = this.tokenize(expression)
    const result = this.parseExpression(tokens, { pos: 0 })

    if (!Number.isFinite(result)) {
      throw new Error('Formula result is not a finite number')
    }
    return result
  }

  private static tokenize(expr: string): string[] {
    const tokens: string[] = []
    let i = 0
    const s = expr.replace(/\s+/g, '')

    while (i < s.length) {
      const ch = s[i]

      // Number (including negative at start or after operator/open-paren)
      if (
        (ch >= '0' && ch <= '9') ||
        (ch === '.' && i + 1 < s.length && s[i + 1] >= '0' && s[i + 1] <= '9') ||
        (ch === '-' &&
          (tokens.length === 0 ||
            tokens[tokens.length - 1] === '(' ||
            '+-*/('.includes(tokens[tokens.length - 1] ?? '')))
      ) {
        let num = ch
        i++
        while (i < s.length && ((s[i] >= '0' && s[i] <= '9') || s[i] === '.')) {
          num += s[i]
          i++
        }
        tokens.push(num)
      } else if ('+-*/()'.includes(ch)) {
        tokens.push(ch)
        i++
      } else {
        // Skip unknown characters
        i++
      }
    }
    return tokens
  }

  private static parseExpression(tokens: string[], ctx: { pos: number }): number {
    let result = this.parseTerm(tokens, ctx)

    while (ctx.pos < tokens.length && (tokens[ctx.pos] === '+' || tokens[ctx.pos] === '-')) {
      const op = tokens[ctx.pos]
      ctx.pos++
      const right = this.parseTerm(tokens, ctx)
      result = op === '+' ? result + right : result - right
    }

    return result
  }

  private static parseTerm(tokens: string[], ctx: { pos: number }): number {
    let result = this.parseFactor(tokens, ctx)

    while (ctx.pos < tokens.length && (tokens[ctx.pos] === '*' || tokens[ctx.pos] === '/')) {
      const op = tokens[ctx.pos]
      ctx.pos++
      const right = this.parseFactor(tokens, ctx)
      if (op === '/' && right === 0) {
        throw new Error('Division by zero')
      }
      result = op === '*' ? result * right : result / right
    }

    return result
  }

  private static parseFactor(tokens: string[], ctx: { pos: number }): number {
    if (ctx.pos >= tokens.length) {
      throw new Error('Unexpected end of expression')
    }

    const token = tokens[ctx.pos]

    if (token === '(') {
      ctx.pos++
      const result = this.parseExpression(tokens, ctx)
      if (ctx.pos >= tokens.length || tokens[ctx.pos] !== ')') {
        throw new Error('Missing closing parenthesis')
      }
      ctx.pos++
      return result
    }

    ctx.pos++
    const num = Number(token)
    if (!Number.isFinite(num)) {
      throw new Error(`Invalid number: ${token}`)
    }
    return num
  }

  // ---------------------------------------------------------------------------
  // Circular Reference Detection
  // ---------------------------------------------------------------------------

  /**
   * Detect circular references in formula cells within a layout
   * Returns an array of cell IDs that participate in circular references
   */
  static detectCircularReferences(layout: ReportLayout): FormulaDependency[] {
    // Build dependency graph from formula cells
    const cellIdMap = new Map<string, { row: number; col: number }>()
    const dependencies = new Map<string, string[]>()

    for (let ri = 0; ri < layout.rows.length; ri++) {
      for (let ci = 0; ci < layout.rows[ri].cells.length; ci++) {
        const cell = layout.rows[ri].cells[ci]
        cellIdMap.set(cell.id, { row: ri, col: ci })

        if (cell.type === 'formula') {
          const formulaContent = cell.content as { content: FormulaCellContent }
          const refs = this.parseFormulaReferences(formulaContent.content.expression)
          // Convert positional refs (A1, B2) to cell IDs by mapping column letter + row number
          const depIds: string[] = []
          for (const ref of refs) {
            const colLetter = ref.match(/[A-Z]+/)?.[0] ?? ''
            const rowNum = parseInt(ref.match(/\d+/)?.[0] ?? '0', 10)
            const colIndex = this.columnLetterToIndex(colLetter)
            if (colIndex >= 0 && rowNum >= 1 && rowNum <= layout.rows.length) {
              const targetCell = layout.rows[rowNum - 1]?.cells[colIndex]
              if (targetCell) {
                depIds.push(targetCell.id)
              }
            }
          }
          dependencies.set(cell.id, depIds)
        }
      }
    }

    // DFS cycle detection
    const results: FormulaDependency[] = []
    const visited = new Set<string>()
    const inStack = new Set<string>()

    const dfs = (cellId: string, path: string[]): boolean => {
      if (inStack.has(cellId)) {
        // Found a cycle — mark all nodes in the cycle
        return true
      }
      if (visited.has(cellId)) return false

      visited.add(cellId)
      inStack.add(cellId)

      const deps = dependencies.get(cellId) ?? []
      let hasCycle = false
      for (const dep of deps) {
        if (dfs(dep, [...path, cellId])) {
          hasCycle = true
        }
      }

      inStack.delete(cellId)

      if (hasCycle || deps.some((d) => inStack.has(d))) {
        results.push({
          cellId,
          references: deps,
          hasCircularRef: true,
        })
      } else {
        results.push({
          cellId,
          references: deps,
          hasCircularRef: false,
        })
      }

      return hasCycle
    }

    for (const cellId of dependencies.keys()) {
      if (!visited.has(cellId)) {
        dfs(cellId, [])
      }
    }

    return results
  }

  /**
   * Convert column letter (A, B, ..., Z, AA, AB...) to 0-based index
   */
  static columnLetterToIndex(letter: string): number {
    let index = 0
    for (let i = 0; i < letter.length; i++) {
      index = index * 26 + (letter.charCodeAt(i) - 64)
    }
    return index - 1
  }

  /**
   * Convert 0-based column index to letter (0 -> A, 1 -> B, ..., 25 -> Z, 26 -> AA)
   */
  static columnIndexToLetter(index: number): string {
    let letter = ''
    let n = index + 1
    while (n > 0) {
      const rem = (n - 1) % 26
      letter = String.fromCharCode(65 + rem) + letter
      n = Math.floor((n - 1) / 26)
    }
    return letter
  }

  // ---------------------------------------------------------------------------
  // Excel Export Generation
  // ---------------------------------------------------------------------------

  /**
   * Generate Excel-compatible data from a report definition and cube data
   */
  static generateExcelExport(report: ReportDefinition, cubeData: CubeData): ExcelExportResult {
    const resolved = this.resolveLayout(report.layout, cubeData)
    const visibleColumns = this.getVisibleColumns(report.layout)

    // Build header row from column headers
    const headerRow = visibleColumns.map((col) => col.header)

    // Build data rows
    const dataRows: Array<Array<string | number | boolean | null>> = []

    const visibleRows = this.getVisibleRows(report.layout)
    for (let ri = 0; ri < report.layout.rows.length; ri++) {
      const row = report.layout.rows[ri]
      if (!row.isVisible) continue

      const excelRow: Array<string | number | boolean | null> = []
      for (let ci = 0; ci < report.layout.columns.length; ci++) {
        const col = report.layout.columns[ci]
        if (!col.isVisible) continue

        const cell = resolved[ri]?.[ci]
        if (cell) {
          excelRow.push(cell.rawValue)
        } else {
          excelRow.push(null)
        }
      }
      dataRows.push(excelRow)
    }

    const columnWidths = visibleColumns.map((col) => col.width)

    return {
      sheets: [
        {
          name: report.name.substring(0, 31), // Excel sheet name limit
          data: [headerRow, ...dataRows],
          columnWidths,
        },
      ],
      metadata: {
        title: report.name,
        createdAt: new Date().toISOString(),
        author: report.createdBy,
        orientation: 'landscape',
      },
    }
  }

  // ---------------------------------------------------------------------------
  // CSV Export Generation
  // ---------------------------------------------------------------------------

  /**
   * Generate CSV content from a report definition and cube data
   */
  static generateCSVExport(report: ReportDefinition, cubeData: CubeData): CSVExportResult {
    const resolved = this.resolveLayout(report.layout, cubeData)
    const visibleColumns = this.getVisibleColumns(report.layout)

    const escapeCSV = (value: string | number | boolean | null): string => {
      if (value === null || value === undefined) return ''
      const str = String(value)
      if (str.includes(',') || str.includes('"') || str.includes('\n')) {
        return `"${str.replace(/"/g, '""')}"`
      }
      return str
    }

    const lines: string[] = []

    // Header line
    const headerLine = visibleColumns.map((col) => escapeCSV(col.header)).join(',')
    lines.push(headerLine)

    // Data lines
    for (let ri = 0; ri < report.layout.rows.length; ri++) {
      const row = report.layout.rows[ri]
      if (!row.isVisible) continue

      const csvCells: string[] = []
      for (let ci = 0; ci < report.layout.columns.length; ci++) {
        const col = report.layout.columns[ci]
        if (!col.isVisible) continue

        const cell = resolved[ri]?.[ci]
        if (cell) {
          csvCells.push(escapeCSV(cell.rawValue))
        } else {
          csvCells.push('')
        }
      }
      lines.push(csvCells.join(','))
    }

    const safeName = report.name.replace(/[^a-zA-Z0-9_-]/g, '_')

    return {
      content: lines.join('\n'),
      filename: `${safeName}.csv`,
      mimeType: 'text/csv',
    }
  }

  // ---------------------------------------------------------------------------
  // Report Parameters
  // ---------------------------------------------------------------------------

  /**
   * Add a parameter to a report definition
   */
  static addParameter(report: ReportDefinition, parameter: ReportParameter): ReportDefinition {
    const existing =
      (report as ReportDefinition & { parameters?: ReportParameter[] }).parameters ?? []
    if (existing.some((p) => p.id === parameter.id)) {
      throw new Error(`Parameter "${parameter.id}" already exists`)
    }

    return {
      ...report,
      parameters: [...existing, parameter],
      updatedAt: new Date().toISOString(),
      version: report.version + 1,
    } as ReportDefinition
  }

  /**
   * Update a parameter value in a report definition
   */
  static updateParameterValue(
    report: ReportDefinition,
    parameterId: string,
    value: string | number | boolean
  ): ReportDefinition {
    const existing =
      (report as ReportDefinition & { parameters?: ReportParameter[] }).parameters ?? []
    const index = existing.findIndex((p) => p.id === parameterId)
    if (index === -1) {
      throw new Error(`Parameter "${parameterId}" not found`)
    }

    const updated = existing.map((p, i) => (i === index ? { ...p, value } : p))

    return {
      ...report,
      parameters: updated,
      updatedAt: new Date().toISOString(),
      version: report.version + 1,
    } as ReportDefinition
  }

  /**
   * Remove a parameter from a report definition
   */
  static removeParameter(report: ReportDefinition, parameterId: string): ReportDefinition {
    const existing =
      (report as ReportDefinition & { parameters?: ReportParameter[] }).parameters ?? []
    return {
      ...report,
      parameters: existing.filter((p) => p.id !== parameterId),
      updatedAt: new Date().toISOString(),
      version: report.version + 1,
    } as ReportDefinition
  }

  /**
   * Get all parameters for a report
   */
  static getParameters(report: ReportDefinition): ReportParameter[] {
    return (report as ReportDefinition & { parameters?: ReportParameter[] }).parameters ?? []
  }

  // ---------------------------------------------------------------------------
  // Section Management
  // ---------------------------------------------------------------------------

  /**
   * Extract logical sections from a layout based on row types
   */
  static getSections(layout: ReportLayout): ReportSection[] {
    const sections: ReportSection[] = []
    let currentSection: ReportSection | null = null

    for (let i = 0; i < layout.rows.length; i++) {
      const row = layout.rows[i]
      const sectionType = this.rowTypeToSectionType(row.type)

      if (!currentSection || currentSection.type !== sectionType) {
        if (currentSection) {
          currentSection.endRowIndex = i - 1
          sections.push(currentSection)
        }
        currentSection = {
          id: this.generateId(),
          type: sectionType,
          title: this.getSectionTitle(layout, i, sectionType),
          startRowIndex: i,
          endRowIndex: i,
          isCollapsed: false,
        }
      } else {
        currentSection.endRowIndex = i
      }
    }

    if (currentSection) {
      sections.push(currentSection)
    }

    return sections
  }

  private static rowTypeToSectionType(rowType: RowType): ReportSection['type'] {
    switch (rowType) {
      case 'header':
        return 'header'
      case 'data':
        return 'data'
      case 'subtotal':
        return 'subtotal'
      case 'total':
        return 'total'
      case 'blank':
        return 'text'
      default:
        return 'data'
    }
  }

  private static getSectionTitle(
    layout: ReportLayout,
    rowIndex: number,
    sectionType: ReportSection['type']
  ): string {
    const row = layout.rows[rowIndex]
    const labelCell = row.cells.find((_, ci) => layout.columns[ci]?.type === 'label')
    if (labelCell) {
      const textContent = labelCell.content as { content?: { text?: string } }
      if (textContent.content?.text) return textContent.content.text
    }
    return `${sectionType.charAt(0).toUpperCase()}${sectionType.slice(1)} Section`
  }

  // ---------------------------------------------------------------------------
  // Multi-format Export Dispatcher
  // ---------------------------------------------------------------------------

  /**
   * Export a report in the specified format
   */
  static exportReport(
    report: ReportDefinition,
    cubeData: CubeData,
    format: ExportFormat
  ): PDFExportMetadata | ExcelExportResult | CSVExportResult {
    switch (format) {
      case 'pdf':
        return this.generatePDFMetadata(report)
      case 'excel':
        return this.generateExcelExport(report, cubeData)
      case 'csv':
        return this.generateCSVExport(report, cubeData)
      default: {
        const _exhaustive: never = format
        throw new Error(`Unsupported export format: ${_exhaustive}`)
      }
    }
  }
}

import type { GLEntry } from '@/types/sector-types'

export interface StoreStats {
  id: string
  name: string
  revenue: number
  labor: number
  cogs: number
  occupancy: number
  grossProfit: number
  netProfit: number
  margin: number
  laborPercent: number
  rank: number
}

export interface RetailDashboardStats {
  avgRevenuePerStore: number
  avgNetMargin: number
  salesPerLaborHour: number
  avgCustSat: number
}

export class RetailEngine {
  /**
   * Calculates Store Performance metrics from GL entries
   * Assumption:
   * - 4xxx: Revenue
   * - 50xx: COGS
   * - 51xx: Labor Cost
   * - 52xx: Occupancy Cost
   */
  static getStoreBreakdown(entries: GLEntry[]): StoreStats[] {
    const entityIds = Array.from(new Set(entries.map((e) => e.entityId)))

    const stats = entityIds
      .map((id) => {
        const eEntries = entries.filter((e) => e.entityId === id)
        const name = eEntries[0]?.accountName || `Store ${id}`

        const revenue = eEntries
          .filter((e) => e.accountCode.startsWith('4'))
          .reduce((acc, e) => acc + e.amount, 0)
        const cogs = eEntries
          .filter((e) => e.accountCode.startsWith('50'))
          .reduce((acc, e) => acc + e.amount, 0)
        const labor = eEntries
          .filter((e) => e.accountCode.startsWith('51'))
          .reduce((acc, e) => acc + e.amount, 0)
        const occupancy = eEntries
          .filter((e) => e.accountCode.startsWith('52'))
          .reduce((acc, e) => acc + e.amount, 0)

        const grossProfit = revenue - cogs
        const netProfit = revenue - cogs - labor - occupancy
        const margin = revenue > 0 ? (netProfit / revenue) * 100 : 0
        const laborPercent = revenue > 0 ? (labor / revenue) * 100 : 0

        return {
          id,
          name,
          revenue,
          labor,
          cogs,
          occupancy,
          grossProfit,
          netProfit,
          margin,
          laborPercent,
          rank: 0,
        }
      })
      .filter((s) => s.revenue > 0)

    // Rank by Net Profit
    return stats
      .sort((a, b) => b.netProfit - a.netProfit)
      .map((s, i) => ({ ...s, rank: i + 1 })) as any
  }

  static calculateDashboardStats(entries: GLEntry[]): RetailDashboardStats {
    const stores = this.getStoreBreakdown(entries)
    if (stores.length === 0)
      return { avgRevenuePerStore: 0, avgNetMargin: 0, salesPerLaborHour: 0, avgCustSat: 92.8 }

    const totalRevenue = stores.reduce((acc, s) => acc + s.revenue, 0)
    const totalProfit = stores.reduce((acc, s) => acc + s.netProfit, 0)

    return {
      avgRevenuePerStore: totalRevenue / stores.length,
      avgNetMargin: (totalProfit / totalRevenue) * 100,
      salesPerLaborHour: 254, // Needs operational data
      avgCustSat: 92.8,
    }
  }

  static getPnLTrend(entries: GLEntry[]): Array<{
    period: string
    revenue: number
    cogs: number
    grossMargin: number
    opex: number
    ebitda: number
  }> {
    const periods = Array.from(new Set(entries.map((e) => e.date.substring(0, 7)))).sort()
    return periods.slice(-6).map((period) => {
      const pEntries = entries.filter((e) => e.date.startsWith(period))
      const revenue = pEntries
        .filter((e) => e.accountCode.startsWith('4'))
        .reduce((acc, e) => acc + e.amount, 0)
      const cogs = pEntries
        .filter((e) => e.accountCode.startsWith('50'))
        .reduce((acc, e) => acc + e.amount, 0)
      const labor = pEntries
        .filter((e) => e.accountCode.startsWith('51'))
        .reduce((acc, e) => acc + e.amount, 0)

      return {
        month: period,
        revenue,
        grossProfit: revenue - cogs,
        labor,
      }
    }) as any
  }
}

import { describe, it, expect } from 'vitest'
import { RevRecEngine, type Contract, type PerformanceObligation } from './RevRecEngine'

describe('RevRecEngine', () => {
  const baseContract: Contract = {
    id: 'ct-1',
    customerId: 'cust-1',
    startDate: '2024-01-01',
    endDate: '2024-12-31',
    totalValue: 120000,
    performanceObligations: [
      {
        id: 'po-1',
        description: 'Software License',
        standalonePrice: 80000,
        allocationPercentage: 0,
        recognitionMethod: 'point_in_time',
        completionMetric: 1, // ASC 606: must explicitly signal completion for PIT
      },
      {
        id: 'po-2',
        description: 'Support',
        standalonePrice: 40000,
        allocationPercentage: 0,
        recognitionMethod: 'over_time',
      },
    ],
    paymentTerms: 'Net 30',
  }

  describe('allocateTransactionPrice', () => {
    it('should allocate price proportionally', () => {
      const result = RevRecEngine.allocateTransactionPrice(baseContract)
      expect(result[0].allocationPercentage).toBeCloseTo(0.667, 2)
      expect(result[1].allocationPercentage).toBeCloseTo(0.333, 2)
    })

    it('should handle zero total standalone price', () => {
      const contract = {
        ...baseContract,
        performanceObligations: [
          {
            id: 'po-1',
            description: 'Item',
            standalonePrice: 0,
            allocationPercentage: 0,
            recognitionMethod: 'point_in_time' as const,
            completionMetric: 1,
          },
        ],
      }
      const result = RevRecEngine.allocateTransactionPrice(contract)
      expect(result[0].allocationPercentage).toBe(0)
    })
  })

  describe('calculateRevenueSchedule', () => {
    it('should calculate monthly revenue schedule', () => {
      const obligations = baseContract.performanceObligations.map((po) => ({
        ...po,
        allocationPercentage: 0.5,
      }))
      const contract = { ...baseContract, performanceObligations: obligations }
      const periods = ['2024-01', '2024-02', '2024-03']
      const result = RevRecEngine.calculateRevenueSchedule(contract, periods)
      expect(result).toHaveLength(3)
      // allocateTransactionPrice re-calculates: PO-1=80000 (80000/120000*120000), PO-2=40000
      // PIT recognizes 80000 in period 0; OT straight-line = 40000/3 = 13333.33/period
      expect(result[0].amount).toBeCloseTo(93333.33, 0)
      expect(result[2].remainingToRecognize).toBeCloseTo(0, 5)
    })

    it('should handle single period', () => {
      const obligations = baseContract.performanceObligations.map((po) => ({
        ...po,
        allocationPercentage: 0.5,
      }))
      const contract = { ...baseContract, performanceObligations: obligations }
      const result = RevRecEngine.calculateRevenueSchedule(contract, ['2024-01'])
      // PIT recognizes 80000 + OT straight-line 40000 = 120000
      expect(result[0].amount).toBe(120000)
    })

    it('should NOT recognize point-in-time when completionMetric is undefined', () => {
      const contract: Contract = {
        ...baseContract,
        totalValue: 100000,
        performanceObligations: [
          {
            id: 'po-uncompleted',
            description: 'Incomplete delivery',
            standalonePrice: 100000,
            allocationPercentage: 1,
            recognitionMethod: 'point_in_time',
            // completionMetric intentionally omitted — ASC 606 requires explicit signal
          },
        ],
      }
      const periods = ['2024-01', '2024-02']
      const result = RevRecEngine.calculateRevenueSchedule(contract, periods)
      // Should NOT recognize — completionMetric must be explicitly >= 1
      expect(result[0].amount).toBe(0)
      expect(result[1].amount).toBe(0)
      expect(result[0].remainingToRecognize).toBe(100000)
    })

    it('should recognize point-in-time when completionMetric is 1', () => {
      const contract: Contract = {
        ...baseContract,
        totalValue: 50000,
        performanceObligations: [
          {
            id: 'po-completed',
            description: 'Delivered software',
            standalonePrice: 50000,
            allocationPercentage: 1,
            recognitionMethod: 'point_in_time',
            completionMetric: 1,
          },
        ],
      }
      const periods = ['2024-01', '2024-02']
      const result = RevRecEngine.calculateRevenueSchedule(contract, periods)
      expect(result[0].amount).toBe(50000)
      expect(result[1].amount).toBe(0)
      expect(result[0].remainingToRecognize).toBe(0)
    })
  })

  describe('handleContractModification', () => {
    it('should add modification and update total value', () => {
      const mod = { date: '2024-06-01', type: 'additional_goods' as const, value: 30000 }
      const updated = RevRecEngine.handleContractModification(baseContract, mod)
      expect(updated.totalValue).toBe(150000)
      expect(updated.contractModifications).toHaveLength(1)
    })

    it('should handle discount modification', () => {
      const mod = { date: '2024-06-01', type: 'discount' as const, value: -10000 }
      const updated = RevRecEngine.handleContractModification(baseContract, mod)
      expect(updated.totalValue).toBe(110000)
    })

    it('should handle termination modification', () => {
      const mod = { date: '2024-06-01', type: 'termination' as const, value: -50000 }
      const updated = RevRecEngine.handleContractModification(baseContract, mod)
      expect(updated.totalValue).toBe(70000)
    })

    it('should not allow negative total value on termination', () => {
      const mod = { date: '2024-06-01', type: 'termination' as const, value: -200000 }
      const updated = RevRecEngine.handleContractModification(baseContract, mod)
      expect(updated.totalValue).toBe(0)
    })

    it('should not mutate original contract', () => {
      const mod = { date: '2024-06-01', type: 'extension' as const, value: 10000 }
      RevRecEngine.handleContractModification(baseContract, mod)
      expect(baseContract.totalValue).toBe(120000)
    })
  })

  describe('getContractAssetLiability', () => {
    it('should calculate contract liability (deferred revenue) when billed > recognized', () => {
      const schedules = [
        { period: '2024-01', amount: 10000, recognizedToDate: 10000, remainingToRecognize: 90000 },
        { period: '2024-02', amount: 10000, recognizedToDate: 20000, remainingToRecognize: 80000 },
      ]
      const billed = new Map([
        ['2024-01', 50000],
        ['2024-02', 0],
      ])
      const result = RevRecEngine.getContractAssetLiability('ct-1', schedules, billed, [
        '2024-01',
        '2024-02',
      ])
      expect(result[0].contractLiability).toBe(40000) // 50000 billed - 10000 recognized
      expect(result[0].contractAsset).toBe(0)
    })

    it('should calculate contract asset (unbilled) when recognized > billed', () => {
      const schedules = [
        { period: '2024-01', amount: 50000, recognizedToDate: 50000, remainingToRecognize: 50000 },
      ]
      const billed = new Map([['2024-01', 10000]])
      const result = RevRecEngine.getContractAssetLiability('ct-1', schedules, billed, ['2024-01'])
      expect(result[0].contractAsset).toBe(40000) // 50000 recognized - 10000 billed
      expect(result[0].contractLiability).toBe(0)
    })
  })

  describe('constrainVariableConsideration', () => {
    it('should include variable consideration when reversal probability is low', () => {
      // probabilityOfReversal = 0.3 (low), variableAmount = 10000
      const result = RevRecEngine.constrainVariableConsideration(10000, 0.3)
      expect(result).toBeCloseTo(7000, 0) // 10000 * (1 - 0.3) = 7000
    })

    it('should constrain variable consideration when reversal probability is high', () => {
      // probabilityOfReversal = 0.8 (> threshold 0.75)
      const result = RevRecEngine.constrainVariableConsideration(10000, 0.8)
      expect(result).toBe(0) // Constrained — too likely to reverse
    })

    it('should respect custom constraint threshold', () => {
      // threshold = 0.9, probability = 0.85
      const result = RevRecEngine.constrainVariableConsideration(10000, 0.85, 0.9)
      expect(result).toBeCloseTo(1500, 0) // 10000 * (1 - 0.85) = 1500
    })
  })

  describe('getDeferredRevenue', () => {
    it('should return remaining to recognize for a given date', () => {
      const schedules = [
        { period: '2024-01', amount: 10000, recognizedToDate: 10000, remainingToRecognize: 90000 },
        { period: '2024-02', amount: 10000, recognizedToDate: 20000, remainingToRecognize: 80000 },
      ]
      expect(RevRecEngine.getDeferredRevenue(schedules, '2024-01')).toBe(90000)
    })

    it('should return 0 if no schedules match', () => {
      expect(RevRecEngine.getDeferredRevenue([], '2024-01')).toBe(0)
    })
  })
})

export interface PerformanceObligation {
  id: string
  description: string
  standalonePrice: number
  allocationPercentage: number
  recognitionMethod: 'point_in_time' | 'over_time'
  recognitionPattern?: 'straight_line' | 'input' | 'output'
  completionMetric?: number // 0 to 1
  recognitionDate?: string // YYYY-MM-DD for PIT
}

export interface ContractModification {
  date: string
  type: 'additional_goods' | 'extension' | 'discount' | 'termination'
  value: number
}

export interface Contract {
  id: string
  customerId: string
  startDate: string
  endDate: string
  totalValue: number
  performanceObligations: PerformanceObligation[]
  paymentTerms: string
  contractModifications?: ContractModification[]
}

export interface RevenueSchedule {
  period: string
  amount: number
  recognizedToDate: number
  remainingToRecognize: number
}

export interface ContractAssetLiability {
  contractId: string
  period: string
  contractAsset: number // unbilled receivable (recognized > billed)
  contractLiability: number // deferred revenue (billed > recognized)
  netPosition: number
}

export class RevRecEngine {
  static allocateTransactionPrice(contract: Contract): PerformanceObligation[] {
    if (!contract || !Array.isArray(contract.performanceObligations)) {
      return []
    }
    const totalStandalone = contract.performanceObligations.reduce(
      (acc, po) => acc + (Number.isFinite(po.standalonePrice) ? po.standalonePrice : 0),
      0
    )
    if (totalStandalone === 0) return contract.performanceObligations

    return contract.performanceObligations.map((po) => ({
      ...po,
      allocationPercentage: po.standalonePrice / totalStandalone,
    }))
  }

  static calculateRevenueSchedule(contract: Contract, periods: string[]): RevenueSchedule[] {
    const schedules: RevenueSchedule[] = []

    // Allocate transaction price across obligations first
    const allocatedPOs = RevRecEngine.allocateTransactionPrice(contract)

    const totalContractValue = contract.totalValue
    let totalRecognizedSoFar = 0

    const poRecognitionState = new Map<string, number>() // poId -> recognizedAmount
    const poCompletionHistory = new Map<string, number[]>() // poId -> completion metrics per period

    periods.forEach((period, periodIndex) => {
      let periodAmount = 0

      allocatedPOs.forEach((po) => {
        const allocatedValue = totalContractValue * po.allocationPercentage
        const alreadyRecognized = poRecognitionState.get(po.id) || 0

        if (po.recognitionMethod === 'point_in_time') {
          // Point-in-Time: Recognize full allocated value when recognitionDate is reached AND completionMetric is 1
          const recognitionPeriod = po.recognitionDate
            ? po.recognitionDate.slice(0, 7)
            : contract.startDate.slice(0, 7)
          // Require explicit completion (completionMetric must be exactly 1, not undefined)
          const isCompleted = po.completionMetric !== undefined && po.completionMetric >= 1

          if (period === recognitionPeriod && isCompleted && alreadyRecognized === 0) {
            const amountToRecognize = allocatedValue
            periodAmount += amountToRecognize
            poRecognitionState.set(po.id, alreadyRecognized + amountToRecognize)
          }
        } else if (po.recognitionMethod === 'over_time') {
          const pattern = po.recognitionPattern || 'straight_line'
          if (pattern === 'straight_line') {
            // Straight-line over periods between start and end date
            const startPeriod = contract.startDate.slice(0, 7)
            const endPeriod = contract.endDate.slice(0, 7)

            if (period >= startPeriod && period <= endPeriod) {
              const contractPeriods = periods.filter((p) => p >= startPeriod && p <= endPeriod)
              const monthlyAmount = allocatedValue / Math.max(1, contractPeriods.length)

              // Ensure we don't over-recognize
              const amountToRecognize = Math.min(monthlyAmount, allocatedValue - alreadyRecognized)
              if (amountToRecognize > 0) {
                periodAmount += amountToRecognize
                poRecognitionState.set(po.id, alreadyRecognized + amountToRecognize)
              }
            }
          } else if (pattern === 'output' || pattern === 'input') {
            // Percentage of Completion (POC) — cumulative method
            // Track completion metrics over time for proper cumulative recognition
            const currentMetric = po.completionMetric || 0
            const history = poCompletionHistory.get(po.id) || []
            history.push(currentMetric)
            poCompletionHistory.set(po.id, history)

            // Use the highest completion metric seen so far (cumulative, non-decreasing)
            const cumulativeCompletion = Math.max(...history)
            const targetTotalRecognition = allocatedValue * cumulativeCompletion
            const amountToRecognize = Math.max(0, targetTotalRecognition - alreadyRecognized)

            if (amountToRecognize > 0) {
              periodAmount += amountToRecognize
              poRecognitionState.set(po.id, alreadyRecognized + amountToRecognize)
            }
          }
        }
      })

      totalRecognizedSoFar += periodAmount
      schedules.push({
        period,
        amount: periodAmount,
        recognizedToDate: totalRecognizedSoFar,
        remainingToRecognize: Math.max(0, totalContractValue - totalRecognizedSoFar),
      })
    })

    return schedules
  }

  static handleContractModification(contract: Contract, mod: ContractModification): Contract {
    const updatedContract = JSON.parse(JSON.stringify(contract)) as Contract
    if (!updatedContract.contractModifications) updatedContract.contractModifications = []
    updatedContract.contractModifications.push(mod)

    // ASC 606 contract modification accounting:
    // - 'termination': reduce value
    // - 'discount': reduce value (prospective or cumulative catch-up)
    // - 'additional_goods': treat as separate contract if priced at standalone selling price
    // - 'extension': treat as termination of old + creation of new contract (prospective)
    switch (mod.type) {
      case 'termination':
        updatedContract.totalValue = Math.max(0, updatedContract.totalValue + mod.value)
        break
      case 'discount':
        // Apply discount (mod.value should be negative for discounts)
        updatedContract.totalValue = Math.max(0, updatedContract.totalValue + mod.value)
        break
      case 'additional_goods':
        // If priced at standalone selling price, treat as separate contract
        // Otherwise, treat as modification of existing contract (cumulative catch-up)
        updatedContract.totalValue += mod.value
        break
      case 'extension':
        // Extend contract and add value
        updatedContract.totalValue += mod.value
        break
      default:
        updatedContract.totalValue += mod.value
    }

    return updatedContract
  }

  static getContractAssetLiability(
    contractId: string,
    schedules: RevenueSchedule[],
    billedAmounts: Map<string, number>, // period -> billed amount
    periods: string[]
  ): ContractAssetLiability[] {
    const results: ContractAssetLiability[] = []
    let cumulativeRecognized = 0
    let cumulativeBilled = 0

    periods.forEach((period) => {
      const schedule = schedules.find((s) => s.period === period)
      const billed = billedAmounts.get(period) || 0

      cumulativeRecognized += schedule?.amount || 0
      cumulativeBilled += billed

      const contractAsset = Math.max(0, cumulativeRecognized - cumulativeBilled) // unbilled
      const contractLiability = Math.max(0, cumulativeBilled - cumulativeRecognized) // deferred

      results.push({
        contractId,
        period,
        contractAsset,
        contractLiability,
        netPosition: contractAsset - contractLiability,
      })
    })

    return results
  }

  static constrainVariableConsideration(
    variableAmount: number,
    probabilityOfReversal: number,
    constraintThreshold: number = 0.75
  ): number {
    // ASC 606-10-32-11: Constrain variable consideration to amounts
    // for which it is probable that a significant reversal will not occur
    // probabilityOfReversal: 0 = no reversal likely, 1 = reversal certain
    if (probabilityOfReversal >= constraintThreshold) {
      return 0 // Constrain — don't include in transaction price
    }
    return variableAmount * (1 - probabilityOfReversal)
  }

  static getDeferredRevenue(schedules: RevenueSchedule[], asOfDate: string): number {
    const lastSchedule = schedules
      .filter((s) => s.period <= asOfDate)
      .sort((a, b) => b.period.localeCompare(a.period))[0]

    return lastSchedule ? lastSchedule.remainingToRecognize : 0
  }
}

