import { describe, it, expect, beforeEach } from 'vitest'
import { WhatIfSandboxEngine, type Sandbox, type SandboxComparison } from './WhatIfSandboxEngine'

describe('WhatIfSandboxEngine', () => {
  let engine: WhatIfSandboxEngine
  let baseCells: Map<string, number>

  beforeEach(() => {
    engine = new WhatIfSandboxEngine()
    baseCells = new Map([
      ['Budget|Account=Account:Revenue|Scenario=Scenario:Budget|amount', 1000000],
      ['Budget|Account=Account:COGS|Scenario=Scenario:Budget|amount', 600000],
      ['Budget|Account=Account:OpEx|Scenario=Scenario:Budget|amount', 300000],
      ['Budget|Account=Account:EBITDA|Scenario=Scenario:Budget|amount', 100000],
    ])
  })

  // ---------------------------------------------------------------------------
  // Sandbox Management
  // ---------------------------------------------------------------------------

  describe('Sandbox Management', () => {
    it('should create a sandbox', () => {
      const sandbox = engine.createSandbox('Base Case', 'Budget assumptions', 'snap-1', baseCells)
      expect(sandbox.id).toBeDefined()
      expect(sandbox.name).toBe('Base Case')
      expect(sandbox.status).toBe('draft')
      expect(sandbox.modifications).toHaveLength(0)
    })

    it('should get a sandbox', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      expect(engine.getSandbox(sandbox.id)).toBeDefined()
    })

    it('should list sandboxes', () => {
      engine.createSandbox('A', undefined, 'snap-1', baseCells)
      engine.createSandbox('B', undefined, 'snap-1', baseCells)
      expect(engine.listSandboxes()).toHaveLength(2)
    })

    it('should delete a sandbox', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      expect(engine.deleteSandbox(sandbox.id)).toBe(true)
      expect(engine.getSandbox(sandbox.id)).toBeUndefined()
    })

    it('should return false when deleting non-existent sandbox', () => {
      expect(engine.deleteSandbox('non-existent')).toBe(false)
    })

    it('should archive a sandbox', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      const archived = engine.archiveSandbox(sandbox.id)
      expect(archived?.status).toBe('archived')
    })

    it('should return undefined when archiving non-existent sandbox', () => {
      expect(engine.archiveSandbox('non-existent')).toBeUndefined()
    })
  })

  // ---------------------------------------------------------------------------
  // Modifications
  // ---------------------------------------------------------------------------

  describe('Modifications', () => {
    it('should apply a modification', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      const mod = engine.applyModification(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )

      expect(mod.id).toBeDefined()
      expect(mod.originalValue).toBe(1000000)
      expect(mod.modifiedValue).toBe(1200000)
    })

    it('should update sandbox after modification', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      engine.applyModification(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )

      const updated = engine.getSandbox(sandbox.id)
      expect(updated?.modifications).toHaveLength(1)
    })

    it('should throw when modifying non-existent sandbox', () => {
      expect(() => engine.applyModification('non-existent', 'Budget', {}, 'amount', 100)).toThrow()
    })

    it('should remove a modification', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      const mod = engine.applyModification(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )

      expect(engine.removeModification(sandbox.id, mod.id)).toBe(true)
      expect(engine.getModifications(sandbox.id)).toHaveLength(0)
    })

    it('should restore original value when removing modification', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      const mod = engine.applyModification(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )

      engine.removeModification(sandbox.id, mod.id)

      const value = engine.getCellValue(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount'
      )
      expect(value).toBe(1000000)
    })

    it('should return false when removing non-existent modification', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      expect(engine.removeModification(sandbox.id, 'non-existent')).toBe(false)
    })

    it('should get modifications for a sandbox', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      engine.applyModification(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )
      engine.applyModification(
        sandbox.id,
        'Budget',
        { Account: 'Account:COGS', Scenario: 'Scenario:Budget' },
        'amount',
        700000
      )

      expect(engine.getModifications(sandbox.id)).toHaveLength(2)
    })

    it('should apply batch modifications', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      const mods = engine.applyBatchModifications(sandbox.id, [
        {
          cube: 'Budget',
          coords: { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
          measure: 'amount',
          newValue: 1200000,
        },
        {
          cube: 'Budget',
          coords: { Account: 'Account:COGS', Scenario: 'Scenario:Budget' },
          measure: 'amount',
          newValue: 700000,
        },
      ])

      expect(mods).toHaveLength(2)
      expect(engine.getModifications(sandbox.id)).toHaveLength(2)
    })
  })

  // ---------------------------------------------------------------------------
  // Cell Access
  // ---------------------------------------------------------------------------

  describe('Cell Access', () => {
    it('should get cell value from sandbox', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      const value = engine.getCellValue(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount'
      )
      expect(value).toBe(1000000)
    })

    it('should return undefined for non-existent cell', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      const value = engine.getCellValue(
        sandbox.id,
        'Budget',
        { Account: 'Account:Missing' },
        'amount'
      )
      expect(value).toBeUndefined()
    })

    it('should return undefined for non-existent sandbox', () => {
      const value = engine.getCellValue('non-existent', 'Budget', {}, 'amount')
      expect(value).toBeUndefined()
    })

    it('should get modified cells', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      engine.applyModification(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )

      const modified = engine.getModifiedCells(sandbox.id)
      expect(modified.size).toBe(1)
      expect(modified.values().next().value).toEqual({ original: 1000000, modified: 1200000 })
    })

    it('should return empty map for sandbox with no modifications', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      expect(engine.getModifiedCells(sandbox.id).size).toBe(0)
    })
  })

  // ---------------------------------------------------------------------------
  // Comparison
  // ---------------------------------------------------------------------------

  describe('Comparison', () => {
    it('should compare two sandboxes', () => {
      const sandboxA = engine.createSandbox('Base Case', undefined, 'snap-1', baseCells)
      const sandboxB = engine.createSandbox('Optimistic', undefined, 'snap-1', baseCells)

      engine.applyModification(
        sandboxB.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )

      const comparison = engine.compare(sandboxA.id, sandboxB.id)
      expect(comparison.differences).toHaveLength(1)
      expect(comparison.differences[0].delta).toBe(200000)
      expect(comparison.summary.totalDifferences).toBe(1)
    })

    it('should throw when comparing sandboxes without snapshots', () => {
      // This shouldn't happen in practice, but test the guard
      expect(() => engine.compare('non-existent-a', 'non-existent-b')).toThrow()
    })

    it('should calculate summary correctly', () => {
      const sandboxA = engine.createSandbox('Base', undefined, 'snap-1', baseCells)
      const sandboxB = engine.createSandbox('Modified', undefined, 'snap-1', baseCells)

      engine.applyModification(
        sandboxB.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )
      engine.applyModification(
        sandboxB.id,
        'Budget',
        { Account: 'Account:COGS', Scenario: 'Scenario:Budget' },
        'amount',
        500000
      )

      const comparison = engine.compare(sandboxA.id, sandboxB.id)
      expect(comparison.summary.totalDifferences).toBe(2)
      expect(comparison.summary.largestDelta?.delta).toBe(200000)
      expect(comparison.summary.averageDelta).toBe(50000) // (200000 + -100000) / 2
    })

    it('should return empty comparison for identical sandboxes', () => {
      const sandboxA = engine.createSandbox('A', undefined, 'snap-1', baseCells)
      const sandboxB = engine.createSandbox('B', undefined, 'snap-1', baseCells)

      const comparison = engine.compare(sandboxA.id, sandboxB.id)
      expect(comparison.differences).toHaveLength(0)
      expect(comparison.summary.totalDifferences).toBe(0)
      expect(comparison.summary.largestDelta).toBeNull()
    })

    it('should cache comparison results', () => {
      const sandboxA = engine.createSandbox('A', undefined, 'snap-1', baseCells)
      const sandboxB = engine.createSandbox('B', undefined, 'snap-1', baseCells)

      const comparison1 = engine.compare(sandboxA.id, sandboxB.id)
      const comparison2 = engine.compare(sandboxA.id, sandboxB.id)
      expect(comparison1).toBe(comparison2) // Same reference
    })

    it('should invalidate cache when modification applied', () => {
      const sandboxA = engine.createSandbox('A', undefined, 'snap-1', baseCells)
      const sandboxB = engine.createSandbox('B', undefined, 'snap-1', baseCells)

      engine.compare(sandboxA.id, sandboxB.id)

      engine.applyModification(
        sandboxB.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )

      const comparison = engine.compare(sandboxA.id, sandboxB.id)
      expect(comparison.differences).toHaveLength(1)
    })

    it('should sort differences by absolute delta', () => {
      const sandboxA = engine.createSandbox('A', undefined, 'snap-1', baseCells)
      const sandboxB = engine.createSandbox('B', undefined, 'snap-1', baseCells)

      engine.applyModification(
        sandboxB.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )
      engine.applyModification(
        sandboxB.id,
        'Budget',
        { Account: 'Account:COGS', Scenario: 'Scenario:Budget' },
        'amount',
        500000
      )

      const comparison = engine.compare(sandboxA.id, sandboxB.id)
      expect(comparison.differences[0].delta).toBe(200000) // Revenue: largest delta
      expect(comparison.differences[1].delta).toBe(-100000) // COGS: second largest
    })
  })

  // ---------------------------------------------------------------------------
  // Clone
  // ---------------------------------------------------------------------------

  describe('Clone', () => {
    it('should clone a sandbox', () => {
      const sandbox = engine.createSandbox('Original', 'Base case', 'snap-1', baseCells)
      engine.applyModification(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )

      const clone = engine.cloneSandbox(sandbox.id, 'Cloned')
      expect(clone.id).not.toBe(sandbox.id)
      expect(clone.name).toBe('Cloned')
      expect(clone.modifications).toHaveLength(1)
    })

    it('should have same cell values as source', () => {
      const sandbox = engine.createSandbox('Original', undefined, 'snap-1', baseCells)
      engine.applyModification(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )

      const clone = engine.cloneSandbox(sandbox.id, 'Cloned')
      const value = engine.getCellValue(
        clone.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount'
      )
      expect(value).toBe(1200000)
    })

    it('should throw when cloning non-existent sandbox', () => {
      expect(() => engine.cloneSandbox('non-existent', 'Clone')).toThrow()
    })
  })

  // ---------------------------------------------------------------------------
  // Export/Import
  // ---------------------------------------------------------------------------

  describe('Export/Import', () => {
    it('should export and import state', () => {
      engine.createSandbox('A', undefined, 'snap-1', baseCells)
      engine.createSandbox('B', undefined, 'snap-1', baseCells)

      const state = engine.exportState()
      expect(state.sandboxes).toHaveLength(2)

      const newEngine = new WhatIfSandboxEngine()
      newEngine.importState(state)
      expect(newEngine.listSandboxes()).toHaveLength(2)
    })

    it('should preserve cell values after import', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells)
      engine.applyModification(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount',
        1200000
      )

      const state = engine.exportState()
      const newEngine = new WhatIfSandboxEngine()
      newEngine.importState(state)

      const value = newEngine.getCellValue(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
        'amount'
      )
      expect(value).toBe(1200000)
    })
  })

  // ---------------------------------------------------------------------------
  // Reset
  // ---------------------------------------------------------------------------

  describe('Reset', () => {
    it('should reset all state', () => {
      engine.createSandbox('A', undefined, 'snap-1', baseCells)
      engine.createSandbox('B', undefined, 'snap-1', baseCells)

      engine.reset()
      expect(engine.listSandboxes()).toHaveLength(0)
    })
  })
})

// =============================================================================
// WHAT-IF SANDBOX ENGINE — Isolated scenario comparison
// Create sandboxes, modify assumptions, compare results side-by-side
// Uses CubeEngine snapshots for isolation
// =============================================================================

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface Sandbox {
  id: string
  name: string
  description?: string
  baseSnapshotId: string
  modifications: SandboxModification[]
  createdAt: string
  updatedAt: string
  status: 'draft' | 'active' | 'archived'
}

export interface SandboxModification {
  id: string
  cube: string
  coords: Record<string, string>
  measure: string
  originalValue: number
  modifiedValue: number
  appliedAt: string
}

export interface SandboxComparison {
  sandboxA: string
  sandboxB: string
  differences: ComparisonDifference[]
  summary: ComparisonSummary
}

export interface ComparisonDifference {
  cube: string
  coords: Record<string, string>
  measure: string
  valueA: number
  valueB: number
  delta: number
  percentChange: number
}

export interface ComparisonSummary {
  totalDifferences: number
  largestDelta: ComparisonDifference | null
  largestPercentChange: ComparisonDifference | null
  averageDelta: number
  averagePercentChange: number
}

export interface SandboxSnapshot {
  sandboxId: string
  cellValues: Map<string, number>
  timestamp: string
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function cellKey(cube: string, coords: Record<string, string>, measure: string): string {
  const sortedCoords = Object.keys(coords)
    .sort()
    .map((k) => `${k}=${coords[k]}`)
    .join('|')
  return `${cube}|${sortedCoords}|${measure}`
}

function generateId(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
}

// ---------------------------------------------------------------------------
// ENGINE
// ---------------------------------------------------------------------------

export class WhatIfSandboxEngine {
  private sandboxes = new Map<string, Sandbox>()
  private snapshots = new Map<string, SandboxSnapshot>()
  private comparisonCache = new Map<string, SandboxComparison>()

  // --- Sandbox Management ---

  createSandbox(
    name: string,
    description: string | undefined,
    baseSnapshotId: string,
    baseCells: Map<string, number>
  ): Sandbox {
    const id = generateId('sandbox')
    const now = new Date().toISOString()

    const sandbox: Sandbox = {
      id,
      name,
      description,
      baseSnapshotId,
      modifications: [],
      createdAt: now,
      updatedAt: now,
      status: 'draft',
    }

    this.sandboxes.set(id, sandbox)

    // Store base snapshot
    const snapshot: SandboxSnapshot = {
      sandboxId: id,
      cellValues: new Map(baseCells),
      timestamp: now,
    }
    this.snapshots.set(id, snapshot)

    return sandbox
  }

  getSandbox(id: string): Sandbox | undefined {
    return this.sandboxes.get(id)
  }

  listSandboxes(): Sandbox[] {
    return Array.from(this.sandboxes.values())
  }

  deleteSandbox(id: string): boolean {
    const existed = this.sandboxes.delete(id)
    if (existed) {
      this.snapshots.delete(id)
      // Clear comparison cache entries involving this sandbox
      for (const [key, comp] of this.comparisonCache) {
        if (comp.sandboxA === id || comp.sandboxB === id) {
          this.comparisonCache.delete(key)
        }
      }
    }
    return existed
  }

  archiveSandbox(id: string): Sandbox | undefined {
    const sandbox = this.sandboxes.get(id)
    if (!sandbox) return undefined
    sandbox.status = 'archived'
    sandbox.updatedAt = new Date().toISOString()
    return sandbox
  }

  // --- Modifications ---

  applyModification(
    sandboxId: string,
    cube: string,
    coords: Record<string, string>,
    measure: string,
    newValue: number
  ): SandboxModification {
    const sandbox = this.sandboxes.get(sandboxId)
    if (!sandbox) throw new Error(`Sandbox "${sandboxId}" not found`)

    const snapshot = this.snapshots.get(sandboxId)
    if (!snapshot) throw new Error(`Snapshot for sandbox "${sandboxId}" not found`)

    const key = cellKey(cube, coords, measure)
    const originalValue = snapshot.cellValues.get(key) ?? 0

    const modification: SandboxModification = {
      id: generateId('mod'),
      cube,
      coords,
      measure,
      originalValue,
      modifiedValue: newValue,
      appliedAt: new Date().toISOString(),
    }

    sandbox.modifications.push(modification)
    sandbox.updatedAt = new Date().toISOString()

    // Update snapshot
    snapshot.cellValues.set(key, newValue)

    // Invalidate comparison cache
    this.comparisonCache.clear()

    return modification
  }

  removeModification(sandboxId: string, modificationId: string): boolean {
    const sandbox = this.sandboxes.get(sandboxId)
    if (!sandbox) return false

    const idx = sandbox.modifications.findIndex((m) => m.id === modificationId)
    if (idx === -1) return false

    const mod = sandbox.modifications[idx]

    // Restore original value in snapshot
    const snapshot = this.snapshots.get(sandboxId)
    if (snapshot) {
      const key = cellKey(mod.cube, mod.coords, mod.measure)
      snapshot.cellValues.set(key, mod.originalValue)
    }

    sandbox.modifications.splice(idx, 1)
    sandbox.updatedAt = new Date().toISOString()

    // Invalidate comparison cache
    this.comparisonCache.clear()

    return true
  }

  getModifications(sandboxId: string): SandboxModification[] {
    const sandbox = this.sandboxes.get(sandboxId)
    return sandbox?.modifications ?? []
  }

  // --- Cell Access ---

  getCellValue(
    sandboxId: string,
    cube: string,
    coords: Record<string, string>,
    measure: string
  ): number | undefined {
    const snapshot = this.snapshots.get(sandboxId)
    if (!snapshot) return undefined
    const key = cellKey(cube, coords, measure)
    return snapshot.cellValues.get(key)
  }

  getModifiedCells(sandboxId: string): Map<string, { original: number; modified: number }> {
    const sandbox = this.sandboxes.get(sandboxId)
    if (!sandbox) return new Map()

    const result = new Map<string, { original: number; modified: number }>()
    for (const mod of sandbox.modifications) {
      const key = cellKey(mod.cube, mod.coords, mod.measure)
      result.set(key, { original: mod.originalValue, modified: mod.modifiedValue })
    }
    return result
  }

  // --- Comparison ---

  compare(sandboxAId: string, sandboxBId: string): SandboxComparison {
    const cacheKey = [sandboxAId, sandboxBId].sort().join('|')
    const cached = this.comparisonCache.get(cacheKey)
    if (cached) return cached

    const snapshotA = this.snapshots.get(sandboxAId)
    const snapshotB = this.snapshots.get(sandboxBId)
    if (!snapshotA || !snapshotB) {
      throw new Error('Both sandboxes must have snapshots for comparison')
    }

    const differences: ComparisonDifference[] = []

    // Compare all cells in A against B
    for (const [key, valueA] of snapshotA.cellValues) {
      const valueB = snapshotB.cellValues.get(key)
      if (valueB === undefined) continue

      const delta = valueB - valueA
      const percentChange = valueA !== 0 ? (delta / Math.abs(valueA)) * 100 : 0

      if (Math.abs(delta) > 0.0001) {
        const [cube, coordsStr, measure] = this.parseCellKey(key)
        const coords = this.parseCoords(coordsStr)

        differences.push({
          cube,
          coords,
          measure,
          valueA,
          valueB,
          delta: Math.round(delta * 100) / 100,
          percentChange: Math.round(percentChange * 100) / 100,
        })
      }
    }

    // Also check cells in B that aren't in A
    for (const [key, valueB] of snapshotB.cellValues) {
      if (!snapshotA.cellValues.has(key)) {
        const [cube, coordsStr, measure] = this.parseCellKey(key)
        const coords = this.parseCoords(coordsStr)

        differences.push({
          cube,
          coords,
          measure,
          valueA: 0,
          valueB,
          delta: valueB,
          percentChange: 100,
        })
      }
    }

    // Sort by absolute delta descending
    differences.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta))

    const summary = this.calculateSummary(differences)

    const comparison: SandboxComparison = {
      sandboxA: sandboxAId,
      sandboxB: sandboxBId,
      differences,
      summary,
    }

    this.comparisonCache.set(cacheKey, comparison)

    return comparison
  }

  private parseCellKey(key: string): [string, string, string] {
    const parts = key.split('|')
    const measure = parts.pop()!
    const coordsStr = parts.slice(1).join('|')
    const cube = parts[0]
    return [cube, coordsStr, measure]
  }

  private parseCoords(coordsStr: string): Record<string, string> {
    const coords: Record<string, string> = {}
    for (const part of coordsStr.split('|')) {
      const [key, value] = part.split('=')
      if (key && value) {
        coords[key] = value
      }
    }
    return coords
  }

  private calculateSummary(differences: ComparisonDifference[]): ComparisonSummary {
    if (differences.length === 0) {
      return {
        totalDifferences: 0,
        largestDelta: null,
        largestPercentChange: null,
        averageDelta: 0,
        averagePercentChange: 0,
      }
    }

    const totalDelta = differences.reduce((sum, d) => sum + d.delta, 0)
    const totalPercent = differences.reduce((sum, d) => sum + d.percentChange, 0)

    return {
      totalDifferences: differences.length,
      largestDelta: differences[0], // Already sorted by abs(delta)
      largestPercentChange: [...differences].sort(
        (a, b) => Math.abs(b.percentChange) - Math.abs(a.percentChange)
      )[0],
      averageDelta: Math.round((totalDelta / differences.length) * 100) / 100,
      averagePercentChange: Math.round((totalPercent / differences.length) * 100) / 100,
    }
  }

  // --- Batch Operations ---

  applyBatchModifications(
    sandboxId: string,
    modifications: Array<{
      cube: string
      coords: Record<string, string>
      measure: string
      newValue: number
    }>
  ): SandboxModification[] {
    return modifications.map((m) =>
      this.applyModification(sandboxId, m.cube, m.coords, m.measure, m.newValue)
    )
  }

  // --- Clone ---

  cloneSandbox(sourceId: string, newName: string): Sandbox {
    const source = this.sandboxes.get(sourceId)
    if (!source) throw new Error(`Source sandbox "${sourceId}" not found`)

    const sourceSnapshot = this.snapshots.get(sourceId)
    if (!sourceSnapshot) throw new Error(`Source snapshot not found`)

    // Create new sandbox with current cell values
    const newSandbox = this.createSandbox(
      newName,
      `Cloned from ${source.name}`,
      source.baseSnapshotId,
      sourceSnapshot.cellValues
    )

    // Re-apply modifications to maintain modification history
    for (const mod of source.modifications) {
      this.applyModification(newSandbox.id, mod.cube, mod.coords, mod.measure, mod.modifiedValue)
    }

    return newSandbox
  }

  // --- Export/Import ---

  exportState(): {
    sandboxes: Sandbox[]
    snapshots: Array<{ sandboxId: string; cellValues: Array<[string, number]>; timestamp: string }>
  } {
    return {
      sandboxes: this.listSandboxes(),
      snapshots: Array.from(this.snapshots.entries()).map(([id, snap]) => ({
        sandboxId: snap.sandboxId,
        cellValues: Array.from(snap.cellValues.entries()),
        timestamp: snap.timestamp,
      })),
    }
  }

  importState(state: {
    sandboxes: Sandbox[]
    snapshots: Array<{ sandboxId: string; cellValues: Array<[string, number]>; timestamp: string }>
  }): void {
    this.sandboxes.clear()
    this.snapshots.clear()
    this.comparisonCache.clear()

    for (const sandbox of state.sandboxes) {
      this.sandboxes.set(sandbox.id, sandbox)
    }

    for (const snap of state.snapshots) {
      this.snapshots.set(snap.sandboxId, {
        sandboxId: snap.sandboxId,
        cellValues: new Map(snap.cellValues),
        timestamp: snap.timestamp,
      })
    }
  }

  // --- Reset ---

  reset(): void {
    this.sandboxes.clear()
    this.snapshots.clear()
    this.comparisonCache.clear()
  }
}

import { describe, it, expect, beforeEach } from 'vitest'
import {
  WorkflowBuilderEngine,
  type WorkflowNode,
  type WorkflowEdge,
} from './WorkflowBuilderEngine'

describe('WorkflowBuilderEngine', () => {
  let engine: WorkflowBuilderEngine

  beforeEach(() => {
    engine = new WorkflowBuilderEngine()
  })

  it('should create a workflow', () => {
    const wf = engine.createWorkflow('Budget Approval', 'Standard approval workflow')
    expect(wf.id).toBeDefined()
    expect(wf.nodes).toHaveLength(2) // start + end
  })

  it('should list workflows', () => {
    engine.createWorkflow('W1', 'test')
    engine.createWorkflow('W2', 'test')
    expect(engine.listWorkflows()).toHaveLength(2)
  })

  it('should delete a workflow', () => {
    const wf = engine.createWorkflow('Test', 'test')
    expect(engine.deleteWorkflow(wf.id)).toBe(true)
    expect(engine.getWorkflow(wf.id)).toBeUndefined()
  })

  it('should add nodes', () => {
    const wf = engine.createWorkflow('Test', 'test')
    const node: WorkflowNode = {
      id: 'task1',
      type: 'task',
      label: 'Review',
      config: {},
      x: 100,
      y: 0,
    }
    expect(engine.addNode(wf.id, node)).toBe(true)
    expect(engine.getWorkflow(wf.id)?.nodes).toHaveLength(3)
  })

  it('should remove nodes and connected edges', () => {
    const wf = engine.createWorkflow('Test', 'test')
    engine.addNode(wf.id, { id: 'task1', type: 'task', label: 'Review', config: {}, x: 100, y: 0 })
    engine.addEdge(wf.id, { id: 'e1', sourceId: 'start', targetId: 'task1', type: 'sequential' })
    engine.addEdge(wf.id, { id: 'e2', sourceId: 'task1', targetId: 'end', type: 'sequential' })
    engine.removeNode(wf.id, 'task1')
    const wf2 = engine.getWorkflow(wf.id)!
    expect(wf2.nodes).toHaveLength(2)
    expect(wf2.edges).toHaveLength(0)
  })

  it('should add edges', () => {
    const wf = engine.createWorkflow('Test', 'test')
    engine.addNode(wf.id, { id: 'task1', type: 'task', label: 'Review', config: {}, x: 100, y: 0 })
    expect(
      engine.addEdge(wf.id, { id: 'e1', sourceId: 'start', targetId: 'task1', type: 'sequential' })
    ).toBe(true)
  })

  it('should not add edge with invalid source', () => {
    const wf = engine.createWorkflow('Test', 'test')
    expect(
      engine.addEdge(wf.id, { id: 'e1', sourceId: 'invalid', targetId: 'end', type: 'sequential' })
    ).toBe(false)
  })

  it('should validate workflow', () => {
    const wf = engine.createWorkflow('Test', 'test')
    engine.addNode(wf.id, { id: 'task1', type: 'task', label: 'Review', config: {}, x: 100, y: 0 })
    engine.addEdge(wf.id, { id: 'e1', sourceId: 'start', targetId: 'task1', type: 'sequential' })
    engine.addEdge(wf.id, { id: 'e2', sourceId: 'task1', targetId: 'end', type: 'sequential' })
    const result = engine.validate(wf.id)
    expect(result.valid).toBe(true)
  })

  it('should detect disconnected nodes', () => {
    const wf = engine.createWorkflow('Test', 'test')
    engine.addNode(wf.id, { id: 'task1', type: 'task', label: 'Orphan', config: {}, x: 100, y: 0 })
    const result = engine.validate(wf.id)
    expect(result.warnings.length).toBeGreaterThan(0)
  })

  it('should save as template', () => {
    const wf = engine.createWorkflow('Test', 'test')
    const template = engine.saveAsTemplate(wf.id, 'My Template')
    expect(template?.id).toContain('tmpl-')
    expect(engine.listTemplates()).toHaveLength(1)
  })

  it('should create from template', () => {
    const wf = engine.createWorkflow('Test', 'test')
    engine.saveAsTemplate(wf.id, 'My Template')
    const newWf = engine.createFromTemplate(engine.listTemplates()[0].id, 'New Workflow')
    expect(newWf?.name).toBe('New Workflow')
  })

  it('should serialize and deserialize', () => {
    const wf = engine.createWorkflow('Test', 'test')
    const json = engine.serialize(wf.id)
    expect(json).toBeDefined()
    const imported = engine.deserialize(json!)
    expect(imported?.name).toBe('Test')
  })
})

