import { useEffect, useState } from 'react'
import { masterStorage } from '@/utils/masterStorage'

export function useFirstRun() {
  const [isFirstRun, setIsFirstRun] = useState<boolean | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    async function checkFirstRun() {
      setIsLoading(true)
      try {
        const setupDone = localStorage.getItem('finplan-setup-complete') === 'true'
        if (setupDone) {
          setIsFirstRun(false)
        } else {
          // If setup not done in localStorage, check if we have data in DB
          const val = await masterStorage.getItem('finplan-setup-complete')
          const hasNoData = !val || (val as any) !== '"true"'
          setIsFirstRun(hasNoData)
        }
      } catch {
        setIsFirstRun(true)
      } finally {
        setIsLoading(false)
      }
    }
    checkFirstRun()
  }, [])

  const completeSetup = async () => {
    localStorage.setItem('finplan-setup-complete', 'true')
    await masterStorage.setItem('finplan-setup-complete', '"true"' as any)
    setIsFirstRun(false)
  }

  const skipSetup = async () => {
    localStorage.setItem('finplan-setup-complete', 'true')
    await masterStorage.setItem('finplan-setup-complete', '"true"' as any)
    setIsFirstRun(false)
  }

  const resetSetup = async () => {
    localStorage.removeItem('finplan-setup-complete')
    await masterStorage.removeItem('finplan-setup-complete')
    setIsFirstRun(true)
  }

  return { isFirstRun, isLoading, completeSetup, skipSetup, resetSetup }
}

import { useCallback, useState } from 'react'
import type { GridApi } from 'ag-grid-community'

interface FreezeState {
  frozenRows: number
  frozenCols: number
}

export function useFreezePanes(gridApi: GridApi | null) {
  const [freezeState, setFreezeState] = useState<FreezeState>({ frozenRows: 0, frozenCols: 0 })

  const freezeTopRow = useCallback(() => {
    if (!gridApi) return
    // AG Grid uses pinnedTopRowData for freezing rows
    // For header freeze, we rely on default header pinning
    setFreezeState((prev) => ({ ...prev, frozenRows: 1 }))
  }, [gridApi])

  const freezeFirstColumns = useCallback(
    (count: number) => {
      if (!gridApi) return
      const allCols = gridApi.getColumns()
      if (!allCols) return
      // Pin first N columns
      allCols.forEach((col, i) => {
        if (i < count) {
          gridApi.setColumnsPinned(col.getColId() as any, 'left')
        } else {
          gridApi.setColumnsPinned(col.getColId() as any, null)
        }
      })
      setFreezeState((prev) => ({ ...prev, frozenCols: count }))
    },
    [gridApi]
  )

  const freezeBoth = useCallback(
    (rowCount: number, colCount: number) => {
      freezeTopRow()
      freezeFirstColumns(colCount)
    },
    [freezeTopRow, freezeFirstColumns]
  )

  const unfreeze = useCallback(() => {
    if (!gridApi) return
    const allCols = gridApi.getColumns()
    if (allCols) {
      allCols.forEach((col) => {
        gridApi.setColumnsPinned(col.getColId() as any, null)
      })
    }
    setFreezeState({ frozenRows: 0, frozenCols: 0 })
  }, [gridApi])

  return {
    ...freezeState,
    freezeTopRow,
    freezeFirstColumns,
    freezeBoth,
    unfreeze,
    isFrozen: freezeState.frozenRows > 0 || freezeState.frozenCols > 0,
  }
}

