import { describe, it, expect, vi, beforeEach } from 'vitest'
import { renderHook, act, waitFor } from '@testing-library/react'
import { usePersistence } from './usePersistence'
import { indexedDBStorage } from '@/utils/indexedDBStorage'

// Mock dependencies
vi.mock('@/utils/indexedDBStorage')

const mockIndexedDBStorage = vi.mocked(indexedDBStorage)
const localStorageMock = (() => {
  let store: Record<string, string> = {}
  return {
    getItem: (key: string) => store[key] || null,
    setItem: (key: string, value: string) => {
      store[key] = value.toString()
    },
    removeItem: (key: string) => {
      delete store[key]
    },
    clear: () => {
      store = {}
    },
  }
})()

Object.defineProperty(window, 'localStorage', { value: localStorageMock })

describe('usePersistence', () => {
  beforeEach(() => {
    vi.resetAllMocks()
    localStorageMock.clear()
  })

  const options = { key: 'test-key' }

  it('should initialize with isLoading=true and then load data', async () => {
    // Arrange
    mockIndexedDBStorage.getItem.mockResolvedValue(
      JSON.stringify({ _data: { value: 'test' }, _version: 1 }) as any
    )

    // Act
    const { result } = renderHook(() => usePersistence({ ...options, version: 1 }))

    // Assert
    expect(result.current.isLoading).toBe(true)

    await waitFor(() => expect(result.current.isLoading).toBe(false))

    expect(result.current.data).toEqual({ value: 'test' })
    expect(result.current.error).toBeNull()
  })

  // --- IndexedDB ---
  describe('with IndexedDB', () => {
    const dbOptions = { ...options, storage: 'master' as const, version: 1 }

    it('should save data to indexedDB', async () => {
      const { result } = renderHook(() => usePersistence(dbOptions))

      await act(async () => {
        await result.current.save({ value: 'new data' })
      })

      const expected = JSON.stringify({ _data: { value: 'new data' }, _version: 1 })
      expect(mockIndexedDBStorage.setItem).toHaveBeenCalledWith('test-key', expected)
      expect(result.current.data).toEqual({ value: 'new data' })
    })

    it('should clear data from indexedDB', async () => {
      const { result } = renderHook(() => usePersistence(dbOptions))
      await act(async () => {
        await result.current.clear()
      })
      expect(mockIndexedDBStorage.removeItem).toHaveBeenCalledWith('test-key')
      expect(result.current.data).toBeNull()
    })
  })

  // --- localStorage ---
  describe('with localStorage', () => {
    const lsOptions = { ...options, storage: 'localstorage' as const, version: 1 }

    it('should save data to localStorage', async () => {
      const { result } = renderHook(() => usePersistence(lsOptions))

      await act(async () => {
        await result.current.save({ value: 'ls data' })
      })

      const expected = JSON.stringify({ _data: { value: 'ls data' }, _version: 1 })
      expect(localStorageMock.getItem('test-key')).toEqual(expected)
      expect(result.current.data).toEqual({ value: 'ls data' })
    })

    it('should load data from localStorage', async () => {
      const stored = JSON.stringify({ _data: { value: 'stored ls data' }, _version: 1 })
      localStorageMock.setItem('test-key', stored)

      const { result } = renderHook(() => usePersistence(lsOptions))

      await waitFor(() => {
        expect(result.current.data).toEqual({ value: 'stored ls data' })
      })
    })

    it('should clear data from localStorage', async () => {
      const { result } = renderHook(() => usePersistence(lsOptions))
      await act(async () => {
        await result.current.clear()
      })
      expect(localStorageMock.getItem('test-key')).toBeNull()
      expect(result.current.data).toBeNull()
    })
  })

  // --- Migration ---
  describe('migration', () => {
    it('should migrate data when version differs', async () => {
      // Arrange
      const oldData = { _data: { old: 'format' }, _version: 1 }
      localStorageMock.setItem('test-key', JSON.stringify(oldData))

      const migrate = vi.fn((old, oldVersion) => {
        expect(old).toEqual(oldData)
        expect(oldVersion).toBe(1)
        return { _data: { new: 'format' }, _version: 2 }
      })

      const migrationOptions = {
        key: 'test-key',
        storage: 'localstorage' as const,
        version: 2,
        migrate,
      }

      // Act
      const { result } = renderHook(() => usePersistence(migrationOptions))

      // Assert
      await waitFor(() => {
        expect(migrate).toHaveBeenCalledTimes(1)
        expect(result.current.data).toEqual({ new: 'format' })
      })
    })

    it('should not migrate data when versions match', async () => {
      const data = { _data: { value: 'test' }, _version: 2 }
      localStorageMock.setItem('test-key', JSON.stringify(data))
      const migrate = vi.fn()
      const migrationOptions = {
        key: 'test-key',
        storage: 'localstorage' as const,
        version: 2,
        migrate,
      }

      const { result } = renderHook(() => usePersistence(migrationOptions))

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false)
      })

      expect(migrate).not.toHaveBeenCalled()
      expect(result.current.data).toEqual({ value: 'test' })
    })
  })

  // --- Error Handling ---
  describe('error handling', () => {
    it('should set an error if loading fails', async () => {
      mockIndexedDBStorage.getItem.mockRejectedValue(new Error('DB read fail'))
      const { result } = renderHook(() => usePersistence(options))
      await waitFor(() => {
        expect(result.current.error).toBe('Failed to load data')
      })
    })

    it('should set an error if saving fails', async () => {
      mockIndexedDBStorage.setItem.mockRejectedValue(new Error('DB write fail'))
      const { result } = renderHook(() => usePersistence(options))
      await act(async () => {
        await result.current.save({ value: 'new data' })
      })
      expect(result.current.error).toBe('Failed to save data')
    })

    it('should set an error if clearing fails', async () => {
      mockIndexedDBStorage.removeItem.mockRejectedValue(new Error('DB clear fail'))
      const { result } = renderHook(() => usePersistence(options))
      await act(async () => {
        await result.current.clear()
      })
      expect(result.current.error).toBe('Failed to clear data')
    })
  })
})

import { useCallback, useEffect, useState } from 'react'
import { masterStorage } from '@/utils/masterStorage'

interface PersistedWrapper<T> {
  _data: T
  _version: number
}

export interface PersistenceOptions {
  key: string
  storage?: 'master' | 'localstorage'
  version?: number
  migrate?: (old: unknown, oldVersion: number) => unknown
}

export function usePersistence<T>(options: PersistenceOptions) {
  const [data, setData] = useState<T | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const load = useCallback(async (): Promise<T | null> => {
    setIsLoading(true)
    try {
      let stored: unknown
      if (options.storage === 'localstorage') {
        const val = localStorage.getItem(options.key)
        stored = val ? JSON.parse(val) : null
      } else {
        const val = await masterStorage.getItem(options.key)
        stored = val ? JSON.parse(String(val)) : null
      }

      const wrapper = stored as PersistedWrapper<T> | null

      if (wrapper && options.version && wrapper._version !== options.version) {
        if (options.migrate) {
          stored = options.migrate(wrapper, wrapper._version || 0)
        }
      }

      const result = wrapper ? (wrapper._data as T) : null
      setData(result)
      return result
    } catch (e) {
      setError('Failed to load data')
      return null
    } finally {
      setIsLoading(false)
    }
  }, [options.key, options.storage, options.version, options.migrate])

  const save = async (newData: T) => {
    try {
      const wrapper = { _data: newData, _version: options.version || 0 }
      const serialized = JSON.stringify(wrapper)
      if (options.storage === 'localstorage') {
        localStorage.setItem(options.key, serialized)
      } else {
        await masterStorage.setItem(options.key, serialized as unknown as never)
      }
      setData(newData)
    } catch (e) {
      setError('Failed to save data')
    }
  }

  const clear = async () => {
    try {
      if (options.storage === 'localstorage') {
        localStorage.removeItem(options.key)
      } else {
        await masterStorage.removeItem(options.key)
      }
      setData(null)
    } catch (e) {
      setError('Failed to clear data')
    }
  }

  useEffect(() => {
    load() // eslint-disable-line react-hooks/set-state-in-effect -- intentional: load persisted data on mount
  }, [load])

  return { data, save, load, clear, isLoading, error }
}

// =============================================================================
// usePresence Hook
// React hook for presence awareness — who is online, where they are
// =============================================================================

import { useCallback, useEffect, useState } from 'react'
import {
  RealtimeCollaborationManager,
  type UserPresence,
  type PresenceChange,
} from '@/services/RealtimeCollaborationManager'

export interface UsePresenceReturn {
  /** All online users */
  users: UserPresence[]
  /** Users on a specific resource */
  getUsersOnResource: (resourceType: string, resourceId: string) => UserPresence[]
  /** Users on a specific cell */
  getUsersOnCell: (cellId: string) => UserPresence[]
  /** Check if a cell is locked by another user */
  isCellLocked: (cellId: string) => boolean
  /** Announce current viewing location */
  setActiveResource: (resourceType: string, resourceId: string, cellId?: string) => void
  /** Clear current viewing location */
  clearActiveResource: () => void
}

/**
 * Hook for presence awareness across the application.
 * Returns the list of online users and utilities to check who is where.
 */
export function usePresence(): UsePresenceReturn {
  const manager = RealtimeCollaborationManager.getInstance()
  const [users, setUsers] = useState<UserPresence[]>([])

  useEffect(() => {
    // Load initial state
    // eslint-disable-next-line react-compiler/react-compiler
    setUsers(manager.presence.getUsers())

    const unsub = manager.presence.onStateChange(setUsers)
    return unsub
  }, [manager])

  const getUsersOnResource = useCallback(
    (resourceType: string, resourceId: string) =>
      manager.presence.getUsersOnResource(resourceType, resourceId),
    [manager]
  )

  const getUsersOnCell = useCallback(
    (cellId: string) => manager.presence.getUsersOnCell(cellId),
    [manager]
  )

  const isCellLocked = useCallback(
    (cellId: string) => manager.presence.isCellLocked(cellId),
    [manager]
  )

  const setActiveResource = useCallback(
    (resourceType: string, resourceId: string, cellId?: string) =>
      manager.presence.setActiveResource(resourceType, resourceId, cellId),
    [manager]
  )

  const clearActiveResource = useCallback(() => manager.presence.clearActiveResource(), [manager])

  return {
    users,
    getUsersOnResource,
    getUsersOnCell,
    isCellLocked,
    setActiveResource,
    clearActiveResource,
  }
}

/**
 * Hook to get presence changes as they happen (join/leave/update).
 * Useful for activity feeds or toast notifications.
 */
export function usePresenceEvents(handler: (change: PresenceChange) => void): void {
  const manager = RealtimeCollaborationManager.getInstance()

  useEffect(() => {
    const unsub = manager.presence.onChange(handler)
    return unsub
  }, [manager, handler])
}

/**
 * Hook to track users on a specific resource.
 * Returns only the users currently viewing the given resource.
 */
export function useResourcePresence(
  resourceType: string,
  resourceId: string | null
): UserPresence[] {
  const manager = RealtimeCollaborationManager.getInstance()
  const [viewers, setViewers] = useState<UserPresence[]>([])

  useEffect(() => {
    if (!resourceId) {
      // eslint-disable-next-line react-compiler/react-compiler
      setViewers([])
      return
    }

    const update = () => {
      setViewers(manager.presence.getUsersOnResource(resourceType, resourceId))
    }

    update()
    const unsub = manager.presence.onStateChange(update)
    return unsub
  }, [manager, resourceType, resourceId])

  return viewers
}

import { useEffect, useRef } from 'react'

export function useRenderCount(componentName: string) {
  const count = useRef(0)

  useEffect(() => {
    count.current += 1
    if (process.env.NODE_ENV === 'development') {
      console.debug(`[${componentName}] renders: ${count.current}`)
    }
  })

  return count.current
}

