import { useState, useCallback, useRef, useEffect, type DragEvent } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Input } from '@/components/ui/Input'
import { Select, type SelectOption } from '@/components/ui/Select'
import {
  Save,
  Download,
  Upload,
  Trash2,
  GripVertical,
  BarChart3,
  TrendingUp,
  PieChart as PieIcon,
  Table2,
  Grid3X3,
  LayoutDashboard,
  X,
} from 'lucide-react'

type WidgetType = 'kpi' | 'line' | 'bar' | 'pie' | 'table' | 'heatmap'

interface Widget {
  id: string
  type: WidgetType
  x: number
  y: number
  w: number
  h: number
  config: { title: string; dataSource?: string; color?: string; pageSize?: number }
}

interface DashboardData {
  name: string
  widgets: Widget[]
}

const STORAGE_KEY = 'fpna-dashboard-builder'

const WIDGET_META: {
  type: WidgetType
  label: string
  icon: typeof BarChart3
  dw: number
  dh: number
}[] = [
  { type: 'kpi', label: 'KPI Card', icon: LayoutDashboard, dw: 3, dh: 2 },
  { type: 'line', label: 'Line Chart', icon: TrendingUp, dw: 6, dh: 4 },
  { type: 'bar', label: 'Bar Chart', icon: BarChart3, dw: 6, dh: 4 },
  { type: 'pie', label: 'Pie Chart', icon: PieIcon, dw: 4, dh: 4 },
  { type: 'table', label: 'Table', icon: Table2, dw: 12, dh: 4 },
  { type: 'heatmap', label: 'Heatmap', icon: Grid3X3, dw: 6, dh: 4 },
]

const DS_OPTIONS: SelectOption[] = [
  { value: 'revenue', label: 'Revenue' },
  { value: 'expenses', label: 'Expenses' },
  { value: 'cashflow', label: 'Cash Flow' },
  { value: 'budget', label: 'Budget vs Actual' },
]

const COLOR_OPTIONS: SelectOption[] = [
  { value: '#3B82F6', label: 'Blue' },
  { value: '#10B981', label: 'Green' },
  { value: '#F59E0B', label: 'Amber' },
  { value: '#EF4444', label: 'Red' },
  { value: '#8B5CF6', label: 'Purple' },
]

const dashboardStore = {
  save(data: DashboardData) {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data))
    } catch {
      /* noop */
    }
  },
  load(): DashboardData | null {
    try {
      const r = localStorage.getItem(STORAGE_KEY)
      return r ? JSON.parse(r) : null
    } catch {
      return null
    }
  },
  export(data: DashboardData) {
    return JSON.stringify(data, null, 2)
  },
  import(json: string): DashboardData | null {
    try {
      const p = JSON.parse(json)
      return Array.isArray(p.widgets) ? p : null
    } catch {
      return null
    }
  },
}

function uid() {
  return `w-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
}

function WidgetPreview({ type, config }: { type: WidgetType; config: Widget['config'] }) {
  const c = config.color ?? '#3B82F6'
  if (type === 'kpi') {
    return (
      <div className="flex flex-col items-center justify-center h-full gap-1">
        <span className="text-sm text-[var(--text-muted)]">{config.title}</span>
        <span className="text-3xl font-bold font-mono">$0.00</span>
        <span className="text-xs text-emerald-500">+0.0%</span>
      </div>
    )
  }
  if (type === 'table') {
    const rows = Array.from({ length: config.pageSize ?? 5 }, (_, i) => i + 1)
    return (
      <div className="overflow-auto h-full">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-[var(--border-default)]">
              {['Account', 'Actual', 'Budget', 'Variance'].map((h) => (
                <th
                  key={h}
                  className={`${h === 'Account' ? 'text-left' : 'text-right'} py-1.5 px-2 text-[var(--text-muted)] font-medium`}
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((n) => (
              <tr key={n} className="border-b border-[var(--border-default)] last:border-0">
                <td className="py-1.5 px-2">Account {n}</td>
                <td className="py-1.5 px-2 text-right font-mono">$0</td>
                <td className="py-1.5 px-2 text-right font-mono">$0</td>
                <td className="py-1.5 px-2 text-right font-mono text-emerald-500">$0</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    )
  }
  if (type === 'heatmap') {
    return (
      <div className="grid grid-cols-8 gap-0.5 h-full">
        {Array.from({ length: 48 }, (_, i) => (
          <div
            key={i}
            className="rounded-sm"
            style={{ backgroundColor: `rgba(59,130,246,${Math.random().toFixed(2)})` }}
          />
        ))}
      </div>
    )
  }
  const label = type === 'line' ? 'Line' : type === 'bar' ? 'Bar' : 'Pie'
  return (
    <div className="flex flex-col items-center justify-center h-full gap-2 text-[var(--text-muted)]">
      {type === 'pie' ? (
        <div
          className="w-20 h-20 rounded-full"
          style={{ background: `conic-gradient(${c} 0% 40%, #94A3B8 40% 100%)` }}
        />
      ) : (
        <svg viewBox="0 0 120 60" className="w-28 h-14">
          {type === 'line' ? (
            <polyline
              points="5,50 25,30 45,40 65,15 85,25 105,10"
              fill="none"
              stroke={c}
              strokeWidth="2"
            />
          ) : (
            [5, 25, 45, 65, 85].map((x, i) => (
              <rect
                key={x}
                x={x}
                y={50 - [25, 40, 30, 45, 35][i]}
                width="15"
                height={[25, 40, 30, 45, 35][i]}
                fill={c}
                rx="2"
              />
            ))
          )}
        </svg>
      )}
      <span className="text-xs">{label} Chart Preview</span>
    </div>
  )
}

export function DashboardBuilderPage() {
  const [name, setName] = useState('My Dashboard')
  const [widgets, setWidgets] = useState<Widget[]>([])
  const [selId, setSelId] = useState<string | null>(null)
  const [dragType, setDragType] = useState<WidgetType | null>(null)
  const gridRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const s = dashboardStore.load()
    if (s) {
      setName(s.name)
      setWidgets(s.widgets)
    }
  }, [])

  const sel = widgets.find((w) => w.id === selId) ?? null

  const update = useCallback((id: string, patch: Partial<Widget>) => {
    setWidgets((p) => p.map((w) => (w.id === id ? { ...w, ...patch } : w)))
  }, [])

  const updateConfig = useCallback((id: string, patch: Partial<Widget['config']>) => {
    setWidgets((p) => p.map((w) => (w.id === id ? { ...w, config: { ...w.config, ...patch } } : w)))
  }, [])

  const remove = useCallback(
    (id: string) => {
      setWidgets((p) => p.filter((w) => w.id !== id))
      if (selId === id) setSelId(null)
    },
    [selId]
  )

  const addWidget = useCallback(
    (type: WidgetType, col = 0, row?: number) => {
      const meta = WIDGET_META.find((m) => m.type === type)
      if (!meta) return
      const y = row ?? widgets.reduce((max, w) => Math.max(max, w.y + w.h), 0)
      const w: Widget = {
        id: uid(),
        type,
        x: col,
        y,
        w: meta.dw,
        h: meta.dh,
        config: { title: `New ${meta.label}` },
      }
      setWidgets((p) => [...p, w])
      setSelId(w.id)
    },
    [widgets]
  )

  const onPaletteDragStart = useCallback((e: DragEvent, t: WidgetType) => {
    setDragType(t)
    e.dataTransfer.effectAllowed = 'copy'
    e.dataTransfer.setData('text/plain', t)
  }, [])

  const onWidgetDragStart = useCallback((e: DragEvent, id: string) => {
    setSelId(id)
    e.dataTransfer.effectAllowed = 'move'
    e.dataTransfer.setData('application/widget-id', id)
  }, [])

  const getGridPos = useCallback((e: DragEvent) => {
    if (!gridRef.current) return null
    const r = gridRef.current.getBoundingClientRect()
    return {
      col: Math.min(11, Math.max(0, Math.floor((e.clientX - r.left) / (r.width / 12)))),
      row: Math.max(0, Math.floor((e.clientY - r.top) / 80)),
    }
  }, [])

  const onGridDrop = useCallback(
    (e: DragEvent) => {
      e.preventDefault()
      const pos = getGridPos(e)
      if (!pos) return
      const moveId = e.dataTransfer.getData('application/widget-id')
      if (moveId) {
        update(moveId, { x: pos.col, y: pos.row })
        setDragType(null)
        return
      }
      const t = (dragType ?? e.dataTransfer.getData('text/plain')) as WidgetType | null
      if (t) addWidget(t, pos.col, pos.row)
      setDragType(null)
    },
    [dragType, getGridPos, addWidget, update]
  )

  const onGridDragOver = useCallback(
    (e: DragEvent) => {
      e.preventDefault()
      e.dataTransfer.dropEffect = dragType ? 'copy' : 'move'
    },
    [dragType]
  )

  const handleSave = useCallback(() => {
    dashboardStore.save({ name, widgets })
  }, [name, widgets])
  const handleLoad = useCallback(() => {
    const d = dashboardStore.load()
    if (d) {
      setName(d.name)
      setWidgets(d.widgets)
      setSelId(null)
    }
  }, [])
  const handleExport = useCallback(() => {
    const blob = new Blob([dashboardStore.export({ name, widgets })], { type: 'application/json' })
    const a = document.createElement('a')
    a.href = URL.createObjectURL(blob)
    a.download = `${name.replace(/\s+/g, '-').toLowerCase()}.json`
    a.click()
    URL.revokeObjectURL(a.href)
  }, [name, widgets])
  const handleImport = useCallback(() => {
    const inp = document.createElement('input')
    inp.type = 'file'
    inp.accept = '.json'
    inp.onchange = () => {
      const f = inp.files?.[0]
      if (!f) return
      const r = new FileReader()
      r.onload = () => {
        const d = dashboardStore.import(r.result as string)
        if (d) {
          setName(d.name)
          setWidgets(d.widgets)
          setSelId(null)
        }
      }
      r.readAsText(f)
    }
    inp.click()
  }, [])

  const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v))

  return (
    <div className="flex flex-col h-[calc(100vh-4rem)]">
      {/* Top Bar */}
      <div className="flex items-center justify-between px-4 py-2 border-b border-[var(--border-default)] bg-[var(--bg-surface)] shrink-0">
        <div className="flex items-center gap-3">
          <LayoutDashboard className="h-5 w-5 text-blue-500" />
          <Input
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="w-64 h-8 text-lg font-semibold border-none focus-visible:ring-0 bg-transparent px-0"
          />
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={handleImport}>
            <Upload className="h-4 w-4 mr-1" /> Import
          </Button>
          <Button variant="outline" size="sm" onClick={handleLoad}>
            <Download className="h-4 w-4 mr-1" /> Load
          </Button>
          <Button variant="outline" size="sm" onClick={handleExport}>
            <Download className="h-4 w-4 mr-1" /> Export
          </Button>
          <Button size="sm" onClick={handleSave}>
            <Save className="h-4 w-4 mr-1" /> Save
          </Button>
        </div>
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Left Sidebar — Widget Palette */}
        <div className="w-52 border-r border-[var(--border-default)] bg-[var(--bg-surface)] p-3 overflow-y-auto shrink-0">
          <h3 className="text-xs font-semibold uppercase text-[var(--text-muted)] mb-3 tracking-wider">
            Widgets
          </h3>
          <div className="space-y-1.5">
            {WIDGET_META.map((m) => {
              const Icon = m.icon
              return (
                <div
                  key={m.type}
                  draggable
                  onDragStart={(e) => onPaletteDragStart(e, m.type)}
                  onClick={() => addWidget(m.type)}
                  className="flex items-center gap-2 px-2.5 py-2 rounded-md cursor-grab active:cursor-grabbing hover:bg-[var(--bg-hover)] transition-colors select-none"
                >
                  <Icon className="h-4 w-4 text-[var(--text-muted)]" />
                  <span className="text-sm">{m.label}</span>
                </div>
              )
            })}
          </div>
        </div>

        {/* Center — Dashboard Grid */}
        <div
          ref={gridRef}
          className="flex-1 p-4 overflow-auto bg-[var(--bg-canvas)]"
          onDragOver={onGridDragOver}
          onDrop={onGridDrop}
        >
          {widgets.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-[var(--text-muted)] gap-3">
              <LayoutDashboard className="h-12 w-12 opacity-30" />
              <p className="text-lg">Drag widgets here or click a widget type to add</p>
              <p className="text-sm">12-column grid &middot; Drag to reposition</p>
            </div>
          ) : (
            <div className="grid grid-cols-12 gap-3 auto-rows-[80px]">
              {widgets.map((w) => (
                <div
                  key={w.id}
                  draggable
                  onDragStart={(e) => onWidgetDragStart(e, w.id)}
                  onClick={() => setSelId(w.id)}
                  className={`col-span-${Math.min(w.w, 12)} row-span-${w.h} ${selId === w.id ? 'ring-2 ring-blue-500 ring-offset-1' : ''}`}
                >
                  <Card className="h-full relative group cursor-grab active:cursor-grabbing">
                    <GripVertical className="absolute top-1.5 left-1.5 h-4 w-4 text-[var(--text-muted)] opacity-0 group-hover:opacity-100 transition-opacity" />
                    <button
                      className="absolute top-1.5 right-1.5 p-0.5 rounded opacity-0 group-hover:opacity-100 hover:bg-red-100 dark:hover:bg-red-900 transition-opacity"
                      onClick={(e) => {
                        e.stopPropagation()
                        remove(w.id)
                      }}
                      title="Remove"
                    >
                      <X className="h-3.5 w-3.5 text-red-500" />
                    </button>
                    <CardHeader className="pb-1 pt-2 px-3">
                      <CardTitle className="text-xs font-medium truncate">
                        {w.config.title}
                      </CardTitle>
                    </CardHeader>
                    <CardContent className="px-3 pb-2 h-[calc(100%-2.5rem)]">
                      <WidgetPreview type={w.type} config={w.config} />
                    </CardContent>
                  </Card>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Right Sidebar — Config Panel */}
        {sel && (
          <div className="w-72 border-l border-[var(--border-default)] bg-[var(--bg-surface)] p-4 overflow-y-auto shrink-0">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-semibold">Widget Settings</h3>
              <button
                className="p-1 rounded hover:bg-[var(--bg-hover)]"
                onClick={() => setSelId(null)}
              >
                <X className="h-4 w-4 text-[var(--text-muted)]" />
              </button>
            </div>
            <div className="space-y-4">
              <Input
                label="Title"
                value={sel.config.title}
                onChange={(e) => updateConfig(sel.id, { title: e.target.value })}
              />
              <div className="grid grid-cols-2 gap-2">
                <Input
                  label="Width (cols)"
                  type="number"
                  min={1}
                  max={12}
                  value={sel.w}
                  onChange={(e) => update(sel.id, { w: clamp(+e.target.value, 1, 12) })}
                />
                <Input
                  label="Height (rows)"
                  type="number"
                  min={1}
                  max={8}
                  value={sel.h}
                  onChange={(e) => update(sel.id, { h: clamp(+e.target.value, 1, 8) })}
                />
              </div>
              <div className="grid grid-cols-2 gap-2">
                <Input
                  label="Column"
                  type="number"
                  min={0}
                  max={11}
                  value={sel.x}
                  onChange={(e) => update(sel.id, { x: clamp(+e.target.value, 0, 11) })}
                />
                <Input
                  label="Row"
                  type="number"
                  min={0}
                  value={sel.y}
                  onChange={(e) => update(sel.id, { y: Math.max(0, +e.target.value) })}
                />
              </div>
              {sel.type !== 'kpi' && sel.type !== 'heatmap' && (
                <Select
                  label="Data Source"
                  options={DS_OPTIONS}
                  value={sel.config.dataSource}
                  onChange={(v) => updateConfig(sel.id, { dataSource: v })}
                  placeholder="Select source..."
                />
              )}
              {sel.type !== 'kpi' && sel.type !== 'table' && (
                <Select
                  label="Color"
                  options={COLOR_OPTIONS}
                  value={sel.config.color}
                  onChange={(v) => updateConfig(sel.id, { color: v })}
                  placeholder="Select color..."
                />
              )}
              {sel.type === 'table' && (
                <Input
                  label="Page Size"
                  type="number"
                  min={1}
                  max={50}
                  value={sel.config.pageSize ?? 5}
                  onChange={(e) => updateConfig(sel.id, { pageSize: Math.max(1, +e.target.value) })}
                />
              )}
              <Button
                variant="destructive"
                size="sm"
                className="w-full mt-2"
                onClick={() => remove(sel.id)}
              >
                <Trash2 className="h-4 w-4 mr-1" /> Remove Widget
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

import { useState, useMemo, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import { useGLStore } from '@/store/glStore'
import { GoalSeekEngine } from '@/engines/GoalSeekEngine'
import type { GoalSeekResult } from '@/engines/GoalSeekEngine'
import { Button } from '@/components/ui/Button'
import { Input } from '@/components/ui/Input'
import { Card, CardContent } from '@/components/ui/Card'
import { Alert } from '@/components/ui/Alert'
import { Skeleton } from '@/components/ui/Skeleton'
import { Target, TrendingUp, BarChart3, Crosshair } from 'lucide-react'
import { EmptyState } from '@/components/ui/EmptyState'

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
  }).format(n)
}

export function GoalSeekPage() {
  const { entries } = useGLStore()
  const navigate = useNavigate()
  const [mode, setMode] = useState<'goalseek' | 'montecarlo' | 'breakeven'>('breakeven')
  const [targetProfit, setTargetProfit] = useState(1000000)
  const [fixedCost, setFixedCost] = useState(500000)
  const [variableCostPct, setVariableCostPct] = useState(60)
  const [iterations, setIterations] = useState(1000)
  const [results, setResults] = useState<any>(null)
  const [loading, setLoading] = useState(false)

  const [gsTargetMetric, setGsTargetMetric] = useState<'netIncome' | 'revenue' | 'expenses'>(
    'netIncome'
  )
  const [gsTargetValue, setGsTargetValue] = useState(5000000)
  const [gsAdjustable, setGsAdjustable] = useState<'revenue' | 'expenses'>('revenue')
  const [gsResult, setGsResult] = useState<GoalSeekResult | null>(null)

  const actuals = useMemo(() => {
    if (entries.length === 0) return null
    const revenue = entries
      .filter((e) => (e.accountCode || '').startsWith('4'))
      .reduce((s, e) => s + (e.debit - e.credit), 0)
    const expenses = entries
      .filter((e) => (e.accountCode || '').startsWith('5') || (e.accountCode || '').startsWith('6'))
      .reduce((s, e) => s + Math.abs(e.debit - e.credit), 0)
    return { revenue, expenses, netIncome: revenue - expenses }
  }, [entries])

  const runBreakeven = () => {
    const contributionMargin = 100 - variableCostPct
    const beRevenue = contributionMargin > 0 ? fixedCost / (contributionMargin / 100) : 0
    const revForTarget =
      contributionMargin > 0 ? (fixedCost + targetProfit) / (contributionMargin / 100) : 0
    setResults({
      breakevenRevenue: beRevenue,
      revenueForTarget: revForTarget,
      contributionMargin,
      fixedCost,
      variableCostPct,
    })
  }

  const runGoalSeek = useCallback(() => {
    const baseRevenue = actuals?.revenue || 1000000
    const baseExpenses = actuals?.expenses || 500000

    const computeTarget = (adjustableValue: number): number => {
      const rev = gsAdjustable === 'revenue' ? adjustableValue : baseRevenue
      const exp = gsAdjustable === 'expenses' ? adjustableValue : baseExpenses
      switch (gsTargetMetric) {
        case 'netIncome':
          return rev - exp
        case 'revenue':
          return rev
        case 'expenses':
          return exp
      }
    }

    const initialGuess = gsAdjustable === 'revenue' ? baseRevenue : baseExpenses

    const result = GoalSeekEngine.seek({
      fn: computeTarget,
      target: gsTargetValue,
      initialGuess,
      lowerBound: 0,
      upperBound: gsTargetValue * 100,
    })

    setGsResult(result)
  }, [actuals, gsTargetMetric, gsTargetValue, gsAdjustable])

  const runMonteCarlo = () => {
    setLoading(true)
    setTimeout(() => {
      const sims = Array.from({ length: iterations }, () => {
        const revMultiplier = 0.8 + Math.random() * 0.4
        const costMultiplier = 0.85 + Math.random() * 0.3
        const base = actuals?.revenue || 1000000
        const revenue = base * revMultiplier
        const costs = (base * (variableCostPct / 100) + fixedCost) * costMultiplier
        return { revenue, costs, profit: revenue - costs }
      })
      const profits = sims.map((s) => s.profit).sort((a, b) => a - b)
      const avgProfit = profits.reduce((s, p) => s + p, 0) / profits.length
      const median = profits[Math.floor(profits.length / 2)]
      const p10 = profits[Math.floor(profits.length * 0.1)]
      const p90 = profits[Math.floor(profits.length * 0.9)]
      const positiveOutcomes = profits.filter((p) => p >= 0).length
      setResults({
        simulations: sims,
        avgProfit,
        median,
        p10,
        p90,
        positivePct: (positiveOutcomes / iterations) * 100,
        count: iterations,
      })
      setLoading(false)
    }, 500)
  }

  if (!actuals && mode === 'montecarlo') {
    return (
      <EmptyState
        icon={Target}
        title="No Data"
        description="Import GL data for Monte Carlo simulations."
        action={<Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>}
      />
    )
  }

  return (
    <div className="p-6 space-y-6">
      <h1 className="text-2xl font-bold">Financial Modeling</h1>
      <div className="flex gap-2">
        {['breakeven', 'goalseek', 'montecarlo'].map((m) => (
          <button
            key={m}
            onClick={() => {
              setMode(m as typeof mode)
              setResults(null)
            }}
            className={
              'px-3 py-1.5 rounded text-xs font-medium ' +
              (mode === m ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400')
            }
          >
            {m === 'breakeven' ? 'Break-Even' : m === 'goalseek' ? 'Goal Seek' : 'Monte Carlo'}
          </button>
        ))}
      </div>

      {mode === 'breakeven' && (
        <Card>
          <CardContent className="p-4 space-y-4">
            <h3 className="font-semibold">Break-Even Analysis</h3>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Fixed Costs</label>
              <Input
                type="number"
                value={fixedCost}
                onChange={(e) => setFixedCost(parseFloat(e.target.value) || 0)}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">
                Variable Cost (% of Revenue)
              </label>
              <Input
                type="number"
                value={variableCostPct}
                onChange={(e) => setVariableCostPct(parseFloat(e.target.value) || 0)}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">
                Target Profit (for goal seek)
              </label>
              <Input
                type="number"
                value={targetProfit}
                onChange={(e) => setTargetProfit(parseFloat(e.target.value) || 0)}
              />
            </div>
            <Button onClick={runBreakeven}>Calculate</Button>
            {results && (
              <div className="space-y-2 text-sm pt-4 border-t border-slate-800">
                <div className="flex justify-between">
                  <span className="text-slate-400">Contribution Margin</span>
                  <span className="font-semibold">{results.contributionMargin.toFixed(1)}%</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">Break-Even Revenue</span>
                  <span className="font-semibold text-green-400">
                    {formatCurrency(results.breakevenRevenue)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">Revenue for Target Profit</span>
                  <span className="font-semibold text-blue-400">
                    {formatCurrency(results.revenueForTarget)}
                  </span>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {mode === 'goalseek' && (
        <Card>
          <CardContent className="p-4 space-y-4">
            <h3 className="font-semibold flex items-center gap-2">
              <Crosshair className="h-4 w-4" />
              Goal Seek
            </h3>
            <p className="text-sm text-slate-400">
              Find the input value needed to achieve a target financial outcome.
            </p>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div>
                <label className="block text-xs text-slate-400 mb-1">Target Metric</label>
                <select
                  value={gsTargetMetric}
                  onChange={(e) => setGsTargetMetric(e.target.value as typeof gsTargetMetric)}
                  className="w-full bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm"
                >
                  <option value="netIncome">Net Income</option>
                  <option value="revenue">Revenue</option>
                  <option value="expenses">Expenses</option>
                </select>
              </div>
              <div>
                <label className="block text-xs text-slate-400 mb-1">Target Value ($)</label>
                <Input
                  type="number"
                  value={gsTargetValue}
                  onChange={(e) => setGsTargetValue(parseFloat(e.target.value) || 0)}
                />
              </div>
              <div>
                <label className="block text-xs text-slate-400 mb-1">Adjustable Variable</label>
                <select
                  value={gsAdjustable}
                  onChange={(e) => setGsAdjustable(e.target.value as typeof gsAdjustable)}
                  className="w-full bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm"
                >
                  <option value="revenue">Revenue</option>
                  <option value="expenses">Expenses</option>
                </select>
              </div>
            </div>
            {actuals && (
              <p className="text-xs text-slate-500">
                Current — Revenue: {formatCurrency(actuals.revenue)}, Expenses:{' '}
                {formatCurrency(actuals.expenses)}, Net Income: {formatCurrency(actuals.netIncome)}
              </p>
            )}
            <Button onClick={runGoalSeek}>
              <Crosshair className="h-4 w-4 mr-2" />
              Find Target
            </Button>
            {gsResult && (
              <div className="space-y-3 text-sm pt-4 border-t border-slate-800">
                <div
                  className={
                    'flex items-center gap-2 px-3 py-2 rounded ' +
                    (gsResult.converged
                      ? 'bg-green-950 text-green-400'
                      : 'bg-yellow-950 text-yellow-400')
                  }
                >
                  {gsResult.converged ? 'Converged' : 'Did not fully converge'} after{' '}
                  {gsResult.iterations} iteration{gsResult.iterations !== 1 ? 's' : ''}
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">
                    Required {gsAdjustable === 'revenue' ? 'Revenue' : 'Expenses'}
                  </span>
                  <span className="font-semibold text-blue-400">
                    {formatCurrency(gsResult.value)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">
                    Achieved{' '}
                    {gsTargetMetric === 'netIncome'
                      ? 'Net Income'
                      : gsTargetMetric === 'revenue'
                        ? 'Revenue'
                        : 'Expenses'}
                  </span>
                  <span className="font-semibold">{formatCurrency(gsResult.finalOutput)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">Error</span>
                  <span className="font-mono text-xs">
                    {Math.abs(gsResult.error) < 0.01
                      ? gsResult.error.toExponential(2)
                      : gsResult.error.toFixed(2)}
                  </span>
                </div>
                <p className="text-slate-400 text-xs pt-2">
                  To achieve{' '}
                  <span className="text-white font-medium">{formatCurrency(gsTargetValue)}</span>{' '}
                  {gsTargetMetric === 'netIncome'
                    ? 'Net Income'
                    : gsTargetMetric === 'revenue'
                      ? 'Revenue'
                      : 'Expenses'}
                  , {gsAdjustable === 'revenue' ? 'Revenue' : 'Expenses'} needs to be{' '}
                  <span className="text-blue-400 font-medium">
                    {formatCurrency(gsResult.value)}
                  </span>
                  .
                </p>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {mode === 'montecarlo' && (
        <Card>
          <CardContent className="p-4 space-y-4">
            <h3 className="font-semibold">Monte Carlo Simulation</h3>
            <p className="text-sm text-slate-400">
              Base revenue: {actuals ? formatCurrency(actuals.revenue) : '$1,000,000'}
            </p>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Iterations</label>
              <Input
                type="number"
                value={iterations}
                onChange={(e) => setIterations(parseInt(e.target.value) || 100)}
              />
            </div>
            <Button onClick={runMonteCarlo} disabled={loading}>
              {loading ? 'Running...' : 'Run Simulation'}
            </Button>
            {loading && <Skeleton variant="rectangular" height={String(100)} />}
            {results && !loading && (
              <div className="space-y-2 text-sm pt-4 border-t border-slate-800">
                <div className="flex justify-between">
                  <span className="text-slate-400">Iterations</span>
                  <span>{results.count.toLocaleString()}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">Avg Profit</span>
                  <span className="font-semibold">{formatCurrency(results.avgProfit)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">Median</span>
                  <span className="font-semibold">{formatCurrency(results.median)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">P10 / P90</span>
                  <span>
                    {formatCurrency(results.p10)} / {formatCurrency(results.p90)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">Positive Outcomes</span>
                  <span
                    className={
                      'font-semibold ' +
                      (results.positivePct > 50 ? 'text-green-400' : 'text-red-400')
                    }
                  >
                    {results.positivePct.toFixed(1)}%
                  </span>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      )}
    </div>
  )
}

import { useEffect, useMemo, useState, useCallback, useRef } from 'react'
import { useNavigate } from 'react-router-dom'
import { CellAuditTrailEngine } from '@/engines/CellAuditTrailEngine'
import { Button } from '@/components/ui/Button'
import { Card, CardContent } from '@/components/ui/Card'
import { ScrollText, Download, RefreshCw } from 'lucide-react'

function formatRelativeTime(timestamp: string): string {
  const diff = Date.now() - new Date(timestamp).getTime()
  const mins = Math.floor(diff / 60000)
  if (mins < 1) return 'Just now'
  if (mins < 60) return mins + 'm ago'
  const hours = Math.floor(mins / 60)
  if (hours < 24) return hours + 'h ago'
  return new Date(timestamp).toLocaleDateString()
}

export function AuditTrailPage() {
  useEffect(() => {
    document.title = 'FinPlan Pro — Audit Trail'
  }, [])

  const navigate = useNavigate()
  const [entries, setEntries] = useState(() => CellAuditTrailEngine.getAllEntries())
  const [filters, setFilters] = useState({ startDate: '', endDate: '', user: '', action: '' })
  const [sortField] = useState<'timestamp' | 'userName'>('timestamp')
  const [sortDir] = useState<'asc' | 'desc'>('desc')
  const intervalRef = useRef<ReturnType<typeof setInterval> | undefined>(undefined)

  // Auto-refresh every 5 seconds
  useEffect(() => {
    intervalRef.current = setInterval(() => {
      setEntries(CellAuditTrailEngine.getAllEntries())
    }, 5000)
    return () => clearInterval(intervalRef.current)
  }, [])

  const filtered = useMemo(() => {
    let list = [...entries]
    if (filters.startDate) list = list.filter((e) => e.timestamp >= filters.startDate)
    if (filters.endDate) list = list.filter((e) => e.timestamp <= filters.endDate + 'T23:59:59')
    if (filters.user)
      list = list.filter((e) => e.userName.toLowerCase().includes(filters.user.toLowerCase()))
    if (filters.action)
      list = list.filter((e) =>
        (e.reason || '').toLowerCase().includes(filters.action.toLowerCase())
      )
    list.sort((a, b) => {
      const cmp = a[sortField] < b[sortField] ? -1 : 1
      return sortDir === 'asc' ? cmp : -cmp
    })
    return list
  }, [entries, filters, sortField, sortDir])

  const handleExport = useCallback(() => {
    const headers = ['Timestamp', 'User', 'Account', 'Old Value', 'New Value', 'Reason']
    const rows = filtered.map((e) => [
      e.timestamp,
      e.userName,
      e.accountName || e.accountId,
      e.oldValue?.toString() ?? '',
      e.newValue?.toString() ?? '',
      e.reason ?? '',
    ])
    const csv = [headers.join(','), ...rows.map((r) => r.map((c) => `"${c}"`).join(','))].join('\n')
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `audit-trail-${new Date().toISOString().slice(0, 10)}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }, [filtered])

  if (entries.length === 0) {
    return (
      <div className="p-12 text-center max-w-md mx-auto">
        <div className="p-4 bg-slate-800 rounded-full inline-block mb-4">
          <ScrollText className="h-10 w-10 text-slate-400" />
        </div>
        <h2 className="text-xl font-semibold mb-2">No Audit Entries</h2>
        <p className="text-slate-400 mb-6">
          Changes appear automatically as you edit budgets, forecasts, and other data. Import data
          and make changes to see them recorded here.
        </p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Audit Trail</h1>
          <p className="text-sm text-slate-400 mt-1">{entries.length} total entries</p>
        </div>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => setEntries(CellAuditTrailEngine.getAllEntries())}
          >
            <RefreshCw className="h-3.5 w-3.5 mr-1.5" />
            Refresh
          </Button>
          <Button size="sm" variant="ghost" onClick={handleExport}>
            <Download className="h-3.5 w-3.5 mr-1.5" />
            Export
          </Button>
        </div>
      </div>

      <Card>
        <CardContent className="p-4">
          <div className="flex gap-3 items-end flex-wrap">
            <div>
              <label className="block text-xs text-slate-500 mb-1">From</label>
              <input
                type="date"
                className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm w-36"
                value={filters.startDate}
                onChange={(e) => setFilters((f) => ({ ...f, startDate: e.target.value }))}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-500 mb-1">To</label>
              <input
                type="date"
                className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm w-36"
                value={filters.endDate}
                onChange={(e) => setFilters((f) => ({ ...f, endDate: e.target.value }))}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-500 mb-1">User</label>
              <input
                className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm w-40"
                placeholder="Filter by user..."
                value={filters.user}
                onChange={(e) => setFilters((f) => ({ ...f, user: e.target.value }))}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-500 mb-1">Action</label>
              <input
                className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm w-40"
                placeholder="Filter by action..."
                value={filters.action}
                onChange={(e) => setFilters((f) => ({ ...f, action: e.target.value }))}
              />
            </div>
            <Button
              size="sm"
              variant="ghost"
              onClick={() => setFilters({ startDate: '', endDate: '', user: '', action: '' })}
            >
              Clear
            </Button>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardContent className="p-0">
          <div className="overflow-x-auto max-h-[600px] overflow-y-auto">
            <table className="w-full text-sm">
              <thead className="sticky top-0 bg-slate-900 z-10">
                <tr className="text-left text-slate-400 text-xs uppercase border-b border-slate-800">
                  <th className="px-4 py-3 w-32">Timestamp</th>
                  <th className="px-4 py-3 w-24">User</th>
                  <th className="px-4 py-3 w-24">Account</th>
                  <th className="px-4 py-3 text-right w-24">Old Value</th>
                  <th className="px-4 py-3 text-right w-24">New Value</th>
                  <th className="px-4 py-3">Reason</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800">
                {filtered.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="text-center py-8 text-slate-500">
                      No entries match filters.
                    </td>
                  </tr>
                ) : (
                  filtered.slice(0, 500).map((e, i) => (
                    <tr key={e.id || i} className="hover:bg-slate-900/50">
                      <td
                        className="px-4 py-2 text-xs text-slate-400 whitespace-nowrap"
                        title={e.timestamp}
                      >
                        {formatRelativeTime(e.timestamp)}
                      </td>
                      <td className="px-4 py-2 text-xs text-slate-300">{e.userName}</td>
                      <td className="px-4 py-2 font-mono text-xs text-slate-400">
                        {e.accountName || e.accountId}
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums text-slate-400">
                        {e.oldValue !== undefined && e.oldValue !== null
                          ? new Intl.NumberFormat('en-US', { minimumFractionDigits: 0 }).format(
                              Number(e.oldValue)
                            )
                          : '-'}
                      </td>
                      <td
                        className="px-4 py-2 text-right tabular-nums font-medium"
                        style={{
                          color: (e.newValue || 0) >= (e.oldValue || 0) ? '#4ade80' : '#f87171',
                        }}
                      >
                        {e.newValue !== undefined && e.newValue !== null
                          ? new Intl.NumberFormat('en-US', { minimumFractionDigits: 0 }).format(
                              Number(e.newValue)
                            )
                          : '-'}
                      </td>
                      <td className="px-4 py-2 text-xs text-slate-500">{e.reason || '-'}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
          {entries.length > 500 && (
            <div className="p-3 text-center text-xs text-slate-500 border-t border-slate-800">
              Showing 500 of {entries.length} entries. Export for full dataset.
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useGLStore } from '@/store/glStore'
import { SOXComplianceEngine } from '@/engines/SOXComplianceEngine'
import type { SOXReport, SOXCheckResult, SOXControlCategory } from '@/engines/SOXComplianceEngine'
import { AuditLogEngine } from '@/engines/AuditLogEngine'
import { WorkflowEngine } from '@/engines/WorkflowEngine'
import { RBACEngine } from '@/engines/RBACEngine'
import { Button } from '@/components/ui/Button'
import { Card, CardContent } from '@/components/ui/Card'
import {
  Shield,
  Download,
  RefreshCw,
  AlertTriangle,
  CheckCircle,
  XCircle,
  Info,
  Lock,
  Users,
  FileText,
  BarChart3,
} from 'lucide-react'

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const SEVERITY_COLORS: Record<string, string> = {
  critical: '#EF4444',
  high: '#F97316',
  medium: '#EAB308',
  low: '#22C55E',
  info: '#3B82F6',
}

const STATUS_ICON: Record<string, typeof CheckCircle> = {
  pass: CheckCircle,
  fail: XCircle,
  warning: AlertTriangle,
  not_applicable: Info,
}

const STATUS_COLORS: Record<string, string> = {
  pass: '#22C55E',
  fail: '#EF4444',
  warning: '#EAB308',
  not_applicable: '#6B7280',
}

const CATEGORY_LABELS: Record<SOXControlCategory, string> = {
  approval_workflow: 'Approval Workflows',
  segregation_of_duties: 'Segregation of Duties',
  audit_trail: 'Audit Trail',
  data_integrity: 'Data Integrity',
  access_control: 'Access Control',
  financial_reporting: 'Financial Reporting',
}

const CATEGORY_ICONS: Record<SOXControlCategory, typeof Shield> = {
  approval_workflow: FileText,
  segregation_of_duties: Users,
  audit_trail: Lock,
  data_integrity: Shield,
  access_control: Lock,
  financial_reporting: BarChart3,
}

// ---------------------------------------------------------------------------
// Components
// ---------------------------------------------------------------------------

function ScoreGauge({ score }: { score: number }) {
  const color =
    score >= 90 ? '#22C55E' : score >= 70 ? '#EAB308' : score >= 50 ? '#F97316' : '#EF4444'
  return (
    <div className="flex flex-col items-center">
      <div className="relative w-32 h-32">
        <svg viewBox="0 0 100 100" className="w-full h-full -rotate-90">
          <circle cx="50" cy="50" r="45" fill="none" stroke="#1E293B" strokeWidth="8" />
          <circle
            cx="50"
            cy="50"
            r="45"
            fill="none"
            stroke={color}
            strokeWidth="8"
            strokeDasharray={`${(score / 100) * 283} 283`}
            strokeLinecap="round"
          />
        </svg>
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-3xl font-bold" style={{ color }}>
            {score}
          </span>
        </div>
      </div>
      <span className="text-sm text-slate-400 mt-2">Compliance Score</span>
    </div>
  )
}

function StatusBadge({ status }: { status: string }) {
  const Icon = STATUS_ICON[status] ?? Info
  const color = STATUS_COLORS[status] ?? '#6B7280'
  return (
    <span
      className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium"
      style={{ backgroundColor: color + '20', color }}
    >
      <Icon className="h-3 w-3" />
      {status.replace('_', ' ')}
    </span>
  )
}

function SeverityBadge({ severity }: { severity: string }) {
  const color = SEVERITY_COLORS[severity] ?? '#6B7280'
  return (
    <span
      className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium"
      style={{ backgroundColor: color + '20', color }}
    >
      {severity}
    </span>
  )
}

function CategorySummaryCard({
  category,
  data,
}: {
  category: SOXControlCategory
  data: { passed: number; failed: number; total: number }
}) {
  const Icon = CATEGORY_ICONS[category]
  const pct = data.total > 0 ? Math.round((data.passed / data.total) * 100) : 100
  return (
    <Card>
      <CardContent className="p-4">
        <div className="flex items-center gap-3 mb-3">
          <div className="p-2 bg-slate-800 rounded">
            <Icon className="h-4 w-4 text-slate-400" />
          </div>
          <div>
            <p className="text-sm font-medium">{CATEGORY_LABELS[category]}</p>
            <p className="text-xs text-slate-500">
              {data.passed}/{data.total} passed
            </p>
          </div>
        </div>
        <div className="w-full bg-slate-800 rounded-full h-2">
          <div
            className="h-2 rounded-full transition-all"
            style={{
              width: `${pct}%`,
              backgroundColor: pct === 100 ? '#22C55E' : pct >= 50 ? '#EAB308' : '#EF4444',
            }}
          />
        </div>
      </CardContent>
    </Card>
  )
}

function CheckRow({ check }: { check: SOXCheckResult }) {
  const [expanded, setExpanded] = useState(false)
  const Icon = STATUS_ICON[check.status] ?? Info
  const color = STATUS_COLORS[check.status] ?? '#6B7280'

  return (
    <div className="border-b border-slate-800 last:border-0">
      <button
        className="w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-900/50 text-left"
        onClick={() => setExpanded(!expanded)}
      >
        <Icon className="h-4 w-4 flex-shrink-0" style={{ color }} />
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium truncate">{check.name}</p>
          <p className="text-xs text-slate-500 truncate">{check.controlId}</p>
        </div>
        <SeverityBadge severity={check.severity} />
        <StatusBadge status={check.status} />
      </button>
      {expanded && (
        <div className="px-4 pb-3 space-y-2">
          <p className="text-xs text-slate-400">{check.description}</p>
          <p className="text-xs text-slate-300">{check.details}</p>
          {check.evidence.length > 0 && (
            <div className="mt-2">
              <p className="text-xs text-slate-500 mb-1">Evidence:</p>
              <ul className="list-disc list-inside space-y-0.5">
                {check.evidence.map((e, i) => (
                  <li key={i} className="text-xs text-slate-400">
                    {e}
                  </li>
                ))}
              </ul>
            </div>
          )}
          {check.remediation && (
            <div className="mt-2 p-2 bg-amber-900/20 border border-amber-800/30 rounded">
              <p className="text-xs text-amber-400">
                <strong>Remediation:</strong> {check.remediation}
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

