export function SOXCompliancePage() {
  useEffect(() => {
    document.title = 'FinPlan Pro - SOX Compliance'
  }, [])

  const navigate = useNavigate()
  const [report, setReport] = useState<SOXReport | null>(null)
  const [filterCategory, setFilterCategory] = useState<SOXControlCategory | 'all'>('all')
  const [filterStatus, setFilterStatus] = useState<string>('all')

  // Create engines with some sample data for demo
  const [engine] = useState(() => {
    const auditEngine = new AuditLogEngine({ retentionDays: 2555 })
    const workflowEngine = new WorkflowEngine()
    const rbacEngine = new RBACEngine()

    // Set up sample RBAC data
    rbacEngine.assignRole('admin-user', 'admin', ['*'], 'system')
    rbacEngine.assignRole('mgr-user', 'manager', ['entity-1'], 'admin-user')
    rbacEngine.assignRole('analyst-user', 'analyst', ['entity-1'], 'admin-user')
    rbacEngine.assignRole('viewer-user', 'viewer', ['entity-1'], 'admin-user')

    // Log some audit entries
    auditEngine.log({
      userId: 'analyst-user',
      userName: 'Analyst',
      action: 'create',
      resource: 'journal_entry',
      resourceId: 'je-001',
      details: 'Created journal entry',
      oldValue: null,
      newValue: { amount: 5000 },
    })
    auditEngine.log({
      userId: 'mgr-user',
      userName: 'Manager',
      action: 'approve',
      resource: 'journal_entry',
      resourceId: 'je-001',
      details: 'Approved journal entry',
    })
    auditEngine.log({
      userId: 'analyst-user',
      userName: 'Analyst',
      action: 'create',
      resource: 'budget',
      resourceId: 'b-001',
      details: 'Created Q1 budget',
    })

    // Create a workflow
    const wf = workflowEngine.createWorkflow({
      name: 'Budget Approval',
      description: 'Standard budget approval workflow',
      steps: [
        {
          id: 's1',
          name: 'Manager Review',
          type: 'sequential',
          approvers: ['mgr-user'],
          order: 0,
          timeoutHours: 48,
        },
        {
          id: 's2',
          name: 'Admin Approval',
          type: 'sequential',
          approvers: ['admin-user'],
          order: 1,
          timeoutHours: 24,
        },
      ],
      createdBy: 'admin-user',
      isTemplate: false,
    })

    // Submit a request
    workflowEngine.submitRequest(
      wf.id,
      'Q1 Budget Review',
      'Quarterly budget',
      'analyst-user',
      50000
    )

    return new SOXComplianceEngine(auditEngine, workflowEngine, rbacEngine)
  })

  const generateReport = useCallback(() => {
    // Derive real data from GL store
    const trialBalance = useGLStore.getState().trialBalance
    const entries = useGLStore.getState().entries

    // Calculate balance sheet from trial balance
    let assets = 0
    let liabilities = 0
    let equity = 0
    for (const row of trialBalance) {
      const ending = row.endingBalance ?? row.beginningBalance + row.debit - row.credit
      if (row.accountType === 'Asset') assets += ending
      else if (row.accountType === 'Liability') liabilities += ending
      else if (row.accountType === 'Equity') equity += ending
    }

    // Fallback to sensible defaults when no GL data exists
    const bs = {
      assets: assets || 100000,
      liabilities: liabilities || 60000,
      equity: equity || 40000,
    }

    // Derive ledger entries from GL entries
    const ledgerEntries =
      entries.length > 0
        ? entries.slice(0, 20).map((e) => ({ debit: e.debit ?? 0, credit: e.credit ?? 0 }))
        : [
            { debit: 5000, credit: 0 },
            { debit: 0, credit: 5000 },
          ]

    // Derive recent entries from GL entries
    const recentEntries =
      entries.length > 0
        ? entries.slice(0, 10).map((e) => ({
            period: e.period ?? 'Unknown',
            timestamp: e.date ?? new Date().toISOString(),
            action: 'create' as const,
          }))
        : [{ period: 'Q1-2026', timestamp: '2026-01-15T10:00:00Z', action: 'create' as const }]

    const r = engine.generateReport({
      balanceSheet: bs,
      ledgerEntries,
      closedPeriods: ['Q4-2025'],
      recentEntries,
    })
    setReport(r)
  }, [engine])

  useEffect(() => {
    generateReport()
  }, [generateReport])

  const filteredChecks = useMemo(() => {
    if (!report) return []
    let checks = [...report.checks]
    if (filterCategory !== 'all') {
      checks = checks.filter((c) => c.category === filterCategory)
    }
    if (filterStatus !== 'all') {
      checks = checks.filter((c) => c.status === filterStatus)
    }
    return checks
  }, [report, filterCategory, filterStatus])

  const handleExport = useCallback(() => {
    if (!report) return
    const headers = [
      'ID',
      'Control',
      'Category',
      'Name',
      'Status',
      'Severity',
      'Details',
      'Remediation',
    ]
    const rows = report.checks.map((c) => [
      c.id,
      c.controlId,
      c.category,
      c.name,
      c.status,
      c.severity,
      c.details,
      c.remediation ?? '',
    ])
    const csv = [
      headers.join(','),
      ...rows.map((r) => r.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(',')),
    ].join('\n')
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `sox-compliance-${new Date().toISOString().slice(0, 10)}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }, [report])

  if (!report) {
    return (
      <div
        className="p-12 text-center max-w-md mx-auto"
        role="main"
        aria-label="Loading SOX compliance report"
      >
        <div className="p-4 bg-slate-800 rounded-full inline-block mb-4">
          <Shield className="h-10 w-10 text-slate-400" aria-hidden="true" />
        </div>
        <h2 className="text-xl font-semibold mb-2">Generating Report...</h2>
        <p className="text-slate-400">Running SOX compliance checks.</p>
      </div>
    )
  }

  return (
    <main className="p-6 space-y-6" role="main" aria-label="SOX Compliance Dashboard">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Shield className="h-6 w-6 text-blue-400" aria-hidden="true" />
            SOX Compliance
          </h1>
          <p className="text-sm text-slate-400 mt-1">
            Sarbanes-Oxley Act compliance monitoring and reporting
          </p>
        </div>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="ghost"
            onClick={generateReport}
            aria-label="Refresh compliance report"
          >
            <RefreshCw className="h-3.5 w-3.5 mr-1.5" aria-hidden="true" />
            Refresh
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={handleExport}
            aria-label="Export compliance report as CSV"
          >
            <Download className="h-3.5 w-3.5 mr-1.5" aria-hidden="true" />
            Export CSV
          </Button>
        </div>
      </div>

      {/* Status Banner */}
      <section aria-label="Compliance Status Summary">
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center gap-8">
              <ScoreGauge score={report.overallScore} />
              <div className="flex-1">
                <div className="flex items-center gap-3 mb-3">
                  <StatusBadge status={report.overallStatus} />
                  <span className="text-sm text-slate-400">
                    Generated {new Date(report.generatedAt).toLocaleString()}
                  </span>
                </div>
                <div className="grid grid-cols-4 gap-4 mb-4">
                  <div>
                    <p className="text-2xl font-bold text-green-400">{report.summary.passed}</p>
                    <p className="text-xs text-slate-500">Passed</p>
                  </div>
                  <div>
                    <p className="text-2xl font-bold text-red-400">{report.summary.failed}</p>
                    <p className="text-xs text-slate-500">Failed</p>
                  </div>
                  <div>
                    <p className="text-2xl font-bold text-yellow-400">{report.summary.warnings}</p>
                    <p className="text-xs text-slate-500">Warnings</p>
                  </div>
                  <div>
                    <p className="text-2xl font-bold text-slate-400">{report.summary.total}</p>
                    <p className="text-xs text-slate-500">Total Checks</p>
                  </div>
                </div>
                {report.criticalFindings.length > 0 && (
                  <div className="p-3 bg-red-900/20 border border-red-800/30 rounded">
                    <p className="text-sm text-red-400 font-medium">
                      {report.criticalFindings.length} critical finding(s) require immediate
                      attention
                    </p>
                  </div>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      </section>

      {/* Category Summary */}
      <section aria-label="Category Summary">
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
          {(Object.keys(report.byCategory) as SOXControlCategory[]).map((cat) => (
            <CategorySummaryCard key={cat} category={cat} data={report.byCategory[cat]} />
          ))}
        </div>
      </section>

      {/* Recommendations */}
      {report.recommendations.length > 0 && (
        <section aria-label="Recommendations">
          <Card>
            <CardContent className="p-4">
              <h3 className="text-sm font-semibold mb-3 flex items-center gap-2">
                <AlertTriangle className="h-4 w-4 text-amber-400" aria-hidden="true" />
                Recommendations
              </h3>
              <ul className="space-y-2">
                {report.recommendations.map((rec, i) => (
                  <li key={i} className="text-sm text-slate-300 flex items-start gap-2">
                    <span className="text-amber-400 mt-0.5">*</span>
                    {rec}
                  </li>
                ))}
              </ul>
            </CardContent>
          </Card>
        </section>
      )}

      {/* Filters */}
      <section aria-label="Compliance Check Filters">
        <Card>
          <CardContent className="p-4">
            <div className="flex gap-3 items-end flex-wrap">
              <div>
                <label className="block text-xs text-slate-500 mb-1">Category</label>
                <select
                  className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm"
                  value={filterCategory}
                  onChange={(e) => setFilterCategory(e.target.value as SOXControlCategory | 'all')}
                >
                  <option value="all">All Categories</option>
                  {Object.entries(CATEGORY_LABELS).map(([key, label]) => (
                    <option key={key} value={key}>
                      {label}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-xs text-slate-500 mb-1">Status</label>
                <select
                  className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm"
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                >
                  <option value="all">All Statuses</option>
                  <option value="pass">Pass</option>
                  <option value="fail">Fail</option>
                  <option value="warning">Warning</option>
                  <option value="not_applicable">N/A</option>
                </select>
              </div>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => {
                  setFilterCategory('all')
                  setFilterStatus('all')
                }}
              >
                Clear
              </Button>
            </div>
          </CardContent>
        </Card>
      </section>

      {/* Checks List */}
      <section aria-label="Compliance Checks">
        <Card>
          <CardContent className="p-0">
            <div className="px-4 py-3 border-b border-slate-800">
              <h3 className="text-sm font-semibold">Compliance Checks ({filteredChecks.length})</h3>
            </div>
            <div className="max-h-[600px] overflow-y-auto">
              {filteredChecks.length === 0 ? (
                <div className="p-8 text-center text-slate-500">
                  No checks match the current filters.
                </div>
              ) : (
                filteredChecks.map((check) => <CheckRow key={check.id} check={check} />)
              )}
            </div>
          </CardContent>
        </Card>
      </section>
    </main>
  )
}

import { useEffect, useState } from 'react'
import { useNavigate, Link } from 'react-router-dom'
import { Button } from '@/components/ui/Button'
import { Input } from '@/components/ui/Input'
import { Card, CardContent } from '@/components/ui/Card'
import { useAuthStore } from '@/store/authStore'
import { LogIn, Mail, Lock, Eye, EyeOff, AlertCircle, Loader2 } from 'lucide-react'
import { z } from 'zod'

const loginSchema = z.object({
  email: z.string().min(1, 'Email is required.').email('Invalid email address.'),
  password: z
    .string()
    .min(1, 'Password is required.')
    .min(6, 'Password must be at least 6 characters.'),
})

export function LoginPage() {
  const navigate = useNavigate()
  const { login, isLoading, error, clearError, isAuthenticated } = useAuthStore()

  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [showPw, setShowPw] = useState(false)
  const [rememberMe, setRememberMe] = useState(false)
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({})
  const [showForgotPw, setShowForgotPw] = useState(false)
  const [forgotEmail, setForgotEmail] = useState('')
  const [forgotSent, setForgotSent] = useState(false)

  useEffect(() => {
    document.title = 'FinPlan Pro — Login'
  }, [])

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated) {
      navigate('/', { replace: true })
    }
  }, [isAuthenticated, navigate])

  const validate = (): boolean => {
    const result = loginSchema.safeParse({ email, password })
    if (!result.success) {
      const errors: Record<string, string> = {}
      for (const issue of result.error.issues) {
        const field = issue.path[0] as string
        errors[field] = issue.message
      }
      setFieldErrors(errors)
      return false
    }
    setFieldErrors({})
    return true
  }

  const handleLogin = async () => {
    if (!validate()) return
    clearError()
    try {
      await login(email, password)
      if (rememberMe) {
        localStorage.setItem('finplan_remembered_email', email)
      } else {
        localStorage.removeItem('finplan_remembered_email')
      }
      navigate('/', { replace: true })
    } catch {
      // Error is handled by authStore
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !isLoading) {
      handleLogin()
    }
  }

  const handleForgotPassword = () => {
    if (!forgotEmail) return
    // Simulate sending reset email (no backend)
    setForgotSent(true)
  }

  // Load remembered email
  useEffect(() => {
    const remembered = localStorage.getItem('finplan_remembered_email')
    if (remembered) {
      setEmail(remembered)
      setRememberMe(true)
    }
  }, [])

  // Forgot password UI
  if (showForgotPw) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
        <Card className="w-full max-w-sm">
          <CardContent className="p-6 space-y-6">
            <div className="text-center">
              <Mail className="h-10 w-10 text-blue-400 mx-auto mb-2" />
              <h1 className="text-xl font-bold">Reset Password</h1>
              <p className="text-sm text-slate-400 mt-1">
                Enter your email to receive a reset link.
              </p>
            </div>

            {forgotSent ? (
              <div className="text-center space-y-4">
                <div className="p-3 bg-green-900/30 text-green-400 rounded-lg text-sm">
                  If an account exists for <strong>{forgotEmail}</strong>, a reset link has been
                  sent.
                </div>
                <Button
                  variant="outline"
                  className="w-full"
                  onClick={() => {
                    setShowForgotPw(false)
                    setForgotSent(false)
                  }}
                >
                  Back to Login
                </Button>
              </div>
            ) : (
              <div className="space-y-4">
                <div>
                  <label className="block text-xs text-slate-400 mb-1">Email</label>
                  <Input
                    type="email"
                    value={forgotEmail}
                    onChange={(e) => setForgotEmail(e.target.value)}
                    placeholder="you@company.com"
                    onKeyDown={(e) => e.key === 'Enter' && handleForgotPassword()}
                  />
                </div>
                <Button className="w-full" onClick={handleForgotPassword}>
                  Send Reset Link
                </Button>
                <Button variant="outline" className="w-full" onClick={() => setShowForgotPw(false)}>
                  Back to Login
                </Button>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    )
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
      <Card className="w-full max-w-sm">
        <CardContent className="p-6 space-y-6">
          <div className="text-center">
            <LogIn className="h-10 w-10 text-blue-400 mx-auto mb-2" />
            <h1 className="text-xl font-bold">FinPlan Pro</h1>
            <p className="text-sm text-slate-400 mt-1">Sign in to your workspace</p>
          </div>

          {/* Global error */}
          {error && (
            <div
              className="flex items-start gap-2 p-3 bg-red-900/30 text-red-400 rounded-lg text-sm"
              role="alert"
            >
              <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
              <span>{error}</span>
            </div>
          )}

          <div className="space-y-4" onKeyDown={handleKeyDown}>
            {/* Email */}
            <div>
              <label htmlFor="login-email" className="block text-xs text-slate-400 mb-1">
                Email
              </label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-500" />
                <Input
                  id="login-email"
                  type="email"
                  value={email}
                  onChange={(e) => {
                    setEmail(e.target.value)
                    setFieldErrors((p) => ({ ...p, email: '' }))
                  }}
                  placeholder="you@company.com"
                  className="pl-10"
                  autoComplete="email"
                  aria-invalid={!!fieldErrors.email}
                  aria-describedby={fieldErrors.email ? 'email-error' : undefined}
                />
              </div>
              {fieldErrors.email && (
                <p id="email-error" className="text-xs text-red-400 mt-1">
                  {fieldErrors.email}
                </p>
              )}
            </div>

            {/* Password */}
            <div>
              <div className="flex items-center justify-between mb-1">
                <label htmlFor="login-password" className="block text-xs text-slate-400">
                  Password
                </label>
                <button
                  type="button"
                  onClick={() => {
                    setShowForgotPw(true)
                    setForgotEmail(email)
                  }}
                  className="text-xs text-blue-400 hover:text-blue-300 transition-colors"
                >
                  Forgot password?
                </button>
              </div>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-500" />
                <Input
                  id="login-password"
                  type={showPw ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => {
                    setPassword(e.target.value)
                    setFieldErrors((p) => ({ ...p, password: '' }))
                  }}
                  placeholder="Enter password"
                  className="pl-10 pr-10"
                  autoComplete="current-password"
                  aria-invalid={!!fieldErrors.password}
                  aria-describedby={fieldErrors.password ? 'password-error' : undefined}
                />
                <button
                  type="button"
                  onClick={() => setShowPw(!showPw)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 hover:text-slate-300"
                  aria-label={showPw ? 'Hide password' : 'Show password'}
                >
                  {showPw ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                </button>
              </div>
              {fieldErrors.password && (
                <p id="password-error" className="text-xs text-red-400 mt-1">
                  {fieldErrors.password}
                </p>
              )}
            </div>

            {/* Remember me */}
            <div className="flex items-center gap-2">
              <input
                id="remember-me"
                type="checkbox"
                checked={rememberMe}
                onChange={(e) => setRememberMe(e.target.checked)}
                className="h-4 w-4 rounded border-slate-600 bg-slate-800 text-blue-500 focus:ring-blue-500"
              />
              <label htmlFor="remember-me" className="text-xs text-slate-400 cursor-pointer">
                Remember my email
              </label>
            </div>

            {/* Submit */}
            <Button className="w-full" onClick={handleLogin} disabled={isLoading}>
              {isLoading ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Signing in...
                </>
              ) : (
                'Sign In'
              )}
            </Button>
          </div>

          {/* Demo hint */}
          <div className="p-3 bg-slate-800/50 rounded-lg text-xs text-slate-400 space-y-1">
            <p className="font-medium text-slate-300">Offline Demo Accounts:</p>
            <p>
              <code className="text-blue-400">admin@finplan.com</code> — Admin (full access)
            </p>
            <p>
              <code className="text-blue-400">analyst@finplan.com</code> — Analyst
            </p>
            <p>
              <code className="text-blue-400">viewer@finplan.com</code> — Viewer (read-only)
            </p>
            <p className="text-slate-500">Any password works in offline mode.</p>
          </div>

          <p className="text-xs text-center text-slate-500">
            Don&apos;t have an account?{' '}
            <Link to="/register" className="text-blue-400 hover:text-blue-300">
              Register
            </Link>
          </p>
        </CardContent>
      </Card>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuthStore } from '@/store/authStore'
import { Button } from '@/components/ui/Button'
import { Input } from '@/components/ui/Input'
import { Card, CardContent } from '@/components/ui/Card'
import { UserPlus, AlertCircle, Loader2 } from 'lucide-react'

export function RegisterPage() {
  const navigate = useNavigate()
  const { register, isLoading, error, isAuthenticated } = useAuthStore()
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [localError, setLocalError] = useState('')

  useEffect(() => {
    if (isAuthenticated) navigate('/')
  }, [isAuthenticated, navigate])

  useEffect(() => {
    document.title = 'FinPlan Pro — Create Account'
  }, [])

  const handleRegister = async () => {
    setLocalError('')

    if (!name || !email || !password || !confirmPassword) {
      setLocalError('All fields are required.')
      return
    }

    if (password !== confirmPassword) {
      setLocalError('Passwords do not match.')
      return
    }

    if (password.length < 8) {
      setLocalError('Password must be at least 8 characters.')
      return
    }

    try {
      await register(name, email, password)
    } catch {
      // error is set in store
    }
  }

  const displayError = localError || error

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
      <Card className="w-full max-w-sm">
        <CardContent className="p-6 space-y-6">
          <div className="text-center">
            <UserPlus className="h-10 w-10 text-blue-400 mx-auto mb-2" />
            <h1 className="text-xl font-bold">Create Account</h1>
            <p className="text-sm text-slate-400">Set up your FinPlan Pro workspace</p>
          </div>

          {displayError && (
            <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/20 rounded-md text-red-400 text-sm">
              <AlertCircle className="h-4 w-4 flex-shrink-0" />
              {displayError}
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label className="block text-xs text-slate-400 mb-1">Full Name</label>
              <Input
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="John Doe"
                disabled={isLoading}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Email</label>
              <Input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="you@company.com"
                disabled={isLoading}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Password</label>
              <Input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Min 8 characters"
                disabled={isLoading}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Confirm Password</label>
              <Input
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="Repeat password"
                disabled={isLoading}
                onKeyDown={(e) => e.key === 'Enter' && handleRegister()}
              />
            </div>
            <Button className="w-full" onClick={handleRegister} disabled={isLoading}>
              {isLoading ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" /> Creating Account...
                </>
              ) : (
                'Create Account'
              )}
            </Button>
          </div>

          <p className="text-xs text-center text-slate-500">
            Already have an account?{' '}
            <button onClick={() => navigate('/login')} className="text-blue-400 hover:underline">
              Sign in
            </button>
          </p>
        </CardContent>
      </Card>
    </div>
  )
}

