import { useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useCollaborationStore } from '@/store/collaborationStore'
import { useBudgetStore } from '@/store/budgetStore'
import { Button } from '@/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { KPIValue } from '@/components/ui/KPIValue'
import { DataTable, type Column } from '@/components/ui/DataTable'
import {
  CheckCircle,
  XCircle,
  Clock,
  FileText,
  Table as TableIcon,
  MessageSquare,
  AlertCircle,
} from 'lucide-react'
import { ExportEngine } from '@/engines/ExportEngine'

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n)
}

interface ApprovalRow {
  id: string
  name: string
  type: string
  requester: string
  amount: number
  submitted: string
  status: 'Pending' | 'Approved' | 'Rejected' | 'ChangesRequested'
}

export function ApprovalQueuePage() {
  const navigate = useNavigate()
  const { approvals, addComment } = useCollaborationStore()
  const { budgets } = useBudgetStore()
  const [filter, setFilter] = useState<'All' | 'Pending' | 'Approved' | 'Rejected'>('All')

  useEffect(() => {
    document.title = 'FinPlan Pro — Approval Queue'
  }, [])

  const rows: ApprovalRow[] = useMemo(() => {
    if (approvals.length > 0) {
      return approvals.map((a) => ({
        id: a.id,
        name: a.resourceName,
        type: a.resourceType,
        requester: a.requesterName,
        amount: a.amount,
        submitted: a.submittedAt ? new Date(a.submittedAt).toLocaleDateString() : '-',
        status: a.status,
      }))
    }
    return budgets.map((b) => ({
      id: b.id,
      name: b.name,
      type: 'Budget',
      requester: 'System',
      amount: b.totalAmount || 0,
      submitted: b.createdAt ? new Date(b.createdAt).toLocaleDateString() : '-',
      status:
        b.status === 'Approved'
          ? ('Approved' as const)
          : b.status === 'Locked'
            ? ('Approved' as const)
            : ('Pending' as const),
    }))
  }, [approvals, budgets])

  const filtered = filter === 'All' ? rows : rows.filter((r) => r.status === filter)
  const pendingCount = rows.filter((r) => r.status === 'Pending').length
  const approvedCount = rows.filter((r) => r.status === 'Approved').length
  const rejectedCount = rows.filter((r) => r.status === 'Rejected').length

  const handleApprove = (id: string) => {
    ;(addComment as any)({
      resourceType: 'Budget',
      resourceId: id,
      cellId: null,
      parentId: null,
      authorId: 'current-user',
      authorName: 'Current User',
      authorInitials: 'CU',
      content: 'Approved',
      mentions: [],
    })
  }

  const handleExportPDF = () => {
    ExportEngine.exportToPDF(
      {
        headers: ['Name', 'Type', 'Requester', 'Amount', 'Submitted', 'Status'],
        rows: filtered.map((r) => [
          r.name,
          r.type,
          r.requester,
          formatCurrency(r.amount),
          r.submitted,
          r.status,
        ]),
      },
      { title: 'Approval Queue Report', companyName: 'FinPlan Pro' }
    )
  }

  const handleExportExcel = () => {
    ExportEngine.exportToExcel(
      {
        headers: ['Name', 'Type', 'Requester', 'Amount', 'Submitted', 'Status'],
        rows: filtered.map((r) => [
          r.name,
          r.type,
          r.requester,
          formatCurrency(r.amount),
          r.submitted,
          r.status,
        ]),
      },
      { title: 'Approval_Queue_Report' }
    )
  }

  const columns: Column[] = [
    { key: 'name', header: 'Name', sortable: true },
    { key: 'type', header: 'Type', sortable: true },
    { key: 'requester', header: 'Requester', sortable: true },
    {
      key: 'amount',
      header: 'Amount',
      align: 'right',
      render: (_, r) => formatCurrency(r.amount as any),
      sortable: true,
    },
    { key: 'submitted', header: 'Submitted', align: 'right', sortable: true },
    {
      key: 'status',
      header: 'Status',
      render: (_, r) => (
        <span
          className={
            r.status === 'Approved'
              ? 'text-green-400'
              : r.status === 'Rejected'
                ? 'text-red-400'
                : r.status === 'Pending'
                  ? 'text-yellow-400'
                  : 'text-blue-400'
          }
        >
          {r.status === 'Approved' ? (
            <CheckCircle className="inline h-4 w-4 mr-1" />
          ) : r.status === 'Rejected' ? (
            <XCircle className="inline h-4 w-4 mr-1" />
          ) : r.status === 'Pending' ? (
            <Clock className="inline h-4 w-4 mr-1" />
          ) : (
            <AlertCircle className="inline h-4 w-4 mr-1" />
          )}
          {r.status as any}
        </span>
      ),
      sortable: true,
    },
  ]

  return (
    <div className="p-6 space-y-6 animate-fade-in">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">Approval Queue</h1>
        <div className="flex gap-2">
          <Button size="sm" variant="ghost" onClick={handleExportPDF} aria-label="Export PDF">
            <FileText className="h-3.5 w-3.5 mr-1.5" />
            PDF
          </Button>
          <Button size="sm" variant="ghost" onClick={handleExportExcel} aria-label="Export Excel">
            <TableIcon className="h-3.5 w-3.5 mr-1.5" />
            Excel
          </Button>
        </div>
      </div>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <KPIValue
          label="Total Items"
          value={rows.length.toString()}
          icon={<MessageSquare className="h-4 w-4" />}
        />
        <KPIValue
          label="Pending"
          value={pendingCount.toString()}
          icon={<Clock className="h-4 w-4" />}
        />
        <KPIValue
          label="Approved"
          value={approvedCount.toString()}
          icon={<CheckCircle className="h-4 w-4" />}
        />
        <KPIValue
          label="Rejected"
          value={rejectedCount.toString()}
          icon={<XCircle className="h-4 w-4" />}
        />
      </div>
      <div className="flex gap-2">
        {(['All', 'Pending', 'Approved', 'Rejected'] as const).map((f) => (
          <Button
            key={f}
            size="sm"
            variant={filter === f ? 'default' : 'ghost'}
            onClick={() => setFilter(f)}
          >
            {f}
          </Button>
        ))}
      </div>
      <DataTable columns={columns} data={filtered} />
    </div>
  )
}

import React, { useState, useMemo } from 'react'
import { Button } from '@/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Input } from '@/components/ui/Input'
import { Select } from '@/components/ui/Select'
import { Skeleton } from '@/components/ui/Skeleton'
import { ConsolidationEngine, EntityData, OwnershipStructure } from '@/engines/ConsolidationEngine'
import { useGLStore } from '@/store/glStore'
import { Plus, Trash2, Edit2 } from 'lucide-react'

interface Entity {
  id: string
  name: string
  code: string
  currency: string
  country: string
  parentId: string | null
  ownershipPct: number
}

const currencies = ['USD', 'EUR', 'GBP', 'JPY', 'CAD', 'AUD']

export function ConsolidationDashboard() {
  const [entities, setEntities] = useState<Entity[]>([])
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [editingEntity, setEditingEntity] = useState<Entity | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [selectedPeriod, setSelectedPeriod] = useState<string>('')

  const glEntries = useGLStore((s) => s.entries)

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    code: '',
    currency: 'USD',
    country: '',
    parentId: '',
    ownershipPct: 100,
  })

  const handleAdd = () => {
    setEditingEntity(null)
    setFormData({
      name: '',
      code: '',
      currency: 'USD',
      country: '',
      parentId: '',
      ownershipPct: 100,
    })
    setIsModalOpen(true)
  }

  const handleEdit = (entity: Entity) => {
    setEditingEntity(entity)
    setFormData({
      name: entity.name,
      code: entity.code,
      currency: entity.currency,
      country: entity.country,
      parentId: entity.parentId || '',
      ownershipPct: entity.ownershipPct,
    })
    setIsModalOpen(true)
  }

  const handleDelete = (entity: Entity) => {
    const hasChildren = entities.some((e) => e.parentId === entity.id)
    if (hasChildren) {
      alert(`Cannot delete ${entity.name} because it has child entities.`)
      return
    }
    if (window.confirm(`Delete ${entity.name}?`)) {
      setEntities(entities.filter((e) => e.id !== entity.id))
    }
  }

  const validate = () => {
    if (formData.name.length < 2) return 'Name must be at least 2 characters'
    if (formData.code.length < 3 || formData.code.length > 8) return 'Code must be 3-8 characters'
    if (
      entities.some(
        (e) => e.code === formData.code && (!editingEntity || e.id !== editingEntity.id)
      )
    ) {
      return 'Code must be unique'
    }
    if (formData.parentId) {
      if (editingEntity && formData.parentId === editingEntity.id)
        return 'Entity cannot be its own parent'

      // Circular check
      let curr = formData.parentId
      while (curr) {
        const parent = entities.find((e) => e.id === curr)
        if (parent && editingEntity && parent.id === editingEntity.id)
          return 'Circular reference detected'
        curr = parent?.parentId || ''
      }
    }
    return null
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    const err = validate()
    if (err) {
      alert(err)
      return
    }

    const newEntity: Entity = {
      id: editingEntity?.id || `ent-${Date.now()}`,
      name: formData.name,
      code: formData.code,
      currency: formData.currency,
      country: formData.country,
      parentId: formData.parentId || null,
      ownershipPct: formData.ownershipPct,
    }

    if (editingEntity) {
      setEntities(entities.map((e) => (e.id === editingEntity.id ? newEntity : e)))
    } else {
      setEntities([...entities, newEntity])
    }
    setIsModalOpen(false)
  }

  const availablePeriods = useMemo(() => {
    const periods = new Set<string>()
    for (const entry of glEntries) {
      periods.add(entry.period || entry.postDate?.slice(0, 7) || entry.date?.slice(0, 7) || '')
    }
    return Array.from(periods)
      .filter(Boolean)
      .sort((a, b) => b.localeCompare(a))
  }, [glEntries])

  const consolidatedData = useMemo(() => {
    if (entities.length === 0) return null

    const period = selectedPeriod || availablePeriods[0] || ''
    if (!period) return null

    const entityData: EntityData[] = entities.map((e) => {
      const entries = glEntries
        .filter((ge) => {
          const entMatch = (ge.entityId || 'default') === e.id
          const perMatch =
            ge.period === period || ge.postDate?.startsWith(period) || ge.date?.startsWith(period)
          return entMatch && perMatch
        })
        .map((ge) => ({
          id: ge.id,
          entityId: e.id,
          accountCode: ge.accountCode,
          accountName: ge.accountName,
          amount: ge.amount ?? ge.debit - ge.credit,
          date: ge.postDate || ge.date,
          period: ge.period || period,
        }))

      return {
        entityId: e.id,
        entityName: e.name,
        currency: e.currency,
        entries,
      }
    })

    const ownerships: OwnershipStructure[] = entities
      .filter((e): e is Entity & { parentId: string } => e.parentId !== null)
      .map((e) => ({
        parentId: e.parentId,
        childId: e.id,
        ownershipPct: e.ownershipPct,
        method: 'full' as const,
      }))

    return ConsolidationEngine.consolidate(entityData, ownerships)
  }, [entities, glEntries, selectedPeriod, availablePeriods])

  if (isLoading)
    return (
      <div className="p-6 space-y-4">
        <Skeleton className="h-10 w-48" />
        <Skeleton className="h-64 w-full" />
      </div>
    )
  if (error)
    return (
      <div className="p-12 text-center text-red-500">
        {error}{' '}
        <Button onClick={() => setError(null)} className="ml-4">
          Retry
        </Button>
      </div>
    )

  return (
    <div className="p-6 space-y-8">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-[var(--text-primary)]">
            Legal Entity Consolidation
          </h1>
          <p className="text-[var(--text-secondary)] mt-1">
            Manage entity structure and view consolidated financial results.
          </p>
        </div>
        <Button onClick={handleAdd}>
          <Plus className="h-4 w-4 mr-2" /> Add Entity
        </Button>
      </div>

      <Card className="border-[var(--border-subtle)] bg-[var(--bg-surface)]">
        <CardHeader>
          <CardTitle>Entity Structure</CardTitle>
        </CardHeader>
        <CardContent>
          {entities.length === 0 ? (
            <div className="py-12 text-center text-[var(--text-secondary)]">
              No entities defined yet. Add your first entity to start consolidation.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <thead className="border-b border-[var(--border-subtle)] text-[var(--text-secondary)] font-medium">
                  <tr>
                    <th className="py-3 px-4">Name</th>
                    <th className="py-3 px-4">Code</th>
                    <th className="py-3 px-4">Currency</th>
                    <th className="py-3 px-4">Country</th>
                    <th className="py-3 px-4">Parent Entity</th>
                    <th className="py-3 px-4">Ownership %</th>
                    <th className="py-3 px-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[var(--border-subtle)] text-[var(--text-primary)]">
                  {entities.map((entity) => (
                    <tr key={entity.id} className="hover:bg-[var(--bg-muted)] transition-colors">
                      <td className="py-3 px-4 font-medium">{entity.name}</td>
                      <td className="py-3 px-4 font-mono">{entity.code}</td>
                      <td className="py-3 px-4">{entity.currency}</td>
                      <td className="py-3 px-4">{entity.country}</td>
                      <td className="py-3 px-4">
                        {entities.find((e) => e.id === entity.parentId)?.name || '-'}
                      </td>
                      <td className="py-3 px-4">{entity.ownershipPct}%</td>
                      <td className="py-3 px-4 text-right space-x-2">
                        <Button variant="outline" size="sm" onClick={() => handleEdit(entity)}>
                          <Edit2 className="h-3 w-3" />
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          className="text-red-500 border-red-500/20 hover:bg-red-500/10"
                          onClick={() => handleDelete(entity)}
                        >
                          <Trash2 className="h-3 w-3" />
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>

      {entities.length > 0 && consolidatedData && (
        <Card className="border-[var(--border-subtle)] bg-[var(--bg-surface)]">
          <CardHeader>
            <CardTitle>Consolidated Profit & Loss</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-6">
              <div className="flex gap-4 items-center">
                <div className="text-sm text-[var(--text-secondary)]">Period:</div>
                <Select
                  options={availablePeriods.map((p) => ({
                    value: p,
                    label: p,
                  }))}
                  value={selectedPeriod || availablePeriods[0] || ''}
                  onChange={setSelectedPeriod}
                />
              </div>

              {(() => {
                const ws = consolidatedData.worksheet
                const period = selectedPeriod || availablePeriods[0] || ''

                const acctNames = new Map<string, string>()
                for (const e of ws.combinedEntries) {
                  if (!acctNames.has(e.accountCode)) acctNames.set(e.accountCode, e.accountName)
                }

                const accounts = Array.from(
                  new Set(ws.consolidatedEntries.map((e) => e.accountCode))
                ).sort()

                const entityAmounts = new Map<string, Map<string, number>>()
                for (const ent of entities) {
                  const inner = new Map<string, number>()
                  const raw = glEntries.filter(
                    (ge) =>
                      (ge.entityId || 'default') === ent.id &&
                      (ge.period === period ||
                        ge.postDate?.startsWith(period) ||
                        ge.date?.startsWith(period))
                  )
                  for (const ge of raw) {
                    inner.set(
                      ge.accountCode,
                      (inner.get(ge.accountCode) ?? 0) + (ge.amount ?? ge.debit - ge.credit)
                    )
                  }
                  entityAmounts.set(ent.id, inner)
                }

                const rows = accounts.map((code) => {
                  const consEntry = ws.consolidatedEntries.find((e) => e.accountCode === code)
                  const consAmt = consEntry?.amount ?? 0
                  const entityAmts = entities.map(
                    (ent) => entityAmounts.get(ent.id)?.get(code) ?? 0
                  )
                  const totalEntity = entityAmts.reduce((s, v) => s + v, 0)
                  const elim = totalEntity - consAmt
                  return { code, name: acctNames.get(code) || code, entityAmts, elim, consAmt }
                })

                const fmt = (n: number) => {
                  const abs = Math.abs(n)
                  const formatted = '$' + abs.toLocaleString('en-US', { minimumFractionDigits: 0 })
                  return n < 0 ? `(${formatted})` : formatted
                }

                return (
                  <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm tabular-nums">
                      <thead className="border-b border-[var(--border-subtle)] text-[var(--text-secondary)]">
                        <tr>
                          <th className="py-3 px-4">Account</th>
                          {entities.map((e) => (
                            <th key={e.id} className="py-3 px-4 text-right">
                              {e.name}
                            </th>
                          ))}
                          <th className="py-3 px-4 text-right">Eliminations</th>
                          <th className="py-3 px-4 text-right font-bold text-blue-400">
                            Consolidated
                          </th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-[var(--border-subtle)] text-[var(--text-primary)]">
                        {rows.map((row) => (
                          <tr key={row.code} className="hover:bg-[var(--bg-muted)]">
                            <td className="py-3 px-4">{row.name}</td>
                            {row.entityAmts.map((amt, i) => (
                              <td key={entities[i].id} className="py-3 px-4 text-right">
                                {fmt(amt)}
                              </td>
                            ))}
                            <td
                              className={`py-3 px-4 text-right ${row.elim !== 0 ? 'text-red-400' : ''}`}
                            >
                              {fmt(row.elim)}
                            </td>
                            <td className="py-3 px-4 text-right font-bold">{fmt(row.consAmt)}</td>
                          </tr>
                        ))}
                        <tr className="bg-[var(--bg-muted)] font-bold border-t-2 border-[var(--border-subtle)]">
                          <td className="py-3 px-4">Net Income</td>
                          {entities.map((ent) => {
                            const entMap = entityAmounts.get(ent.id)
                            const rev = Array.from(entMap?.entries() ?? [])
                              .filter(([c]) => c.startsWith('4'))
                              .reduce((s, [, v]) => s + v, 0)
                            const exp = Array.from(entMap?.entries() ?? [])
                              .filter(([c]) => c.startsWith('5') || c.startsWith('6'))
                              .reduce((s, [, v]) => s + v, 0)
                            return (
                              <td key={ent.id} className="py-3 px-4 text-right text-green-400">
                                {fmt(rev + exp)}
                              </td>
                            )
                          })}
                          <td className="py-3 px-4 text-right">
                            {fmt(
                              consolidatedData.totalRevenue +
                                consolidatedData.totalExpenses -
                                entities.reduce((s, ent) => {
                                  const entMap = entityAmounts.get(ent.id)
                                  const rev = Array.from(entMap?.entries() ?? [])
                                    .filter(([c]) => c.startsWith('4'))
                                    .reduce((ss, [, v]) => ss + v, 0)
                                  const exp = Array.from(entMap?.entries() ?? [])
                                    .filter(([c]) => c.startsWith('5') || c.startsWith('6'))
                                    .reduce((ss, [, v]) => ss + v, 0)
                                  return s + rev + exp
                                }, 0)
                            )}
                          </td>
                          <td className="py-3 px-4 text-right text-blue-400">
                            {fmt(consolidatedData.netIncome)}
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                )
              })()}
            </div>
          </CardContent>
        </Card>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <Card className="w-full max-w-lg mx-4">
            <CardHeader>
              <CardTitle>{editingEntity ? 'Edit Entity' : 'Add New Entity'}</CardTitle>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">Name</label>
                    <Input
                      required
                      placeholder="e.g. US Parent"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">Code</label>
                    <Input
                      required
                      maxLength={8}
                      placeholder="e.g. US001"
                      value={formData.code}
                      onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Currency
                    </label>
                    <Select
                      options={currencies.map((c) => ({ value: c, label: c }))}
                      value={formData.currency}
                      onChange={(val) => setFormData({ ...formData, currency: val })}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Country
                    </label>
                    <Input
                      placeholder="e.g. United States"
                      value={formData.country}
                      onChange={(e) => setFormData({ ...formData, country: e.target.value })}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Parent Entity
                    </label>
                    <Select
                      options={[
                        { value: '', label: 'No Parent' },
                        ...entities
                          .filter((e) => !editingEntity || e.id !== editingEntity.id)
                          .map((e) => ({ value: e.id, label: e.name })),
                      ]}
                      value={formData.parentId}
                      onChange={(val) => setFormData({ ...formData, parentId: val })}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Ownership %
                    </label>
                    <Input
                      type="number"
                      min={0}
                      max={100}
                      value={formData.ownershipPct}
                      onChange={(e) =>
                        setFormData({ ...formData, ownershipPct: Number(e.target.value) })
                      }
                    />
                  </div>
                </div>

                <div className="flex justify-end gap-3 pt-4">
                  <Button variant="outline" type="button" onClick={() => setIsModalOpen(false)}>
                    Cancel
                  </Button>
                  <Button type="submit">{editingEntity ? 'Update Entity' : 'Create Entity'}</Button>
                </div>
              </form>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  )
}

