  const filteredAccounts = useMemo(() => {
    let list = accounts
    if (filterType !== 'all') list = list.filter((a) => a.type === filterType)
    if (search) {
      const q = search.toLowerCase()
      list = list.filter(
        (a) => a.code.toLowerCase().includes(q) || a.name.toLowerCase().includes(q)
