  const handleSubmit = useCallback(() => {
    if (Object.keys(formErrors).length > 0) return
    if (editingId) {
      updateAccount(editingId, {
        code: form.code.toUpperCase(),
        name: form.name,
        type: form.type,
        category: form.category || '-',
        subCategory: form.subCategory,
