                    </label>
                    <select
                      id="rec-key-col"
                      className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:outline-none"
                      value={recKeyCol}
                      onChange={(e) => setRecKeyCol(e.target.value)}
                      aria-label="Select account key column"
                    >
                      {csvHeaders.map((h) => (
                        <option key={h} value={h}>
                          {h}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label htmlFor="rec-val-col" className="block text-xs text-slate-500 mb-1">
                      Balance Column
                    </label>
                    <select
                      id="rec-val-col"
                      className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:outline-none"
                      value={recValCol}
                      onChange={(e) => setRecValCol(e.target.value)}
                      aria-label="Select balance column"
                    >
                      {csvHeaders.map((h) => (
                        <option key={h} value={h}>
                          {h}
                        </option>
                      ))}
                    </select>
                  </div>
                  <Button
                    className="mt-5"
                    onClick={runReconciliation}
                    disabled={!recKeyCol || !recValCol}
                    aria-label="Run reconciliation"
                  >
                    <ArrowLeftRight className="h-4 w-4 mr-2" aria-hidden="true" />
                    Run Reconciliation
                  </Button>
                </div>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {recResult && (
        <Card>
          <CardContent className="p-4">
            <h3 className="font-semibold mb-3">Reconciliation Results</h3>
            <div
              className="grid grid-cols-3 gap-4 mb-4"
              role="group"
              aria-label="Reconciliation summary"
            >
              <div className="p-3 bg-green-900/20 rounded-lg border border-green-800/30 text-center">
                <CheckCircle2 className="h-5 w-5 text-green-400 mx-auto mb-1" aria-hidden="true" />
                <div
                  className="text-xl font-bold text-green-400"
                  aria-label={`${recResult.matching} matching`}
                >
                  {recResult.matching}
                </div>
                <div className="text-xs text-green-400/70">Matching</div>
              </div>
              <div className="p-3 bg-red-900/20 rounded-lg border border-red-800/30 text-center">
                <XCircle className="h-5 w-5 text-red-400 mx-auto mb-1" aria-hidden="true" />
                <div
                  className="text-xl font-bold text-red-400"
                  aria-label={`${recResult.mismatches} mismatches`}
                >
                  {recResult.mismatches}
                </div>
                <div className="text-xs text-red-400/70">Mismatches</div>
              </div>
              <div className="p-3 bg-yellow-900/20 rounded-lg border border-yellow-800/30 text-center">
                <AlertTriangle
                  className="h-5 w-5 text-yellow-400 mx-auto mb-1"
                  aria-hidden="true"
                />
                <div
                  className="text-xl font-bold text-yellow-400"
                  aria-label={`${recResult.missing} missing`}
                >
                  {recResult.missing}
                </div>
                <div className="text-xs text-yellow-400/70">Missing</div>
              </div>
            </div>
            <div className="overflow-x-auto" aria-live="polite">
              <table className="w-full text-sm" role="grid" aria-label="Reconciliation details">
                <thead>
                  <tr
                    className="text-left text-slate-400 text-xs uppercase border-b border-slate-800"
                    role="row"
                  >
                    <th className="pb-3 pr-4" role="columnheader" scope="col">
                      Account Key
                    </th>
                    <th className="pb-3 pr-4 text-right" role="columnheader" scope="col">
                      Expected (GL)
                    </th>
                    <th className="pb-3 pr-4 text-right" role="columnheader" scope="col">
                      Actual (File)
                    </th>
                    <th className="pb-3 pr-4 text-right" role="columnheader" scope="col">
                      Difference
                    </th>
                    <th className="pb-3" role="columnheader" scope="col">
                      Status
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800">
                  {recResult.details
                    .filter((d) => d.expected !== 0 || d.actual !== 0)
                    .map((d) => {
                      const status =
                        d.expected === 0
                          ? 'missing'
                          : Math.abs(d.diff) < 0.01
                            ? 'match'
                            : 'mismatch'
                      return (
                        <tr
                          key={d.key}
                          className={`hover:bg-slate-900/50 ${
                            status === 'mismatch'
                              ? 'bg-red-900/10'
                              : status === 'missing'
                                ? 'bg-yellow-900/10'
                                : ''
                          }`}
                        >
                          <td className="py-3 pr-4 font-mono text-xs">{d.key}</td>
                          <td className="py-3 pr-4 text-right tabular-nums">
                            {new Intl.NumberFormat('en-US', {
                              style: 'currency',
                              currency: 'USD',
                              minimumFractionDigits: 0,
                            }).format(d.expected)}
                          </td>
                          <td className="py-3 pr-4 text-right tabular-nums">
                            {new Intl.NumberFormat('en-US', {
                              style: 'currency',
                              currency: 'USD',
                              minimumFractionDigits: 0,
                            }).format(d.actual)}
                          </td>
                          <td
                            className={`py-3 pr-4 text-right tabular-nums font-medium ${
                              Math.abs(d.diff) < 0.01
                                ? 'text-slate-400'
                                : d.diff > 0
                                  ? 'text-green-400'
                                  : 'text-red-400'
                            }`}
                          >
                            {new Intl.NumberFormat('en-US', {
                              style: 'currency',
                              currency: 'USD',
                              minimumFractionDigits: 0,
                              signDisplay: 'exceptZero',
                            }).format(d.diff)}
                          </td>
                          <td className="py-3">
                            {status === 'match' && (
                              <Badge variant="default" className="text-[10px]">
                                Match
                              </Badge>
                            )}
                            {status === 'mismatch' && (
                              <Badge variant="destructive" className="text-[10px]">
                                Mismatch
                              </Badge>
                            )}
                            {status === 'missing' && (
                              <Badge variant="secondary" className="text-[10px]">
                                Missing
                              </Badge>
                            )}
                          </td>
                        </tr>
                      )
                    })}
                </tbody>
              </table>
            </div>
            <div className="mt-4 flex justify-end">
              <Button size="sm" variant="ghost" aria-label="Export differences to file">
                <Download className="h-3.5 w-3.5 mr-1.5" />
                Export Differences
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {importJobs.length > 0 && (
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-2 mb-4">
              <Database className="h-5 w-5 text-purple-400" aria-hidden="true" />
              <h3 className="font-semibold">Import Job History</h3>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm" role="grid" aria-label="Import job history">
                <thead>
                  <tr
                    className="text-left text-slate-400 text-xs uppercase border-b border-slate-800"
                    role="row"
                  >
                    <th className="pb-3 pr-4" role="columnheader" scope="col">
                      File
                    </th>
                    <th className="pb-3 pr-4" role="columnheader" scope="col">
                      Type
                    </th>
                    <th className="pb-3 pr-4" role="columnheader" scope="col">
                      Rows
                    </th>
                    <th className="pb-3 pr-4" role="columnheader" scope="col">
                      Status
                    </th>
                    <th className="pb-3" role="columnheader" scope="col">
                      Started
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800">
                  {importJobs.slice(0, 10).map((job) => (
                    <tr key={job.id} className="hover:bg-slate-900/50" role="row">
                      <td className="py-2 pr-4 font-mono text-xs" role="gridcell">
                        {job.filename}
                      </td>
                      <td className="py-2 pr-4" role="gridcell">
                        {job.fileType}
                      </td>
                      <td className="py-2 pr-4" role="gridcell">
                        {job.rowCount.toLocaleString()}
                      </td>
                      <td className="py-2 pr-4" role="gridcell">
                        <Badge
                          variant={
                            job.status === 'Completed'
                              ? 'default'
                              : job.status === 'Failed'
                                ? 'destructive'
                                : 'secondary'
                          }
                          className="text-[10px]"
                        >
                          {job.status}
                        </Badge>
                      </td>
                      <td className="py-2 text-xs text-slate-400" role="gridcell">
                        {new Date(job.startedAt).toLocaleString()}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>
      )}
    </main>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { useLocation } from 'react-router-dom'
import { useNavigate } from 'react-router-dom'
import { useGLStore } from '@/store/glStore'
import { Skeleton } from '@/components/ui/Skeleton'
import { Button } from '@/components/ui/Button'
import { Select } from '@/components/ui/Select'
import { Card, CardContent } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { BarChart3, TrendingUp, TrendingDown, Minus, Search } from 'lucide-react'

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n)
}

export function GLAccountAnalysisPage() {
  const [helpOpen, setHelpOpen] = useState(false)

  useEffect(() => {
    document.title = 'FinPlan Pro — G L Account Analysis'
  }, [])

  const { entries, accounts, accountAnalysis, isLoading, analyzeAccount } = useGLStore()
  const navigate = useNavigate()
  const [selectedAccountId, setSelectedAccountId] = useState('')

  const accountOptions = useMemo(
    () => [
      { value: '', label: 'Select an account...' },
      ...accounts.map((a) => ({ value: a.id, label: a.code + ' — ' + a.name })),
    ],
    [accounts]
  )

  const accountStats = useMemo(() => {
    if (!selectedAccountId || entries.length === 0) return null
    const filtered = entries.filter(
      (e) => e.accountId === selectedAccountId || e.accountCode === selectedAccountId
    )
    if (filtered.length === 0) return null
    const totalDebit = filtered.reduce((s, e) => s + e.debit, 0)
    const totalCredit = filtered.reduce((s, e) => s + e.credit, 0)
    const monthMap = new Map<string, { debit: number; credit: number; count: number }>()
    filtered.forEach((e) => {
      const month = e.period || e.date.slice(0, 7)
      if (!month) return
      const g = monthMap.get(month) || { debit: 0, credit: 0, count: 0 }
      g.debit += e.debit
      g.credit += e.credit
      g.count++
      monthMap.set(month, g)
    })
    const monthlyTotals = Array.from(monthMap.entries())
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([month, g]) => ({
        month,
        debit: g.debit,
        credit: g.credit,
        net: g.debit - g.credit,
        count: g.count,
      }))
    const maxNet = Math.max(...monthlyTotals.map((m) => Math.abs(m.net)), 1)
    return {
      totalDebit,
      totalCredit,
      netChange: totalDebit - totalCredit,
      transactionCount: filtered.length,
      monthlyTotals,
      maxNet,
      avgPerMonth: monthlyTotals.length > 0 ? (totalDebit - totalCredit) / monthlyTotals.length : 0,
    }
  }, [entries, selectedAccountId])

  const handleAccountChange = (value: string) => {
    setSelectedAccountId(value)
    if (value) {
      analyzeAccount(value)
    }
  }

  if (entries.length === 0) {
    return (
      <div className="p-12 text-center max-w-md mx-auto">
        <div className="p-4 bg-slate-800 rounded-full inline-block mb-4">
          <BarChart3 className="h-10 w-10 text-slate-400" />
        </div>
        <h2 className="text-xl font-semibold mb-2">No GL Data</h2>
        <p className="text-slate-400 mb-6">
          Import General Ledger data first to analyze individual accounts.
        </p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center justify-between mb-6">
            <h1 className="text-2xl font-bold">Account Analysis</h1>
            <button
              onClick={() => setHelpOpen(true)}
              className="p-2 hover:bg-slate-800 rounded-full text-slate-500 hover:text-white transition-colors"
              aria-label="Help"
            ></button>
          </div>
          <p className="text-sm text-slate-400 mt-1">
            {entries.length.toLocaleString()} total entries across {accounts.length} accounts
          </p>
        </div>
      </div>

      <Card>
        <CardContent className="p-4">
          <label className="block text-xs font-medium text-slate-400 mb-1.5">Select Account</label>
          <div className="flex gap-3 items-center">
            <div className="flex-1 max-w-md">
              <Select
                options={accountOptions}
                value={selectedAccountId}
                onChange={handleAccountChange}
                placeholder="Search or select an account..."
              />
            </div>
            {selectedAccountId && (
              <Button
                size="sm"
                variant="ghost"
                onClick={() => {
                  setSelectedAccountId('')
                }}
              >
                Clear
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {!selectedAccountId && (
        <div className="text-center py-12 text-slate-500">
          <Search className="h-8 w-8 mx-auto mb-2 opacity-50" />
          <p>Select an account above to view detailed analysis.</p>
        </div>
      )}

      {isLoading && selectedAccountId && (
        <div className="space-y-4">
          <Skeleton variant="rectangular" height={String(100)} />
          <Skeleton variant="rectangular" height={String(200)} />
        </div>
      )}

      {!isLoading && selectedAccountId && !accountStats && (
        <div className="p-12 text-center max-w-md mx-auto">
          <h2 className="text-lg font-semibold mb-2">No Transactions Found</h2>
          <p className="text-slate-400">
            The selected account has no transactions in the current data set.
          </p>
        </div>
      )}

      {accountStats && (
        <>
          <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
            <Card>
              <CardContent className="p-4 text-center">
                <div className="text-xs text-slate-400 mb-1">Total Debits</div>
                <div className="text-lg font-bold tabular-nums text-blue-400">
                  {formatCurrency(accountStats.totalDebit)}
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4 text-center">
                <div className="text-xs text-slate-400 mb-1">Total Credits</div>
                <div className="text-lg font-bold tabular-nums text-green-400">
                  {formatCurrency(accountStats.totalCredit)}
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4 text-center">
                <div className="text-xs text-slate-400 mb-1">Net Change</div>
                <div
                  className={`text-lg font-bold tabular-nums ${accountStats.netChange >= 0 ? 'text-green-400' : 'text-red-400'}`}
                >
                  {formatCurrency(accountStats.netChange)}
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4 text-center">
                <div className="text-xs text-slate-400 mb-1">Transactions</div>
                <div className="text-lg font-bold tabular-nums">
                  {accountStats.transactionCount.toLocaleString()}
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4 text-center">
                <div className="text-xs text-slate-400 mb-1">Avg Monthly</div>
                <div className="text-lg font-bold tabular-nums">
                  {formatCurrency(accountStats.avgPerMonth)}
                </div>
              </CardContent>
            </Card>
          </div>

          <Card>
            <CardContent className="p-4">
              <h3 className="font-semibold mb-4">Monthly Trend</h3>
              {accountStats.monthlyTotals.length === 0 ? (
                <p className="text-slate-500 text-sm text-center py-4">No monthly data available</p>
              ) : (
                <div className="space-y-2">
                  {accountStats.monthlyTotals.map((m) => {
                    const barWidth = (Math.abs(m.net) / accountStats.maxNet) * 100
                    const isPositive = m.net >= 0
                    return (
                      <div key={m.month} className="flex items-center gap-3 text-sm">
                        <span className="w-16 text-xs text-slate-400 shrink-0">{m.month}</span>
                        <div className="flex-1 flex items-center gap-2">
                          <div className="flex-1 bg-slate-800 rounded-full h-5 overflow-hidden flex">
                            {!isPositive && (
                              <div
                                className="bg-red-500/60 h-full rounded-full transition-all"
                                style={{
                                  width: Math.min(barWidth, 100) + '%',
                                  marginLeft: 100 - Math.min(barWidth, 100) + '%',
                                }}
                              />
                            )}
                            {isPositive && (
                              <div
                                className="bg-green-500/60 h-full rounded-full transition-all"
                                style={{ width: Math.min(barWidth, 100) + '%' }}
                              />
                            )}
                          </div>
                          <span
                            className={`w-24 text-right tabular-nums font-medium ${isPositive ? 'text-green-400' : 'text-red-400'}`}
                          >
                            {formatCurrency(m.net)}
                          </span>
                        </div>
                      </div>
                    )
                  })}
                </div>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-0">
              <div className="px-4 py-3 border-b border-slate-800">
                <h3 className="font-semibold">Monthly Breakdown</h3>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-left text-slate-400 text-xs uppercase border-b border-slate-800">
                      <th className="px-4 py-3">Month</th>
                      <th className="px-4 py-3 text-right">Debits</th>
                      <th className="px-4 py-3 text-right">Credits</th>
                      <th className="px-4 py-3 text-right">Net</th>
                      <th className="px-4 py-3 text-right">Transactions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800">
                    {accountStats.monthlyTotals.map((m) => (
                      <tr key={m.month} className="hover:bg-slate-900/50">
                        <td className="px-4 py-3 text-xs text-slate-400">{m.month}</td>
                        <td className="px-4 py-3 text-right tabular-nums text-blue-400">
                          {formatCurrency(m.debit)}
                        </td>
                        <td className="px-4 py-3 text-right tabular-nums text-green-400">
                          {formatCurrency(m.credit)}
                        </td>
                        <td
                          className={`px-4 py-3 text-right tabular-nums font-medium ${m.net >= 0 ? 'text-green-400' : 'text-red-400'}`}
                        >
                          {formatCurrency(m.net)}
                        </td>
                        <td className="px-4 py-3 text-right tabular-nums text-slate-400">
                          {m.count}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>
        </>
      )}
    </div>
  )
}

