export function GLTrialBalancePage() {
  const [helpOpen, setHelpOpen] = useState(false)

  useEffect(() => {
    document.title = 'FinPlan Pro — G L Trial Balance'
  }, [])

  const { entries, trialBalance, isLoading, generateTrialBalance } = useGLStore()
  const navigate = useNavigate()

  useEffect(() => {
    if (entries.length > 0 && trialBalance.length === 0 && !isLoading) {
      generateTrialBalance()
    }
  }, [entries, trialBalance, isLoading, generateTrialBalance])

  const { totalDebits, totalCredits, diff, isBalanced } = useMemo(() => {
    const debits = trialBalance.reduce((s, r) => s + r.debit, 0)
    const credits = trialBalance.reduce((s, r) => s + r.credit, 0)
    return {
      totalDebits: debits,
      totalCredits: credits,
      diff: debits - credits,
      isBalanced: Math.abs(debits - credits) < 0.01,
    }
  }, [trialBalance])

  const columns: Column[] = useMemo(
    () => [
      {
        key: 'accountCode',
        header: 'Code',
        width: '80px',
        render: (v) => <span className="font-mono text-xs text-slate-400">{String(v)}</span>,
      },
      { key: 'accountName', header: 'Account Name' },
      {
        key: 'accountType',
        header: 'Type',
        width: '64px',
        render: (v) => (
          <Badge variant="default" className="text-[10px]">
            {String(v)}
          </Badge>
        ),
      },
      {
        key: 'beginningBalance',
        header: 'Beginning Balance',
        align: 'right',
        width: '112px',
        render: (v) => formatCurrency(v as number),
      },
      {
        key: 'debit',
        header: 'Debits',
        align: 'right',
        width: '112px',
        render: (v) => <span className="text-blue-400">{formatCurrency(v as number)}</span>,
      },
      {
        key: 'credit',
        header: 'Credits',
        align: 'right',
        width: '112px',
        render: (v) => <span className="text-green-400">{formatCurrency(v as number)}</span>,
      },
      {
        key: 'netChange',
        header: 'Net Change',
        align: 'right',
        width: '112px',
        render: (v) => {
          const n = v as number
          return (
            <span
              className={`font-medium ${n > 0 ? 'text-green-400' : n < 0 ? 'text-red-400' : 'text-slate-300'}`}
            >
              {formatCurrency(n)}
            </span>
          )
        },
      },
      {
        key: 'endingBalance',
        header: 'Ending Balance',
        align: 'right',
        width: '112px',
        render: (v) => {
          const n = v as number
          return (
            <span
              className={`font-semibold ${n > 0 ? 'text-green-400' : n < 0 ? 'text-red-400' : 'text-slate-300'}`}
            >
              {formatCurrency(n)}
            </span>
          )
        },
      },
    ],
    []
  )

  if (isLoading) {
    return (
      <div className="p-6 space-y-4">
        <Skeleton variant="rectangular" height="32px" className="w-60" />
        <Skeleton variant="rectangular" height="48px" />
        <Skeleton variant="rectangular" height="400px" />
      </div>
    )
  }

  if (entries.length === 0) {
    return (
      <div className="p-12 text-center max-w-md mx-auto">
        <div className="p-4 bg-slate-800 rounded-full inline-block mb-4">
          <Scale className="h-10 w-10 text-slate-400" />
        </div>
        <h2 className="text-xl font-semibold mb-2">No GL Data</h2>
        <p className="text-slate-400 mb-6">
          Import General Ledger entries first to generate the Trial Balance. The Trial Balance
          verifies that total debits equal total credits.
        </p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    )
  }

  if (trialBalance.length === 0) {
    return (
      <div className="p-12 text-center max-w-md mx-auto">
        <h2 className="text-xl font-semibold mb-2">Trial Balance Not Generated</h2>
        <p className="text-slate-400 mb-6">
          Click below to generate the Trial Balance from {entries.length.toLocaleString()} GL
          entries.
        </p>
        <Button onClick={generateTrialBalance}>
          <RefreshCw className="h-4 w-4 mr-2" />
          Generate Trial Balance
        </Button>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      <div
        className={`px-4 py-3 rounded-lg text-sm font-semibold flex items-center gap-3 ${
          isBalanced
            ? 'bg-green-900/30 text-green-400 border border-green-800/50'
            : 'bg-red-900/30 text-red-400 border border-red-800/50'
        }`}
      >
        <div className={`p-1.5 rounded-full ${isBalanced ? 'bg-green-800/50' : 'bg-red-800/50'}`}>
          <Scale className="h-5 w-5" />
        </div>
        <div>
          {isBalanced
            ? 'Trial Balance is Balanced — Total Debits = Total Credits'
            : `Trial Balance is Off by ${formatCurrency(Math.abs(diff))}`}
        </div>
      </div>

      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center justify-between mb-6">
            <h1 className="text-2xl font-bold">Trial Balance</h1>
            <button
              onClick={() => setHelpOpen(true)}
              className="p-2 hover:bg-slate-800 rounded-full text-slate-500 hover:text-white transition-colors"
              aria-label="Help"
            ></button>
          </div>
          <p className="text-sm text-slate-400 mt-1">
            {trialBalance.length} accounts · {entries.length.toLocaleString()} entries
          </p>
        </div>
        <div className="flex gap-2">
          <Button size="sm" variant="secondary" onClick={generateTrialBalance}>
            <RefreshCw className="h-3.5 w-3.5 mr-1.5" />
            Refresh
          </Button>
          <Button size="sm" variant="ghost">
            <Download className="h-3.5 w-3.5 mr-1.5" />
            Export
          </Button>
        </div>
      </div>

      <Card>
        <CardContent className="p-0">
          <DataTable
            columns={columns}
            data={trialBalance as unknown as Record<string, unknown>[]}
            pageSize={50}
          />
        </CardContent>
      </Card>

      <div className="flex items-center justify-end gap-8 px-4 py-3 rounded-lg border border-slate-800 bg-slate-900/50 font-bold text-sm text-slate-200 tabular-nums">
        <span>Total</span>
        <span>{formatCurrency(trialBalance.reduce((s, r) => s + r.beginningBalance, 0))}</span>
        <span className="text-blue-400">{formatCurrency(totalDebits)}</span>
        <span className="text-green-400">{formatCurrency(totalCredits)}</span>
        <span>{formatCurrency(trialBalance.reduce((s, r) => s + r.netChange, 0))}</span>
        <span>{formatCurrency(trialBalance.reduce((s, r) => s + r.endingBalance, 0))}</span>
      </div>
    </div>
  )
}

