      { key: 'unit', header: 'Unit', width: '100px' },
      {
        key: 'current',
        header: 'Current',
        align: 'right',
        render: (v) => formatNumber(v as number),
      },
      { key: 'target', header: 'Target', align: 'right', render: (v) => formatNumber(v as number) },
      {
        key: 'trend',
        header: 'Trend',
        align: 'right',
        render: (v) => {
          const val = v as number
          return (
            <span
              className={val > 0 ? 'text-green-400' : val < 0 ? 'text-red-400' : 'text-slate-400'}
            >
              {val > 0 ? '+' : ''}
              {val}%
            </span>
          )
        },
      },
      {
        key: 'status',
        header: 'Status',
        render: (_v, row) => {
          const current = row.current as number
          const target = row.target as number
          const pct = target > 0 ? (current / target) * 100 : 100
          const color =
            pct >= 90 ? 'text-green-400' : pct >= 70 ? 'text-yellow-400' : 'text-red-400'
          return (
            <span className={color}>
              {pct >= 90 ? 'On Track' : pct >= 70 ? 'In Progress' : 'Behind'}
            </span>
          )
        },
      },
    ],
    []
  )

  const mapMetrics = (metrics: ESGMetric[]) =>
    metrics.map((m) => ({
      metric: m.name,
      unit: m.unit,
      current: m.value,
      target: m.target,
      trend: m.trend === 'up' ? 5 : m.trend === 'down' ? -5 : 0,
    }))

  const envMetrics = getMetricsByCategory('environmental')
  const socialMetrics = getMetricsByCategory('social')
  const govMetrics = getMetricsByCategory('governance')

  // TODO: Remove mock fallback once store is populated with real ESG data
  const activeData =
    activeTab === 'env'
      ? envMetrics.length > 0
        ? mapMetrics(envMetrics)
