// New Driver Form
// ---------------------------------------------------------------------------

interface NewDriverForm {
  name: string
  description: string
  unit: 'percentage' | 'absolute' | 'index' | 'ratio'
  baseValue: number
  currentValue: number
  minValue: number
  maxValue: number
  step: number
