const MONTH_NAMES = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
]

interface MonthData {
  month: string
  actual: number | null
  forecast: number
  low?: number
  high?: number
}

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n)
}

function aggregateByMonth(
  entries: { postDate?: string; date: string; amount: number; debit: number; credit: number }[]
): Map<string, number> {
  const map = new Map<string, number>()
  for (const e of entries) {
    const d = new Date(e.postDate || e.date)
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
    const amount = e.amount || e.debit - e.credit
    map.set(key, (map.get(key) ?? 0) + amount)
  }
  return map
}

function linearRegression(values: number[]): { slope: number; intercept: number; r2: number } {
  const n = values.length
  if (n < 2) return { slope: 0, intercept: values[0] ?? 0, r2: 0 }
  let sumX = 0,
    sumY = 0,
    sumXY = 0,
    sumXX = 0
  for (let i = 0; i < n; i++) {
    sumX += i
    sumY += values[i]
    sumXY += i * values[i]
    sumXX += i * i
  }
  const denom = n * sumXX - sumX * sumX
  if (denom === 0) return { slope: 0, intercept: sumY / n, r2: 0 }
  const slope = (n * sumXY - sumX * sumY) / denom
  const intercept = (sumY - slope * sumX) / n
  const meanY = sumY / n
  let ssRes = 0,
    ssTot = 0
  for (let i = 0; i < n; i++) {
    const pred = slope * i + intercept
    ssRes += (values[i] - pred) ** 2
    ssTot += (values[i] - meanY) ** 2
  }
  const r2 = ssTot === 0 ? 0 : 1 - ssRes / ssTot
  return { slope, intercept, r2 }
}

function applyLinearForecast(
  historical: { month: string; actual: number }[],
  futureCount: number
): { forecast: number; low: number; high: number }[] {
  const values = historical.map((h) => h.actual)
  const { slope, intercept } = linearRegression(values)
  const n = values.length
  const results: { forecast: number; low: number; high: number }[] = []
  for (let i = 0; i < futureCount; i++) {
    const forecast = slope * (n + i) + intercept
    const margin = Math.abs(forecast) * 0.08
    results.push({
      forecast: Math.max(0, forecast),
      low: Math.max(0, forecast - margin),
      high: forecast + margin,
    })
  }
  return results
}

function applySeasonalForecast(
  historical: { month: string; actual: number }[],
  futureMonthNames: string[]
): { forecast: number; low: number; high: number }[] {
  const monthTotals = new Map<string, number[]>()
  for (const h of historical) {
    const existing = monthTotals.get(h.month) ?? []
    existing.push(h.actual)
    monthTotals.set(h.month, existing)
  }
  const monthAvg = new Map<string, number>()
  for (const [m, vals] of monthTotals) {
    monthAvg.set(m, vals.reduce((a, b) => a + b, 0) / vals.length)
  }
  const allAvg = Array.from(monthAvg.values()).reduce((a, b) => a + b, 0) / (monthAvg.size || 1)
  return futureMonthNames.map((m) => {
    const base = monthAvg.get(m) ?? allAvg
    const trendMultiplier =
      historical.length > 0
        ? historical[historical.length - 1].actual / (historical[0]?.actual || 1)
        : 1
    const scaled = base * (1 + (trendMultiplier - 1) * 0.3)
    const margin = Math.abs(scaled) * 0.12
    return {
      forecast: Math.max(0, scaled),
      low: Math.max(0, scaled - margin),
      high: scaled + margin,
    }
  })
}

function applyAIForecast(
  historical: { month: string; actual: number }[],
  futureCount: number
): { forecast: number; low: number; high: number }[] {
  const values = historical.map((h) => h.actual)
  // Use ForecastMethodEngine Holt-Winters for AI method
  const result = ForecastMethodEngine.holtWinters(values, 0.3, 0.1, 0.1, 12, futureCount)
  return result.forecast.map((f, i) => {
    const band = 0.12 + i * 0.015
    return {
      forecast: Math.max(0, f),
      low: Math.max(0, f * (1 - band)),
      high: f * (1 + band),
    }
  })
}

function computeAccuracy(
  actuals: number[],
  forecasts: number[]
): { mape: string; rmse: string; r2: string; bias: string } {
  const n = Math.min(actuals.length, forecasts.length)
  if (n === 0) return { mape: '—', rmse: '—', r2: '—', bias: '—' }
  let sqErr = 0,
    pctErrSum = 0,
    biasSum = 0
  for (let i = 0; i < n; i++) {
    const diff = actuals[i] - forecasts[i]
    sqErr += diff * diff
    if (actuals[i] !== 0) pctErrSum += Math.abs(diff / actuals[i])
    biasSum += diff
  }
  const mape = ((pctErrSum / n) * 100).toFixed(1) + '%'
  const rmse = formatCurrency(Math.sqrt(sqErr / n))
  const { r2 } = ForecastMethodEngine.linearRegression(actuals, 1)
  const bias = ((biasSum / (actuals.reduce((a, b) => a + b, 0) || 1)) * 100).toFixed(1) + '%'
  return { mape, rmse, r2: r2.toFixed(2), bias }
}

export function ForecastBuilderPage() {
  const { createForecast, updateForecast } = useForecastStore()
  const { entries } = useGLStore()
  const [method, setMethod] = useState<'linear' | 'seasonal' | 'ai'>('linear')

  useEffect(() => {
    document.title = 'FinPlan Pro — Forecast Builder'
  }, [])

  const monthlyAggregation = useMemo(() => {
    if (entries.length === 0) return { historical: [], byMonth: new Map<string, number>() }
    const byMonth = aggregateByMonth(entries)
    const sortedKeys = Array.from(byMonth.keys()).sort()
    const historical = sortedKeys.map((key) => {
      const parts = key.split('-')
      const monthIdx = parseInt(parts[1], 10) - 1
      return { month: MONTH_NAMES[monthIdx], key, actual: byMonth.get(key) ?? 0 }
    })
    return { historical, byMonth }
  }, [entries])

  const chartData = useMemo((): MonthData[] => {
    const { historical } = monthlyAggregation
    if (historical.length === 0) {
      return MONTH_NAMES.map((m) => ({ month: m, actual: null, forecast: 0 }))
    }

    const historicalSlice = historical.slice(0, Math.min(6, historical.length))
    const futureCount = 12 - historicalSlice.length
    const futureMonthNames = MONTH_NAMES.slice(historicalSlice.length, 12)

    let projections: { forecast: number; low: number; high: number }[] = []
    if (futureCount > 0) {
      const regressionData = historical.map((h) => ({ month: h.month, actual: h.actual }))
      if (method === 'linear') {
        projections = applyLinearForecast(regressionData, futureCount)
      } else if (method === 'seasonal') {
        projections = applySeasonalForecast(regressionData, futureMonthNames)
      } else {
        projections = applyAIForecast(regressionData, futureCount)
      }
    }

    const result: MonthData[] = []
    for (let i = 0; i < historicalSlice.length; i++) {
      result.push({
        month: historicalSlice[i].month,
        actual: historicalSlice[i].actual,
        forecast: historicalSlice[i].actual,
      })
    }
    for (let i = 0; i < projections.length; i++) {
      result.push({
        month: MONTH_NAMES[historicalSlice.length + i] ?? `M${historicalSlice.length + i + 1}`,
        actual: null,
        forecast: projections[i].forecast,
        low: projections[i].low,
        high: projections[i].high,
      })
    }
    return result
  }, [monthlyAggregation, method])

  const accuracyMetrics = useMemo(() => {
    const { historical } = monthlyAggregation
    if (historical.length < 3) {
      return [
        { metric: 'MAPE', value: '—', description: 'Mean Absolute Percentage Error' },
        { metric: 'RMSE', value: '—', description: 'Root Mean Square Error' },
        { metric: 'R-Squared', value: '—', description: 'Coefficient of Determination' },
        { metric: 'Bias', value: '—', description: 'Forecast Bias' },
      ]
    }
    const actuals = historical.map((h) => h.actual)
    const reg = ForecastMethodEngine.linearRegression(actuals, 1)
    const fitted = actuals.map((_, i) => reg.slope * i + reg.intercept)
    const acc = computeAccuracy(actuals, fitted)
    return [
      { metric: 'MAPE', value: acc.mape, description: 'Mean Absolute Percentage Error' },
      { metric: 'RMSE', value: acc.rmse, description: 'Root Mean Square Error' },
      { metric: 'R-Squared', value: acc.r2, description: 'Coefficient of Determination' },
      { metric: 'Bias', value: acc.bias, description: 'Forecast Bias' },
    ]
  }, [monthlyAggregation])

  const totalForecast = useMemo(
    () => chartData.filter((d) => d.actual === null).reduce((s, d) => s + d.forecast, 0),
    [chartData]
  )

  const avgConfidence = useMemo(() => {
    const future = chartData.filter((d) => d.actual === null && d.high && d.low)
    if (future.length === 0) return 0
    const total = future.reduce((s, d) => {
      const range = (d.high! - d.low!) / d.forecast
      return s + (1 - Math.min(range, 1)) * 100
    }, 0)
    return Math.round(total / future.length)
  }, [chartData])

  const forecastIdRef = useRef<string | null>(null)

  useEffect(() => {
    if (entries.length === 0) return
    const forecastName = `Revenue Forecast — ${method === 'linear' ? 'Linear' : method === 'seasonal' ? 'Seasonal' : 'AI-Assisted'}`
    const forecastMonths = chartData.filter((d) => d.actual === null)
    const total = forecastMonths.reduce((s, d) => s + d.forecast, 0)
    const confidence = avgConfidence > 80 ? 'High' : avgConfidence > 60 ? 'Medium' : 'Low'
    const desc = JSON.stringify({ method, totalForecast: total, avgConfidence })
    if (forecastIdRef.current) {
      updateForecast(forecastIdRef.current, {
        name: forecastName,
        description: desc,
        confidenceLevel: confidence,
      } as Partial<import('@/types').Forecast>)
    } else {
      const id = createForecast({
        name: forecastName,
        description: desc,
        type: 'Rolling',
        baseBudgetId: '',
        baseBudgetName: '',
        status: 'Draft',
        rollingWindowMonths: 12,
        confidenceLevel: confidence,
        createdBy: 'system',
        createdByName: 'Forecast Builder',
        lastUpdated: new Date().toISOString(),
      })
      if (id) forecastIdRef.current = id
    }
  }, [method, chartData, entries.length, avgConfidence, createForecast, updateForecast])

  const handleExportPDF = () => {
    ExportEngine.exportToPDF(
      {
        headers: ['Month', 'Actual', 'Forecast', 'Low', 'High'],
        rows: chartData.map((d) => [
          d.month,
          d.actual ? formatCurrency(d.actual) : '—',
          formatCurrency(d.forecast),
          d.low ? formatCurrency(d.low) : '—',
