                    size="sm"
                    onClick={handleCompare}
                    disabled={!compareTargetId}
                  >
                    <Zap className="h-3 w-3 mr-1" /> Compare
                  </Button>
                </div>
              )}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {!comparison ? (
              <p className="text-sm text-muted-foreground text-center py-4">
                {sandboxes.length < 2
                  ? 'Create at least 2 scenarios to compare.'
                  : 'Select a target scenario and click Compare.'}
              </p>
            ) : (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="text-center p-3 bg-muted rounded-lg">
                    <p className="text-xs text-muted-foreground">Avg Delta</p>
                    <p className="text-lg font-bold">
                      {formatCurrency(comparison.summary.averageDelta)}
                    </p>
                  </div>
                  <div className="text-center p-3 bg-muted rounded-lg">
                    <p className="text-xs text-muted-foreground">Avg Change</p>
                    <p className="text-lg font-bold">
                      {formatPercent(comparison.summary.averagePercentChange)}
                    </p>
                  </div>
                </div>

                {comparisonChartData.length > 0 && (
                  <div className="h-48">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={comparisonChartData} layout="vertical">
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis type="number" tickFormatter={(v) => formatCurrency(v)} />
                        <YAxis type="category" dataKey="name" width={100} tick={{ fontSize: 12 }} />
                        <Tooltip formatter={(v: any) => formatCurrency(v)} />
                        <Bar dataKey="delta" radius={[0, 4, 4, 0]}>
                          {comparisonChartData.map((entry, i) => (
                            <Cell key={i} fill={entry.delta >= 0 ? '#16a34a' : '#dc2626'} />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                )}

                <div className="space-y-1 max-h-40 overflow-y-auto">
                  {comparison.differences.slice(0, 15).map((d, i) => (
                    <div
                      key={i}
                      className="flex items-center justify-between text-sm py-1 border-b last:border-0"
                    >
                      <span className="truncate">{d.coords.key ?? d.measure}</span>
                      <span className={d.delta >= 0 ? 'text-green-600' : 'text-red-600'}>
                        {formatCurrency(d.delta)} ({formatPercent(d.percentChange)})
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  )
}

import React, { useEffect, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import { useGLStore } from '@/store/glStore'
import { useLogisticsStore } from '@/store/logisticsStore'
import { Button } from '@/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { KPIValue } from '@/components/ui/KPIValue'
import { DataTable, Column } from '@/components/ui/DataTable'
import { formatCurrency, formatNumber, formatCompactNumber } from '@/utils/formatters'
import { Truck, Package, MapPin, Clock } from 'lucide-react'
import type { GLEntry } from '@/types'

function computeLogisticsStats(entries: readonly GLEntry[]) {
  const totalDebit = entries.reduce((s, e) => s + e.debit, 0)
  const totalCredit = entries.reduce((s, e) => s + e.credit, 0)
  const netChange = entries.reduce((s, e) => s + e.netChange, 0)
  const uniqueAccounts = new Set(entries.map((e) => e.accountCode)).size
  const uniqueDepartments = new Set(entries.map((e) => e.departmentId).filter(Boolean)).size

  const accountMap = new Map<
    string,
    { name: string; debit: number; credit: number; net: number; count: number }
  >()
  for (const e of entries) {
    const existing = accountMap.get(e.accountCode) ?? {
      name: e.accountName,
      debit: 0,
      credit: 0,
      net: 0,
      count: 0,
    }
    existing.debit += e.debit
    existing.credit += e.credit
    existing.net += e.netChange
    existing.count += 1
    accountMap.set(e.accountCode, existing)
  }

  const accountBreakdown = Array.from(accountMap.entries())
    .map(([code, data]) => ({
      accountCode: code,
      accountName: data.name,
      debit: data.debit,
      credit: data.credit,
      netChange: data.net,
      transactions: data.count,
    }))
    .sort((a, b) => Math.abs(b.netChange) - Math.abs(a.netChange))

  return {
    totalDebit,
    totalCredit,
    netChange,
    uniqueAccounts,
    uniqueDepartments,
    accountBreakdown,
  }
}

const columns: Column[] = [
  { key: 'accountCode', header: 'Account Code', sortable: true },
  { key: 'accountName', header: 'Account Name', sortable: true },
  { key: 'debit', header: 'Debit', align: 'right', sortable: true },
  { key: 'credit', header: 'Credit', align: 'right', sortable: true },
  { key: 'netChange', header: 'Net Change', align: 'right', sortable: true },
  { key: 'transactions', header: 'Transactions', align: 'right', sortable: true },
]

export function LogisticsPage() {
  const { entries } = useGLStore()
  const { shipments, carrierPerformance, routeCosts } = useLogisticsStore()
  const navigate = useNavigate()

  useEffect(() => {
    document.title = 'FinPlan Pro — Logistics'
  }, [])

  const stats = useMemo(() => computeLogisticsStats(entries), [entries])

  const tableData = useMemo(
    () =>
      stats.accountBreakdown.map((row) => ({
        accountCode: row.accountCode,
        accountName: row.accountName,
        debit: formatCurrency(row.debit),
        credit: formatCurrency(row.credit),
        netChange: formatCurrency(row.netChange),
        transactions: formatNumber(row.transactions),
      })),
    [stats.accountBreakdown]
  )

  const handleImportKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      navigate('/data/gl-upload')
    }
  }

  if (entries.length === 0) {
    return (
      <main className="p-12 text-center" role="main" aria-label="Logistics - No Data">
        <a
          href="#import-btn"
          className="sr-only focus:not-sr-only focus:absolute focus:top-2 focus:left-2 focus:z-50 focus:px-4 focus:py-2 focus:bg-blue-600 focus:text-white focus:rounded"
        >
          Skip to import action
        </a>
        <Truck className="h-10 w-10 text-slate-400 mx-auto mb-4" aria-hidden="true" />
        <h2 className="text-xl font-semibold mb-2">No Logistics Data</h2>
        <p className="text-slate-400 mb-6">Import GL data to view logistics metrics.</p>
        <Button
          id="import-btn"
          onClick={() => navigate('/data/gl-upload')}
          onKeyDown={handleImportKeyDown}
          aria-label="Import GL data to view logistics metrics"
        >
          Import Data
        </Button>
      </main>
    )
  }

  return (
    <main className="p-6 space-y-6 animate-fade-in" role="main" aria-label="Logistics Dashboard">
      <a
        href="#kpi-section"
        className="sr-only focus:not-sr-only focus:absolute focus:top-2 focus:left-2 focus:z-50 focus:px-4 focus:py-2 focus:bg-blue-600 focus:text-white focus:rounded"
      >
        Skip to key metrics
      </a>
      <header className="flex items-center justify-between">
        <h1 id="logistics-heading" className="text-2xl font-bold">
          Logistics
        </h1>
        <span className="text-sm text-slate-400">
          {formatNumber(entries.length)} entries imported
        </span>
      </header>
      <section
        id="kpi-section"
        className="grid grid-cols-2 md:grid-cols-4 gap-4"
        aria-label="Logistics KPIs"
        aria-labelledby="logistics-heading"
      >
        <KPIValue
          label="Total Debit"
          value={formatCompactNumber(stats.totalDebit)}
          icon={<Package className="h-4 w-4" aria-hidden="true" />}
        />
        <KPIValue
          label="Total Credit"
          value={formatCompactNumber(stats.totalCredit)}
          icon={<Clock className="h-4 w-4" aria-hidden="true" />}
        />
        <KPIValue
          label="Active Accounts"
          value={formatNumber(stats.uniqueAccounts)}
          icon={<MapPin className="h-4 w-4" aria-hidden="true" />}
        />
        <KPIValue
          label="Net Change"
          value={formatCompactNumber(stats.netChange)}
          icon={<Truck className="h-4 w-4" aria-hidden="true" />}
        />
        {/* TODO: Replace with store-driven shipment KPIs when logisticsStore is populated */}
        {shipments.length > 0 && (
          <>
            <KPIValue
              label="In Transit"
              value={formatNumber(shipments.filter((s) => s.status === 'In Transit').length)}
