      </section>
      <Card aria-label="Account Breakdown" aria-live="polite">
        <CardHeader>
          <CardTitle id="account-breakdown-title">Account Breakdown</CardTitle>
        </CardHeader>
        <CardContent aria-labelledby="account-breakdown-title">
          {/* TODO: Use routeCosts/carrierPerformance from logisticsStore for charts when populated */}
          {tableData.length > 0 ? (
            <DataTable columns={columns} data={tableData} sortable />
          ) : (
            <p className="text-slate-400">No account data available.</p>
          )}
        </CardContent>
      </Card>
    </main>
  )
}

