          )}
          {activeStatement === 'bva' && (
            <BudgetVsActual
              entity="Company"
              period={new Date().getFullYear().toString()}
              currency="USD"
              data={data}
              onExport={handleExport}
            />
          )}
        </CardContent>
      </Card>
    </div>
  );
