        />
        <KPIValue
          label="Avg Churn"
          value={formatPct(metrics.avgChurn)}
          icon={<TrendingDown className="h-4 w-4" />}
          trend="down"
        />
        <KPIValue
          label="Avg Revenue / Cohort"
