                  <tr key={String(row.cohort)} className="border-b border-slate-800">
                    <td className="py-2 px-3 font-medium">{String(row.cohort)}</td>
                    {Array.from({ length: 6 }, (_, i) => {
                      const val = row[`M${i}`]
                      const numVal = typeof val === 'number' ? val : null
                      const bg =
                        numVal !== null
                          ? numVal >= 80
                            ? 'bg-green-900/40 text-green-300'
                            : numVal >= 60
                              ? 'bg-yellow-900/40 text-yellow-300'
                              : 'bg-red-900/40 text-red-300'
                          : 'text-slate-600'
                      return (
                        <td key={i} className={`text-center py-2 px-3 rounded ${bg}`}>
                          {numVal !== null ? `${numVal}%` : '—'}
                        </td>
                      )
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useScenarioStore } from '@/store/scenarioStore'
import { useGLStore } from '@/store/glStore'
import { Button } from '@/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { KPIValue } from '@/components/ui/KPIValue'
import { DataTable, Column } from '@/components/ui/DataTable'
import { FileText, Table as TableIcon, Save, BarChart3 } from 'lucide-react'
import { ExportEngine } from '@/engines/ExportEngine'
import { AssumptionEngine } from '@/engines/AssumptionEngine'
import { SensitivityTableEngine } from '@/engines/SensitivityTableEngine'
import { MonteCarloEngine } from '@/engines/MonteCarloEngine'
import type { ScenarioMonteCarloResult } from '@/engines/MonteCarloEngine'
import { SensitivityEngine } from '@/engines/SensitivityEngine'
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  LineChart,
  Line,
} from 'recharts'
import { VarianceChart } from '@/components/charts/VarianceChart'
import type { Scenario } from '@/types'

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n)
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

export function ScenarioBuilderPage() {
  const { scenarios, createScenario } = useScenarioStore()
  const { entries, accounts } = useGLStore()
  const navigate = useNavigate()

  const [growthRate, setGrowthRate] = useState(10)
  const [headcountChange, setHeadcountChange] = useState(20)
  const [pricingChange, setPricingChange] = useState(5)
  const [cogsChange, setCogsChange] = useState(-2)
  const [mcResult, setMcResult] = useState<ScenarioMonteCarloResult | null>(null)
  const [mcRunning, setMcRunning] = useState(false)

  useEffect(() => {
    document.title = 'FinPlan Pro — Scenario Builder'
  }, [])

  const baseMetrics = useMemo(() => {
    if (entries.length === 0) {
      return { revenue: 0, cogs: 0, opex: 0, headcount: 0, avgSalary: 0 }
    }

    const accountMap = new Map(accounts.map((a) => [a.id, a.type]))

    let revenue = 0
    let cogs = 0
    let opex = 0

    for (const entry of entries) {
      const type = accountMap.get(entry.accountId) ?? 'Unknown'
      const amount = entry.netChange || entry.debit - entry.credit

      if (type === 'Revenue') revenue += Math.abs(amount)
      else if (type === 'COGS') cogs += Math.abs(amount)
      else if (type === 'OpEx') opex += Math.abs(amount)
    }

    return {
      revenue,
      cogs,
      opex,
      headcount: 0,
      avgSalary: 0,
    }
  }, [entries, accounts])

  const scenarioImpact = useMemo(() => {
    const revenueImpact = baseMetrics.revenue * (growthRate / 100)
    const pricingImpact = baseMetrics.revenue * (pricingChange / 100)
    const headcountCost = headcountChange * baseMetrics.avgSalary
    const cogsImpact = baseMetrics.cogs * (cogsChange / 100)
    const totalRevenueChange = revenueImpact + pricingImpact
    const totalCostChange = headcountCost + cogsImpact
    const netImpact = totalRevenueChange - totalCostChange
    return {
      revenueImpact: totalRevenueChange,
      costImpact: totalCostChange,
      netImpact,
      newRevenue: baseMetrics.revenue + totalRevenueChange,
      newOpex: baseMetrics.opex + headcountCost,
      newCogs: baseMetrics.cogs + cogsImpact,
    }
  }, [baseMetrics, growthRate, headcountChange, pricingChange, cogsChange])

  const comparisonData = useMemo(() => {
    const accountMap = new Map(accounts.map((a) => [a.id, a]))

    const monthlyRevenue = new Map<string, number>()
    for (const entry of entries) {
      const acct = accountMap.get(entry.accountId)
      if (!acct || acct.type !== 'Revenue') continue
      const d = new Date(entry.postDate || entry.date)
      const monthKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
      monthlyRevenue.set(
        monthKey,
        (monthlyRevenue.get(monthKey) ?? 0) +
          Math.abs(entry.netChange || entry.debit - entry.credit)
      )
    }

    const sortedKeys = Array.from(monthlyRevenue.keys()).sort()
    const monthsToShow = sortedKeys.length > 0 ? sortedKeys.slice(-6) : []

    if (monthsToShow.length === 0) {
      const monthlyBase = baseMetrics.revenue / 12
      const multiplier = 1 + (growthRate + pricingChange) / 100
      return MONTHS.slice(0, 6).map((month) => ({
        month,
        base: Math.round(monthlyBase),
        scenario: Math.round(monthlyBase * multiplier),
      }))
    }

    const multiplier = 1 + (growthRate + pricingChange) / 100
    return monthsToShow.map((key) => {
      const [, mm] = key.split('-')
      const monthLabel = MONTHS[Number(mm) - 1] ?? key
      const base = monthlyRevenue.get(key) ?? 0
      return {
        month: monthLabel,
        base: Math.round(base),
        scenario: Math.round(base * multiplier),
      }
    })
  }, [entries, accounts, baseMetrics, growthRate, pricingChange])

  const sensitivityData = useMemo(
    () => [
      {
        parameter: 'Revenue Growth',
        low: Math.min(growthRate - 5, -5),
        base: growthRate,
        high: growthRate + 15,
      },
      {
        parameter: 'COGS %',
        low: Math.min(cogsChange - 3, -10),
        base: cogsChange,
        high: cogsChange + 7,
      },
      {
        parameter: 'Headcount',
        low: Math.min(headcountChange - 10, -20),
        base: headcountChange,
        high: headcountChange + 30,
      },
      {
        parameter: 'Pricing',
        low: Math.min(pricingChange - 5, -10),
        base: pricingChange,
        high: pricingChange + 10,
      },
    ],
    [growthRate, cogsChange, headcountChange, pricingChange]
  )

  const sensitivityVariables = useMemo(
    () => [
      {
        name: 'growthRate',
        baseValue: growthRate,
        lowValue: growthRate - 5,
        highValue: growthRate + 15,
      },
      {
        name: 'pricingChange',
        baseValue: pricingChange,
        lowValue: pricingChange - 5,
        highValue: pricingChange + 10,
      },
      {
        name: 'cogsChange',
        baseValue: cogsChange,
        lowValue: cogsChange - 3,
        highValue: cogsChange + 7,
      },
      {
        name: 'headcountChange',
        baseValue: headcountChange,
        lowValue: headcountChange - 10,
        highValue: headcountChange + 30,
      },
    ],
    [growthRate, pricingChange, cogsChange, headcountChange]
  )

  const tornadoData = useMemo(() => {
    if (baseMetrics.revenue === 0) return []

    const tornadoModel = (vars: Record<string, number>): number => {
      const gr = vars.growthRate ?? growthRate
      const pc = vars.pricingChange ?? pricingChange
      const hc = vars.headcountChange ?? headcountChange
      const cc = vars.cogsChange ?? cogsChange

      const revenueImpact = baseMetrics.revenue * ((gr + pc) / 100)
      const costImpact = hc * baseMetrics.avgSalary + baseMetrics.cogs * (cc / 100)
      return revenueImpact - costImpact
    }

    const baseVars: Record<string, number> = {
      growthRate,
      pricingChange,
      headcountChange,
      cogsChange,
    }

    return SensitivityEngine.tornado(sensitivityVariables, tornadoModel, baseVars)
  }, [baseMetrics, growthRate, pricingChange, headcountChange, cogsChange, sensitivityVariables])

  const handleRunMonteCarlo = () => {
    setMcRunning(true)
    requestAnimationFrame(() => {
      const result = MonteCarloEngine.simulateScenario({
        baseMetrics: {
          revenue: scenarioImpact.newRevenue,
          ebitda: scenarioImpact.newRevenue - scenarioImpact.newCogs - scenarioImpact.newOpex,
          netIncome: scenarioImpact.netImpact,
          cashFlow: scenarioImpact.netImpact * 0.8,
          headcount: baseMetrics.headcount + headcountChange,
          burnRate: scenarioImpact.newOpex + scenarioImpact.newCogs,
          runway: 12,
          grossMargin:
            scenarioImpact.newRevenue > 0
              ? ((scenarioImpact.newRevenue - scenarioImpact.newCogs) / scenarioImpact.newRevenue) *
                100
              : 0,
          ebitdaMargin:
            scenarioImpact.newRevenue > 0
              ? ((scenarioImpact.newRevenue - scenarioImpact.newCogs - scenarioImpact.newOpex) /
                  scenarioImpact.newRevenue) *
                100
              : 0,
        },
        drivers: [
          {
            name: 'Revenue Growth',
            distribution: { name: 'revGrowth', type: 'normal', mean: growthRate, stdDev: 5 },
            targetMetric: 'revenue',
            impactType: 'percentage',
          },
          {
            name: 'COGS Change',
            distribution: { name: 'cogsChange', type: 'normal', mean: cogsChange, stdDev: 3 },
            targetMetric: 'revenue',
            impactType: 'percentage',
          },
          {
            name: 'Headcount',
            distribution: {
              name: 'hcChange',
              type: 'triangular',
              min: headcountChange * 0.5,
              max: headcountChange * 1.5,
              mode: headcountChange,
            },
            targetMetric: 'headcount',
            impactType: 'absolute',
          },
          {
            name: 'Pricing',
            distribution: { name: 'pricingChange', type: 'normal', mean: pricingChange, stdDev: 2 },
            targetMetric: 'revenue',
            impactType: 'percentage',
          },
        ],
        iterations: 1000,
        confidenceLevel: 0.95,
        seed: 42,
      })
      setMcResult(result)
      setMcRunning(false)
    })
  }

  const handleSave = () => {
    createScenario({
      name: `Scenario ${scenarios.length + 1}`,
      description: `Growth ${growthRate}%, HC +${headcountChange}, Pricing +${pricingChange}%, COGS ${cogsChange}%`,
      baseBudgetId: '',
      baseBudgetName: '',
      type: 'Custom' as const,
      probability: 50,
      isActive: false,
      assumptions: [
        {
          id: 'growth',
          name: 'Revenue Growth Rate',
          driverType: 'percentage',
          baseValue: 0,
          currentValue: growthRate,
          minValue: -20,
          maxValue: 50,
          stepSize: 1,
          unit: '%',
          affectedAccountIds: [],
        },
        {
          id: 'hc',
          name: 'Headcount Change',
          driverType: 'absolute',
          baseValue: 0,
          currentValue: headcountChange,
          minValue: -50,
          maxValue: 100,
          stepSize: 1,
          unit: 'FTE',
          affectedAccountIds: [],
        },
        {
          id: 'pricing',
          name: 'Pricing Change',
          driverType: 'percentage',
          baseValue: 0,
          currentValue: pricingChange,
          minValue: -20,
          maxValue: 30,
          stepSize: 1,
          unit: '%',
          affectedAccountIds: [],
        },
        {
          id: 'cogs',
          name: 'COGS Change',
          driverType: 'percentage',
          baseValue: 0,
          currentValue: cogsChange,
          minValue: -20,
          maxValue: 20,
          stepSize: 1,
          unit: '%',
          affectedAccountIds: [],
        },
      ],
      calculatedMetrics: {
        revenue: scenarioImpact.newRevenue,
        ebitda: scenarioImpact.newRevenue - scenarioImpact.newCogs - scenarioImpact.newOpex,
        netIncome: scenarioImpact.netImpact,
        grossMargin:
          scenarioImpact.newRevenue > 0
            ? (scenarioImpact.newRevenue - scenarioImpact.newCogs) / scenarioImpact.newRevenue
            : 0,
        operatingMargin:
          scenarioImpact.newRevenue > 0
            ? (scenarioImpact.newRevenue - scenarioImpact.newCogs - scenarioImpact.newOpex) /
              scenarioImpact.newRevenue
            : 0,
      },
      createdBy: 'user',
      createdByName: 'User',
    } as unknown as Omit<Scenario, 'id' | 'createdAt' | 'updatedAt'>)
  }

  const handleExportPDF = () => {
    ExportEngine.exportToPDF(
      {
        headers: ['Parameter', 'Base', 'Scenario', 'Impact'],
        rows: [
          [
            'Revenue',
            formatCurrency(baseMetrics.revenue),
            formatCurrency(scenarioImpact.newRevenue),
            formatCurrency(scenarioImpact.revenueImpact),
          ],
          [
            'COGS',
            formatCurrency(baseMetrics.cogs),
            formatCurrency(scenarioImpact.newCogs),
            formatCurrency(scenarioImpact.newCogs - baseMetrics.cogs),
          ],
          [
            'OpEx',
            formatCurrency(baseMetrics.opex),
            formatCurrency(scenarioImpact.newOpex),
            formatCurrency(scenarioImpact.newOpex - baseMetrics.opex),
          ],
          ['Net Impact', '', '', formatCurrency(scenarioImpact.netImpact)],
        ],
      },
      { title: 'Scenario Analysis' }
    )
  }

  const handleExportExcel = () => {
    ExportEngine.exportToExcel(
      {
        headers: ['Parameter', 'Base', 'Scenario', 'Impact'],
        rows: [
          ['Revenue', baseMetrics.revenue, scenarioImpact.newRevenue, scenarioImpact.revenueImpact],
          [
            'COGS',
            baseMetrics.cogs,
            scenarioImpact.newCogs,
            scenarioImpact.newCogs - baseMetrics.cogs,
          ],
          [
            'OpEx',
            baseMetrics.opex,
            scenarioImpact.newOpex,
            scenarioImpact.newOpex - baseMetrics.opex,
          ],
        ],
      },
      { title: 'Scenario_Analysis' }
    )
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Scenario Builder</h1>
          <p className="text-sm text-slate-400 mt-1">Model assumptions and compare outcomes</p>
        </div>
        <div className="flex gap-2">
          <Button size="sm" onClick={handleSave}>
            <Save className="h-3.5 w-3.5 mr-1.5" />
            Save Scenario
          </Button>
          <Button size="sm" variant="ghost" onClick={handleRunMonteCarlo} disabled={mcRunning}>
            <BarChart3 className="h-3.5 w-3.5 mr-1.5" />
            {mcRunning ? 'Running...' : 'Run Monte Carlo'}
          </Button>
          <Button size="sm" variant="ghost" onClick={handleExportPDF}>
            <FileText className="h-3.5 w-3.5 mr-1.5" />
            PDF
          </Button>
          <Button size="sm" variant="ghost" onClick={handleExportExcel}>
            <TableIcon className="h-3.5 w-3.5 mr-1.5" />
            Excel
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-4 gap-4">
        <KPIValue
          label="Revenue Impact"
          value={formatCurrency(scenarioImpact.revenueImpact)}
          trend="up"
        />
        <KPIValue
          label="Cost Impact"
          value={formatCurrency(scenarioImpact.costImpact)}
          trend="down"
        />
        <KPIValue
          label="Net Impact"
          value={formatCurrency(scenarioImpact.netImpact)}
          trend={scenarioImpact.netImpact >= 0 ? 'up' : 'down'}
        />
        <KPIValue label="Scenarios Saved" value={String(scenarios.length)} />
      </div>

      <div className="grid grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle>Assumption Sliders</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {[
              {
                label: 'Revenue Growth Rate',
                value: growthRate,
                set: setGrowthRate,
                min: -20,
                max: 50,
                suffix: '%',
              },
              {
                label: 'Headcount Change',
                value: headcountChange,
                set: setHeadcountChange,
                min: -50,
                max: 100,
                suffix: '',
              },
              {
                label: 'Pricing Change',
                value: pricingChange,
                set: setPricingChange,
                min: -20,
                max: 30,
                suffix: '%',
              },
              {
                label: 'COGS Change',
                value: cogsChange,
                set: setCogsChange,
                min: -20,
                max: 20,
                suffix: '%',
              },
            ].map(({ label, value, set, min, max, suffix }) => (
              <div key={label}>
                <div className="flex justify-between text-sm mb-1">
                  <span className="text-slate-300">{label}</span>
                  <span className="text-white font-mono">
                    {value}
                    {suffix}
                  </span>
                </div>
                <input
                  type="range"
                  min={min}
                  max={max}
                  value={value}
                  onChange={(e) => set(Number(e.target.value))}
                  className="w-full accent-blue-500"
                  aria-label={label}
                />
              </div>
            ))}
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Base vs Scenario</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={250}>
              <BarChart data={comparisonData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                <XAxis dataKey="month" stroke="#94a3b8" />
                <YAxis stroke="#94a3b8" tickFormatter={(v) => `$${(v / 1e6).toFixed(1)}M`} />
                <Tooltip
                  contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155' }}
                  formatter={(v: any) => formatCurrency(v)}
                />
                <Legend />
                <Bar dataKey="base" fill="#64748b" name="Base" />
                <Bar dataKey="scenario" fill="#3b82f6" name="Scenario" />
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Scenario Variance</CardTitle>
        </CardHeader>
        <CardContent>
          <VarianceChart
            data={comparisonData.map((d) => ({
              name: d.month,
              budget: d.base,
              actual: d.scenario,
            }))}
            height={200}
            ariaLabel="Scenario variance chart comparing base vs scenario"
          />
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Sensitivity Analysis (Tornado)</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-xs text-slate-500 mb-3">
            Net income impact when each variable is swept from low to high
          </p>
          <DataTable
            columns={[
              { key: 'name', header: 'Parameter' },
              {
                key: 'lowOutput',
                header: 'Low Impact',
                align: 'right',
                render: (v) => formatCurrency(v as number),
              },
              {
                key: 'highOutput',
                header: 'High Impact',
                align: 'right',
                render: (v) => formatCurrency(v as number),
              },
              {
                key: 'swing',
                header: 'Swing',
                align: 'right',
                render: (v) => formatCurrency(v as number),
              },
            ]}
            data={tornadoData as unknown as Record<string, unknown>[]}
            pageSize={10}
          />
        </CardContent>
      </Card>

      {mcResult && (
        <Card>
          <CardHeader>
            <CardTitle>Monte Carlo Simulation Results</CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="grid grid-cols-3 gap-4 text-sm">
              <div className="bg-slate-800 rounded-lg p-3">
                <span className="text-slate-400">Probability of Profit</span>
                <p className="text-2xl font-bold text-green-400">
                  {(mcResult.probabilityOfProfit * 100).toFixed(1)}%
                </p>
              </div>
              <div className="bg-slate-800 rounded-lg p-3">
                <span className="text-slate-400">Value at Risk (95%)</span>
                <p className="text-2xl font-bold text-red-400">
                  {formatCurrency(mcResult.valueAtRisk)}
                </p>
              </div>
              <div className="bg-slate-800 rounded-lg p-3">
                <span className="text-slate-400">CVaR (Expected Shortfall)</span>
                <p className="text-2xl font-bold text-red-400">
                  {formatCurrency(mcResult.conditionalValueAtRisk)}
                </p>
              </div>
            </div>

            <div>
              <h4 className="text-sm font-medium text-slate-300 mb-3">
                Percentile Outcomes (P10 / P50 / P90)
              </h4>
              <div className="grid grid-cols-3 gap-4">
                {(['revenue', 'ebitda', 'netIncome'] as const).map((metric) => {
                  const r = mcResult.metrics[metric]
                  return (
                    <div key={metric} className="bg-slate-800/50 rounded-lg p-3 text-sm space-y-1">
                      <span className="text-slate-400 capitalize">
                        {metric === 'netIncome'
                          ? 'Net Income'
                          : metric === 'ebitda'
                            ? 'EBITDA'
                            : 'Revenue'}
                      </span>
                      <div className="flex justify-between">
                        <span className="text-slate-500">P10</span>
                        <span className="text-white font-mono">
                          {formatCurrency(r.percentiles[10])}
                        </span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-slate-500">P50</span>
                        <span className="text-blue-400 font-mono">
                          {formatCurrency(r.percentiles[50])}
                        </span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-slate-500">P90</span>
                        <span className="text-white font-mono">
                          {formatCurrency(r.percentiles[90])}
                        </span>
                      </div>
                      <div className="flex justify-between border-t border-slate-700 pt-1">
                        <span className="text-slate-500">95% CI</span>
                        <span className="text-slate-300 font-mono text-xs">
                          {formatCurrency(r.confidenceInterval.lower)} –{' '}
                          {formatCurrency(r.confidenceInterval.upper)}
                        </span>
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>

            <div>
              <h4 className="text-sm font-medium text-slate-300 mb-3">Net Income Distribution</h4>
              <div className="flex items-end gap-px h-32">
                {mcResult.netIncome.histogram.map((bin, i) => {
                  const maxCount = Math.max(...mcResult.netIncome.histogram.map((b) => b.count))
                  const heightPct = maxCount > 0 ? (bin.count / maxCount) * 100 : 0
                  const mid = (bin.lower + bin.upper) / 2
                  const ci = mcResult.netIncome.confidenceInterval
                  const inCI = mid >= ci.lower && mid <= ci.upper
                  return (
                    <div
                      key={i}
                      className={`flex-1 rounded-t-sm min-w-[2px] ${inCI ? 'bg-blue-500' : 'bg-slate-600'}`}
                      style={{ height: `${heightPct}%` }}
                      title={`${formatCurrency(bin.lower)}–${formatCurrency(bin.upper)}: ${bin.count}`}
                    />
                  )
                })}
              </div>
              <div className="flex justify-between text-xs text-slate-500 mt-1">
                <span>{formatCurrency(mcResult.netIncome.min)}</span>
                <span className="text-slate-400">1,000 simulations · seed=42</span>
                <span>{formatCurrency(mcResult.netIncome.max)}</span>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

import { useState, useMemo, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import { useScenarioStore, scenarioSelectors } from '@/store/scenarioStore'
import type { ScenarioMetrics } from '@/types'
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'

interface MetricRow {
  key: keyof ScenarioMetrics
  label: string
  format: 'currency' | 'percent' | 'number'
  higherIsBetter: boolean
}

const METRICS: MetricRow[] = [
  { key: 'revenue', label: 'Revenue', format: 'currency', higherIsBetter: true },
  { key: 'ebitda', label: 'EBITDA', format: 'currency', higherIsBetter: true },
  { key: 'netIncome', label: 'Net Income', format: 'currency', higherIsBetter: true },
  { key: 'cashFlow', label: 'Cash Flow', format: 'currency', higherIsBetter: true },
  { key: 'grossMargin', label: 'Gross Margin', format: 'percent', higherIsBetter: true },
  { key: 'ebitdaMargin', label: 'EBITDA Margin', format: 'percent', higherIsBetter: true },
  { key: 'headcount', label: 'Headcount', format: 'number', higherIsBetter: true },
  { key: 'burnRate', label: 'Burn Rate', format: 'currency', higherIsBetter: false },
  { key: 'runway', label: 'Runway (months)', format: 'number', higherIsBetter: true },
]

function formatValue(value: number, format: MetricRow['format']): string {
  if (format === 'currency') {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      notation: 'compact',
      maximumFractionDigits: 1,
    }).format(value)
  }
  if (format === 'percent') {
    return `${(value * 100).toFixed(1)}%`
  }
  return new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 }).format(value)
}

function getVarianceClass(current: number, base: number, higherIsBetter: boolean): string {
  if (base === 0) return ''
  const diff = current - base
  if (Math.abs(diff) < 0.001) return ''
  const isFavorable = higherIsBetter ? diff > 0 : diff < 0
  return isFavorable ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'
}

function getBarWidth(value: number, max: number): number {
  if (max === 0) return 0
  return Math.min(100, Math.max(2, (Math.abs(value) / Math.abs(max)) * 100))
}

const BAR_COLORS = [
  'bg-blue-500',
  'bg-emerald-500',
  'bg-amber-500',
  'bg-purple-500',
  'bg-rose-500',
  'bg-cyan-500',
]

export function ScenarioComparisonPage() {
  const navigate = useNavigate()
  const scenarios = useScenarioStore(scenarioSelectors.scenarios)
  const comparedIds = useScenarioStore(scenarioSelectors.comparedScenarioIds)
  const toggleComparison = useScenarioStore((s) => s.toggleScenarioComparison)

  const [selectedIds, setSelectedIds] = useState<string[]>(comparedIds)

  const selectedScenarios = useMemo(
    () => scenarios.filter((s) => selectedIds.includes(s.id)),
    [scenarios, selectedIds]
  )

  const baseScenario = useMemo(
    () => selectedScenarios.find((s) => s.type === 'Base') ?? selectedScenarios[0],
    [selectedScenarios]
  )

  const toggleSelection = useCallback(
    (id: string) => {
      setSelectedIds((prev) =>
        prev.includes(id) ? prev.filter((sid) => sid !== id) : [...prev, id]
      )
      toggleComparison(id)
    },
    [toggleComparison]
  )

  const barMetric = METRICS[0]
  const barMaxValue = useMemo(
    () =>
      Math.max(1, ...selectedScenarios.map((s) => Math.abs(s.calculatedMetrics[barMetric.key]))),
    [selectedScenarios, barMetric.key]
  )

  if (scenarios.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center gap-4 py-24">
        <h2 className="text-xl font-semibold text-[var(--text-primary)]">No Scenarios Available</h2>
        <p className="text-sm text-[var(--text-secondary)]">
          Create a scenario first to enable comparison.
        </p>
        <Button onClick={() => navigate('/scenarios/create')}>Create Scenario</Button>
      </div>
    )
  }

  return (
    <div className="mx-auto flex max-w-7xl flex-col gap-6 p-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-[var(--text-primary)]">Scenario Comparison</h1>
          <p className="mt-1 text-sm text-[var(--text-secondary)]">
            Select scenarios to compare side-by-side.
          </p>
        </div>
        <Button onClick={() => navigate('/scenarios/create')}>Create Scenario</Button>
      </div>

      {/* Scenario Selector */}
      <Card>
        <CardHeader>
          <CardTitle>Select Scenarios</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-3">
            {scenarios.map((scenario) => {
              const isSelected = selectedIds.includes(scenario.id)
              return (
                <label
                  key={scenario.id}
                  className={`flex cursor-pointer items-center gap-2 rounded-lg border px-3 py-2 text-sm transition-colors ${
                    isSelected
                      ? 'border-blue-500 bg-blue-50 text-blue-700 dark:border-blue-400 dark:bg-blue-900/30 dark:text-blue-300'
                      : 'border-[var(--border-subtle)] bg-[var(--bg-surface)] hover:border-gray-400'
                  }`}
                >
                  <input
                    type="checkbox"
                    checked={isSelected}
                    onChange={() => toggleSelection(scenario.id)}
                    className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="font-medium">{scenario.name}</span>
                  <span className="rounded bg-gray-100 px-1.5 py-0.5 text-xs text-[var(--text-secondary)] dark:bg-gray-700">
                    {scenario.type}
                  </span>
                </label>
              )
            })}
          </div>
        </CardContent>
      </Card>

      {/* Comparison Table */}
      {selectedScenarios.length >= 2 && baseScenario && (
        <Card>
          <CardHeader>
            <CardTitle>Metrics Comparison</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--border-subtle)]">
                    <th className="pb-3 pr-4 text-left font-medium text-[var(--text-secondary)]">
                      Metric
                    </th>
                    {selectedScenarios.map((s) => (
                      <th
                        key={s.id}
                        className="pb-3 px-3 text-right font-medium text-[var(--text-secondary)]"
                      >
                        {s.name}
                        {s.id === baseScenario.id && (
                          <span className="ml-1 text-xs text-blue-500">(base)</span>
                        )}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-[var(--border-subtle)]">
                  {METRICS.map((metric) => (
                    <tr key={metric.key} className="hover:bg-[var(--bg-hover)]">
                      <td className="py-3 pr-4 font-medium text-[var(--text-primary)]">
                        {metric.label}
                      </td>
                      {selectedScenarios.map((s) => {
                        const value = s.calculatedMetrics[metric.key]
                        const baseValue = baseScenario.calculatedMetrics[metric.key]
                        const varianceClass =
                          s.id === baseScenario.id
                            ? ''
                            : getVarianceClass(value, baseValue, metric.higherIsBetter)
                        return (
                          <td
                            key={s.id}
                            className={`py-3 px-3 text-right tabular-nums ${varianceClass}`}
                          >
                            {formatValue(value, metric.format)}
                          </td>
                        )
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Grouped Bar Chart */}
      {selectedScenarios.length >= 2 && (
        <Card>
          <CardHeader>
            <CardTitle>Visual Comparison</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-5">
              {METRICS.filter((m) => m.format !== 'percent').map((metric) => {
                const maxVal = Math.max(
                  1,
                  ...selectedScenarios.map((s) => Math.abs(s.calculatedMetrics[metric.key]))
                )
                return (
                  <div key={metric.key}>
                    <p className="mb-2 text-sm font-medium text-[var(--text-primary)]">
                      {metric.label}
                    </p>
                    <div className="space-y-1.5">
                      {selectedScenarios.map((s, idx) => {
                        const value = s.calculatedMetrics[metric.key]
                        return (
                          <div key={s.id} className="flex items-center gap-3">
                            <span className="w-28 shrink-0 truncate text-xs text-[var(--text-secondary)]">
                              {s.name}
                            </span>
                            <div className="relative h-5 flex-1 overflow-hidden rounded bg-gray-100 dark:bg-gray-700">
                              <div
                                className={`h-full rounded transition-all ${BAR_COLORS[idx % BAR_COLORS.length]}`}
                                style={{ width: `${getBarWidth(value, maxVal)}%` }}
                              />
                            </div>
                            <span className="w-20 text-right text-xs tabular-nums text-[var(--text-secondary)]">
                              {formatValue(value, metric.format)}
                            </span>
                          </div>
                        )
                      })}
                    </div>
                  </div>
                )
              })}
            </div>

            {/* Legend */}
            <div className="mt-6 flex flex-wrap gap-4 border-t border-[var(--border-subtle)] pt-4">
              {selectedScenarios.map((s, idx) => (
                <div key={s.id} className="flex items-center gap-2">
                  <span className={`h-3 w-3 rounded-sm ${BAR_COLORS[idx % BAR_COLORS.length]}`} />
                  <span className="text-xs text-[var(--text-secondary)]">{s.name}</span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {selectedScenarios.length < 2 && (
        <div className="flex flex-col items-center gap-2 py-16 text-[var(--text-secondary)]">
          <p className="text-lg font-medium">Select at least 2 scenarios to compare</p>
          <p className="text-sm">Check the boxes above to begin comparing metrics.</p>
        </div>
      )}
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { useLocation } from 'react-router-dom'
import { useNavigate } from 'react-router-dom'
import { useScenarioStore } from '@/store/scenarioStore'
import { Button } from '@/components/ui/Button'
import { Badge } from '@/components/ui/Badge'
import { Card, CardContent } from '@/components/ui/Card'
import { TreemapChart, TreemapDataPoint } from '@/components/charts/TreemapChart'
import { Plus, Eye, FlaskConical } from 'lucide-react'

export function ScenarioListPage() {
  const [helpOpen, setHelpOpen] = useState(false)

  useEffect(() => {
    document.title = 'FinPlan Pro — Scenario List'
  }, [])

  const { scenarios } = useScenarioStore()
  const navigate = useNavigate()
  const [typeFilter, setTypeFilter] = useState('all')

  const filtered = useMemo(() => {
    let list = scenarios
    if (typeFilter !== 'all') list = list.filter((s) => s.type === typeFilter)
    return list.sort((a, b) => b.createdAt.localeCompare(a.createdAt))
  }, [scenarios, typeFilter])

  const treemapData = useMemo<TreemapDataPoint[]>(() => {
    return scenarios.map((s) => ({
      name: s.name,
      size: Math.round(s.probability * 100) || 1,
    }))
  }, [scenarios])

  if (scenarios.length === 0) {
    return (
      <div className="p-12 text-center max-w-md mx-auto">
        <div className="p-4 bg-slate-800 rounded-full inline-block mb-4">
          <FlaskConical className="h-10 w-10 text-slate-400" />
        </div>
        <h2 className="text-xl font-semibold mb-2">No Scenarios Yet</h2>
        <p className="text-slate-400 mb-6">
          Create scenarios to model different financial outcomes and compare them side by side.
        </p>
        <Button onClick={() => navigate('/scenarios/create')}>
          <Plus className="h-4 w-4 mr-2" />
          Create Scenario
        </Button>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center justify-between mb-6">
            <h1 className="text-2xl font-bold">Scenarios</h1>
            <button
              onClick={() => setHelpOpen(true)}
              className="p-2 hover:bg-slate-800 rounded-full text-slate-500 hover:text-white transition-colors"
              aria-label="Help"
            ></button>
          </div>
          <p className="text-sm text-slate-400 mt-1">{scenarios.length} scenarios</p>
        </div>
        <Button onClick={() => navigate('/scenarios/create')}>
          <Plus className="h-4 w-4 mr-2" />
          Create Scenario
        </Button>
      </div>

      <div className="flex gap-1">
        {['all', 'Base', 'Optimistic', 'Pessimistic', 'Custom'].map((t) => (
          <button
            key={t}
            onClick={() => setTypeFilter(t)}
            className={
              'px-2.5 py-1.5 rounded text-xs font-medium transition-colors ' +
              (typeFilter === t
                ? 'bg-blue-600 text-white'
                : 'bg-slate-800 text-slate-400 hover:bg-slate-700')
            }
          >
            {t === 'all' ? 'All' : t}
          </button>
        ))}
      </div>

      {treemapData.length > 0 && (
        <Card>
          <CardContent className="p-4">
            <h3 className="text-sm font-medium mb-2">Scenario Probability Distribution</h3>
            <TreemapChart
              data={treemapData}
              height={200}
              ariaLabel="Scenario probability treemap"
            />
          </CardContent>
        </Card>
      )}

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {filtered.length === 0 ? (
          <div className="col-span-full text-center py-8 text-slate-500">
            No scenarios match the filter.
          </div>
        ) : (
          filtered.map((s) => (
            <Card
              key={s.id}
              className="cursor-pointer hover:border-blue-500/50 transition-all"
              onClick={() => navigate('/scenarios/' + s.id)}
            >
              <CardContent className="p-4">
                <div className="flex items-start justify-between mb-2">
                  <h3 className="font-semibold">{s.name}</h3>
                  <Badge variant={s.isActive ? 'default' : 'outline'} className="text-[10px]">
                    {s.isActive ? 'Active' : 'Inactive'}
                  </Badge>
                </div>
                <p className="text-xs text-slate-400 mb-3 line-clamp-2">{s.description}</p>
                <div className="flex gap-2 text-xs text-slate-500">
                  <Badge variant="secondary" className="text-[10px]">
                    {s.type}
                  </Badge>
                  <span>{(s.probability * 100).toFixed(0)}% probability</span>
                </div>
              </CardContent>
            </Card>
          ))
        )}
      </div>
    </div>
  )
}

