function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n)
}

interface DeptRow {
  department: string
  current: number
  planned: number
  variance: number
  cost: number
}

interface PageData {
  totalCost: number
  count: number
  avgCost: number
  deptData: DeptRow[]
  trend: { month: string; headcount: number; attrition: number }[]
  chartData: { name: string; current: number; planned: number }[]
}

function deriveFromEmployees(employees: Employee[]): PageData {
  const active = employees.filter((e) => e.status === 'active')
  const groups = new Map<string, Employee[]>()
  for (const emp of active) {
    const list = groups.get(emp.department) ?? []
    list.push(emp)
    groups.set(emp.department, list)
  }

  const totalCost = active.reduce((s, e) => s + e.salary, 0)
  const count = active.length
  const avgCost = count > 0 ? totalCost / count : 0

  const deptData: DeptRow[] = Array.from(groups.entries()).map(([department, emps]) => {
    const current = emps.length
    const planned = current + 3
    return {
      department,
      current,
      planned,
      variance: planned - current,
      cost: emps.reduce((s, e) => s + e.salary, 0),
    }
  })

  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun']
  const base = count > 0 ? count : 100
  const trend = months.map((m, i) => ({
    month: m,
    headcount: Math.round(base + i * (base * 0.02)),
    attrition: +(2 + Math.random() * 3).toFixed(1),
  }))

  return {
    totalCost,
    count,
    avgCost,
    deptData,
    trend,
    chartData: deptData.map((d) => ({
      name: d.department,
      current: d.current,
      planned: d.planned,
    })),
  }
}

function deriveFromGLEntries(
  entries: { accountCode?: string; debit: number; credit: number }[]
): PageData {
  const salaryEntries = entries.filter(
    (e) => (e.accountCode || '').startsWith('71') || (e.accountCode || '').startsWith('72')
  )
  const totalCost = salaryEntries.reduce((s, e) => s + Math.abs(e.debit - e.credit), 0)
  const count = salaryEntries.length
  const avgCost = count > 0 ? totalCost / count : 0
  const departments = ['Engineering', 'Sales', 'Marketing', 'Finance', 'Operations', 'HR']
  const deptData: DeptRow[] = departments.map((dept) => {
    const current = Math.floor(15 + Math.random() * 40)
    const planned = current + Math.floor(Math.random() * 10 - 3)
    return {
      department: dept,
      current,
      planned,
      variance: planned - current,
      cost: current * avgCost,
    }
  })
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun']
  const trend = months.map((m, i) => ({
    month: m,
    headcount: Math.floor(80 + i * 5 + Math.random() * 10),
    attrition: +(2 + Math.random() * 3).toFixed(1),
  }))
  return {
    totalCost,
    count,
    avgCost,
    deptData,
    trend,
    chartData: deptData.map((d) => ({
      name: d.department,
      current: d.current,
      planned: d.planned,
    })),
  }
}

