// =============================================================================
// Real-time Collaboration Manager
// Singleton orchestrator: WebSocket + Presence + Change Broadcasting
// =============================================================================

import { WebSocketManager, type WebSocketConfig, type ConnectionState } from './WebSocketManager'
import { PresenceService, type UserPresence, type PresenceChange } from './PresenceService'
import {
  ChangeBroadcaster,
  type DataChange,
  type ConflictInfo,
  type ResourceType,
} from './ChangeBroadcaster'

export interface CollaborationConfig {
  /** WebSocket URL (e.g., wss://api.example.com/ws) */
  wsUrl: string
  /** Auth token for the WS connection */
  token?: string
  /** Whether to auto-connect on init (default: false) */
  autoConnect?: boolean
}

/**
 * Central entry point for real-time collaboration.
 * Creates and manages the WebSocket, Presence, and ChangeBroadcasting services.
 *
 * Usage:
 * ```ts
 * const collab = RealtimeCollaborationManager.getInstance();
 * collab.initialize({ wsUrl: 'wss://api.example.com/ws', token: '...' });
 * collab.connect();
 *
 * // Presence
 * collab.presence.onChange((change) => { ... });
 *
 * // Changes
 * collab.changes.onChange((change) => { ... });
 * collab.changes.broadcastCellChange('budget', 'bgt-001', 'q1Amount', 100, 150, 'Sarah');
 * ```
 */
export class RealtimeCollaborationManager {
  private static instance: RealtimeCollaborationManager | null = null

  private wsManager: WebSocketManager | null = null
  private presenceSvc: PresenceService | null = null
  private changeBroadcaster: ChangeBroadcaster | null = null
  private initialized = false

  private constructor() {}

  /** Get the singleton instance */
  static getInstance(): RealtimeCollaborationManager {
    if (!RealtimeCollaborationManager.instance) {
      RealtimeCollaborationManager.instance = new RealtimeCollaborationManager()
    }
    return RealtimeCollaborationManager.instance
  }

  /** Reset the singleton (for testing) */
  static resetInstance(): void {
    if (RealtimeCollaborationManager.instance) {
      RealtimeCollaborationManager.instance.destroy()
      RealtimeCollaborationManager.instance = null
    }
  }

  // --- Public API ---

  /** Initialize all services */
  initialize(config: CollaborationConfig): void {
    if (this.initialized) this.destroy()

    this.wsManager = new WebSocketManager({
      url: config.wsUrl,
      token: config.token,
    })

    this.presenceSvc = new PresenceService(this.wsManager)
    this.changeBroadcaster = new ChangeBroadcaster(this.wsManager)
    this.initialized = true

    if (config.autoConnect) {
      this.connect()
    }
  }

  /** Connect the WebSocket */
  connect(): void {
    this.ensureInitialized()
    this.wsManager!.connect()
  }

  /** Disconnect */
  disconnect(): void {
    this.wsManager?.disconnect()
  }

  /** Current connection state */
  get connectionState(): ConnectionState {
    return this.wsManager?.connectionState ?? 'disconnected'
  }

  /** Whether connected */
  get isConnected(): boolean {
    return this.wsManager?.isConnected ?? false
  }

  /** Access the Presence service */
  get presence(): PresenceService {
    this.ensureInitialized()
    return this.presenceSvc!
  }

  /** Access the ChangeBroadcaster service */
  get changes(): ChangeBroadcaster {
    this.ensureInitialized()
    return this.changeBroadcaster!
  }

  /** Subscribe to connection state changes */
  onConnectionStateChange(handler: (state: ConnectionState) => void): () => void {
    this.ensureInitialized()
    return this.wsManager!.onStateChange(handler)
  }

  /** Set the current user for presence and change attribution */
  setUser(user: {
    id: string
    firstName: string
    lastName: string
    avatarUrl: string | null
  }): void {
    this.ensureInitialized()
    this.presenceSvc!.initialize(user)
    this.changeBroadcaster!.setUser(user.id)
  }

  /** Destroy all services and clean up */
  destroy(): void {
    this.presenceSvc?.destroy()
    this.changeBroadcaster?.destroy()
    this.wsManager?.destroy()
    this.presenceSvc = null
    this.changeBroadcaster = null
    this.wsManager = null
    this.initialized = false
  }

  private ensureInitialized(): void {
    if (!this.initialized) {
      throw new Error('RealtimeCollaborationManager not initialized. Call initialize() first.')
    }
  }
}

// Re-export types for convenience
export type {
  ConnectionState,
  UserPresence,
  PresenceChange,
  DataChange,
  ConflictInfo,
  ResourceType,
}

// =============================================================================
// WebSocket Connection Manager
// Manages WebSocket lifecycle: connect, reconnect, heartbeat, message routing
// =============================================================================

export type ConnectionState = 'connecting' | 'connected' | 'disconnected' | 'reconnecting'

export type MessageHandler = (data: unknown) => void

export interface WebSocketConfig {
  /** WebSocket server URL */
  url: string
  /** Auth token passed as query param or via first message */
  token?: string
  /** Max reconnection attempts before giving up (default: 10) */
  maxRetries?: number
  /** Base delay for exponential backoff in ms (default: 1000) */
  baseRetryDelay?: number
  /** Max retry delay in ms (default: 30000) */
  maxRetryDelay?: number
  /** Heartbeat interval in ms (default: 15000) */
  heartbeatInterval?: number
  /** Heartball timeout — disconnect if no pong within this ms (default: 5000) */
  heartbeatTimeout?: number
}

const DEFAULT_CONFIG: Required<Omit<WebSocketConfig, 'url' | 'token'>> = {
  maxRetries: 10,
  baseRetryDelay: 1000,
  maxRetryDelay: 30000,
  heartbeatInterval: 15000,
  heartbeatTimeout: 5000,
}

export interface CollaborationMessage {
  type: string
  payload: unknown
  senderId?: string
  timestamp?: string
}

/**
 * Manages a single WebSocket connection with automatic reconnection,
 * heartbeat monitoring, and typed message routing.
 *
 * Usage:
 * ```ts
 * const ws = new WebSocketManager({ url: 'wss://api.example.com/ws', token: '...' });
 * ws.on('presence:update', handlePresence);
 * ws.connect();
 * ws.send({ type: 'join', payload: { resourceId: 'budget-1' } });
 * ```
 */
export class WebSocketManager {
  private ws: WebSocket | null = null
  private config: Required<WebSocketConfig>
  private state: ConnectionState = 'disconnected'
  private retryCount = 0
  private retryTimer: ReturnType<typeof setTimeout> | null = null
  private heartbeatTimer: ReturnType<typeof setInterval> | null = null
  private heartbeatTimeoutTimer: ReturnType<typeof setTimeout> | null = null
  private listeners = new Map<string, Set<MessageHandler>>()
  private stateListeners = new Set<(state: ConnectionState) => void>()
  private messageQueue: CollaborationMessage[] = []
  private isIntentionalClose = false

  constructor(config: WebSocketConfig) {
    this.config = { ...DEFAULT_CONFIG, ...config } as any
  }

  // --- Public API ---

  /** Current connection state */
  get connectionState(): ConnectionState {
    return this.state
  }

  /** Whether the socket is currently open */
  get isConnected(): boolean {
    return this.state === 'connected'
  }

  /** Connect to the WebSocket server */
  connect(): void {
    if (this.state === 'connected' || this.state === 'connecting') return

    this.isIntentionalClose = false
    this.setState('connecting')

    try {
      const url = this.buildUrl()
      this.ws = new WebSocket(url)
      this.ws.onopen = this.handleOpen.bind(this)
      this.ws.onmessage = this.handleMessage.bind(this)
      this.ws.onclose = this.handleClose.bind(this)
      this.ws.onerror = this.handleError.bind(this)
    } catch {
      this.setState('disconnected')
      this.scheduleReconnect()
    }
  }

  /** Gracefully disconnect */
  disconnect(): void {
    this.isIntentionalClose = true
    this.clearTimers()
    this.retryCount = 0

    if (this.ws) {
      this.ws.close(1000, 'Client disconnect')
      this.ws = null
    }

    this.setState('disconnected')
  }

  /** Send a message. Queues if not connected. */
  send(message: CollaborationMessage): void {
    if (this.state === 'connected' && this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(message))
    } else {
      this.messageQueue.push(message)
    }
  }

  /** Register a handler for a specific message type */
  on(type: string, handler: MessageHandler): () => void {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, new Set())
    }
    this.listeners.get(type)!.add(handler)
    return () => this.off(type, handler)
  }

  /** Remove a handler */
  off(type: string, handler: MessageHandler): void {
    this.listeners.get(type)?.delete(handler)
  }

  /** Subscribe to connection state changes */
  onStateChange(handler: (state: ConnectionState) => void): () => void {
    this.stateListeners.add(handler)
    return () => this.stateListeners.delete(handler)
  }

  /** Remove all listeners and close */
  destroy(): void {
    this.disconnect()
    this.listeners.clear()
    this.stateListeners.clear()
    this.messageQueue = []
  }

  // --- Internal ---

  private buildUrl(): string {
    const { url, token } = this.config
    const separator = url.includes('?') ? '&' : '?'
    return token ? `${url}${separator}token=${encodeURIComponent(token)}` : url
  }

  private setState(state: ConnectionState): void {
    if (this.state === state) return
    this.state = state
    this.stateListeners.forEach((fn) => fn(state))
  }

  private handleOpen(): void {
    this.setState('connected')
    this.retryCount = 0
    this.startHeartbeat()
    this.flushQueue()
  }

  private handleMessage(event: MessageEvent): void {
    // Reset heartbeat on any incoming message
    this.resetHeartbeatTimeout()

    if (event.data === 'pong') return

    let message: CollaborationMessage
    try {
      message = JSON.parse(event.data as string)
    } catch {
      return // ignore malformed messages
    }

    const handlers = this.listeners.get(message.type)
    if (handlers) {
      handlers.forEach((fn) => {
        try {
          fn(message.payload)
        } catch {
          // prevent one bad handler from breaking others
        }
      })
    }

    // Fire wildcard listeners
    const wildcardHandlers = this.listeners.get('*')
    if (wildcardHandlers) {
      wildcardHandlers.forEach((fn) => {
        try {
          fn(message)
        } catch {
          // ignore
        }
      })
    }
  }

  private handleClose(event: CloseEvent): void {
    this.stopHeartbeat()
    this.ws = null

    if (this.isIntentionalClose || event.code === 1000) {
      this.setState('disconnected')
      return
    }

    this.scheduleReconnect()
  }

  private handleError(): void {
    // The close handler will fire after this, triggering reconnect
  }

  private scheduleReconnect(): void {
    if (this.retryCount >= this.config.maxRetries) {
      this.setState('disconnected')
      this.emit('connection:failed', { retries: this.retryCount })
      return
    }

    this.setState('reconnecting')

    const delay = Math.min(
      this.config.baseRetryDelay * Math.pow(2, this.retryCount) + Math.random() * 500,
      this.config.maxRetryDelay
    )

    this.retryTimer = setTimeout(() => {
      this.retryCount++
      this.connect()
    }, delay)
  }

  private startHeartbeat(): void {
    this.stopHeartbeat()
    this.heartbeatTimer = setInterval(() => {
      if (this.ws?.readyState === WebSocket.OPEN) {
        this.ws.send('ping')
        this.heartbeatTimeoutTimer = setTimeout(() => {
          // No pong received — force reconnect
          this.ws?.close(4000, 'Heartbeat timeout')
        }, this.config.heartbeatTimeout)
      }
    }, this.config.heartbeatInterval)
  }

  private resetHeartbeatTimeout(): void {
    if (this.heartbeatTimeoutTimer) {
      clearTimeout(this.heartbeatTimeoutTimer)
      this.heartbeatTimeoutTimer = null
    }
  }

  private stopHeartbeat(): void {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer)
      this.heartbeatTimer = null
    }
    this.resetHeartbeatTimeout()
  }

  private clearTimers(): void {
    this.stopHeartbeat()
    if (this.retryTimer) {
      clearTimeout(this.retryTimer)
      this.retryTimer = null
    }
  }

  private flushQueue(): void {
    const queue = [...this.messageQueue]
    this.messageQueue = []
    queue.forEach((msg) => this.send(msg))
  }

  private emit(type: string, payload: unknown): void {
    const handlers = this.listeners.get(type)
    if (handlers) {
      handlers.forEach((fn) => fn(payload))
    }
  }
}

/**
 * API Integration Framework - QuickBooks Connector
 *
 * Connects to the QuickBooks Online API (Intuit) to sync:
 * - Accounts (Chart of Accounts)
 * - Transactions (Journal Entries, Expenses)
 * - Invoices
 * - Budgets (via Reports API)
 *
 * API docs: https://developer.intuit.com/app/developer/qbo/docs/api/accounting/most-commonly-used/account
 */

import { BaseConnector } from './BaseConnector'
import type {
  ConnectorConfig,
  ConnectorHealth,
  ExternalAccount,
  ExternalBudget,
  ExternalInvoice,
  ExternalInvoiceLineItem,
  ExternalTransaction,
  OAuth2Tokens,
  PaginatedResponse,
  PaginationParams,
  SyncOptions,
} from './types'

// ─── QuickBooks API response shapes ──────────────────────────────────────────

interface QBCompanyInfo {
  CompanyName: string
  Id: string
}

interface QBCompanyInfoResponse {
  QueryResponse: {
    CompanyInfo: QBCompanyInfo[]
  }
}

interface QBTokenResponse {
  access_token: string
  refresh_token: string
  expires_in: number
  token_type: string
  x_refresh_token_expires_in: number
}

interface QBQueryResponse<T> {
  QueryResponse: {
    [key: string]: T[] | number | undefined
    startPosition: number
    maxResults: number
    totalCount?: number
  } & Record<string, any>
  time: string
}

interface QBLine {
  Id?: string
  Description?: string
  Amount: number
  DetailType: string
  SalesItemLineDetail?: {
    UnitPrice?: number
    Qty?: number
    ItemRef?: { value: string }
    AccountRef?: { value: string }
  }
}

interface QBAccount {
  Id: string
  Name: string
  FullyQualifiedName: string
  AccountType: string
  AccountSubType: string
  Classification: string
  CurrencyRef?: { value: string }
  CurrentBalance: number
  Active: boolean
  MetaData: { LastUpdatedTime: string }
}

interface QBTransaction {
  Id: string
  TxnDate: string
  TotalAmt: number
  PrivateNote?: string
  Line: QBLine[]
  CurrencyRef?: { value: string }
  DocNumber?: string
}

interface QBInvoice {
  Id: string
  DocNumber: string
  TxnDate: string
  DueDate: string
  TotalAmt: number
  Balance: number
  CurrencyRef?: { value: string }
  CustomerRef: { value: string }
  Line: QBLine[]
}

// ─── QuickBooksConnector ─────────────────────────────────────────────────────

export class QuickBooksConnector extends BaseConnector {
  private realmId: string

  constructor(config: ConnectorConfig & { realmId: string }) {
    super({
      ...config,
      baseUrl: `https://quickbooks.api.intuit.com/v3/company/${config.realmId}`,
    })
    this.realmId = config.realmId
  }

  // ── Token Management ─────────────────────────────────────────────────────

  /**
   * Exchange authorization code for tokens (called during OAuth2 callback).
   */
  async exchangeCodeForTokens(code: string, redirectUri: string): Promise<OAuth2Tokens> {
    const oauthConfig = this.config.auth.oauth2
    if (!oauthConfig) {
      throw new Error('OAuth2 configuration required')
    }

    const credentials = btoa(`${oauthConfig.clientId}:${oauthConfig.clientSecret}`)

    const response = await this.client.post<QBTokenResponse>(
      'https://oauth.platform.intuit.com/oauth2/v1/tokens/bearer',
      new URLSearchParams({
        grant_type: 'authorization_code',
        code,
        redirect_uri: redirectUri,
      }).toString()
    )

    // Override content-type for token endpoint
    const tokens: OAuth2Tokens = {
      accessToken: response.data.access_token,
      refreshToken: response.data.refresh_token,
      expiresAt: Date.now() + response.data.expires_in * 1000,
      tokenType: 'Bearer',
    }

    this.client.setOAuthTokens(tokens)
    return tokens
  }

  /**
   * Refresh access token using stored refresh token.
   */
  async refreshAccessToken(): Promise<OAuth2Tokens> {
    const currentTokens = this.client.getOAuthTokens()
    if (!currentTokens?.refreshToken) {
      throw new Error('No refresh token available')
    }

    const oauthConfig = this.config.auth.oauth2
    if (!oauthConfig) {
      throw new Error('OAuth2 configuration required')
    }

    const credentials = btoa(`${oauthConfig.clientId}:${oauthConfig.clientSecret}`)

    const response = await this.client.post<QBTokenResponse>(
      'https://oauth.platform.intuit.com/oauth2/v1/tokens/bearer',
      new URLSearchParams({
        grant_type: 'refresh_token',
        refresh_token: currentTokens.refreshToken,
      }).toString()
    )

    const tokens: OAuth2Tokens = {
      accessToken: response.data.access_token,
      refreshToken: response.data.refresh_token,
      expiresAt: Date.now() + response.data.expires_in * 1000,
      tokenType: 'Bearer',
    }

    this.client.setOAuthTokens(tokens)
    return tokens
  }

  // ── Health Check ─────────────────────────────────────────────────────────

  protected async performHealthCheck(): Promise<ConnectorHealth> {
    try {
      const response = await this.client.get<QBCompanyInfoResponse>('/companyinfo/1')

      const companyInfo = response.data.QueryResponse?.CompanyInfo?.[0]
      if (!companyInfo) {
        return { status: 'error', lastError: 'No company info returned' }
      }

      return {
        status: 'connected',
        lastSyncAt: Date.now(),
        rateLimitRemaining: parseInt(response.headers['x-ratelimit-remaining'] ?? '500', 10),
        rateLimitReset: parseInt(response.headers['x-ratelimit-reset'] ?? '0', 10),
      }
    } catch (error: unknown) {
      return {
        status: 'error',
        lastError: error instanceof Error ? error.message : 'Health check failed',
      }
    }
  }

  // ── Accounts ─────────────────────────────────────────────────────────────

  async getAccounts(pagination?: PaginationParams): Promise<PaginatedResponse<ExternalAccount>> {
    const startPosition = ((pagination?.page ?? 1) - 1) * (pagination?.pageSize ?? 100) + 1
    const maxResults = pagination?.pageSize ?? 100

    const query = `SELECT * FROM Account WHERE Active = true STARTPOSITION ${startPosition} MAXRESULTS ${maxResults}`

    const response = await this.client.get<QBQueryResponse<QBAccount>>('/query', {
      query,
    })

    const accounts = response.data.QueryResponse.Account ?? []
    const totalCount = response.data.QueryResponse.totalCount ?? accounts.length

    return {
      items: accounts.map(this.mapAccount),
      total: totalCount,
      page: pagination?.page ?? 1,
      pageSize: maxResults,
      hasNext: startPosition + maxResults < totalCount,
    }
  }

  private mapAccount(qb: QBAccount): ExternalAccount {
    const typeMap: Record<string, ExternalAccount['type']> = {
      // Classification-level values
      Asset: 'asset',
      Liability: 'liability',
      Equity: 'equity',
      Income: 'revenue',
      Expense: 'expense',
      // AccountType-level values (more specific)
      AccountsPayable: 'liability',
      AccountsReceivable: 'asset',
      Bank: 'asset',
      CostOfGoodsSold: 'expense',
      CreditCard: 'liability',
      FixedAsset: 'asset',
      LongTermLiability: 'liability',
      OtherCurrentAsset: 'asset',
      OtherCurrentLiability: 'liability',
      OtherExpense: 'expense',
      OtherIncome: 'revenue',
    }

    return {
      externalId: qb.Id,
      name: qb.FullyQualifiedName ?? qb.Name,
      type: typeMap[qb.Classification] ?? 'asset',
      subtype: qb.AccountSubType,
      currency: qb.CurrencyRef?.value ?? 'USD',
      balance: qb.CurrentBalance ?? 0,
      active: qb.Active,
      lastUpdated: new Date(qb.MetaData.LastUpdatedTime).getTime(),
    }
  }

  // ── Transactions ─────────────────────────────────────────────────────────

  async getTransactions(
    accountId: string,
    pagination?: PaginationParams
  ): Promise<PaginatedResponse<ExternalTransaction>> {
    const startPosition = ((pagination?.page ?? 1) - 1) * (pagination?.pageSize ?? 100) + 1
    const maxResults = pagination?.pageSize ?? 100

    const query = `SELECT * FROM JournalEntry WHERE Id IN (SELECT JournalEntryId FROM JournalEntryLine WHERE JournalEntryLine.AccountRef = '${accountId}') STARTPOSITION ${startPosition} MAXRESULTS ${maxResults}`

    const response = await this.client.get<QBQueryResponse<QBTransaction>>('/query', {
      query,
    })

    const txns = response.data.QueryResponse.JournalEntry ?? []
    const totalCount = response.data.QueryResponse.totalCount ?? txns.length

    const items: ExternalTransaction[] = []

    for (const txn of txns) {
      for (const line of txn.Line ?? []) {
        items.push({
          externalId: `${txn.Id}-${line.Id ?? '0'}`,
          accountId,
          date: txn.TxnDate,
          description: line.Description ?? txn.PrivateNote ?? '',
          amount: line.Amount,
          currency: txn.CurrencyRef?.value ?? 'USD',
          type: line.Amount >= 0 ? 'debit' : 'credit',
          reference: txn.DocNumber,
        })
      }
    }

    return {
      items,
      total: totalCount,
      page: pagination?.page ?? 1,
      pageSize: maxResults,
      hasNext: startPosition + maxResults < totalCount,
    }
  }

  // ── Invoices ─────────────────────────────────────────────────────────────

  async getInvoices(pagination?: PaginationParams): Promise<PaginatedResponse<ExternalInvoice>> {
    const startPosition = ((pagination?.page ?? 1) - 1) * (pagination?.pageSize ?? 100) + 1
    const maxResults = pagination?.pageSize ?? 100

    const query = `SELECT * FROM Invoice ORDERBY TxnDate DESC STARTPOSITION ${startPosition} MAXRESULTS ${maxResults}`

    const response = await this.client.get<QBQueryResponse<QBInvoice>>('/query', {
      query,
    })

    const invoices = response.data.QueryResponse.Invoice ?? []
    const totalCount = response.data.QueryResponse.totalCount ?? invoices.length

    return {
      items: invoices.map(this.mapInvoice),
      total: totalCount,
      page: pagination?.page ?? 1,
      pageSize: maxResults,
      hasNext: startPosition + maxResults < totalCount,
    }
  }

  private mapInvoice(qb: QBInvoice): ExternalInvoice {
    const lineItems: ExternalInvoiceLineItem[] = (qb.Line ?? [])
      .filter((l) => l.DetailType === 'SalesItemLineDetail')
      .map((l) => ({
        description: l.Description ?? '',
        quantity: l.SalesItemLineDetail?.Qty ?? 1,
        unitPrice: l.SalesItemLineDetail?.UnitPrice ?? l.Amount,
        amount: l.Amount,
        accountId: l.SalesItemLineDetail?.AccountRef?.value,
      }))

    const status: ExternalInvoice['status'] =
      qb.Balance === 0 ? 'paid' : qb.Balance === qb.TotalAmt ? 'sent' : 'draft'

    return {
      externalId: qb.Id,
      number: qb.DocNumber,
      customerId: qb.CustomerRef.value,
      date: qb.TxnDate,
      dueDate: qb.DueDate,
      status,
      subtotal: lineItems.reduce((sum, li) => sum + li.amount, 0),
      tax: 0, // QB tax is on separate lines
      total: qb.TotalAmt,
      currency: qb.CurrencyRef?.value ?? 'USD',
      lineItems,
    }
  }

  // ── Budgets (via Profit & Loss Report) ───────────────────────────────────

  async getBudgets(pagination?: PaginationParams): Promise<PaginatedResponse<ExternalBudget>> {
    // QuickBooks does not have a direct Budget API for all versions.
    // Use the BudgetSummary report when available, otherwise return empty.
    try {
      const year = new Date().getFullYear()
      const response = await this.client.get<{ rows?: { ColData: { value: string }[] }[] }>(
        `/reports/BudgetSummary?start_date=${year}-01-01&end_date=${year}-12-31`
      )

      const rows = response.data.rows ?? []
      const entries = rows
        .filter((row) => row.ColData?.length >= 2)
        .map((row) => ({
          accountId: row.ColData[0]?.value ?? '',
          category: row.ColData[0]?.value ?? '',
          amount: parseFloat(row.ColData[1]?.value ?? '0') || 0,
          period: `${year}`,
        }))

      return {
        items: [
          {
            externalId: `budget-${year}`,
            name: `Budget ${year}`,
            fiscalYear: `${year}`,
            entries,
          },
        ],
        total: 1,
        page: 1,
        pageSize: 1,
        hasNext: false,
      }
    } catch {
      return { items: [], total: 0, page: 1, pageSize: 50, hasNext: false }
    }
  }

  // ── Sync ─────────────────────────────────────────────────────────────────

  protected async pullData(options: SyncOptions): Promise<number> {
    let total = 0
    const pageSize = options.batchSize ?? 100

    // Pull accounts
    const accounts = await this.getAccounts({ page: 1, pageSize })
    total += accounts.items.length

    // Pull transactions per account
    for (const account of accounts.items.slice(0, 10)) {
      const txns = await this.getTransactions(account.externalId, { page: 1, pageSize })
      total += txns.items.length
    }

    // Pull invoices
    const invoices = await this.getInvoices({ page: 1, pageSize })
    total += invoices.items.length

    return total
  }

  protected async pushData(_options: SyncOptions): Promise<number> {
    // QuickBooks push is not implemented in this phase
    // Would require creating/updating JournalEntries, Invoices, etc.
    return 0
  }
}

import axios from 'axios'
import { useAuthStore } from '@/store/authStore'

const api = axios.create({
  baseURL: (import.meta as any).env.VITE_API_URL || '/api',
  timeout: 30_000,
  headers: {
    'Content-Type': 'application/json',
  },
})

// --- Request interceptor: attach Bearer token ---
api.interceptors.request.use(
  (config) => {
    const token = useAuthStore.getState().accessToken
    if (token) {
      config.headers.Authorization = `Bearer ${token}`
    }
    return config
  },
  (error) => Promise.reject(error)
)

// --- Response interceptor: handle 401 with refresh ---
let isRefreshing = false
let pendingQueue: Array<{
  resolve: (token: string) => void
  reject: (error: unknown) => void
}> = []

function processPendingQueue(error: unknown, token: string | null) {
  pendingQueue.forEach(({ resolve, reject }) => {
    if (error || !token) {
      reject(error)
    } else {
      resolve(token)
    }
  })
  pendingQueue = []
}

api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config

    // Only attempt refresh once per request
    if (error.response?.status !== 401 || originalRequest._retry) {
      return Promise.reject(error)
    }

    // Don't try to refresh if the failing request was itself a refresh
    if (originalRequest.url === '/auth/refresh') {
      useAuthStore.getState().logout()
      window.location.href = '/login'
      return Promise.reject(error)
    }

    if (isRefreshing) {
      // Queue this request until the refresh completes
      return new Promise((resolve, reject) => {
        pendingQueue.push({
          resolve: (token: string) => {
            originalRequest.headers.Authorization = `Bearer ${token}`
            resolve(api(originalRequest))
          },
          reject,
        })
      })
    }

    originalRequest._retry = true
    isRefreshing = true

    try {
      // Read refresh token from Zustand store (persisted via masterStorage).
      // Do NOT read from raw localStorage — it bypasses the secure storage adapter.
      const refreshToken = useAuthStore.getState().refreshToken
      if (!refreshToken) {
        throw new Error('No refresh token available')
      }

      const { data } = await axios.post<{ accessToken: string }>(
        `${api.defaults.baseURL}/auth/refresh`,
        { refreshToken }
      )

      const newToken = data.accessToken
      useAuthStore.setState({ accessToken: newToken })
      processPendingQueue(null, newToken)

      originalRequest.headers.Authorization = `Bearer ${newToken}`
      return api(originalRequest)
    } catch (refreshError) {
      processPendingQueue(refreshError, null)
      useAuthStore.getState().logout()
      window.location.href = '/login'
      return Promise.reject(refreshError)
    } finally {
      isRefreshing = false
    }
  }
)

