  })

  // --- submitBudget ---

  it('should change budget status to InReview after submission', async () => {
    const budgets = [
      {
        ...createBudgetInput({ status: 'Draft' }),
        id: 'bgt-1',
        createdAt: '2024-01-01T00:00:00.000Z',
        updatedAt: '2024-01-01T00:00:00.000Z',
        createdBy: 'usr-001',
      },
    ] as Budget[]
    useBudgetStore.setState({ budgets })
    const submitPromise = useBudgetStore.getState().submitBudget('bgt-1')
    expect(useBudgetStore.getState().isSubmitting).toBe(true)
    await submitPromise
    const state = useBudgetStore.getState()
    expect(state.isSubmitting).toBe(false)
    expect(state.budgets[0].status).toBe('InReview')
  })

  // --- approveBudget ---

  it('should change budget status to Approved', () => {
    const budgets = [
      {
        ...createBudgetInput({ status: 'InReview' }),
        id: 'bgt-1',
        createdAt: '2024-01-01T00:00:00.000Z',
        updatedAt: '2024-01-01T00:00:00.000Z',
        createdBy: 'usr-001',
      },
    ] as Budget[]
    useBudgetStore.setState({ budgets })
    useBudgetStore.getState().approveBudget('bgt-1')
    expect(useBudgetStore.getState().budgets[0].status).toBe('Approved')
  })

  it('should not throw when approving non-existent budget', () => {
    expect(() => useBudgetStore.getState().approveBudget('non-existent')).not.toThrow()
  })

  // --- rejectBudget ---

  it('should change budget status back to Draft', () => {
    const budgets = [
      {
        ...createBudgetInput({ status: 'InReview' }),
        id: 'bgt-1',
        createdAt: '2024-01-01T00:00:00.000Z',
        updatedAt: '2024-01-01T00:00:00.000Z',
        createdBy: 'usr-001',
      },
    ] as Budget[]
    useBudgetStore.setState({ budgets })
    useBudgetStore.getState().rejectBudget('bgt-1')
    expect(useBudgetStore.getState().budgets[0].status).toBe('Draft')
  })

  it('should reject non-existent budget without error', () => {
    expect(() => useBudgetStore.getState().rejectBudget('non-existent')).not.toThrow()
  })

  // --- undo / redo ---

  it('should undo to previous line items state', () => {
    const items1 = [createLineItem({ id: 'item-1', amount: 100 })]
    const items2 = [createLineItem({ id: 'item-1', amount: 200 })]
    useBudgetStore.setState({ lineItems: items2, history: [items1, items2], historyIndex: 1 })
    useBudgetStore.getState().undo()
    const state = useBudgetStore.getState()
    expect(state.lineItems).toEqual(items1)
    expect(state.historyIndex).toBe(0)
  })

  it('should not undo when already at beginning', () => {
    const items = [createLineItem({ id: 'item-1', amount: 100 })]
    useBudgetStore.setState({ lineItems: items, history: [items], historyIndex: 0 })
    useBudgetStore.getState().undo()
    expect(useBudgetStore.getState().historyIndex).toBe(0)
  })

  it('should redo to next line items state', () => {
    const items1 = [createLineItem({ id: 'item-1', amount: 100 })]
    const items2 = [createLineItem({ id: 'item-1', amount: 200 })]
    useBudgetStore.setState({ lineItems: items1, history: [items1, items2], historyIndex: 0 })
    useBudgetStore.getState().redo()
    const state = useBudgetStore.getState()
    expect(state.lineItems).toEqual(items2)
    expect(state.historyIndex).toBe(1)
  })

  it('should not redo when already at end', () => {
    const items = [createLineItem({ id: 'item-1', amount: 100 })]
    useBudgetStore.setState({ lineItems: items, history: [items], historyIndex: 0 })
    useBudgetStore.getState().redo()
    expect(useBudgetStore.getState().historyIndex).toBe(0)
  })

  // --- setSelectedCell ---

  it('should set selected cell id', () => {
    useBudgetStore.getState().setSelectedCell('cell-1')
    expect(useBudgetStore.getState().selectedCellId).toBe('cell-1')
  })

  it('should clear selected cell id with null', () => {
    useBudgetStore.setState({ selectedCellId: 'cell-1' })
    useBudgetStore.getState().setSelectedCell(null)
    expect(useBudgetStore.getState().selectedCellId).toBeNull()
  })
})

import { create } from 'zustand'
import { persist, subscribeWithSelector } from 'zustand/middleware'
import { immer } from 'zustand/middleware/immer'
import type { Budget, BudgetLineItem, BudgetState } from '../types'
import { masterStorage } from '../utils/masterStorage'

export const useBudgetStore = create<BudgetState>()(
  subscribeWithSelector(
    persist(
      immer((set, get) => ({
        budgets: [],
        activeBudgetId: null,
        lineItems: [],
        isLoading: false,
        isSubmitting: false,
        lastChange: null,
        history: [[]],
        historyIndex: 0,
        selectedCellId: null,

        setBudgets: (budgets) => {
          set((state) => {
            state.budgets = budgets as any
          })
        },

        setActiveBudget: (id) => {
          const budget = get().budgets.find((b) => b.id === id)
          if (!budget) return
          set((state) => {
            state.activeBudgetId = id
          })
        },

        setLineItems: (items) => {
          set((state) => {
            state.lineItems = items
          })
        },

        updateLineItem: (id, updates) => {
          // Input validation
          if (!id || typeof id !== 'string') {
            throw new Error('id must be a non-empty string')
          }
          if (!updates || typeof updates !== 'object') {
            throw new Error('updates must be an object')
          }
          if (
            updates.amount !== undefined &&
            (typeof updates.amount !== 'number' || !Number.isFinite(updates.amount))
          ) {
            throw new Error('amount must be a finite number')
          }
          set((state) => {
            const idx = state.lineItems.findIndex((i) => i.id === id)
            if (idx !== -1) {
              const oldItem = state.lineItems[idx]
              Object.assign(state.lineItems[idx], updates)
              state.lastChange = {
                cellId: id,
                oldValue: oldItem.amount,
                newValue: updates.amount ?? oldItem.amount,
                timestamp: new Date().toISOString(),
              }
            }
          })
        },

        createBudget: (budget) => {
          // Input validation
          if (!budget || typeof budget !== 'object') {
            throw new Error('budget must be an object')
          }
          if (!budget.name || typeof budget.name !== 'string' || budget.name.trim().length === 0) {
            throw new Error('budget name must be a non-empty string')
          }
          if (budget.name.length > 200) {
            throw new Error('budget name must be 200 characters or less')
          }
          const newBudget: Budget = {
            ...budget,
            id: `bgt-${Date.now()}`,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
            createdBy: 'usr-001',
          }
          set((state) => {
            state.budgets.push(newBudget as any)
          })
          return newBudget.id
        },

        deleteBudget: (id) => {
          set((state) => {
            const idx = state.budgets.findIndex((b) => b.id === id)
            if (idx !== -1) state.budgets.splice(idx, 1)
            if (state.activeBudgetId === id) state.activeBudgetId = null
          })
        },

        duplicateBudget: (id) => {
          const budget = get().budgets.find((b) => b.id === id)
          if (budget) {
            const newId = `bgt-${Date.now()}`
            const newBudget: Budget = {
              ...budget,
              id: newId,
              name: `${budget.name} (Copy)`,
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString(),
            }
            set((state) => {
              state.budgets.push(newBudget as any)
            })
            return newId
          }
          return ''
        },

        submitBudget: async (id) => {
          set((state) => {
            state.isSubmitting = true
          })
          await new Promise((r) => setTimeout(r, 1000))
          set((state) => {
            const budget = state.budgets.find((b) => b.id === id)
            if (budget) budget.status = 'InReview'
            state.isSubmitting = false
          })
        },

        approveBudget: (id) => {
          set((state) => {
            const budget = state.budgets.find((b) => b.id === id)
            if (budget) budget.status = 'Approved'
          })
        },

        rejectBudget: (id) => {
          set((state) => {
            const budget = state.budgets.find((b) => b.id === id)
            if (budget) budget.status = 'Draft'
          })
        },

        undo: () => {
          const { historyIndex, history } = get()
          if (historyIndex > 0) {
            set((state) => {
              state.lineItems = history[historyIndex - 1]
              state.historyIndex = historyIndex - 1
            })
          }
        },

        redo: () => {
          const { historyIndex, history } = get()
          if (historyIndex < history.length - 1) {
            set((state) => {
              state.lineItems = history[historyIndex + 1]
              state.historyIndex = historyIndex + 1
            })
          }
        },

        setSelectedCell: (id) => {
          set((state) => {
            state.selectedCellId = id
          })
        },
      })),
      {
        name: 'budget-store',
        storage: masterStorage,
      }
    )
  )
)

// Memoized selectors to prevent unnecessary re-renders
export const budgetSelectors = {
  budgets: (state: BudgetState) => state.budgets,
  activeBudgetId: (state: BudgetState) => state.activeBudgetId,
  lineItems: (state: BudgetState) => state.lineItems,
  isLoading: (state: BudgetState) => state.isLoading,
  isSubmitting: (state: BudgetState) => state.isSubmitting,
  lastChange: (state: BudgetState) => state.lastChange,
  historyIndex: (state: BudgetState) => state.historyIndex,
  selectedCellId: (state: BudgetState) => state.selectedCellId,
  // Derived selectors
  activeBudget: (state: BudgetState) =>
    state.budgets.find((b) => b.id === state.activeBudgetId) ?? null,
  budgetCount: (state: BudgetState) => state.budgets.length,
  canUndo: (state: BudgetState) => state.historyIndex > 0,
  canRedo: (state: BudgetState) => state.historyIndex < state.history.length - 1,
  draftBudgets: (state: BudgetState) => state.budgets.filter((b) => b.status === 'Draft'),
  inReviewBudgets: (state: BudgetState) => state.budgets.filter((b) => b.status === 'InReview'),
  approvedBudgets: (state: BudgetState) => state.budgets.filter((b) => b.status === 'Approved'),
}

