import { create } from 'zustand'
import { subscribeWithSelector } from 'zustand/middleware'
import { persist } from 'zustand/middleware'
import type { GLAccount, ImportJob, DataState } from '../types'
import { masterStorage } from '../utils/masterStorage'

export const useDataStore = create<DataState>()(
  subscribeWithSelector(
    persist(
      (set, get) => ({
        accounts: [],
        importJobs: [],
        selectedAccountId: null,
        lastImportDate: null,

        setAccounts: (accounts) => set({ accounts }),

        addAccount: (account) =>
          set((state) => ({
            accounts: [...state.accounts, { ...account, id: `acct-${Date.now()}`, children: [] }],
          })),

        updateAccount: (id, updates) =>
          set((state) => {
            const updateRecursive = (list: GLAccount[]): GLAccount[] =>
              list.map((a) => {
                if (a.id === id) return { ...a, ...updates }
                if (a.children) return { ...a, children: updateRecursive(a.children) }
                return a
              })
            return { accounts: updateRecursive(state.accounts) }
          }),

        deleteAccount: (id) => {
          set((state) => {
            const removeRecursive = (list: GLAccount[]): GLAccount[] =>
              list
                .filter((a) => a.id !== id)
                .map((a) => ({
                  ...a,
                  children: a.children ? removeRecursive(a.children) : [],
                }))
            return {
              accounts: removeRecursive(state.accounts),
              selectedAccountId: state.selectedAccountId === id ? null : state.selectedAccountId,
            }
          })
        },

        toggleAccountActive: (id) => {
          set((state) => {
            const toggleRecursive = (list: GLAccount[]): GLAccount[] =>
              list.map((a) => {
                if (a.id === id) return { ...a, isActive: !a.isActive }
                if (a.children) return { ...a, children: toggleRecursive(a.children) }
                return a
              })
            return { accounts: toggleRecursive(state.accounts) }
          })
        },

        addImportJob: (job) => {
          const id = `import-${Date.now()}`
          const now = new Date().toISOString()
          set((state) => ({
            importJobs: [
              { ...job, id, status: 'Pending', startedAt: now } as ImportJob,
              ...state.importJobs,
            ],
          }))
          return id
        },

        updateImportStatus: (id, status, error) => {
          set((state) => {
            const isCompleted = status === 'Completed'
            const newJobs = state.importJobs.map((j) => {
              if (j.id === id) {
                return {
                  ...j,
                  status,
                  ...(isCompleted ? { completedAt: new Date().toISOString() } : {}),
                  ...(error ? { error } : {}),
                }
              }
              return j
            })
            return {
              importJobs: newJobs,
              ...(isCompleted ? { lastImportDate: new Date().toISOString() } : {}),
            }
          })
        },

        setSelectedAccount: (id) => set({ selectedAccountId: id }),
      }),
      {
        name: 'data-store',
        storage: masterStorage,
      }
    )
  )
)

import { create } from 'zustand'
import { persist, subscribeWithSelector } from 'zustand/middleware'
import { immer } from 'zustand/middleware/immer'
import type { Entity } from '../types'
import { masterStorage } from '../utils/masterStorage'
import { cacheSet, cacheGet, cacheClearStore, isOnline, markSynced } from '../utils/offlineCache'

// =============================================================================
// ENTITY STORE — Multi-entity management with offline caching
// =============================================================================

interface EntityState {
  entities: Entity[]
  selectedEntityId: string | null
  isLoading: boolean
  error: string | null

  // CRUD
  setEntities: (entities: Entity[]) => void
  addEntity: (entity: Omit<Entity, 'id'>) => string
  updateEntity: (id: string, updates: Partial<Entity>) => void
  deleteEntity: (id: string) => void

  // Selection
  setSelectedEntity: (id: string | null) => void
  getSelectedEntity: () => Entity | null

  // Hierarchy
  getChildEntities: (parentId: string) => Entity[]
  getParentEntity: (childId: string) => Entity | null
  getEntityTree: (rootId?: string) => Entity[]

  // Offline cache
  syncToCache: () => Promise<void>
  loadFromCache: () => Promise<boolean>
  clearCache: () => Promise<void>

  // State
  setError: (error: string | null) => void
  clearError: () => void
  setLoading: (loading: boolean) => void
}

export const useEntityStore = create<EntityState>()(
  subscribeWithSelector(
    persist(
      immer((set, get) => ({
        entities: [],
        selectedEntityId: null,
        isLoading: false,
        error: null,

        // --- CRUD ---

        setEntities: (entities) => {
          set((state) => {
            state.entities = entities
          })
        },

        addEntity: (entity) => {
          const newId = `ent-${Date.now()}`
          const newEntity: Entity = {
            ...entity,
            id: newId,
          } as Entity
          set((state) => {
            state.entities.push(newEntity)
          })
          return newId
        },

        updateEntity: (id, updates) => {
          set((state) => {
            const idx = state.entities.findIndex((e) => e.id === id)
            if (idx !== -1) {
              Object.assign(state.entities[idx], updates)
            }
          })
        },

        deleteEntity: (id) => {
          set((state) => {
            // Remove the entity and all its descendants
            const idsToRemove = new Set<string>()
            const collectDescendants = (parentId: string) => {
              idsToRemove.add(parentId)
              state.entities
                .filter((e) => e.parentId === parentId)
                .forEach((child) => collectDescendants(child.id))
            }
            collectDescendants(id)

            state.entities = state.entities.filter((e) => !idsToRemove.has(e.id))
            if (state.selectedEntityId && idsToRemove.has(state.selectedEntityId)) {
              state.selectedEntityId = null
            }
          })
        },

        // --- Selection ---

        setSelectedEntity: (id) => {
          set((state) => {
            state.selectedEntityId = id
          })
        },

        getSelectedEntity: () => {
          const { entities, selectedEntityId } = get()
          return entities.find((e) => e.id === selectedEntityId) ?? null
        },

        // --- Hierarchy ---

        getChildEntities: (parentId) => {
          return get().entities.filter((e) => e.parentId === parentId)
        },

        getParentEntity: (childId) => {
          const child = get().entities.find((e) => e.id === childId)
          if (!child?.parentId) return null
          return get().entities.find((e) => e.id === child.parentId) ?? null
        },

        getEntityTree: (rootId) => {
          const { entities } = get()
          const result: Entity[] = []

          // Find root: either specified or top-level (parentId === null)
          const roots = rootId
            ? entities.filter((e) => e.id === rootId)
            : entities.filter((e) => e.parentId === null)

          const traverse = (parentId: string) => {
            const children = entities.filter((e) => e.parentId === parentId)
            for (const child of children) {
              result.push(child)
              traverse(child.id)
            }
          }

          for (const root of roots) {
            result.push(root)
            traverse(root.id)
          }

          return result
        },

        // --- Offline Cache ---

        syncToCache: async () => {
          const { entities } = get()
          try {
            await cacheClearStore('entities')
            await cacheSet('entities', 'all', entities)
            markSynced()
          } catch {
            // Cache sync is best-effort
          }
        },

        loadFromCache: async () => {
          try {
            const cached = await cacheGet<Entity[]>('entities', 'all')
            if (cached && cached.length > 0) {
              set((state) => {
                state.entities = cached
              })
              return true
            }
            return false
          } catch {
            return false
          }
        },

        clearCache: async () => {
          await cacheClearStore('entities')
        },

        // --- State ---

        setError: (error) => {
          set((state) => {
            state.error = error
          })
        },

        clearError: () => {
          set((state) => {
            state.error = null
          })
        },

        setLoading: (loading) => {
          set((state) => {
            state.isLoading = loading
          })
        },
      })),
      {
        name: 'entity-store',
        storage: masterStorage,
      }
    )
  )
)

import { describe, it, expect, beforeEach } from 'vitest'
import { useForecastStore } from './forecastStore'

describe('forecastStore', () => {
  beforeEach(() => {
    useForecastStore.setState({
      forecasts: [],
      drivers: [],
      selectedForecastId: null,
      isLoading: false,
    })
  })

  it('should have correct initial state', () => {
    const state = useForecastStore.getState()
    expect(state.forecasts).toEqual([])
    expect(state.drivers).toEqual([])
    expect(state.selectedForecastId).toBeNull()
    expect(state.isLoading).toBe(false)
  })

  it('should create a forecast', () => {
    const id = useForecastStore.getState().createForecast({
      name: 'Q1 Forecast',
      description: 'Test',
      status: 'draft',
    } as any)
    expect(id).toMatch(/^fcst-/)
    expect(useForecastStore.getState().forecasts).toHaveLength(1)
    expect(useForecastStore.getState().forecasts[0].name).toBe('Q1 Forecast')
  })

  it('should update a forecast', () => {
    const id = useForecastStore.getState().createForecast({
      name: 'Forecast 1',
      status: 'draft',
    } as any)
    useForecastStore.getState().updateForecast(id, { name: 'Updated' })
    expect(useForecastStore.getState().forecasts[0].name).toBe('Updated')
    expect(useForecastStore.getState().forecasts[0].updatedAt).toBeDefined()
  })

  it('should delete a forecast', () => {
    const id = useForecastStore.getState().createForecast({
      name: 'Forecast 1',
      status: 'draft',
    } as any)
    useForecastStore.getState().deleteForecast(id)
    expect(useForecastStore.getState().forecasts).toHaveLength(0)
  })

  it('should clear selected forecast when deleted', () => {
    const id = useForecastStore.getState().createForecast({
      name: 'Forecast 1',
      status: 'draft',
    } as any)
    useForecastStore.getState().setSelectedForecast(id)
    useForecastStore.getState().deleteForecast(id)
    expect(useForecastStore.getState().selectedForecastId).toBeNull()
  })

  it('should set selected forecast', () => {
    const id = useForecastStore.getState().createForecast({
      name: 'Forecast 1',
      status: 'draft',
    } as any)
    useForecastStore.getState().setSelectedForecast(id)
    expect(useForecastStore.getState().selectedForecastId).toBe(id)
  })

  it('should not set selected forecast for non-existent id', () => {
    useForecastStore.getState().setSelectedForecast('non-existent')
    expect(useForecastStore.getState().selectedForecastId).toBeNull()
  })

  it('should set forecasts', () => {
    const forecasts = [{ id: 'fcst-1', name: 'F1' }] as any
    useForecastStore.getState().setForecasts(forecasts)
    expect(useForecastStore.getState().forecasts).toEqual(forecasts)
  })

  it('should set drivers', () => {
    const drivers = [{ id: 'drv-1', name: 'Growth' }] as any
    useForecastStore.getState().setDrivers(drivers)
    expect(useForecastStore.getState().drivers).toEqual(drivers)
  })

  it('should update a driver', () => {
    useForecastStore.getState().setDrivers([{ id: 'drv-1', name: 'Growth', value: 10 }] as any)
    useForecastStore.getState().updateDriver('drv-1', { value: 15 })
    expect(useForecastStore.getState().drivers[0].value).toBe(15)
  })
})

import { create } from 'zustand'
import { persist, subscribeWithSelector } from 'zustand/middleware'
import { immer } from 'zustand/middleware/immer'
import type { Forecast, ForecastDriver, ForecastState } from '../types'
import { masterStorage } from '../utils/masterStorage'
import { UndoRedoEngine } from '@/engines/UndoRedoEngine'

interface ForecastSnapshot {
  forecasts: Forecast[]
  drivers: ForecastDriver[]
  selectedForecastId: string | null
}

const undoEngine = new UndoRedoEngine<ForecastSnapshot>(100)

function captureForecastSnapshot(get: () => ReturnType<typeof useForecastStore.getState>) {
  const state = get()
  undoEngine.push({
    forecasts: state.forecasts,
    drivers: state.drivers,
    selectedForecastId: state.selectedForecastId,
  })
}

export const useForecastStore = create<ForecastState>()(
  subscribeWithSelector(
    persist(
      immer((set, get) => ({
        forecasts: [],
        drivers: [],
        selectedForecastId: null,
        isLoading: false,
        error: null as string | null,

        undo: () => {
          const snapshot = undoEngine.undo()
          if (snapshot !== null) {
            set({
              forecasts: snapshot.forecasts,
              drivers: snapshot.drivers,
              selectedForecastId: snapshot.selectedForecastId,
            })
          }
        },

        redo: () => {
          const snapshot = undoEngine.redo()
          if (snapshot !== null) {
            set({
              forecasts: snapshot.forecasts,
              drivers: snapshot.drivers,
              selectedForecastId: snapshot.selectedForecastId,
            })
          }
        },

        canUndo: () => undoEngine.canUndo(),
        canRedo: () => undoEngine.canRedo(),
        getHistoryLength: () => undoEngine.getHistoryLength(),

        setForecasts: (forecasts) => {
          captureForecastSnapshot(get)
          set({ forecasts })
        },

        setSelectedForecast: (id) => {
          const forecast = get().forecasts.find((f) => f.id === id)
          if (!forecast) return
          set({ selectedForecastId: id })
        },

        createForecast: (forecast) => {
          // Input validation
          if (!forecast || typeof forecast !== 'object') {
            throw new Error('forecast must be an object')
          }
          if (
            !forecast.name ||
            typeof forecast.name !== 'string' ||
            forecast.name.trim().length === 0
          ) {
            throw new Error('forecast name must be a non-empty string')
          }
          if (forecast.name.length > 200) {
            throw new Error('forecast name must be 200 characters or less')
          }
          captureForecastSnapshot(get)
          const newForecast: Forecast = {
            ...forecast,
            id: `fcst-${Date.now()}`,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
          }
          set((state) => {
            state.forecasts.push(newForecast)
          })
          return newForecast.id
        },

        updateForecast: (id, updates) => {
          captureForecastSnapshot(get)
          set((state) => {
            const forecast = state.forecasts.find((f) => f.id === id)
            if (forecast) {
              Object.assign(forecast, updates)
              ;(forecast as any).updatedAt = new Date().toISOString()
            }
          })
        },

        deleteForecast: (id) => {
          captureForecastSnapshot(get)
          set((state) => {
            const idx = state.forecasts.findIndex((f) => f.id === id)
            if (idx !== -1) state.forecasts.splice(idx, 1)
            if (state.selectedForecastId === id) state.selectedForecastId = null
          })
        },

        setDrivers: (drivers) => {
          captureForecastSnapshot(get)
          set({ drivers })
        },

        updateDriver: (id, updates) => {
          captureForecastSnapshot(get)
          set((state) => {
            const driver = state.drivers.find((d) => d.id === id)
            if (driver) Object.assign(driver, updates)
          })
        },

        setError: (error) => {
          set({ error })
        },

        clearError: () => {
          set({ error: null })
        },

        setLoading: (loading) => {
          set({ isLoading: loading })
        },
      })),
      {
        name: 'forecast-store',
        storage: masterStorage,
      }
    )
  )
)

// Memoized selectors to prevent unnecessary re-renders
export const forecastSelectors = {
  forecasts: (state: ForecastState) => state.forecasts,
  drivers: (state: ForecastState) => state.drivers,
  selectedForecastId: (state: ForecastState) => state.selectedForecastId,
  isLoading: (state: ForecastState) => state.isLoading,
  // Derived selectors
  forecastCount: (state: ForecastState) => state.forecasts.length,
  driverCount: (state: ForecastState) => state.drivers.length,
  selectedForecast: (state: ForecastState) =>
    state.forecasts.find((f) => f.id === state.selectedForecastId) ?? null,
  hasForecasts: (state: ForecastState) => state.forecasts.length > 0,
  hasDrivers: (state: ForecastState) => state.drivers.length > 0,
}

import { create } from 'zustand'
import { persist, subscribeWithSelector } from 'zustand/middleware'
import { immer } from 'zustand/middleware/immer'
import type {
  GLAccount,
  GLEntry,
  TrialBalanceRow,
  AccountAnalysis,
  ColumnMapping,
  GLState,
  ImportResult,
} from '@/types'
import { masterStorage } from '../utils/masterStorage'
import { UndoRedoEngine } from '@/engines/UndoRedoEngine'
import { useCubeStore } from './cubeStore'
import { invalidateStoreCache } from '@/utils/storeCache'

function extractTimeCode(dateStr: string): string {
  const d = new Date(dateStr)
  const year = d.getFullYear()
  const month = d.getMonth() + 1
  const quarter = Math.ceil(month / 3)
  return `Time:${year}-Q${quarter}-M${String(month).padStart(2, '0')}`
}

interface GLSnapshot {
  entries: GLEntry[]
  accounts: GLAccount[]
  trialBalance: TrialBalanceRow[]
  accountAnalysis: AccountAnalysis | null
}

const undoEngine = new UndoRedoEngine<GLSnapshot>(100)

function captureGLSnapshot(get: () => ReturnType<typeof useGLStore.getState>) {
  const state = get()
  undoEngine.push({
    entries: state.entries,
    accounts: state.accounts,
    trialBalance: state.trialBalance,
    accountAnalysis: state.accountAnalysis,
  })
}

export const useGLStore = create<GLState>()(
  subscribeWithSelector(
    persist(
      immer((set, get) => ({
        entries: [],
        accounts: [],
        trialBalance: [],
        accountAnalysis: null,
        columnMapping: [
          { sourceColumn: '', targetField: 'date', isRequired: true },
          { sourceColumn: '', targetField: 'accountCode', isRequired: true },
          { sourceColumn: '', targetField: 'debit', isRequired: false },
          { sourceColumn: '', targetField: 'credit', isRequired: false },
          { sourceColumn: '', targetField: 'description', isRequired: false },
          { sourceColumn: '', targetField: 'reference', isRequired: false },
        ],
        dateFilter: null,
        accountFilter: [],
        isLoading: false,
        importProgress: 0,
        importStatus: 'idle',
        importError: null,
        lastImportResult: null,
        importHistory: [],
        lastImportEntryIds: [],

        // --- Undo/Redo Actions ---
        undo: () => {
          const snapshot = undoEngine.undo()
          if (snapshot !== null) {
            set({
              entries: snapshot.entries,
              accounts: snapshot.accounts,
              trialBalance: snapshot.trialBalance,
              accountAnalysis: snapshot.accountAnalysis,
            })
          }
        },

        redo: () => {
          const snapshot = undoEngine.redo()
          if (snapshot !== null) {
            set({
              entries: snapshot.entries,
              accounts: snapshot.accounts,
              trialBalance: snapshot.trialBalance,
              accountAnalysis: snapshot.accountAnalysis,
            })
          }
        },

        canUndo: () => undoEngine.canUndo(),
        canRedo: () => undoEngine.canRedo(),
        getHistoryLength: () => undoEngine.getHistoryLength(),

        // --- Mutation Actions (with undo capture) ---

        setEntries: (entries) => {
          captureGLSnapshot(get)
          const ids = entries.map((e) => e.id)
          set({
            entries,
            trialBalance: [],
            accountAnalysis: null,
            lastImportEntryIds: ids,
          })
        },

        addEntry: (entry) => {
          captureGLSnapshot(get)
          const entries = Array.isArray(entry) ? entry : [entry]
          set((state) => {
            state.entries.push(...entries)
            state.lastImportEntryIds = entries.map((e) => e.id)
          })
        },

        setAccounts: (accounts) => {
          captureGLSnapshot(get)
          set({ accounts })
        },

        generateTrialBalance: () => {
          set({ isLoading: true })
          const { entries, accounts } = get()
          const accountMap = new Map(accounts.map((a) => [a.id, a]))

          const balanceMap = new Map<string, TrialBalanceRow>()
          for (const entry of entries) {
            const key = entry.accountId
            const existing = balanceMap.get(key) ?? {
              accountId: entry.accountId,
              accountCode: entry.accountCode,
              accountName: entry.accountName,
              accountType: accountMap.get(entry.accountId)?.type ?? 'Unknown',
              beginningBalance: 0,
              debit: 0,
              credit: 0,
              netChange: 0,
              endingBalance: 0,
            }
            existing.debit += entry.debit
            existing.credit += entry.credit
            existing.netChange += entry.netChange
            existing.endingBalance = existing.beginningBalance + existing.netChange
            balanceMap.set(key, existing)
          }

          const balance = Array.from(balanceMap.values()).sort((a, b) =>
            a.accountCode.localeCompare(b.accountCode)
          )

          set({ trialBalance: balance, isLoading: false })
        },

        analyzeAccount: (accountId) => {
          set({ isLoading: true })
          const { entries } = get()
          const filtered = entries.filter((e) => e.accountId === accountId)

          const monthGroups = new Map<string, { debit: number; credit: number; count: number }>()
          for (const entry of filtered) {
            const month = entry.period
            const g = monthGroups.get(month) ?? { debit: 0, credit: 0, count: 0 }
            g.debit += entry.debit
            g.credit += entry.credit
            g.count += 1
            monthGroups.set(month, g)
          }

          const monthlyTotals = Array.from(monthGroups.entries())
            .map(([month, g]) => ({
              month,
              debit: g.debit,
              credit: g.credit,
              net: g.debit - g.credit,
            }))
            .sort((a, b) => a.month.localeCompare(b.month))

          const totalDebit = monthlyTotals.reduce((s, m) => s + m.debit, 0)
          const totalCredit = monthlyTotals.reduce((s, m) => s + m.credit, 0)

          set({
            accountAnalysis: {
              accountId,
              accountCode: filtered[0]?.accountCode ?? '',
              accountName: filtered[0]?.accountName ?? '',
              monthlyTotals,
              totalDebit,
              totalCredit,
              averageBalance:
                monthlyTotals.length > 0 ? (totalDebit - totalCredit) / monthlyTotals.length : 0,
              transactionCount: filtered.length,
            },
            isLoading: false,
          })
        },

        filterByDate: (start, end) => {
          set({ dateFilter: { start, end } })
        },

        filterByAccount: (accountIds) => {
          set({ accountFilter: accountIds })
        },

        clearFilters: () => {
          set({ dateFilter: null, accountFilter: [] })
        },

        updateColumnMapping: (mapping) => {
          set({ columnMapping: mapping })
        },

        clearData: () => {
          captureGLSnapshot(get)
          set({
            entries: [],
            trialBalance: [],
            accountAnalysis: null,
            dateFilter: null,
            accountFilter: [],
          })
        },

        setImportProgress: (progress) =>
          set({ importProgress: Math.max(0, Math.min(100, progress)) }),

        setImportStatus: (status) =>
          set({
            importStatus: status,
            importError: status === 'error' ? get().importError : null,
          }),

        setImportError: (error) => set({ importError: error, importStatus: 'error' }),

        recordImport: (result) =>
          set((state) => {
            state.importHistory.unshift({
              id: `import-${Date.now()}`,
              ...result,
              timestamp: new Date().toISOString(),
            })
            state.lastImportResult = { ...result, timestamp: new Date().toISOString() }
            state.importStatus = 'complete'
            state.importProgress = 100
          }),

        undoLastImport: () =>
          set((state) => {
            const ids = new Set(state.lastImportEntryIds)
            state.entries = state.entries.filter((e) => !ids.has(e.id))
            state.lastImportEntryIds = []
            state.lastImportResult = null
          }),

        checkDuplicates: (entries) => {
          const state = get()
          const keys = new Set(
            state.entries.map(
              (e) => `${e.accountCode}|${e.postDate || e.date}|${e.amount || e.debit - e.credit}`
            )
          )
          const dups = entries.filter((e) =>
            keys.has(`${e.accountCode}|${e.postDate || e.date}|${e.amount || e.debit - e.credit}`)
          )
          const newEntries = entries.filter(
            (e) =>
              !keys.has(
                `${e.accountCode}|${e.postDate || e.date}|${e.amount || e.debit - e.credit}`
              )
          )
          return { duplicates: dups.length, newEntries }
        },

        // --- CubeEngine integration ---

        syncToCube: () => {
          const { entries, accounts } = get()
          const cubeStore = useCubeStore.getState()
          if (!cubeStore.isInitialized) return

          for (const account of accounts) {
            try {
              cubeStore.addMember('Account', {
                code: account.code,
                name: account.name,
                hierarchy: 'reporting',
                level: account.level,
                isLeaf: account.children.length === 0,
                isActive: account.isActive,
                attributes: {
                  type: account.type,
                  category: account.category,
                  subCategory: account.subCategory,
                },
                sortOrder: account.sortOrder,
              })
            } catch {
              // Member may already exist
            }
          }

          const cubeCells: { cube: string; cell: import('@/types/cube-types').CubeCell }[] = []
          for (const e of entries) {
            const timeCode = extractTimeCode(e.postDate || e.date)
            const entityId = e.entityId || 'default_entity'
            const accountCode = `Account:${e.accountCode}`
            const coords: Record<string, string> = {
              Account: accountCode,
              Entity: `Entity:${entityId}`,
              Time: timeCode,
              Scenario: 'Scenario:Actual',
              Currency: 'Currency:USD',
            }
            const amount = e.amount ?? e.debit - e.credit

            cubeCells.push({
              cube: 'GL_Actuals',
              cell: { coords, measure: 'debit', value: e.debit, dataType: 'input' },
            })
            cubeCells.push({
              cube: 'GL_Actuals',
              cell: { coords, measure: 'credit', value: e.credit, dataType: 'input' },
            })
            cubeCells.push({
              cube: 'GL_Actuals',
              cell: { coords, measure: 'netChange', value: e.netChange, dataType: 'input' },
            })
            cubeCells.push({
              cube: 'GL_Actuals',
              cell: { coords, measure: 'amount', value: amount, dataType: 'input' },
            })
          }
          cubeStore.bulkWriteCells(cubeCells)
        },

        syncFromCube: () => {
          const cubeStore = useCubeStore.getState()
          if (!cubeStore.isInitialized) return

          const result = cubeStore.query({
            cube: 'GL_Actuals',
            rows: ['Account'],
            columns: ['Time'],
            filters: [{ dimension: 'Scenario', memberIds: ['Scenario:Actual'] }],
            measures: ['debit', 'credit', 'netChange', 'amount'],
            aggregation: 'sum',
            includeGrandTotal: true,
          })

          const balance: TrialBalanceRow[] = result.rows.map((row) => {
            const debit = typeof row.values[0] === 'number' ? row.values[0] : 0
            const credit = typeof row.values[1] === 'number' ? row.values[1] : 0
            const netChange = typeof row.values[2] === 'number' ? row.values[2] : 0
            const accountCode = row.label.split('|')[0]?.replace('Account:', '') ?? ''
            return {
              accountId: accountCode,
              accountCode,
              accountName: '',
              accountType: 'Unknown' as const,
              beginningBalance: 0,
              debit,
              credit,
              netChange,
              endingBalance: netChange,
            }
          })

          set({ trialBalance: balance })
        },

        getCubeState: () => {
          const cubeStore = useCubeStore.getState()
          return {
            isInitialized: cubeStore.isInitialized,
            cellCount: cubeStore.cellCount,
            historyCount: cubeStore.historyCount,
            snapshotCount: cubeStore.snapshots.length,
          }
        },
      })),
      {
        name: 'gl-store',
        storage: masterStorage,
        partialize: (state) => ({
          entries: state.entries,
          importHistory: state.importHistory,
          columnMapping: state.columnMapping,
        }),
      }
    )
  )
)

// Memoized selectors to prevent unnecessary re-renders
export const glSelectors = {
