  })

  it('should not alter safe text', () => {
    expect(escapeHTML('Hello World 123')).toBe('Hello World 123')
  })

  it('should escape multiple entities in one string', () => {
    expect(escapeHTML('<b>"bold" & \'italic\'</b>')).toBe(
