function makeMockToken(expMs: number): string {
  const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }))
  const payload = btoa(
    JSON.stringify({
      sub: 'user-001',
      role: 'Admin',
      iat: Math.floor(Date.now() / 1000),
      exp: Math.floor(expMs / 1000),
    })
  )
  return `${header}.${payload}.mock-sig`
